def acquire_app_runtime_lock():
    """Prevent the desktop UI and LAN worker from writing shared state together."""
    try:
        import msvcrt

        lock_file = APP_RUNTIME_LOCK_PATH.open('a+b')
        lock_file.seek(0, os.SEEK_END)
        if lock_file.tell() == 0:
            lock_file.write(b'0')
            lock_file.flush()
        lock_file.seek(0)
        msvcrt.locking(lock_file.fileno(), msvcrt.LK_NBLCK, 1)
        return lock_file
    except Exception:
        try:
            lock_file.close()
        except Exception:
            pass
        return None


