    def open_local_help_document(self, filename, title):
        path = PROJECT_DIR / filename
        if not path.exists():
            messagebox.showerror('帮助文件不存在', f'没有找到：\n{path}', parent=self.root)
            return
        try:
            text_value = path.read_text(encoding='utf-8-sig')
        except Exception as exc:
            messagebox.showerror('打开失败', f'无法读取帮助文件：\n{exc}', parent=self.root)
            return

        win = tk.Toplevel(self.root)
        win.title(title)
        win.geometry('1000x760')
        win.minsize(760, 520)

        toolbar = ttk.Frame(win)
        toolbar.pack(fill=tk.X, padx=10, pady=(10, 4))
        ttk.Label(toolbar, text=title, font=('Microsoft YaHei UI', 12, 'bold')).pack(side=tk.LEFT)
        ttk.Button(toolbar, text='用默认程序打开', command=lambda: os.startfile(path)).pack(side=tk.RIGHT, padx=4)
        ttk.Button(toolbar, text='关闭', command=win.destroy).pack(side=tk.RIGHT, padx=4)

        viewer = scrolledtext.ScrolledText(
            win,
            wrap=tk.WORD,
            font=('Microsoft YaHei UI', 10),
            padx=12,
            pady=10,
        )
        viewer.pack(fill=tk.BOTH, expand=True, padx=10, pady=(4, 10))
        viewer.insert('1.0', text_value)
        viewer.configure(state=tk.DISABLED)

    def open_project_directory(self):
        try:
            os.startfile(PROJECT_DIR)
        except Exception as exc:
            messagebox.showerror('打开失败', f'无法打开项目目录：\n{exc}', parent=self.root)

    def open_migration_tool(self):
        try:
            import subprocess
            migrate_script = PROJECT_DIR / "migrate_from_old_version.py"
            if not migrate_script.exists():
                messagebox.showerror('未找到工具', f'未找到数据迁移脚本：\n{migrate_script}', parent=self.root)
                return
            if messagebox.askyesno(
                '从旧版本系统迁移数据',
                '即将启动旧版本数据迁移向导。\n\n'
                '说明：\n'
                '1. 迁移工具将把旧版系统中的【历史数据库、学生名册、标准答案、试卷模板与API Key】安全导入到当前系统；\n'
                '2. 迁移过程对旧版本文件【完全只读】，绝不修改、删除旧版本的任何数据。\n\n'
                '是否立即启动迁移向导？',
                parent=self.root
            ):
                cmd = [sys.executable, str(migrate_script)]
                creation_flags = 0
                if os.name == 'nt':
                    creation_flags = getattr(subprocess, 'CREATE_NEW_CONSOLE', 0x00000010)
                subprocess.Popen(cmd, cwd=str(PROJECT_DIR.parent), creationflags=creation_flags)
        except Exception as exc:
            messagebox.showerror('启动失败', f'无法启动迁移工具：\n{exc}', parent=self.root)

    def action_export_data_package(self):
        try:
            from tkinter import filedialog
            from core.data_backup_manager import export_data_package
            ts = datetime.now().strftime("%Y%m%d_%H%M%S")
            default_name = f"答题批改系统_业务数据备份_{ts}.zip"
            save_path = filedialog.asksaveasfilename(
                title="导出全量业务数据备份包",
                defaultextension=".zip",
                filetypes=[("ZIP 数据备份包", "*.zip")],
                initialfile=default_name,
                parent=self.root
            )
            if not save_path:
                return

            manifest = export_data_package(save_path, PROJECT_DIR)
            db_s = manifest.get("db_stats", {})
            messagebox.showinfo(
                "导出成功",
                f"全量业务数据已成功打包导出！\n\n"
                f"保存位置：\n{save_path}\n\n"
                f"数据包大小：{manifest.get('package_size_mb', 0)} MB\n"
                f"包含数据：\n"
                f" - 核心测试记录：{db_s.get('sessions', 0)} 场测试，{db_s.get('results', 0)} 条成绩\n"
                f" - 学生名册班级：{manifest.get('classes_count', 0)} 个班级\n"
                f" - 标准答案方案：{manifest.get('answer_keys_count', 0)} 套\n"
                f" - 试卷自定义模板：{manifest.get('templates_count', 0)} 个\n\n"
                f"提示：此数据包可在任意新版或异机中一键导入，也可随时备份至 U 盘或网盘。",
                parent=self.root
            )
        except Exception as exc:
            messagebox.showerror("导出失败", f"导出数据包时发生异常：\n{exc}", parent=self.root)

    def action_import_data_package(self):
        try:
            from tkinter import filedialog
            from core.data_backup_manager import inspect_data_package, import_data_package
            open_path = filedialog.askopenfilename(
                title="选择要导入的业务数据备份包 (*.zip)",
                filetypes=[("ZIP 数据备份包", "*.zip"), ("所有文件", "*.*")],
                parent=self.root
            )
            if not open_path:
                return

            info = inspect_data_package(open_path)
            if not info.get("valid"):
                messagebox.showerror(
                    "无效备份包",
                    f"所选文件不是有效的答题系统业务数据备份包：\n{open_path}\n\n"
                    "提示：请选择由本系统导出的 *.zip 数据包。",
                    parent=self.root
                )
                return

            confirm = messagebox.askyesno(
                "确认导入数据包",
                f"检测到备份包信息如下：\n\n"
                f"创建时间：{info.get('created_at', '未知')}\n"
                f"包体大小：{info.get('size_mb', 0)} MB\n"
                f"历史测试：{info.get('sessions', 0)} 场，{info.get('results', 0)} 条成绩\n"
                f"班级名册：{info.get('classes_count', 0)} 个班级\n"
                f"标准答案：{info.get('answer_keys_count', 0)} 套\n\n"
                f"【安全保障】：导入前系统会自动为当前系统的数据创建一份本地安全快照。\n\n"
                f"是否确认将此备份包导入到当前系统中？",
                parent=self.root
            )
            if not confirm:
                return

            logs = import_data_package(open_path, PROJECT_DIR)

            # 刷新系统状态
            try:
                self.init_database()
            except Exception:
                pass
            try:
                self.load_classes()
            except Exception:
                pass

            log_summary = "\n".join(logs[:8])
            if len(logs) > 8:
                log_summary += f"\n...等共 {len(logs)} 项同步操作"

            messagebox.showinfo(
                "导入成功",
                f"数据备份包已成功导入并刷新！\n\n"
                f"{log_summary}\n\n"
                f"现在您可以直接在系统中查看所有历史测试与学生数据。",
                parent=self.root
            )
        except Exception as exc:
            messagebox.showerror("导入失败", f"导入数据包时发生异常：\n{exc}", parent=self.root)

    def begin_automation_run(self, name):
        """Acquire the shared one-click workflow lock."""
        name = str(name or '自动任务').strip()
        if any(win.winfo_exists() for win in getattr(self, '_context_windows', [])):
            self.context_change_allowed()
            return False
        if getattr(self, '_automation_running', False):
            active_name = str(getattr(self, '_automation_name', '') or '自动任务')
            if hasattr(self, 'status_var'):
                self.status_var.set(f'{active_name}正在执行，本次重复点击未启动。')
            try:
                self.root.bell()
            except Exception:
                pass
            return False

        self._automation_running = True
        self._automation_name = name
        for attr_name in ('auto_setup_grade_button', 'auto_ocr_upload_button'):
            button = getattr(self, attr_name, None)
            if button is not None:
                try:
                    button.configure(state=tk.DISABLED)
                except Exception:
                    pass
        return True

    def context_change_allowed(self, ignore_answer_window=False):
        """Keep open grading/preview windows attached to their original test."""
        windows = [win for win in getattr(self, '_context_windows', []) if win.winfo_exists()]
        self._context_windows = windows
        blocking_windows = [win for win in windows
                            if not (ignore_answer_window and win is getattr(self, 'answer_key_window', None))]
        if getattr(self, '_automation_running', False) or blocking_windows:
            messagebox.showwarning('当前任务尚未结束',
                                   '请先结束批改任务并关闭主观题/整卡预览窗口，再切换测试、文件夹或答案方案。',
                                   parent=self.root)
            return False
        return True

    def track_context_window(self, window):
        self._context_windows = [win for win in getattr(self, '_context_windows', []) if win.winfo_exists()]
        self._context_windows.append(window)

    def score_context_identity(self):
        return (str((self.current_session or {}).get('id') or ''),
                self.current_template_key, self.subjective_answer_signature(),
                self.subjective_structure_signature())

    def result_context_signature(self):
        value = {'template': self.current_template_key,
                 'answers': {str(key): value for key, value in self.extract_answer_map().items()},
                 'zones': (self.answer_config or {}).get('zones', []),
                 'structure': self.subjective_structure_signature()}
        return hashlib.sha256(json.dumps(value, ensure_ascii=False, sort_keys=True,
                                         default=str).encode('utf-8')).hexdigest()

    def validate_overlay_context(self):
        if getattr(self, '_session_requires_structure', False):
            raise ValueError('当前测试缺少自己的试卷结构，请明确加载对应答案方案并重新批改后再导出。')
        self.validate_result_ownership(self.summary_data)
        current = self.result_context_signature()
        for entry in self.summary_data:
            source_signature = entry.get('_source_image_signature')
            if source_signature and source_signature != self.source_image_signature(entry):
                raise ValueError('原始扫描图已被替换或修改，请重新批改后再导出，避免旧成绩印到新试卷。')
            previous = entry.get('_result_context_signature') or getattr(self, '_loaded_results_signature', '')
            if previous and previous != current:
                raise ValueError('答案或试卷结构已改变，请重新批改后再生成标注，避免旧成绩套用新试卷。')

    def source_image_signature(self, entry):
        sources = []
        for value in [entry.get('input_path')] + list((entry.get('side_files') or {}).values()):
            if value:
                path = Path(value)
                stat = path.stat() if path.is_file() else None
                sources.append([str(path.resolve()), stat.st_size if stat else None,
                                stat.st_mtime_ns if stat else None])
        return hashlib.sha256(json.dumps(sorted(sources)).encode('utf-8')).hexdigest()

    def end_automation_run(self):
        """Release the workflow lock even after an exception or early return."""
        self._automation_running = False
        self._automation_name = ''
        for attr_name in ('auto_setup_grade_button', 'auto_ocr_upload_button'):
            button = getattr(self, attr_name, None)
            if button is not None:
                try:
                    button.configure(state=tk.NORMAL)
                except Exception:
                    pass

