    # ----------------------------
    # 模板
    # ----------------------------
    def refresh_template_registry(self):
        self.template_manifest = ensure_template_registry(PROJECT_DIR)
        self.template_entries = self.template_manifest.get('templates', {})
        self.template_display_to_key = {}
        self.template_display_names = []
        for key, entry in self.template_entries.items():
            if key == 'default':
                continue
            display = entry.get('display_name') or key
            self.template_display_to_key[display] = key
            self.template_display_names.append(display)
        return self.template_display_names

    def load_template_by_key(self, template_key):
        entry = self.template_entries.get(template_key)
        if not entry:
            raise RuntimeError(f'模板不存在：{template_key}')

        paths = resolve_template_paths(PROJECT_DIR, entry)
        self.current_template_paths = paths
        self.answer_config = json.loads(paths['answer_config'].read_text(encoding='utf-8'))
        self.student_config = (
            json.loads(paths['student_id_config'].read_text(encoding='utf-8'))
            if paths['student_id_config'].exists() else None
        )
        self.marker_config = json.loads(paths['marker_config'].read_text(encoding='utf-8'))
        subjective_value = entry.get('subjective_config') or ''
        subjective_path = PROJECT_DIR / subjective_value if subjective_value else PROJECT_DIR / '__missing__'
        self.subjective_config_path = subjective_path if subjective_path.exists() else None
        self.subjective_config = (
            json.loads(subjective_path.read_text(encoding='utf-8-sig'))
            if subjective_path.exists() else {}
        )
        self.current_template_key = template_key
        self._session_requires_structure = False
        self.current_template_entry = entry
        self.current_template_name = entry.get('display_name') or template_key
        self.current_template_mode = entry.get('mode', 'grader')
        self.available_zone_names = [zone.get('zone_name', f'zone{i + 1}') for i, zone in enumerate(self.answer_config.get('zones', []))]
        if self.is_direct_paper_choice_template():
            self.selected_zones = list(self.available_zone_names)
        else:
            self.selected_zones = self.available_zone_names[:1] if self.available_zone_names else []
        self.answer_key = {}
        self.loaded_answer_key = {}
        self.loaded_answer_key_scheme_path = None
        self.loaded_answer_key_scheme_name = ''
        self.knowledge_identity_payload = {}
        self.template_marker_points = self.get_template_marker_points()
        self.ensure_direct_subjective_crop_geometry_current()
        return entry

    def refresh_current_template_config_from_disk(self):
        """Reload the active template structure without clearing answers."""
        if self.current_session:
            # Session state is authoritative; shared files are the last opened paper.
            return True
        paths = getattr(self, 'current_template_paths', {}) or {}
        answer_path = paths.get('answer_config')
        marker_path = paths.get('marker_config')
        student_path = paths.get('student_id_config')
        if answer_path and Path(answer_path).exists():
            self.answer_config = json.loads(Path(answer_path).read_text(encoding='utf-8-sig'))
        if marker_path and Path(marker_path).exists():
            self.marker_config = json.loads(Path(marker_path).read_text(encoding='utf-8-sig'))
        if student_path and Path(student_path).exists():
            self.student_config = json.loads(Path(student_path).read_text(encoding='utf-8-sig'))

        entry = getattr(self, 'current_template_entry', {}) or {}
        subjective_value = entry.get('subjective_config') or ''
        subjective_path = PROJECT_DIR / subjective_value if subjective_value else None
        if subjective_path and subjective_path.exists():
            self.subjective_config_path = subjective_path
            self.subjective_config = json.loads(subjective_path.read_text(encoding='utf-8-sig'))
        else:
            self.subjective_config_path = None
            self.subjective_config = {}

        self.available_zone_names = [
            zone.get('zone_name', f'zone{i + 1}')
            for i, zone in enumerate((self.answer_config or {}).get('zones', []))
        ]
        if self.is_direct_paper_choice_template():
            self.selected_zones = list(self.available_zone_names)
        elif self.selected_zones:
            self.selected_zones = [zone for zone in self.selected_zones if zone in self.available_zone_names]
        else:
            self.selected_zones = self.available_zone_names[:1] if self.available_zone_names else []
        self.ensure_direct_subjective_crop_geometry_current()
        self.template_marker_points = self.get_template_marker_points()
        return True

    def ensure_direct_subjective_crop_geometry_current(self):
        """Regenerate direct-paper crop rectangles when crop margins change."""
        if not self.is_direct_paper_choice_template():
            return False
        current_version = int((getattr(self, 'subjective_config', {}) or {}).get('crop_geometry_version') or 0)
        if current_version >= DIRECT_SUBJECTIVE_CROP_GEOMETRY_VERSION:
            return False
        line_path = self.direct_subjective_line_config_path()
        if not line_path.exists():
            return False
        try:
            line_config = json.loads(line_path.read_text(encoding='utf-8-sig'))
            return bool(self.sync_direct_subjective_lines_to_subjective_config(line_config))
        except Exception:
            return False

    def is_direct_paper_choice_template(self):
        mode = str((getattr(self, 'answer_config', {}) or {}).get('mode', ''))
        entry = getattr(self, 'current_template_entry', {}) or {}
        return bool(
            entry.get('direct_paper_choice')
            or mode.startswith('direct_paper_choice')
            or str(getattr(self, 'current_template_key', '') or '').startswith('direct_paper_choice')
        )

    def set_packed_visible(self, widget, visible, pack_options=None):
        """Show only actions that make sense for the active template."""
        if widget is None:
            return
        pack_options = pack_options or {'side': tk.LEFT, 'padx': (0, 4)}
        try:
            widget.pack_info()
            is_packed = True
        except tk.TclError:
            is_packed = False
        if visible and not is_packed:
            widget.pack(**pack_options)
        elif not visible and is_packed:
            widget.pack_forget()

    def direct_paper_has_back_side(self):
        if not self.is_direct_paper_choice_template():
            return False
        calculation_region = (getattr(self, 'subjective_config', {}) or {}).get('direct_calculation_region') or {}
        if isinstance(calculation_region, dict) and calculation_region.get('enabled') and calculation_region.get('rect'):
            return True
        for zone in (getattr(self, 'answer_config', {}) or {}).get('zones', []) or []:
            if str(zone.get('side') or '').lower() == 'back':
                return True
        for item in (getattr(self, 'subjective_config', {}) or {}).get('items', []) or []:
            if str(item.get('side') or '').lower() == 'back':
                return True
            for blank in item.get('blanks', []) or []:
                if str(blank.get('side') or '').lower() == 'back':
                    return True
            for sub in item.get('subquestions', []) or []:
                if str(sub.get('side') or '').lower() == 'back':
                    return True
                for blank in sub.get('blanks', []) or []:
                    if str(blank.get('side') or '').lower() == 'back':
                        return True
        return False

    def direct_paper_has_calculation_structure(self):
        """Check whether the direct paper structure has back-page calculation enabled."""
        if not self.is_direct_paper_choice_template():
            return False
        subj_calc = (getattr(self, 'subjective_config', {}) or {}).get('direct_calculation_region')
        if isinstance(subj_calc, dict) and 'enabled' in subj_calc:
            if not subj_calc.get('enabled'):
                return False
            if bool(self.direct_calculation_region_config().get('enabled')):
                return True
        line_path = self.direct_subjective_line_config_path()
        if line_path.exists():
            try:
                line_config = json.loads(line_path.read_text(encoding='utf-8-sig'))
                sides = line_config.get('sides') if isinstance(line_config.get('sides'), dict) else {}
                back = sides.get('back') if isinstance(sides.get('back'), dict) else {}
                calc = back.get('calculation_region')
                if isinstance(calc, dict):
                    return bool(calc.get('enabled'))
            except Exception:
                pass
        region = self.direct_calculation_region_config()
        return bool(region.get('enabled'))

    def update_template_ui_state(self):
        mode_label = '阅卷模式' if self.current_template_mode == 'grader' else '采集模式'
        question_count = sum(len(zone.get('questions', [])) for zone in self.answer_config.get('zones', []))
        subjective_count = len(self.subjective_config.get('items', [])) if getattr(self, 'subjective_config', None) else 0
        direct_choice_enabled = self.is_direct_paper_choice_template()
        mixed_template_enabled = self.is_mixed_objective_subjective_template()
        mixed_single_side = self.mixed_template_single_side_mode_enabled()
        self.template_mode_var.set(f'模式：{mode_label}')
        extra = f' 主观{subjective_count}' if subjective_count else ''
        self.template_hint_var.set(f'题位{question_count}{extra}')
        if hasattr(self, 'answer_key_button'):
            self.answer_key_button.config(state=('normal' if self.current_template_mode == 'grader' else 'disabled'))
        if hasattr(self, 'auto_setup_grade_button'):
            self.auto_setup_grade_button.config(
                state=('normal' if direct_choice_enabled and self.current_template_mode == 'grader' else 'disabled')
            )
        subjective_tools_visible = bool(
            subjective_count
            and self.current_template_mode == 'grader'
            and (mixed_template_enabled or direct_choice_enabled)
        )
        if hasattr(self, 'subjective_crop_button'):
            self.set_packed_visible(self.subjective_crop_button, False)
            self.subjective_crop_button.config(state=('normal' if subjective_tools_visible else 'disabled'))
        if hasattr(self, 'subjective_grade_button'):
            self.set_packed_visible(self.subjective_grade_button, subjective_tools_visible)
            self.subjective_grade_button.config(state=('normal' if subjective_tools_visible else 'disabled'))
        if hasattr(self, 'auto_ocr_upload_button'):
            self.set_packed_visible(self.auto_ocr_upload_button, subjective_tools_visible)
            self.auto_ocr_upload_button.config(state=('normal' if subjective_tools_visible else 'disabled'))
        if hasattr(self, 'web_manual_upload_button'):
            self.set_packed_visible(self.web_manual_upload_button, subjective_tools_visible)
            self.web_manual_upload_button.config(state=('normal' if subjective_tools_visible else 'disabled'))
        if hasattr(self, 'web_manual_download_button'):
            self.set_packed_visible(self.web_manual_download_button, subjective_tools_visible)
            self.web_manual_download_button.config(state=('normal' if subjective_tools_visible else 'disabled'))
        if hasattr(self, 'web_manual_delete_button'):
            self.set_packed_visible(self.web_manual_delete_button, subjective_tools_visible)
            self.web_manual_delete_button.config(state=('normal' if subjective_tools_visible else 'disabled'))
        if hasattr(self, 'subjective_structure_button'):
            show_experiment_structure = bool(subjective_count and mixed_template_enabled)
            self.set_packed_visible(self.subjective_structure_button, show_experiment_structure, {'side': tk.LEFT, 'padx': (0, 4)})
            self.subjective_structure_button.config(state=('normal' if show_experiment_structure else 'disabled'))
        if hasattr(self, 'calculation_structure_button'):
            show_calculation_tools = bool(
                direct_choice_enabled
                or (mixed_template_enabled and not mixed_single_side)
            )
            # Direct-paper calculation settings belong to the answer scheme.
            # Keep the standalone editor only for the older mixed template.
            show_calculation_structure = bool(mixed_template_enabled and not mixed_single_side)
            self.set_packed_visible(self.calculation_structure_button, show_calculation_structure)
            calc_structure_state = 'normal' if show_calculation_structure else 'disabled'
            self.calculation_structure_button.config(state=calc_structure_state)
        if hasattr(self, 'calculation_score_button'):
            has_calc_questions = bool(self.calculation_question_config())
            show_calculation_score = bool(
                (mixed_template_enabled and not mixed_single_side)
                or (direct_choice_enabled and (has_calc_questions or self.direct_calculation_region_config()))
            )
            pack_opts = {'side': tk.LEFT, 'padx': (0, 8)}
            if hasattr(self, 'subjective_grade_button'):
                # 紧挨主观批改右侧展示
                self.calculation_score_button.pack_configure(**pack_opts)
            self.set_packed_visible(self.calculation_score_button, show_calculation_score, pack_opts)
            calc_score_state = 'normal' if show_calculation_score else 'disabled'
            self.calculation_score_button.config(state=calc_score_state)
        if hasattr(self, 'mixed_single_side_check'):
            self.set_packed_visible(self.mixed_single_side_check, mixed_template_enabled, {'side': tk.LEFT, 'padx': (0, 4)})
            self.mixed_single_side_check.config(state=('normal' if mixed_template_enabled else 'disabled'))
        if hasattr(self, 'direct_choice_structure_button'):
            direct_pack_options = {'side': tk.LEFT, 'padx': (0, 4)}
            if hasattr(self, 'subjective_grade_button'):
                direct_pack_options['before'] = self.subjective_grade_button
            self.set_packed_visible(self.direct_choice_structure_button, direct_choice_enabled, direct_pack_options)
            self.direct_choice_structure_button.config(state=('normal' if direct_choice_enabled else 'disabled'))
        if hasattr(self, 'direct_structure_preview_button'):
            preview_pack_options = {'side': tk.LEFT, 'padx': (0, 4)}
            if hasattr(self, 'subjective_grade_button'):
                preview_pack_options['before'] = self.subjective_grade_button
            self.set_packed_visible(self.direct_structure_preview_button, direct_choice_enabled, preview_pack_options)
            self.direct_structure_preview_button.config(state=('normal' if direct_choice_enabled else 'disabled'))
        if hasattr(self, 'direct_subjective_line_button'):
            self.set_packed_visible(self.direct_subjective_line_button, False)
            self.direct_subjective_line_button.config(state=('normal' if direct_choice_enabled else 'disabled'))
        if hasattr(self, 'template_box'):
            self.template_box.configure(values=self.template_display_names)
            self.template_var.set(self.current_template_name)
        if hasattr(self, 'selected_zones_var'):
            self.selected_zones_var.set('试卷正背面自动' if direct_choice_enabled else '手动设置')
        self.update_session_hint()

    def on_auto_latest_zone_changed(self):
        if hasattr(self, 'selected_zones_var'):
            self.selected_zones_var.set('试卷正背面自动' if self.is_direct_paper_choice_template() else '手动设置')
        self.save_ui_settings()

    def on_mixed_single_side_mode_changed(self):
        self.save_ui_settings()
        self.update_template_ui_state()
        if self.summary_data:
            self.apply_subjective_scores_to_entries()
            self.detail_text.delete(1.0, tk.END)
            for entry in self.summary_data:
                self.display_single_result(entry)
            self.update_summary_display()
            self.update_analysis_display()
            try:
                self.save_results_to_database()
            except Exception:
                pass
        if self.mixed_template_single_side_mode_enabled():
            self.status_var.set('已切换为混合模板单面模式：每张图片都按一名学生处理，不统计计算题。')
        else:
            self.status_var.set('已切换为混合模板双面模式：按正面+背面绑定计算题。')

    def on_template_selected(self, event=None):
        selected_display = self.template_var.get().strip()
        current_display = self.current_template_name
        if not selected_display or selected_display == current_display:
            return
        self.switch_template(template_display=selected_display)

    def switch_template(self, template_display=None):
        if not self.context_change_allowed():
            return
        template_display = (template_display or self.template_var.get() or '').strip()
        template_key = self.template_display_to_key.get(template_display)
        if not template_key:
            messagebox.showwarning('警告', '请先选择一个模板')
            return
        try:
            set_current_template(PROJECT_DIR, template_key)
            self.refresh_template_registry()
            self.load_template_by_key(template_key)
            self.clear_all()
            self.update_template_ui_state()
            self.status_var.set(f'已切换模板：{self.current_template_name}')
            messagebox.showinfo('成功', f'已切换到模板：{self.current_template_name}')
        except Exception as e:
            messagebox.showerror('切换失败', str(e))

    def get_answer_key_file_path(self, scheme_name):
        safe_name = re.sub(r'[\\/:*?"<>|]+', '_', (scheme_name or '').strip())
        safe_name = safe_name.strip(' .')
        if not safe_name:
            raise ValueError('方案名称不能为空')
        ANSWER_KEYS_DIR.mkdir(parents=True, exist_ok=True)
        return ANSWER_KEYS_DIR / f'{self.current_template_key}__{safe_name}.json'

    def normalize_knowledge_identity_payload(self, payload):
        if not isinstance(payload, dict):
            return {}
        raw_rows = payload.get('rows') or []
        if not isinstance(raw_rows, list):
            return {}
        columns = [str(column or '').strip() for column in (payload.get('columns') or []) if str(column or '').strip()]
        rows = []
        seen = set()
        for raw_row in raw_rows:
            if not isinstance(raw_row, dict):
                continue
            row = {str(key or '').strip(): str(value or '').strip() for key, value in raw_row.items()}
            question_no = row.get('题号', '')
            knowledge_code = row.get('知识点编号', '')
            if not question_no or not knowledge_code:
                continue
            signature = tuple(sorted(row.items()))
            if signature in seen:
                continue
            seen.add(signature)
            rows.append(row)
            for key in row:
                if key and key not in columns:
                    columns.append(key)
        if not rows:
            return {}
        for required in ('题号', '知识点编号'):
            if required not in columns:
                columns.append(required)
        return {
            'version': 1,
            'columns': columns,
            'rows': rows,
            'source_name': str(payload.get('source_name') or '').strip(),
            'imported_at': str(payload.get('imported_at') or '').strip(),
        }

    def read_knowledge_identity_csv(self, path):
        path = Path(path)
        last_error = None
        for encoding in ('utf-8-sig', 'gb18030'):
            try:
                with path.open('r', encoding=encoding, newline='') as handle:
                    reader = csv.DictReader(handle)
                    columns = [str(column or '').strip() for column in (reader.fieldnames or [])]
                    if not all(required in columns for required in ('题号', '知识点编号')):
                        raise ValueError('CSV必须包含“题号”和“知识点编号”两列。')
                    rows = [
                        {str(key or '').strip(): str(value or '').strip() for key, value in row.items()}
                        for row in reader
                    ]
                payload = self.normalize_knowledge_identity_payload({
                    'columns': columns,
                    'rows': rows,
                    'source_name': path.name,
                    'imported_at': datetime.now().isoformat(timespec='seconds'),
                })
                if not payload:
                    raise ValueError('CSV中没有有效的“题号-知识点编号”记录。')
                return payload
            except UnicodeDecodeError as exc:
                last_error = exc
                continue
            except Exception:
                raise
        raise last_error or ValueError('无法读取知识点清单CSV。')

    def find_folder_answer_template_files(self, folder_path=None):
        """Locate the conventional Word answer template and knowledge CSV."""
        folder = Path(folder_path or self.selected_folder_path or '')
        if not folder.exists() or not folder.is_dir():
            raise ValueError('请先选择包含试卷文件的文件夹。')
        all_docx = [
            path for path in folder.glob('*.docx')
            if not path.name.startswith('~$') and '错题本' not in path.stem
        ]
        if not all_docx:
            raise ValueError('当前文件夹没有找到任何 Word (*.docx) 试卷或参考答案文件。')

        def docx_score(p):
            stem = p.stem
            score = 0
            if any(kw in stem for kw in ('compact_print', '透打', '打印辅助', '讲评')):
                score -= 500
            if '套用模板' in stem or '套模板' in stem:
                score += 1000
                if any(kw in stem for kw in ('删除', '修改', '编辑', '最终', '改')):
                    score += 50
            elif '模板' in stem:
                score += 100
            elif '答案' in stem:
                score += 60
            elif '试卷' in stem:
                score += 50
            elif '题' in stem:
                score += 30
            return (score, p.stat().st_mtime)

        all_docx.sort(key=docx_score, reverse=True)
        word_candidates = all_docx

        csv_candidates = [
            path for path in folder.glob('*.csv')
            if not path.name.startswith('~$')
        ]
        csv_candidates.sort(
            key=lambda path: ('知识点' in path.stem, path.stat().st_mtime),
            reverse=True,
        )
        return {'folder': folder, 'word': word_candidates[0], 'csv': csv_candidates[0] if csv_candidates else None}

    def parse_word_calculation_scores(self, lines):
        """Convert Word reference marks such as ``18.(1)2(2)2`` or ``15. (1)解... (2)解...`` to 15: 2, 2, 2."""
        circle_map = {
            '①': ' (1) ', '②': ' (2) ', '③': ' (3) ', '④': ' (4) ', '⑤': ' (5) ',
            '⑥': ' (6) ', '⑦': ' (7) ', '⑧': ' (8) ', '⑨': ' (9) ', '⑩': ' (10) '
        }
        full_text = ''
        for raw_line in lines or []:
            raw = str(raw_line or '')
            for c, r in circle_map.items():
                raw = raw.replace(c, r)
            full_text += '\n' + raw
        full_text = unicodedata.normalize('NFKC', full_text)

        # 1. First, check single-sub lines like: 16(1): 4, 16(2): 6
        single_sub_matches = re.findall(
            r'^\s*(?:第)?\s*(\d{1,3})\s*(?:题)?\s*(?:[（(\-_.]\s*([1-9]\d*)\s*[）)]?|第\s*([1-9]\d*)\s*(?:小题|题)?)\s*[:：=＝.]?\s*([+-]?\d+(?:\.\d+)?)\s*(?:分)?\s*$',
            full_text,
            re.M,
        )
        if single_sub_matches:
            q_map = defaultdict(list)
            for qno, sno1, sno2, sc in single_sub_matches:
                q_map[int(qno)].append((int(sno1 or sno2), float(sc)))
            if q_map:
                res = []
                for q, subs in sorted(q_map.items()):
                    subs.sort(key=lambda x: x[0])
                    res.append(f'{q}: ' + ', '.join(f'{sc:g}' for _, sc in subs))
                return '\n'.join(res)

        # 2. Split by question blocks: e.g. 15. or 第15题: or 10(1)
        blocks = re.split(r'(?m)^\s*(?:第)?\s*(\d{1,3})\s*(?:题)?\s*(?:[.．、:：]\s*|(?=[（(]))', full_text)
        questions_map = {}
        if len(blocks) >= 3:
            for i in range(1, len(blocks), 2):
                qno = int(blocks[i])
                q_text = blocks[i + 1]
                questions_map[qno] = q_text

        results = []
        for qno, text in sorted(questions_map.items()):
            # Check if first line is comma/space/plus-separated numbers: e.g. '2, 2, 2' or '4分, 6分' or '4+6'
            first_line = text.strip().splitlines()[0] if text.strip() else ''
            first_cleaned = re.sub(r'(?<=\d)\s*分', '', first_line).strip()
            comma_parts = [v for v in re.split(r'[,，、;；/+\s]+', first_cleaned) if v]
            all_numeric = True
            scores = []
            if comma_parts:
                for part in comma_parts:
                    try:
                        scores.append(float(part))
                    except ValueError:
                        all_numeric = False
                        break
            if all_numeric and scores:
                results.append(f'{qno}: ' + ', '.join(f'{s:g}' for s in scores))
                continue

            # Check explicit sub scores: (1) 2分 (2) 2分 or (1) 2 (2) 2
            explicit_matches = re.findall(
                r'[（(]\s*([1-9]\d*)\s*[）)]\s*[:：=＝.]?\s*([+-]?\d+(?:\.\d+)?)\s*(?:分)?(?!\s*[a-zA-Z/])',
                text,
            )
            if explicit_matches:
                sub_scores = [float(sc) for _sno, sc in explicit_matches]
                results.append(f'{qno}: ' + ', '.join(f'{s:g}' for s in sub_scores))
                continue

            # Check subquestion markers without explicit score numbers: (1)解... (2)解... or (1)(2)(3)(4)
            plain_subs = re.findall(r'[（(]\s*([1-9]\d*)\s*[）)]', text)
            if plain_subs:
                unique_subs = []
                for s in plain_subs:
                    s_int = int(s)
                    if s_int not in unique_subs:
                        unique_subs.append(s_int)
                unique_subs.sort()
                if unique_subs:
                    default_scores = [2.0] * len(unique_subs)
                    results.append(f'{qno}: ' + ', '.join(f'{s:g}' for s in default_scores))
                    continue

        return '\n'.join(results)

    @staticmethod
    def extract_paragraph_full_text(paragraph):
        """Extract text from a docx Paragraph including regular runs and Office Math (m:oMath) formulas."""
        if not hasattr(paragraph, '_p'):
            return str(getattr(paragraph, 'text', '') or '').strip()
        texts = []
        for elem in paragraph._p.iter():
            tag = elem.tag.split('}')[-1] if '}' in elem.tag else elem.tag
            if tag == 't':
                texts.append(elem.text or '')
            elif tag == 'tab':
                texts.append('\t')
            elif tag in ('br', 'cr'):
                texts.append('\n')
        full = ''.join(texts).strip()
        return full or str(paragraph.text or '').strip()

    def read_word_answer_template(self, path):
        """Read the answer and calculation sections from a teacher Word template."""
        try:
            from docx import Document
        except Exception as exc:
            raise RuntimeError(f'读取 Word 模板需要 python-docx：{exc}')
        path = Path(path)
        try:
            document = Document(path)
        except Exception as exc:
            raise RuntimeError(f'无法读取 Word 模板：{exc}')
        paragraphs = [self.extract_paragraph_full_text(paragraph) for paragraph in document.paragraphs]
        reference_index = next(
            (index for index, text in enumerate(paragraphs) if '参考答案' in text),
            None,
        )
        if reference_index is None:
            raise ValueError('Word 模板中没有找到“参考答案”标题。')
        calculation_index = next(
            (
                index for index in range(reference_index + 1, len(paragraphs))
                if '计算题' in paragraphs[index]
            ),
            None,
        )
        if calculation_index is None:
            # Calculation questions are optional. When the heading is absent,
            # the reference-answer section simply continues to the end of Word.
            answer_lines = [text for text in paragraphs[reference_index + 1:] if text]
            calculation_lines = []
        else:
            answer_lines = [text for text in paragraphs[reference_index + 1:calculation_index] if text]
            calculation_lines = [text for text in paragraphs[calculation_index + 1:] if text]
        if not answer_lines:
            raise ValueError('“参考答案”标题后没有可导入的答案内容。')

        # 尝试从“参考答案”前面的题目题干中自动提取选填题限定备选词
        q_candidates = self.extract_candidate_words_from_question_paragraphs(paragraphs[:reference_index])
        if q_candidates:
            enriched_lines = []
            current_ans_q = None
            for para in answer_lines:
                lines = [l.strip() for l in str(para or '').splitlines() if l.strip()]
                for line in lines:
                    q_match = re.match(r'^(?:第\s*)?(\d+)\s*[.．、:：]\s*(?:[（(]\s*(\d+)\s*[）)])?', line)
                    sub_match = re.match(r'^[（(]\s*(\d+)\s*[）)]', line)
                    if q_match:
                        current_ans_q = int(q_match.group(1))
                        sub = q_match.group(2)
                        key = f"{current_ans_q}({sub})" if sub else str(current_ans_q)
                    elif sub_match and current_ans_q:
                        sub = sub_match.group(1)
                        key = f"{current_ans_q}({sub})"
                    else:
                        key = str(current_ans_q) if current_ans_q else None
                    cand_entry = q_candidates.get(key)
                    if cand_entry and not any(mark in line for mark in ('选填', '[', '【')):
                        cands = cand_entry if isinstance(cand_entry, list) else [cand_entry]
                        # 按分号或逗号拆分答案段落进行智能关联（哪怕只有1组候选词，也需智能对位到对应的空，杜绝末尾错位追加）
                        sub_parts = re.split(r'([;；,，]+)', line)
                        if len(sub_parts) == 1 and len(cands) == 1:
                            c_opts = [o.strip() for o in re.split(r'[/／|或]+', cands[0]) if o.strip()]
                            if any(o in line or line in o for o in c_opts):
                                enriched_lines.append(f"{line} (选填: {cands[0]})")
                            else:
                                enriched_lines.append(line)
                        else:
                            mapped_parts = []
                            cand_pool = list(cands)
                            for sp in sub_parts:
                                if re.match(r'^[;；,，]+$', sp):
                                    mapped_parts.append(sp)
                                    continue
                                sp_clean = sp.strip()
                                matched_cand = None
                                for c in cand_pool:
                                    c_opts = [o.strip() for o in re.split(r'[/／|或]+', c) if o.strip()]
                                    if any(o in sp_clean or sp_clean in o for o in c_opts):
                                        matched_cand = c
                                        break
                                if matched_cand:
                                    cand_pool.remove(matched_cand)
                                    mapped_parts.append(f"{sp} (选填: {matched_cand})")
                                else:
                                    mapped_parts.append(sp)
                            enriched_lines.append(''.join(mapped_parts))
                    else:
                        enriched_lines.append(line)
            answer_lines = enriched_lines

        return {
            'answer_text': '\n'.join(answer_lines),
            'calculation_text': self.parse_word_calculation_scores(calculation_lines),
            'calculation_source_text': '\n'.join(calculation_lines),
            'source_name': path.name,
        }

    def extract_candidate_words_from_question_paragraphs(self, paragraphs):
        """从Word题干段落中自动提取选填题限定备选词（识别横线后跟有的‘（’选填空位，支持一题多空）"""
        q_candidates = {}
        current_q = None
        for p in paragraphs or []:
            p = unicodedata.normalize('NFKC', str(p or '')).strip()
            if not p:
                continue
            q_match = re.match(r'^(?:第\s*)?(\d+)\s*[.．、:：]\s*(?:[（(]\s*(\d+)\s*[）)])?', p)
            sub_match = re.match(r'^[（(]\s*(\d+)\s*[）)]', p)
            if q_match:
                current_q = int(q_match.group(1))
                sub = q_match.group(2)
                key = f"{current_q}({sub})" if sub else str(current_q)
            elif sub_match and current_q:
                sub = sub_match.group(1)
                key = f"{current_q}({sub})"
            else:
                key = str(current_q) if current_q else None

            # 匹配横线/空位后紧跟的“（”，以及明确的选填/或括号
            patterns = [
                re.compile(r'(?:[_—–]{1,}|\(\s*\)|（\s*）|\s{2,})\s*[(（]\s*([^()（）]+?)\s*[)）]'),
                re.compile(r'[(（]\s*(?:选填|请选填|选择|备选)[：:]?\s*([^()（）]+?)\s*[)）]'),
                re.compile(r'[(（]\s*([^\s()（）]+?(?:\s*或\s*|[/／、])[^\s()（）]+?)\s*[)）]'),
            ]
            found_candidates = []
            seen_spans = set()
            for pat in patterns:
                for m in pat.finditer(p):
                    span = m.span()
                    if any(s[0] <= span[0] and span[1] <= s[1] for s in seen_spans):
                        continue
                    inner = m.group(1).strip()
                    inner_clean = re.sub(r'^(?:[前后上下第\d一二三四五六七八九十两\s]*空)?(?:选填|请选填|选择|备选)[：:]?\s*', '', inner)
                    inner_clean = re.sub(r'["\'“”‘’`]', ' ', inner_clean)
                    raw_parts = [w.strip() for w in re.split(r'[/／,，、|\s]+|(?:\s*或\s*)', inner_clean) if w.strip()]
                    parts = [w for w in raw_parts if not re.search(r'(?:[前后上下第\d一二三四五六七八九十两\s]*空)?(?:选填|备选|选择)', w)]
                    unique = []
                    for w in parts:
                        if w not in unique:
                            unique.append(w)
                    if len(unique) >= 2:
                        seen_spans.add(span)
                        found_candidates.append({
                            'span': span,
                            'options_str': '/'.join(unique)
                        })
            found_candidates.sort(key=lambda x: x['span'][0])
            if key and found_candidates:
                if key not in q_candidates:
                    q_candidates[key] = []
                for c in found_candidates:
                    q_candidates[key].append(c['options_str'])
        return q_candidates

    def derive_wrong_answers_and_keywords(self, correct_answer, candidate_words):
        """
        根据正确答案和候选词（从Word题干或答案括号中提取），
        自动推导常见错误答案，并将错误答案拆字后填入错误答案关键词，
        同时严格过滤掉与正确答案相关的字符（防止误伤学生正确作答）。
        """
        if isinstance(candidate_words, str):
            raw_candidates = [w.strip() for w in re.split(r'[/／,，、|\s]+|(?:\s*或\s*)', candidate_words) if w.strip()]
        else:
            raw_candidates = [str(w).strip() for w in candidate_words if str(w).strip()]
        norm_correct_list = [c.strip() for c in re.split(r'[,，;；/|]+', str(correct_answer or '')) if c.strip()]
        if not norm_correct_list or not raw_candidates:
            return '', ''
        correct_chars = set()
        for ans in norm_correct_list:
            for ch in ans:
                if ch.strip() and ch not in ' ,，;；/|()（）[]【】"\'“”‘’':
                    correct_chars.add(ch)
        wrong_answers = []
        for cand in raw_candidates:
            if cand not in norm_correct_list and not any(cand == c for c in norm_correct_list):
                if cand not in wrong_answers:
                    wrong_answers.append(cand)
        if not wrong_answers:
            wrong_answers = [cand for cand in raw_candidates if cand not in norm_correct_list]
        wrong_keywords = []
        for w in wrong_answers:
            for ch in w:
                if ch.strip() and ch not in ' ,，;；/|()（）[]【】"\'“”‘’':
                    if ch not in correct_chars and ch not in wrong_keywords:
                        wrong_keywords.append(ch)
        return ','.join(wrong_answers), ','.join(wrong_keywords)

    def is_dedicated_physics_terminology(self, text):
        """
        判断一个词或字符是否属于客观唯一的学科专有名词/单字符号（自动勾选唯一答案）。
        """
        clean = re.sub(r'[\s\u3000\.,!?;:，。！？；：、_—\(\)（）\-\+]+', '', str(text or ''))
        if not clean or clean == '作图':
            return False
        # 单字客观答案（如 甲, 乙, 丙, 丁, A, B, C, D, S, N 等）
        if len(clean) == 1:
            return True
        terms = {
            # 光学与声学
            '凸透镜', '凹透镜', '平面镜', '凹面镜', '凸面镜', '实像', '虚像', '放大', '缩小', '等大',
            '正立', '倒立', '会聚', '发散', '可逆', '频率', '振幅', '音调', '响度', '音色',
            '超声波', '次声波', '电磁波', '漫反射', '镜面反射', '折射', '反射', '照相机', '投影仪', '放大镜',
            '入射角', '反射角', '折射角', '法线', '光心', '焦点', '焦距', '物距', '像距', '实线', '虚线',
            # 物态变化与热学
            '熔化', '凝固', '汽化', '液化', '升华', '凝华', '晶体', '非晶体', '沸腾', '蒸发',
            '固态', '液态', '气态', '固液共存', '比热容', '热值', '内能', '热传递', '做功',
            # 力学与运动
            '重力', '弹力', '摩擦力', '静摩擦力', '滑动摩擦力', '滚动摩擦力', '浮力', '压力', '压强',
            '大气压强', '惯性', '加速度', '质量', '密度', '省力', '费力', '等臂', '省距离', '费距离',
            '支点', '动力臂', '阻力臂', '漂浮', '悬浮', '下沉', '沉底', '上浮', '机械能', '动能',
            '重力势能', '弹性势能', '功率', '机械效率', '匀速直线运动',
            # 电学与磁学
            '串联', '并联', '混联', '通路', '断路', '开路', '短路', '电源', '正极', '负极',
            '导体', '绝缘体', '半导体', '超导体', '电压表', '电流表', '滑动变阻器', '电阻',
            '欧姆定律', '焦耳定律', '磁极', '南极', '北极', '地磁场', '电磁铁', '磁感线',
            '电磁感应', '感应电流', '吸引', '排斥', '同名', '异名', '正电荷', '负电荷',
        }
        for sub in re.split(r'[,，;；/|]+', clean):
            if sub in terms:
                return True
        return False

    def extract_candidate_words_from_answer_text(self, raw_text):
        """
        从单空答案文本中解构标准答案与限定备选词：
        - '运动 (选填: 运动/静止)' -> ('运动', '运动/静止')
        - '加速 [加速/减速/匀速]' -> ('加速', '加速/减速/匀速')
        - '时间 (选填“路程”或“时间”)' -> ('时间', '路程/时间')
        - '增大/变大' -> ('增大/变大', '')
        """
        text = str(raw_text or '').strip()
        pattern = re.compile(r'[\(（\[【]([^\(\)（）\[\]【】]+?)[\)）\]】]\s*$')
        match = pattern.search(text)
        if match:
            inner = match.group(1).strip()
            is_explicit = bool(re.search(r'^(?:选填|请选填|选择|备选)', inner))
            inner_clean = re.sub(r'^(?:选填|请选填|选择|备选)[：:]?\s*', '', inner)
            inner_clean = re.sub(r'["\'“”‘’`]', ' ', inner_clean)
            parts = [w.strip() for w in re.split(r'[/,，、|\s]+|(?:\s*或\s*)', inner_clean) if w.strip()]
            unique = []
            for w in parts:
                if w not in unique:
                    unique.append(w)
            if len(unique) >= 2 and (is_explicit or any(sep in inner for sep in ('/', '或', '、', '|'))):
                clean_ans = text[:match.start()].strip(' ：:，,；;。.')
                return clean_ans, '/'.join(unique)
        return text, ''

    def split_by_delimiters_outside_brackets(self, text, delimiters=',，;；、|'):
        """按分隔符切分字符串，但严格忽略括号 ( ) （ ） [ ] 【 】 内的分隔符"""
        parts = []
        current = []
        depth = 0
        for char in str(text or ''):
            if char in '([（【':
                depth += 1
                current.append(char)
            elif char in ')]）】':
                if depth > 0:
                    depth -= 1
                current.append(char)
            elif depth == 0 and char in delimiters:
                part = ''.join(current).strip(' ：:，,；;。.')
                if part:
                    parts.append(part)
                current = []
            else:
                current.append(char)
        last = ''.join(current).strip(' ：:，,；;。.')
        if last:
            parts.append(last)
        return parts

    def auto_configure_direct_paper_structure(self, pair, enable_calculation=False, choice_question_numbers=None):
        """Build a fresh direct-paper structure from the coloured template pair.

        This is the non-interactive counterpart of the paired structure editor.
        It deliberately stops on an incomplete colour template instead of silently
        retaining an older paper's structure.
        """
        pages = {}
        for side in ('front', 'back'):
            path = Path((pair or {}).get(side) or '')
            if not path.exists():
                raise ValueError(f'缺少{ "正面" if side == "front" else "背面" }模板图。')
            try:
                boxes = self.detect_direct_choice_boxes_from_red_template(
                    path,
                    include_top=(side == 'back'),
                )
            except Exception:
                boxes = []
            try:
                lines, _rejected = self.detect_direct_subjective_lines_from_red_template(path, side=side)
            except Exception:
                lines = []
            if not boxes and not lines:
                if side == 'back' and (pages.get('front', {}).get('boxes') or pages.get('front', {}).get('lines') or enable_calculation):
                    pass
                else:
                    side_name = '正面' if side == 'front' else '背面'
                    raise ValueError(
                        f'{side_name}没有识别到红色选择框、红色横线或蓝色作图框。'
                        '请确认文件夹开头两张图片是彩色结构模板，而不是黑白学生卷。'
                    )
            with Image.open(path) as image:
                pages[side] = {
                    'path': path,
                    'boxes': boxes,
                    'lines': lines,
                    'image_size': image.size,
                }

        box_count = sum(len(pages[side]['boxes']) for side in ('front', 'back'))
        if not box_count:
            raise ValueError('两张模板都没有识别到选择题小框，不能自动生成选择题结构。')
        if box_count % 4:
            raise ValueError(
                f'识别到 {box_count} 个选择题小框，不能按每题 4 个选项自动分题。'
                '请改用“正反面结构”手动删除误抓框后再批改。'
            )

        # This is a new paper setup. Clearing both sides prevents old pages from
        # being mixed into the current structure when a side happens to have no boxes.
        self.clear_direct_paper_side_structure('front')
        self.clear_direct_paper_side_structure('back')

        questions_by_side, _ = self.build_direct_choice_questions_from_continuous_boxes([
            (side, pages[side]['boxes']) for side in ('front', 'back')
        ], choice_question_numbers=choice_question_numbers)
        for side in ('front', 'back'):
            # Saving an empty side is intentional: it records the page markers and
            # keeps front/back pairing active even when that side has no choices.
            self.save_direct_choice_structure(
                pages[side]['path'], questions_by_side.get(side) or [], side=side
            )

        for side in ('front', 'back'):
            kept_lines = []
            for position, item in enumerate(pages[side]['lines'], 1):
                cloned = copy.deepcopy(item)
                cloned['index'] = position
                kept_lines.append(cloned)
            calculation_region = None
            if side == 'back':
                calculation_region = {'enabled': False}
                if enable_calculation:
                    calculation_region = self.build_direct_calculation_region(
                        kept_lines,
                        pages[side]['image_size'][0],
                        pages[side]['image_size'][1],
                        boxes=pages[side]['boxes'],
                    )
            self.save_direct_subjective_line_structure_with_labels(
                pages[side]['path'], kept_lines, side=side,
                labels_by_index=None, calculation_region=calculation_region,
            )

        sync_info = self.ensure_answer_scheme_matches_current_structure(persist=False)
        return {
            'choice_boxes': box_count,
            'choice_questions': box_count // 4,
            'subjective_lines': sum(len(pages[side]['lines']) for side in ('front', 'back')),
            'sync_info': sync_info,
        }

    def auto_apply_bulk_answer_text(self, text):
        """Strictly apply one pasted answer text without relying on the settings UI."""
        raw_text = str(text or '').strip()
        if not raw_text:
            raise ValueError('Word 模板的“参考答案”标题后没有可导入的答案。')

        diagnostics = {}
        if self.is_direct_paper_choice_template():
            self.sync_direct_paper_choice_questions_from_answer_text(raw_text)
        answer_map, _subjective_values = self.parse_bulk_answer_text(raw_text, diagnostics=diagnostics)
        # The first parse determines the labels of direct-paper answer lines.
        # Parse once more after synchronising so values use the final part IDs.
        self.sync_direct_paper_subjective_labels_from_answer_text(raw_text)
        diagnostics = {}
        answer_map, subjective_values = self.parse_bulk_answer_text(raw_text, diagnostics=diagnostics)

        expected_objective = set(self.current_objective_question_numbers())
        parsed_objective = set(answer_map)
        parts = list(self.iter_subjective_parts())
        fillable_parts = [part for part in parts if part.get('kind') != 'drawing']
        fillable_ids = {str(part.get('part_id')) for part in fillable_parts if part.get('part_id')}
        parsed_fillable_ids = {
            str(part_id) for part_id, value in subjective_values.items()
            if str(part_id) in fillable_ids and str(value or '').strip()
        }
        missing_objective = sorted(expected_objective - parsed_objective)
        missing_parts = [
            part for part in fillable_parts
            if str(part.get('part_id')) not in parsed_fillable_ids
        ]
        problems = []
        if missing_objective:
            problems.append('缺少选择题答案：' + '、'.join(f'第{qno}题' for qno in missing_objective))
        if diagnostics.get('duplicate_objective_questions'):
            values = sorted(set(diagnostics['duplicate_objective_questions']))
            problems.append('选择题题号重复：' + '、'.join(f'第{qno}题' for qno in values))
        if diagnostics.get('unexpected_objective_questions'):
            values = sorted(set(diagnostics['unexpected_objective_questions']))
            problems.append('试卷结构中不存在这些选择题：' + '、'.join(str(qno) for qno in values))
        if missing_parts:
            labels = [str(part.get('answer_label') or part.get('label') or part.get('part_id')) for part in missing_parts]
            problems.append('缺少主观题答案：' + '、'.join(labels[:12]))
        if diagnostics.get('subjective_overflow'):
            first = diagnostics['subjective_overflow'][0]
            problems.append(
                f"{first.get('label') or '主观题'}答案过多：提供 {first.get('provided')} 个，"
                f"结构只能容纳 {first.get('capacity')} 个"
            )
        if diagnostics.get('unassigned_subjective_values'):
            values = diagnostics['unassigned_subjective_values'][:8]
            problems.append('没有对应空位的答案：' + '、'.join(str(value) for value in values))
        if problems:
            raise ValueError('答案与自动识别的试卷结构不一致：\n' + '\n'.join(f'• {item}' for item in problems))

        self.set_global_answer_map(answer_map)
        settings = {}
        for part in fillable_parts:
            part_id = str(part.get('part_id') or '')
            value = subjective_values.get(part_id)
            if not part_id or not str(value or '').strip():
                continue
            clean_value, cand_words = self.extract_candidate_words_from_answer_text(value)
            config = self.default_ocr_config()
            config['enabled'] = True
            config['expected_answer'] = self.expand_expected_answer_aliases(clean_value)
            if cand_words:
                config['candidate_words'] = cand_words
                config['choice_fill'] = True
                config['unique_answer'] = True
                wa, wk = self.derive_wrong_answers_and_keywords(clean_value, cand_words)
                if wa:
                    config['common_wrong_answers'] = wa
                if wk:
                    config['wrong_keywords'] = wk
            else:
                config['unique_answer'] = self.is_dedicated_physics_terminology(clean_value)

            settings[part_id] = self.normalize_ocr_config(config)
        if settings:
            self.save_ocr_settings_for_parts(settings)
        self.ensure_answer_scheme_matches_current_structure(persist=False)
        return {
            'objective_questions': len(answer_map),
            'subjective_blanks': len(settings),
            'drawing_parts': sum(1 for part in parts if part.get('kind') == 'drawing'),
        }

    def auto_save_calculation_question_config(self, calculation_text):
        """Save Word-derived calculation scores with the current subject structure."""
        if self.is_direct_paper_choice_template() and not self.direct_paper_has_calculation_structure():
            raw_text = ''
        else:
            raw_text = str(calculation_text or '').strip()
        questions = self.parse_calculation_question_text(raw_text) if raw_text else []
        config_path = Path(getattr(self, 'subjective_config_path', '') or '')
        if not config_path.exists():
            raise RuntimeError('主观题结构尚未保存，不能写入计算题分值。')
        config = json.loads(config_path.read_text(encoding='utf-8-sig'))
        config['calculation_questions'] = {
            'enabled': bool(questions),
            'mode': 'back_region_manual' if self.is_direct_paper_choice_template() else 'back_page_manual_whole_page',
            'questions': questions,
            'max_score': round(sum(item['max_score'] for item in questions), 2),
            'updated_at': datetime.now().isoformat(timespec='seconds'),
        }
        config['updated_at'] = datetime.now().isoformat(timespec='seconds')
        atomic_write_json(config_path, config)
        self.subjective_config = config
        if questions and self.is_direct_paper_choice_template() and self.direct_paper_has_calculation_structure():
            self.ensure_direct_calculation_region_for_questions(questions)
        return questions

    def auto_save_answer_scheme(self, scheme_name):
        """Persist the complete answer, structure, OCR and knowledge package."""
        scheme_name = str(scheme_name or '').strip()
        if not scheme_name:
            raise ValueError('答案方案名称不能为空。')
        target = self.get_answer_key_file_path(scheme_name)
        payload = {
            'template_key': self.current_template_key,
            'template_name': self.current_template_name,
            'name': scheme_name,
            'answer_key': self.clone_answer_key(self.answer_key),
            'direct_paper_structure': self.get_direct_paper_structure_for_scheme(target),
            'template_structure': self.get_template_structure_for_scheme(target),
            'subjective_ocr_settings': self.get_subjective_ocr_settings_for_scheme(),
            'subjective_config': self.get_subjective_config_for_scheme(),
            'knowledge_identity': self.normalize_knowledge_identity_payload(self.knowledge_identity_payload),
            'saved_at': datetime.now().isoformat(timespec='seconds'),
            'ocr_settings_updated_at': datetime.now().isoformat(timespec='seconds'),
        }
        atomic_write_json(target, payload)
        self.loaded_answer_key = self.clone_answer_key(self.answer_key)
        self.remember_loaded_answer_scheme(target, scheme_name)
        return target

    def auto_setup_grade_and_upload_current_folder(self):
        """Run the folder convention workflow without hiding setup failures."""
        if not self.require_current_session_for_grading('自动设置、批改并上传'):
            return
        if not self.begin_automation_run('自动设置并批改上传'):
            return
        stage = '检查当前文件夹'
        try:
            if not self.is_direct_paper_choice_template():
                raise ValueError('“自动设置并批改上传”目前只用于“试卷直接批改”模板。')
            folder = Path(self.selected_folder_path or '')
            if not folder.exists() or not folder.is_dir():
                raise ValueError(
                    '请先选择包含 0.1/0.2（或 0.01/0.02）、Word 模板、'
                    '知识点 CSV 和学生扫描图的文件夹。'
                )

            stage = '读取正反面模板图'
            self.status_var.set('自动流程：正在读取文件夹开头两张结构模板…')
            self.root.update_idletasks()
            pair = self.find_direct_paper_structure_template_pair(folder)
            if not pair:
                raise ValueError(
                    '当前文件夹未找到完整模板对：需要 0.1/0.2，或 0.01/0.02。'
                )

            stage = '读取 Word 答案和知识点 CSV'
            files = self.find_folder_answer_template_files(folder)
            word_payload = self.read_word_answer_template(files['word'])
            calculation_questions = (
                self.parse_calculation_question_text(word_payload['calculation_text'])
                if word_payload['calculation_text'].strip() else []
            )
            if word_payload.get('calculation_source_text') and not calculation_questions:
                raise ValueError(
                    'Word 中检测到了计算题，但“计算题”标题后只写了题号/小题号，没有写各小题满分。\n\n'
                    '请写成例如“15: 2,2,2”，冒号后的数字依次表示各小题满分。'
                )
            knowledge_payload = self.read_knowledge_identity_csv(files['csv']) if files.get('csv') else None

            stage = '自动设置正反面结构'
            self.status_var.set('自动流程：正在识别正反面选择框、横线和作图框…')
            self.root.update_idletasks()
            choice_answers = self.extract_direct_choice_answers_from_text(word_payload.get('answer_text') or '')
            choice_qnos = list(choice_answers.keys()) if choice_answers else None
            structure_info = self.auto_configure_direct_paper_structure(
                pair,
                enable_calculation=bool(calculation_questions),
                choice_question_numbers=choice_qnos,
            )

            stage = '导入标准答案'
            self.status_var.set('自动流程：正在填入选择题和主观题答案…')
            self.root.update_idletasks()
            answer_info = self.auto_apply_bulk_answer_text(word_payload['answer_text'])

            stage = '设置计算题分值'
            self.auto_save_calculation_question_config(word_payload['calculation_text'])

            stage = '导入知识点 CSV'
            self.knowledge_identity_payload = knowledge_payload

            stage = '保存答案方案'
            scheme_path = self.auto_save_answer_scheme(folder.name)

            stage = '读取学生扫描图'
            self.image_paths = self.collect_image_paths_from_folder(folder)
            if not self.image_paths:
                raise ValueError('除正反面模板图外，没有找到可批改的学生扫描图。')
            self.image_paths = sorted(self.image_paths, key=self.natural_path_sort_key)

            stage = '批改选择题并生成学生结果'
            self.status_var.set(f'自动流程：正在批改 {len(self.image_paths)} 张学生扫描图…')
            self.root.update_idletasks()
            grade_result = self.process_all()
            if not isinstance(grade_result, dict) or not grade_result.get('success'):
                error_count = len((grade_result or {}).get('errors') or [])
                raise RuntimeError(f'批改阶段有 {error_count} 份文件失败，已停止 OCR 和上传。')
            if not self.summary_data:
                raise RuntimeError('批改没有生成任何学生结果，已停止后续流程。')

            stage = 'OCR 主观题'
            self.status_var.set('自动流程：正在 OCR 主观题并自动判分…')
            self.root.update_idletasks()
            tasks = self.build_subjective_task_list_for_automation(reuse_existing=True)
            stats = self.run_subjective_two_stage_ocr_automation(
                tasks,
                status_callback=lambda text: (self.status_var.set('自动流程：' + text), self.root.update_idletasks()),
            )
            self.refresh_result_views_after_subjective_update()

            stage = '上传待人工打分部分'
            if int(stats.get('manual', 0) or 0) > 0:
                package_path, manifest = self.build_manual_web_task_package()
                with package_path.open('rb') as fh:
                    result = self.manual_web_request(
                        'POST', '/api/upload', body=fh.read(), content_type='application/zip'
                    )
                config = self.load_manual_web_sync_config()
                index_url = str(config.get('teacher_url') or config.get('server_url') or '').rstrip('/')
                job_url = result.get('job_url') or ''
                upload_note = (
                    f'已上传 {len(manifest.get("tasks") or [])} 个待人工空位。\n'
                    f'网页入口：{index_url or job_url}\n当前任务：{job_url}'
                )
            else:
                upload_note = '没有需要人工打分的空位，本次无需上传网页。'

            self.status_var.set('自动流程完成')
            messagebox.showinfo(
                '自动设置、批改并上传完成',
                f'答案方案：{scheme_path.name}\n'
                f'结构：选择题 {structure_info["choice_questions"]} 题，主观区域 {structure_info["subjective_lines"]} 个\n'
                f'答案：选择题 {answer_info["objective_questions"]} 题，OCR 空位 {answer_info["subjective_blanks"]} 个\n'
                f'学生扫描图：{len(self.image_paths)} 张（已自动跳过正反面模板图）\n'
                f'OCR：自动判分 {stats.get("auto", 0)} 个，需要人工 {stats.get("manual", 0)} 个\n\n'
                f'{upload_note}',
            )
        except Exception as exc:
            self.status_var.set(f'自动流程已中断：{stage}')
            messagebox.showerror(
                '自动流程已中断',
                f'卡在“{stage}”。\n\n{exc}\n\n已停止后续批改和上传，请修正后重新点击“自动设置并批改上传”。',
            )
        finally:
            self.end_automation_run()

    def knowledge_identity_summary(self, payload=None):
        payload = self.normalize_knowledge_identity_payload(
            self.knowledge_identity_payload if payload is None else payload
        )
        if not payload:
            return '知识点清单：未导入'
        question_numbers = {
            re.search(r'\d+', str(row.get('题号') or '')).group()
            for row in payload.get('rows', [])
            if re.search(r'\d+', str(row.get('题号') or ''))
        }
        source = payload.get('source_name') or '已导入CSV'
        return f'知识点清单：{source}（{len(question_numbers)}题，{len(payload.get("rows", []))}条对应关系）'

    def list_saved_answer_key_schemes(self):
        ANSWER_KEYS_DIR.mkdir(parents=True, exist_ok=True)
        prefix = f'{self.current_template_key}__'
        schemes = []
        for path in sorted(ANSWER_KEYS_DIR.glob(f'{prefix}*.json')):
            try:
                payload = json.loads(path.read_text(encoding='utf-8-sig'))
            except Exception:
                continue
            schemes.append({
                'name': payload.get('name') or path.stem[len(prefix):],
                'path': path,
                'saved_at': payload.get('saved_at', ''),
                'template_name': payload.get('template_name') or self.current_template_name,
                'answer_key': payload.get('answer_key') or {},
                'direct_paper_structure': payload.get('direct_paper_structure') or {},
                'template_structure': payload.get('template_structure') or {},
                'subjective_ocr_settings': payload.get('subjective_ocr_settings') or {},
                'subjective_config': payload.get('subjective_config') or {},
                'knowledge_identity': self.normalize_knowledge_identity_payload(payload.get('knowledge_identity') or {}),
            })
        return schemes

    def auto_load_answer_scheme_for_session(self, session_name):
        # Kept for old manual recovery only. Normal session loading must use
        # a per-session answer snapshot to avoid silently mixing tests.
        return False
        name = str(session_name or '').strip()
        if not name:
            return False
        candidates = [name]
        for token in re.split(r'[\\/]+', name):
            token = token.strip()
            if token and token not in candidates:
                candidates.append(token)

        schemes = self.list_saved_answer_key_schemes()
        chosen = None
        for candidate in reversed(candidates):
            for item in schemes:
                if str(item.get('name', '')).strip() == candidate:
                    chosen = item
                    break
            if chosen:
                break
        if not chosen:
            return False

        new_answer_map = self.extract_answer_map(chosen.get('answer_key', {}) or {})
        self.set_global_answer_map(new_answer_map)
        self.remember_loaded_answer_scheme(chosen.get('path'), chosen.get('name', ''))
        self.apply_subjective_config_from_scheme(chosen.get('subjective_config') or {})
        self.apply_subjective_ocr_settings_from_scheme(chosen.get('subjective_ocr_settings') or {})
        self.knowledge_identity_payload = self.normalize_knowledge_identity_payload(chosen.get('knowledge_identity') or {})
        return True

    def remember_loaded_answer_scheme(self, path=None, name=''):
        self.loaded_answer_key_scheme_path = str(path) if path else None
        self.loaded_answer_key_scheme_name = (name or '').strip()
        if all(hasattr(self, attr) for attr in (
            'answer_threshold_var',
            'student_id_threshold_var',
            'sample_box_var',
            'student_id_sample_box_var',
            'debug_info_var',
            'auto_latest_zone_var',
            'overlay_offset_x_mm_var',
            'overlay_offset_y_mm_var',
            'overlay_scale_percent_var',
            'overlay_back_offset_x_mm_var',
            'overlay_back_offset_y_mm_var',
            'overlay_back_scale_percent_var',
            'overlay_print_percent_score_var',
            'overlay_total_display_mode_var',
        )):
            self.save_ui_settings()

    def load_answer_scheme_file_into_state(self, scheme_path, scheme_name=''):
        if not scheme_path:
            return False
        path = Path(scheme_path)
        if not path.exists():
            return False
        try:
            payload = json.loads(path.read_text(encoding='utf-8-sig'))
        except Exception:
            return False
        if not isinstance(payload, dict):
            return False
        if payload.get('template_key') and payload.get('template_key') != self.current_template_key:
            return False
        self.set_global_answer_map(self.extract_answer_map(payload.get('answer_key') or {}))
        self.subjective_config = {}
        if self.is_direct_paper_choice_template():
            self._session_requires_structure = not bool(payload.get('direct_paper_structure'))
        self.remember_loaded_answer_scheme(path, scheme_name or payload.get('name') or path.stem)
        self.apply_template_structure_from_scheme(payload.get('template_structure') or {})
        if self.is_direct_paper_choice_template():
            self.apply_direct_paper_structure_from_scheme(payload.get('direct_paper_structure') or {})
            self.apply_subjective_config_from_scheme(payload.get('subjective_config') or {})
        elif self.is_mixed_objective_subjective_template():
            self.apply_subjective_config_from_scheme(payload.get('subjective_config') or {})
        self.apply_subjective_ocr_settings_from_scheme(payload.get('subjective_ocr_settings') or {})
        self.knowledge_identity_payload = self.normalize_knowledge_identity_payload(payload.get('knowledge_identity') or {})
        return True

    def sync_loaded_answer_scheme_ocr_settings(self):
        if self.current_session:
            self.save_session_answer_key_snapshot()
            return len(self.get_subjective_ocr_settings_for_scheme())
        scheme_path = getattr(self, 'loaded_answer_key_scheme_path', None)
        if not scheme_path:
            return 0
        path = Path(scheme_path)
        if not path.exists():
            return 0
        payload = json.loads(path.read_text(encoding='utf-8-sig'))
        if payload.get('template_key') and payload.get('template_key') != self.current_template_key:
            return 0
        settings = self.get_subjective_ocr_settings_for_scheme()
        payload['subjective_ocr_settings'] = settings
        payload['subjective_config'] = self.get_subjective_config_for_scheme()
        payload['ocr_settings_updated_at'] = datetime.now().isoformat(timespec='seconds')
        atomic_write_json(path, payload)
        return len(settings)

    def current_objective_question_numbers(self):
        numbers = []
        for question in (self.merged_objective_answer_zone().get('questions') or []):
            qno = question.get('question_no_in_zone')
            if qno is None:
                continue
            try:
                qno = int(qno)
            except Exception:
                pass
            if qno not in numbers:
                numbers.append(qno)
        return numbers

    def ensure_answer_scheme_matches_current_structure(self, persist=True):
        """Keep the loaded answer scheme aligned with the latest template structure.

        This only adds placeholders for newly detected objective questions and
        subjective blanks. Existing answers/OCR settings are preserved.
        """
        objective_added = 0
        answer_map = self.extract_answer_map(self.answer_key or self.loaded_answer_key or {})
        for qno in self.current_objective_question_numbers():
            if qno not in answer_map and str(qno) not in answer_map:
                answer_map[qno] = []
                objective_added += 1
        if objective_added or answer_map:
            self.set_global_answer_map(answer_map)

        subjective_settings = self.get_subjective_ocr_settings_for_scheme() if self.subjective_items() else {}
        subjective_count = len(list(self.iter_subjective_parts()))
        synced_path = None
        if persist:
            scheme_path = getattr(self, 'loaded_answer_key_scheme_path', None)
            if scheme_path and not self.current_session:
                path = Path(scheme_path)
                if path.exists():
                    try:
                        payload = json.loads(path.read_text(encoding='utf-8-sig'))
                    except Exception:
                        payload = {}
                    if not payload.get('template_key') or payload.get('template_key') == self.current_template_key:
                        payload['template_key'] = self.current_template_key
                        payload['template_name'] = self.current_template_name
                        payload['answer_key'] = self.clone_answer_key(self.answer_key)
                        if self.is_direct_paper_choice_template():
                            payload['direct_paper_structure'] = self.get_direct_paper_structure_for_scheme(path)
                        elif self.is_mixed_objective_subjective_template():
                            payload['template_structure'] = self.get_template_structure_for_scheme(path)
                        payload['subjective_ocr_settings'] = subjective_settings
                        payload['subjective_config'] = self.get_subjective_config_for_scheme()
                        payload['structure_synced_at'] = datetime.now().isoformat(timespec='seconds')
                        atomic_write_json(path, payload)
                        synced_path = path
            if self.current_session:
                self.save_session_answer_key_snapshot()
        return {
            'objective_questions': len(self.current_objective_question_numbers()),
            'objective_added': objective_added,
            'subjective_blanks': subjective_count,
            'scheme_path': str(synced_path) if synced_path else '',
        }

    def apply_answer_key_to_entries(self, answer_key):
        if not hasattr(self, 'answer_entries'):
            return
        answer_map = self.extract_answer_map(answer_key)
        for zone_name, zone_entries in self.answer_entries.items():
            for qno, payload in zone_entries.items():
                existing = answer_map.get(qno) or answer_map.get(str(qno)) or []
                if payload['type'] == 'single':
                    selected = (existing[0] if existing else '').strip().upper()
                    payload['state']['value'] = selected
                    refresh = payload.get('refresh')
                    if callable(refresh):
                        refresh(selected)
                else:
                    selected_set = {str(opt).strip().upper() for opt in existing}
                    for opt, var in payload['vars'].items():
                        var.set(opt.upper() in selected_set)

    def clone_answer_key(self, answer_key):
        cloned = {}
        for zone_name, zone_answers in (answer_key or {}).items():
            if not isinstance(zone_answers, dict):
                continue
            cloned[zone_name] = {}
            for qno, values in zone_answers.items():
                normalized_qno = int(qno) if isinstance(qno, str) and qno.isdigit() else qno
                if isinstance(values, list):
                    cloned[zone_name][normalized_qno] = list(values)
                elif values is None:
                    cloned[zone_name][normalized_qno] = []
                else:
                    cloned[zone_name][normalized_qno] = [str(values)]
        return cloned

    def clone_answer_map(self, answer_map):
        cloned = {}
        for qno, values in (answer_map or {}).items():
            normalized_qno = int(qno) if isinstance(qno, str) and qno.isdigit() else qno
            if isinstance(values, list):
                cloned[normalized_qno] = list(values)
            elif values is None:
                cloned[normalized_qno] = []
            else:
                cloned[normalized_qno] = [str(values)]
        return cloned

    def extract_answer_map(self, answer_key=None):
        raw_answer_key = self.answer_key if answer_key is None else (answer_key or {})
        if isinstance(raw_answer_key, dict) and any(not isinstance(v, dict) for v in raw_answer_key.values()):
            return self.clone_answer_map(raw_answer_key)
        answer_key = self.clone_answer_key(raw_answer_key)
        if GLOBAL_ANSWER_ZONE in answer_key:
            return self.clone_answer_map(answer_key.get(GLOBAL_ANSWER_ZONE, {}))

        best_map = {}
        for zone_name in getattr(self, 'available_zone_names', []):
            zone_answers = answer_key.get(zone_name)
            if isinstance(zone_answers, dict) and len(zone_answers) > len(best_map):
                best_map = zone_answers
        for zone_answers in answer_key.values():
            if isinstance(zone_answers, dict) and len(zone_answers) > len(best_map):
                best_map = zone_answers
        return self.clone_answer_map(best_map)

    def set_global_answer_map(self, answer_map):
        self.answer_key = {GLOBAL_ANSWER_ZONE: self.clone_answer_map(answer_map)}
        self.loaded_answer_key = self.clone_answer_key(self.answer_key)
        return self.answer_key

    def has_standard_answers(self):
        answer_map = self.extract_answer_map(self.answer_key)
        return any(bool(values) for values in answer_map.values())

    def ocr_config_has_answer_content(self, config):
        config = self.normalize_ocr_config(config)
        return any(
            str(config.get(key) or '').strip()
            for key in ('expected_answer', 'expected_keywords', 'common_wrong_answers', 'wrong_keywords')
        )

    def has_answer_scheme_state(self):
        if self.has_standard_answers():
            return True
        if self.extract_answer_map(getattr(self, 'loaded_answer_key', {}) or {}):
            return True
        return bool(getattr(self, 'loaded_answer_key_scheme_path', None))

    def ensure_answer_scheme_loaded_for_grading(self):
        if self.current_template_mode != 'grader':
            return True
        scheme_path = getattr(self, 'loaded_answer_key_scheme_path', None)
        if not self.current_session and scheme_path and Path(scheme_path).exists():
            if self.load_answer_scheme_file_into_state(scheme_path, getattr(self, 'loaded_answer_key_scheme_name', '')):
                if self.current_session:
                    self.save_session_answer_key_snapshot()
                return self.has_standard_answers()
        if self.has_standard_answers():
            return True
        if self.extract_answer_map(getattr(self, 'loaded_answer_key', {}) or {}):
            self.answer_key = self.clone_answer_key(self.loaded_answer_key)
            return self.has_standard_answers()

        if self.current_session and self.load_session_answer_key_snapshot(self.current_session.get('id')):
            return self.has_standard_answers()
        return False

    def fill_missing_answers_from_scheme_file(self, scheme_path, scheme_name=''):
        if not scheme_path:
            return {'objective_filled': 0, 'subjective_filled': 0, 'knowledge_filled': 0}
        path = Path(scheme_path)
        if not path.exists():
            return {'objective_filled': 0, 'subjective_filled': 0, 'knowledge_filled': 0}
        try:
            payload = json.loads(path.read_text(encoding='utf-8-sig'))
        except Exception:
            return {'objective_filled': 0, 'subjective_filled': 0, 'knowledge_filled': 0}
        if payload.get('template_key') and payload.get('template_key') != self.current_template_key:
            return {'objective_filled': 0, 'subjective_filled': 0, 'knowledge_filled': 0}

        objective_filled = 0
        fallback_answer_map = self.extract_answer_map(payload.get('answer_key') or {})
        if fallback_answer_map and not self.has_standard_answers():
            self.set_global_answer_map(fallback_answer_map)
            objective_filled = len(fallback_answer_map)

        subjective_filled = 0
        fallback_settings = payload.get('subjective_ocr_settings') or {}
        if isinstance(fallback_settings, dict) and fallback_settings:
            current_settings = self.get_subjective_ocr_settings_for_scheme()
            merged = {}
            for part_id, fallback_config in fallback_settings.items():
                fallback_config = self.normalize_ocr_config(fallback_config)
                current_config = self.normalize_ocr_config(current_settings.get(part_id))
                updated_config = dict(current_config)
                changed = False
                for key in ('expected_answer', 'expected_keywords', 'common_wrong_answers', 'wrong_keywords'):
                    if str(fallback_config.get(key) or '').strip() and not str(updated_config.get(key) or '').strip():
                        updated_config[key] = fallback_config.get(key) or ''
                        changed = True
                if changed:
                    merged[part_id] = self.normalize_ocr_config(updated_config)
                    subjective_filled += 1
            if merged:
                self.save_ocr_settings_for_parts(merged)

        knowledge_filled = 0
        current_knowledge = self.normalize_knowledge_identity_payload(
            getattr(self, 'knowledge_identity_payload', {}) or {}
        )
        fallback_knowledge = self.normalize_knowledge_identity_payload(
            payload.get('knowledge_identity') or {}
        )
        if not current_knowledge.get('rows') and fallback_knowledge.get('rows'):
            self.knowledge_identity_payload = fallback_knowledge
            knowledge_filled = len(fallback_knowledge.get('rows') or [])

        if objective_filled or subjective_filled or knowledge_filled:
            self.remember_loaded_answer_scheme(path, scheme_name or payload.get('name') or path.stem)
        return {
            'objective_filled': objective_filled,
            'subjective_filled': subjective_filled,
            'knowledge_filled': knowledge_filled,
        }

    def find_saved_answer_scheme_by_name(self, scheme_name):
        wanted = str(scheme_name or '').strip()
        if not wanted:
            return None
        for item in self.list_saved_answer_key_schemes():
            if str(item.get('name', '')).strip() == wanted:
                return item
        return None

    def expected_answers_for_question(self, qno):
        answer_map = self.extract_answer_map(self.answer_key)
        val = answer_map.get(qno, answer_map.get(str(qno), []))
        if isinstance(val, str):
            return [val]
        return list(val or [])

    def is_mixed_objective_subjective_template(self):
        if self.is_direct_paper_choice_template():
            return False
        key = str(getattr(self, 'current_template_key', '') or '')
        if key == 'mixed_objective_subjective_v1':
            return True
        return bool(self.answer_config.get('zones')) and bool(self.subjective_items())

    def mixed_template_has_calculation_back_pages(self):
        if not self.is_mixed_objective_subjective_template():
            return False
        config = (getattr(self, 'subjective_config', {}) or {}).get('calculation_questions') or {}
        return bool(config.get('enabled') or self.calculation_question_config())

    def mixed_template_single_side_mode_enabled(self):
        if not self.is_mixed_objective_subjective_template():
            return False
        var = getattr(self, 'mixed_single_side_mode_var', None)
        return bool(var.get()) if var is not None else False

    def mixed_template_should_pair_back_pages(self):
        if not self.is_mixed_objective_subjective_template():
            return False
        if self.mixed_template_single_side_mode_enabled():
            return False
        if len(self.image_paths) < 2:
            return False
        if self.mixed_template_has_calculation_back_pages():
            return True
        if str(getattr(self, 'current_template_key', '') or '') != 'mixed_objective_subjective_v1':
            return False
        return len(self.image_paths) % 2 == 0

    def prompt_set_subjective_ocr_after_experiment_structure(self):
        if not self.is_mixed_objective_subjective_template():
            return
        if messagebox.askyesno(
            '下一步：设置OCR空位',
            '实验题结构已经保存。\n\n下一步建议设置 OCR 空位，包括标准答案、关键词、常见错答案和诱导字。\n\n现在去设置 OCR 空位吗？',
        ):
            self.open_subjective_ocr_settings()

    def prompt_experiment_structure_after_answer_key(self):
        if not self.is_mixed_objective_subjective_template():
            return
        if messagebox.askyesno(
            '下一步：设置实验题结构',
            '选择题标准答案已经保存。\n\n这个模板还需要设置实验题结构，程序才能知道 20-23 题每个空对应哪一小题。\n\n现在去设置实验题结构吗？',
        ):
            self.open_experiment_structure_setup(
                after_save_callback=self.prompt_set_subjective_ocr_after_experiment_structure
            )

    def prompt_and_save_named_answer_key(self):
        if self.current_template_mode != 'grader':
            messagebox.showinfo('提示', '当前模板是采集模式，不需要保存标准答案方案。')
            return
        self.collect_answer_key_from_entries()
        self.loaded_answer_key = self.clone_answer_key(self.answer_key)
        if not self.has_standard_answers():
            messagebox.showwarning('提示', '请先设置至少一道题的标准答案。')
            return
        default_name = datetime.now().strftime('%Y%m%d-%H%M%S')
        scheme_name = simpledialog.askstring('保存答案方案', '给这套标准答案起个名字：', initialvalue=default_name, parent=self.root)
        if scheme_name is None:
            return
        try:
            target = self.get_answer_key_file_path(scheme_name)
            payload = {
                'template_key': self.current_template_key,
                'template_name': self.current_template_name,
                'name': scheme_name.strip(),
                'answer_key': self.answer_key,
                'direct_paper_structure': self.get_direct_paper_structure_for_scheme(target),
                'template_structure': self.get_template_structure_for_scheme(target),
                'subjective_ocr_settings': self.get_subjective_ocr_settings_for_scheme(),
                'subjective_config': self.get_subjective_config_for_scheme(),
                'knowledge_identity': self.normalize_knowledge_identity_payload(self.knowledge_identity_payload),
                'saved_at': datetime.now().isoformat(timespec='seconds'),
            }
            atomic_write_json(target, payload)
            self.remember_loaded_answer_scheme(target, scheme_name)
            self.root.after(100, self.prompt_experiment_structure_after_answer_key)
            messagebox.showinfo('成功', f'答案方案已保存：{scheme_name.strip()}')
        except Exception as e:
            messagebox.showerror('保存失败', str(e))

    def load_named_answer_key(self):
        if not self.context_change_allowed(ignore_answer_window=True):
            return
        schemes = self.list_saved_answer_key_schemes()
        if not schemes:
            messagebox.showinfo('提示', f'当前模板“{self.current_template_name}”还没有已保存的答案方案。')
            return

        win = tk.Toplevel(self.root)
        win.title('加载答案方案')
        win.geometry('520x360')
        win.transient(self.root)
        win.grab_set()

        tk.Label(win, text=f'选择要加载的答案方案（模板：{self.current_template_name}）', font=('Arial', 10, 'bold')).pack(anchor='w', padx=12, pady=(12, 8))

        listbox = tk.Listbox(win, font=('Consolas', 10))
        listbox.pack(fill='both', expand=True, padx=12, pady=(0, 10))
        for item in schemes:
            saved_at = item.get('saved_at') or ''
            display = f"{item['name']}    {saved_at}".strip()
            listbox.insert(tk.END, display)
        if schemes:
            listbox.selection_set(0)

        def open_selected(event=None):
            try:
                selection = listbox.curselection()
                if not selection:
                    messagebox.showwarning('提示', '请先选择一个答案方案', parent=win)
                    return
                item = schemes[selection[0]]
                new_answer_map = self.extract_answer_map(item.get('answer_key', {}) or {})
                self.set_global_answer_map(new_answer_map)
                self.subjective_config = {}
                if self.is_direct_paper_choice_template():
                    self._session_requires_structure = not bool(item.get('direct_paper_structure'))
                self.remember_loaded_answer_scheme(item.get('path'), item.get('name', ''))
                self.apply_template_structure_from_scheme(item.get('template_structure') or {})
                if self.is_direct_paper_choice_template():
                    self.apply_direct_paper_structure_from_scheme(item.get('direct_paper_structure') or {})
                self.apply_subjective_config_from_scheme(item.get('subjective_config') or {})
                ocr_loaded = self.apply_subjective_ocr_settings_from_scheme(item.get('subjective_ocr_settings') or {})
                self.knowledge_identity_payload = self.normalize_knowledge_identity_payload(item.get('knowledge_identity') or {})
                if self.current_session:
                    self.save_session_template_config_snapshot()
                    self.save_session_answer_key_snapshot()
                if self.summary_data:
                    self.apply_subjective_scores_to_entries()
                    self.update_summary_display()
                loaded_count = len(new_answer_map)
                ocr_text = f"，OCR空位{ocr_loaded}项" if ocr_loaded else ''
                self.status_var.set(f"已加载答案方案：{item['name']}（{loaded_count}题{ocr_text}，已直接应用）")

                answer_window = getattr(self, 'answer_key_window', None)
                win.destroy()
                if answer_window is not None and answer_window.winfo_exists():
                    answer_window.destroy()
                    self.answer_key_window = None
            except Exception as e:
                messagebox.showerror('加载失败', str(e), parent=win)

        button_bar = tk.Frame(win)
        button_bar.pack(fill='x', padx=12, pady=(0, 12))
        tk.Button(button_bar, text='加载', command=open_selected, width=10).pack(side='left', padx=4)
        def delete_selected():
            try:
                selection = listbox.curselection()
                if not selection:
                    messagebox.showwarning('提示', '请先选择一个答案方案', parent=win)
                    return
                item = schemes[selection[0]]
                name = item.get('name', '未命名方案')
                if not messagebox.askyesno('确认删除', f'确定删除答案方案“{name}”吗？\n\n删除后不会出现在方案列表里。', parent=win):
                    return
                path = Path(item.get('path'))
                if path.exists():
                    backup = path.with_suffix(path.suffix + f'.deleted_{datetime.now().strftime("%Y%m%d_%H%M%S")}')
                    path.rename(backup)
                schemes.pop(selection[0])
                listbox.delete(selection[0])
                if schemes:
                    listbox.selection_set(min(selection[0], len(schemes) - 1))
                self.status_var.set(f'已删除答案方案：{name}')
            except Exception as e:
                messagebox.showerror('删除失败', str(e), parent=win)

        tk.Button(button_bar, text='删除选中方案', command=delete_selected, width=14).pack(side='left', padx=4)
        tk.Button(button_bar, text='取消', command=win.destroy, width=10).pack(side='left', padx=4)

        listbox.bind('<Double-1>', open_selected)
        win.bind('<Return>', open_selected)
        win.bind('<KP_Enter>', open_selected)

    def normalize_bulk_answer_text(self, text):
        text = unicodedata.normalize('NFKC', str(text or ''))
        text = text.replace('\u3000', ' ')
        text = re.sub(
            r'(\d+(?:\.\d+)?)\s*[×xX*]\s*10\s*([+-]?\d+)',
            r'\1x10^\2',
            text,
        )
        text = re.sub(r'\s+', ' ', text)
        return text.strip()
    def should_disable_split_char_check(self, expected_answer, candidate_words='', is_drawing=False):
        """
        自动判断主观填空是否应该【关闭拆字判错】（即 split_char_check = False）。

        以下情况自动判定为不拆字判错：
        1. 作图题（人工批改，无字可拆）；
        2. 纯数字/小数/数值/比值/带单位物理量（如 0.3, 10.0, 15, 3x10^8, 20cm, 3:2 等，数值需精确比对，无拆字意义）；
        3. 单字答案（如 丁, 甲, 乙, 丙, 大, 小, 凸, 凹, 快, 慢, 能, 变, A, B 等，无字可拆，极易因连笔形近被误杀）；
        4. 成对否定词（如 不能, 不会, 没有, 不变），或限定备选词中包含否定对立词；
        5. 包含逗号/分号分隔的多个并列答案（如 铁轨,路面,铁路）。
        """
        if is_drawing:
            return True, '作图题'

        ans = unicodedata.normalize('NFKC', str(expected_answer or '')).strip()
        if not ans or ans == '作图':
            return True, '作图/无标准答案'

        alt_answers = [a.strip() for a in re.split(r'[,，;；|]+', ans) if a.strip()]
        if len(alt_answers) > 1:
            return True, '多备选并列答案'

        primary = alt_answers[0] if alt_answers else ans

        # 单字母代号（如 A, B, C, D, N, S, F）
        if re.fullmatch(r'[A-Za-z]', primary):
            return True, '单字母代号'

        # 1. 纯数字 / 科学计数法 / 带单位数值 / 比值
        if re.fullmatch(r'^[+-]?\d+(?:\.\d+)?(?:[%％])?$', primary):
            return True, '纯数值/数字'
        if re.search(r'\d+(?:\.\d+)?\s*[xX*×]\s*10\s*[\^]?[+-]?\d+', primary):
            return True, '科学记数法'
        if re.fullmatch(r'^\d+\s*[:：比/]\s*\d+$', primary):
            return True, '比值'
        if re.fullmatch(r'^[+-]?\d+(?:\.\d+)?\s*(?:cm|m|km|g|kg|t|s|min|h|km/h|m/s|n|pa|kpa|j|kj|w|kw|v|a|ma|ω|hz|khz|℃|度|欧|伏|安|牛|焦|瓦|帕|克|千克|米|厘米|秒|分|小时)(?:[/／](?:s|min|h|m|cm|kg|g|m³|cm³))?$', primary, re.I):
            return True, '带单位数值'

        # 2. 单字答案（无字可拆，极易因OCR形近/连笔字被拆字误杀）
        clean_chinese = re.sub(r'[^\u4e00-\u9fa5A-Za-z0-9]', '', primary)
        if len(clean_chinese) == 1:
            return True, '单字答案'

        # 3. 对立否定词（如 不能、不会、没有、不变、不相同、不均匀）
        negation_words = {'不能', '不会', '没有', '不变', '不相同', '不均匀', '非晶体', '不省力'}
        if primary in negation_words:
            return True, '否定对立词'
        if any(k in str(candidate_words or '') for k in ('能/不能', '会/不会', '变/不变', '相同/不相同')):
            return True, '备选词包含否定对立词'

        # 4. 物理因果长句规律（如“反射角等于入射角”、“电流与电压成正比”）
        if any(w in primary for w in ('等于', '相等', '正比', '反比')) and len(primary) >= 5:
            return True, '物理规律长句'

        # 5. 变化趋势词（非选填时存在近义表达，如 增大/变大、升高/变高、加快/变快）
        trend_words = {
            '增大', '变大', '增加', '增多', '升高', '变高', '变快', '加快', '变强', '增强', '变粗', '变长', '加速',
            '减小', '变小', '减少', '变少', '降低', '变低', '变慢', '减慢', '变弱', '减弱', '变细', '变短', '减速'
        }
        if primary in trend_words and not candidate_words:
            return True, '变化趋势词'

        return False, '多字概念词'

    def expand_expected_answer_aliases(self, answer_text):
        raw_values = [
            item.strip()
            for item in re.split(r'[,，、/；;]+', str(answer_text or ''))
            if item.strip()
        ]
        aliases = []
        for raw in raw_values:
            if raw not in aliases:
                aliases.append(raw)
            compact = re.sub(r'\s+', '', raw)
            if compact and compact not in aliases:
                aliases.append(compact)
            match = re.fullmatch(r'([+-]?\d+(?:\.\d+)?)\s*[×xX*]\s*10\^?([+-]?\d+)', compact)
            if match:
                base_text, exp_text = match.groups()
                for variant in (
                    f'{base_text}x10^{exp_text}',
                    f'{base_text}×10^{exp_text}',
                    f'{base_text}*10^{exp_text}',
                ):
                    if variant not in aliases:
                        aliases.append(variant)
                try:
                    value = float(base_text) * (10 ** int(exp_text))
                    if abs(value - round(value)) < 1e-9:
                        plain = str(int(round(value)))
                    else:
                        plain = f'{value:g}'
                    if plain not in aliases:
                        aliases.append(plain)
                except Exception:
                    pass
        return ','.join(aliases)

    def split_bulk_answer_values(self, segment, expected_count):
        segment = self.normalize_bulk_answer_text(segment)
        segment = segment.strip(' ：:，,；;')
        if expected_count <= 1:
            return [segment] if segment else []

        # In the integrated importer, comma/semicolon are the natural way to
        # write multiple blanks in one question. Alternatives for the same blank
        # should be written with "/" or "或", for example: 增大/变大.
        explicit_parts = self.split_by_delimiters_outside_brackets(segment, delimiters='；;，,')
        if len(explicit_parts) >= expected_count:
            return explicit_parts[:expected_count]

        parts = self.split_by_delimiters_outside_brackets(segment, delimiters='；;|')
        if len(parts) >= expected_count:
            return parts[:expected_count]

        raw_tokens = [item for item in segment.split(' ') if item]
        tokens = []
        unit_pattern = re.compile(r'^(?:mL|ml|L|cm|mm|m|s|kg|g|N|Pa|W|V|A|Ω|欧|欧姆|℃|°C)$', re.I)
        cursor = 0
        while cursor < len(raw_tokens):
            current = raw_tokens[cursor]
            next_token = raw_tokens[cursor + 1] if cursor + 1 < len(raw_tokens) else ''
            if re.fullmatch(r'[+-]?\d+(?:\.\d+)?(?:x10\^[+-]?\d+)?', current, re.I) and unit_pattern.fullmatch(next_token):
                tokens.append(current + next_token)
                cursor += 2
                continue
            tokens.append(current)
            cursor += 1
        if len(tokens) >= expected_count:
            # Strict import rule: spaces separate blanks. Extra tokens are not
            # merged into the last blank, otherwise the next blank can be swallowed.
            return tokens[:expected_count]

        values = [segment] if segment else []
        while len(values) < expected_count:
            values.append('')
        return values

    def direct_paper_subjective_parts_in_order(self):
        # Drawing items do not use OCR, but they must still occupy their
        # original answer position so pasted answers such as "7.作图" do not
        # shift the following blanks forward.
        parts = list(self.iter_subjective_parts())

        def sort_key(part):
            side = str(part.get('side') or 'front').lower()
            side_order = 1 if side == 'back' else 0
            part_id = str(part.get('part_id') or '')
            match = re.match(r'q([FB])(\d+)_b(\d+)$', part_id, re.I)
            if match:
                prefix, order, blank_no = match.groups()
                side_order = 1 if prefix.upper() == 'B' else 0
                return (side_order, int(order), int(blank_no))
            drawing_match = re.match(r'q([FB])(\d+)_drawing(?:_\d+)?$', part_id, re.I)
            if drawing_match:
                prefix, order = drawing_match.groups()
                side_order = 1 if prefix.upper() == 'B' else 0
                return (side_order, int(order), 0)
            rect = part.get('rect') or {}
            return (side_order, float(rect.get('y', 0)), float(rect.get('x', 0)))

        return sorted(parts, key=sort_key)

    def normalize_direct_subjective_marker(self, marker):
        marker = unicodedata.normalize('NFKC', str(marker or '')).strip().upper()
        marker = re.sub(r'\s+', '', marker)
        marker = marker.replace('第', '').replace('题', '').replace('空', '').replace('横线', '')
        return marker

    def direct_paper_subjective_part_by_marker(self, marker, ordered_parts):
        marker = self.normalize_direct_subjective_marker(marker)
        if not marker:
            return None
        for part in ordered_parts:
            aliases = [
                part.get('answer_label'),
                part.get('label'),
                part.get('question_no'),
            ]
            for alias in aliases:
                if alias and self.normalize_direct_subjective_marker(alias) == marker:
                    return part
        side_prefix = ''
        number_text = marker
        match = re.fullmatch(r'([FB])\s*0*(\d+)', marker, re.I)
        if match:
            side_prefix, number_text = match.groups()
        elif not marker.isdigit():
            return None
        try:
            number = int(number_text)
        except Exception:
            return None
        if side_prefix:
            wanted = f'q{side_prefix.upper()}{number:03d}_b'
            for part in ordered_parts:
                if str(part.get('part_id') or '').upper().startswith(wanted.upper()):
                    return part
            return None
        if 1 <= number <= len(ordered_parts):
            return ordered_parts[number - 1]
        return None

    def direct_paper_parts_by_label(self, marker, ordered_parts):
        wanted = self.normalize_direct_subjective_marker(marker)
        if not wanted:
            return []
        matched = []
        for part in ordered_parts:
            for alias in (part.get('answer_label'), part.get('label'), part.get('question_no')):
                if alias and self.normalize_direct_subjective_marker(alias) == wanted:
                    matched.append(part)
                    break
        return matched

    def split_direct_paper_subjective_values(self, answer_text):
        answer_text = self.normalize_bulk_answer_text(answer_text)
        answer_text = re.sub(r'^[（(]\s*\d+\s*[）)]\s*', '', answer_text).strip()
        answer_text = answer_text.strip(' ：:，,；;。.')
        if not answer_text:
            return []
        values = self.split_by_delimiters_outside_brackets(answer_text, delimiters=',，;；、|')
        return values or [answer_text]

    def is_pure_choice_answer_line(self, line):
        """Check if a line represents ONLY a choice question answer with no other content."""
        line = unicodedata.normalize('NFKC', str(line or '')).strip()
        line = line.replace('\u3000', ' ')
        if not line or line.startswith('#'):
            return False
        m = re.match(
            r'^(?:第\s*)?[(（【\[]?\s*([1-9]\d{0,2})\s*[)）】\]]?(?:题|答案)?\s*[:：.．、,，=|-]?\s*([A-D](?:\s*[,，、/／ ]?\s*[A-D])*)\s*$',
            line,
            re.I,
        )
        if m:
            return True
        tokens = list(re.finditer(
            r'(?:第\s*)?[(（【\[]?\s*([1-9]\d{0,2})\s*[)）】\]]?(?:题|答案)?\s*[:：.．、,，=|-]?\s*([A-D](?:\s*[,，、/／ ]?\s*[A-D])*)',
            line,
            re.I,
        ))
        if tokens:
            reconstructed = ''.join(t.group(0) for t in tokens)
            line_clean = re.sub(r'[\s,，;；、|/／-]+', '', line)
            recon_clean = re.sub(r'[\s,，;；、|/／-]+', '', reconstructed)
            if line_clean == recon_clean:
                return True
        return False

    def extract_direct_choice_answers_from_text(self, text):
        """Extract choice question answers from bulk answer text.

        Rule:
        Any item/line where a question number is followed ONLY by option letters
        A, B, C, D (and optional separators) with no other content is judged
        as a choice question answer. Choice questions can be interspersed between
        fill-in-the-blank questions.
        """
        text = unicodedata.normalize('NFKC', str(text or ''))
        text = text.replace('\u3000', ' ')
        results = {}
        for raw_line in text.splitlines():
            line = raw_line.strip()
            if not line or line.startswith('#'):
                continue
            m = re.match(
                r'^(?:第\s*)?[(（【\[]?\s*([1-9]\d{0,2})\s*[)）】\]]?(?:题|答案)?\s*[:：.．、,，=|-]?\s*([A-D](?:\s*[,，、/／ ]?\s*[A-D])*)\s*$',
                line,
                re.I,
            )
            if m:
                qno = int(m.group(1))
                opts = list(''.join(re.findall(r'[A-D]', m.group(2).upper())))
                if opts:
                    results[qno] = opts
                continue
            tokens = list(re.finditer(
                r'(?:第\s*)?[(（【\[]?\s*([1-9]\d{0,2})\s*[)）】\]]?(?:题|答案)?\s*[:：.．、,，=|-]?\s*([A-D](?:\s*[,，、/／ ]?\s*[A-D])*)',
                line,
                re.I,
            ))
            if tokens:
                reconstructed = ''.join(t.group(0) for t in tokens)
                line_clean = re.sub(r'[\s,，;；、|/／-]+', '', line)
                recon_clean = re.sub(r'[\s,，;；、|/／-]+', '', reconstructed)
                if line_clean == recon_clean:
                    for t in tokens:
                        qno = int(t.group(1))
                        opts = list(''.join(re.findall(r'[A-D]', t.group(2).upper())))
                        if opts:
                            results[qno] = opts
        return results

    def reassign_zones_choice_questions_by_slot(self, zones, new_qnos):
        """Reassign choice question numbers across zones by logical question slot.

        Supports questions spanning across front and back page boundary (e.g. Q6
        having 1 option on front and 3 options on back).
        """
        if not zones or not new_qnos:
            return 0
        total_boxes = sum(len(q.get('options', {})) for z in zones for q in z.get('questions', []))
        total_slots = total_boxes // 4
        if total_slots != len(new_qnos):
            return 0

        accum = 0
        slot_idx = 0
        for zone in zones:
            for q in zone.get('questions', []):
                if slot_idx < len(new_qnos):
                    qno = int(new_qnos[slot_idx])
                    q['question_no_in_zone'] = qno
                    q['question_label'] = f'第{qno}题'
                    accum += len(q.get('options', {}))
                    if accum >= 4:
                        accum = 0
                        slot_idx += 1
        return slot_idx

    def sync_direct_paper_choice_questions_from_answer_text(self, text):
        """Synchronize direct paper choice question numbers with choice answers in text."""
        if not self.is_direct_paper_choice_template():
            return 0
        choice_answers = self.extract_direct_choice_answers_from_text(text)
        if not choice_answers:
            return 0
        new_qnos = list(choice_answers.keys())
        zones = (self.answer_config or {}).get('zones', [])
        if not zones:
            return 0

        # Check if current question numbers already match new_qnos
        current_qnos = []
        for zone in zones:
            for q in zone.get('questions', []):
                qno = q.get('question_no_in_zone')
                if qno not in current_qnos:
                    current_qnos.append(qno)
        if current_qnos == new_qnos:
            return len(new_qnos)

        reassigned = self.reassign_zones_choice_questions_by_slot(zones, new_qnos)
        if not reassigned:
            return 0

        # Update self.direct_paper_structure if present
        if isinstance(getattr(self, 'direct_paper_structure', None), dict):
            dps_zones = self.direct_paper_structure.get('answer_config', {}).get('zones', [])
            self.reassign_zones_choice_questions_by_slot(dps_zones, new_qnos)

        # Update self.template_structure if present
        if isinstance(getattr(self, 'template_structure', None), dict):
            self.reassign_zones_choice_questions_by_slot(
                self.template_structure.get('zones', []),
                new_qnos,
            )

        # Update answer_config disk file if present
        paths = getattr(self, 'current_template_paths', {}) or {}
        answer_config_path = Path(paths.get('answer_config') or '')
        if answer_config_path.exists():
            try:
                disk_config = json.loads(answer_config_path.read_text(encoding='utf-8-sig'))
                disk_zones = disk_config.get('zones', [])
                if self.reassign_zones_choice_questions_by_slot(disk_zones, new_qnos):
                    disk_config['updated_at'] = datetime.now().isoformat(timespec='seconds')
                    atomic_write_json(answer_config_path, disk_config)
            except Exception:
                pass

        # Update loaded_answer_key_scheme_path if present
        scheme_path = Path(str(getattr(self, 'loaded_answer_key_scheme_path', '') or ''))
        if scheme_path.exists():
            try:
                scheme_data = json.loads(scheme_path.read_text(encoding='utf-8-sig'))
                scheme_zones = scheme_data.get('direct_paper_structure', {}).get('answer_config', {}).get('zones', [])
                if self.reassign_zones_choice_questions_by_slot(scheme_zones, new_qnos):
                    atomic_write_json(scheme_path, scheme_data)
            except Exception:
                pass

        return reassigned

    def parse_direct_paper_subjective_answers(self, text, capture_labels=False, diagnostics=None):
        if diagnostics is None:
            diagnostics = {}
        unassigned_values = diagnostics.setdefault('unassigned_subjective_values', [])
        unassigned_sources = diagnostics.setdefault('unassigned_subjective_sources', [])
        text = unicodedata.normalize('NFKC', str(text or ''))
        text = text.replace('\u3000', ' ')
        text = re.sub(
            r'(\d+(?:\.\d+)?)\s*[×xX*]\s*10\s*([+-]?\d+)',
            r'\1x10^\2',
            text,
        )
        text = re.sub(r'[ \t\r\f\v]+', ' ', text)
        text = re.sub(r'\s+\)', ')', text)
        text = re.sub(r'\(\s+', '(', text)
        text = re.sub(r'\n\s+', '\n', text).strip()
        ordered_parts = self.direct_paper_subjective_parts_in_order()
        if not ordered_parts:
            return ({}, {}) if capture_labels else {}
        objective_qnos = {
            int(qno)
            for qno in self.current_objective_question_numbers()
            if str(qno).isdigit()
        }
        calculation_qnos = {
            int(q.get('question_no'))
            for q in self.calculation_question_config()
            if q.get('question_no') is not None
        }
        values = {}
        label_updates = {}
        used_ids = set()
        pending_drawings = []
        cursor = 0
        current_question = None
        explicit_patterns = [
            re.compile(r'^\s*([FB]\s*0*\d{1,3})\s*(?:[.、:：=]|-|\s)\s*(.+?)\s*$', re.I),
            re.compile(r'^\s*(?:第\s*)?(空|横线)\s*0*(\d{1,3})\s*(?:空|横线)?\s*(?:[.、:：=]|-|\s)\s*(.+?)\s*$', re.I),
        ]
        question_patterns = [
            re.compile(r'^\s*(?:第\s*)?(\d{1,3})\s*(?:题)?\s*[.．、:：]\s*(?:[（(]\s*(\d+)\s*[）)])?\s*(.*?)\s*$'),
            re.compile(r'^\s*(?:第\s*)?(\d{1,3})\s*(?:题)?\s*[（(]\s*(\d+)\s*[）)]\s*(?:[.．、:：])?\s*(.*?)\s*$'),
        ]
        subquestion_pattern = re.compile(r'^\s*[（(]\s*(\d+)\s*[）)]\s*(.*?)\s*$')
        f_pattern = re.compile(r'^\s*([FB]\s*0*\d{1,3})\s+(.+?)\s*$', re.I)

        def add_unassigned(value, answer_label=''):
            """Keep the source of an overflow answer so the import dialog is actionable."""
            value = str(value or '').strip()
            if not value:
                return
            label = re.sub(
                r'\s+', '', unicodedata.normalize('NFKC', str(answer_label or '')).strip()
            )
            unassigned_values.append(value)
            unassigned_sources.append({'value': value, 'label': label})

        def is_drawing_placeholder(value):
            normalized = unicodedata.normalize('NFKC', str(value or '')).strip().lower()
            normalized = re.sub(r'\s+', '', normalized)
            return normalized == '/' or self.is_direct_subjective_drawing_label(normalized)

        def claim_pending_drawing(answer_label=''):
            answer_label = re.sub(
                r'\s+', '',
                unicodedata.normalize('NFKC', str(answer_label or '')).strip(),
            )
            while pending_drawings:
                part = pending_drawings.pop(0)
                part_id = part.get('part_id')
                if not part_id:
                    continue
                values[part_id] = '作图'
                used_ids.add(part_id)
                if answer_label:
                    label_updates[part_id] = answer_label
                return True
            return False

        def assign_to_parts(parts, split_values, answer_label=''):
            answer_label = unicodedata.normalize('NFKC', str(answer_label or '')).strip()
            answer_label = re.sub(r'\s+', '', answer_label)
            assigned = 0
            available_parts = [
                part for part in parts
                if part.get('part_id') and part.get('part_id') not in used_ids
            ]
            for part, value in zip(available_parts, split_values):
                part_id = part.get('part_id')
                value = str(value or '').strip()
                if value:
                    values[part_id] = '作图' if part.get('kind') == 'drawing' and is_drawing_placeholder(value) else value
                    if answer_label:
                        label_updates[part_id] = answer_label
                    used_ids.add(part_id)
                    assigned += 1
            for value in split_values[len(available_parts):]:
                value = str(value or '').strip()
                if value:
                    add_unassigned(value, answer_label)
            return assigned

        def assign_sequential(split_values, answer_label=''):
            nonlocal cursor
            answer_label = unicodedata.normalize('NFKC', str(answer_label or '')).strip()
            answer_label = re.sub(r'\s+', '', answer_label)
            for value in split_values:
                value = str(value or '').strip()
                if is_drawing_placeholder(value) and claim_pending_drawing(answer_label):
                    continue
                while cursor < len(ordered_parts) and (
                    ordered_parts[cursor].get('part_id') in used_ids
                ):
                    cursor += 1
                # The structure already tells us which physical lines are
                # drawings. Even if the pasted answer omits a drawing line,
                # reserve it automatically instead of shifting later answers.
                while (
                    cursor < len(ordered_parts)
                    and ordered_parts[cursor].get('kind') == 'drawing'
                    and not is_drawing_placeholder(value)
                ):
                    drawing_part = ordered_parts[cursor]
                    drawing_part_id = drawing_part.get('part_id')
                    if drawing_part_id:
                        values[drawing_part_id] = '作图'
                        used_ids.add(drawing_part_id)
                        pending_drawings.append(drawing_part)
                    cursor += 1
                if cursor >= len(ordered_parts):
                    value = str(value or '').strip()
                    if value:
                        add_unassigned(value, answer_label)
                    continue
                part = ordered_parts[cursor]
                part_id = part.get('part_id')
                if part_id and value:
                    if is_drawing_placeholder(value) and part.get('kind') != 'drawing':
                        add_unassigned(value, answer_label)
                        continue
                    values[part_id] = '作图' if part.get('kind') == 'drawing' else value
                    if answer_label:
                        label_updates[part_id] = answer_label
                    used_ids.add(part_id)
                cursor += 1

        for raw_line in str(text or '').splitlines():
            line = raw_line.strip()
            if not line or line.startswith('#'):
                continue
            if self.is_pure_choice_answer_line(line):
                continue

            explicit_match = None
            explicit_marker = None
            explicit_answer = None
            for pattern in explicit_patterns:
                explicit_match = pattern.match(line)
                if explicit_match:
                    if len(explicit_match.groups()) == 2:
                        explicit_marker, explicit_answer = explicit_match.group(1), explicit_match.group(2)
                    else:
                        explicit_marker = explicit_match.group(2)
                        explicit_answer = explicit_match.group(3)
                    break
            if not explicit_match:
                f_match = f_pattern.match(line)
                if f_match:
                    explicit_marker, explicit_answer = f_match.group(1), f_match.group(2)
            if explicit_marker:
                part = self.direct_paper_subjective_part_by_marker(str(explicit_marker).replace(' ', ''), ordered_parts)
                if part and explicit_answer:
                    assign_to_parts(
                        [part],
                        [self.normalize_bulk_answer_text(explicit_answer).strip(' ：:，,；;。.')],
                        str(explicit_marker).replace(' ', ''),
                    )
                continue

            qno = None
            sub_no = None
            answer = ''
            for pattern in question_patterns:
                q_match = pattern.match(line)
                if q_match:
                    qno = int(q_match.group(1))
                    sub_no = q_match.group(2)
                    answer = q_match.group(3) or ''
                    current_question = qno
                    break
            if qno is None:
                sub_match = subquestion_pattern.match(line)
                if sub_match and current_question is not None:
                    qno = current_question
                    sub_no = sub_match.group(1)
                    answer = sub_match.group(2) or ''
            if qno is None or qno in calculation_qnos:
                continue

            marker = f'{qno}({sub_no})' if sub_no else str(qno)
            split_values = self.split_direct_paper_subjective_values(answer)
            if not split_values:
                # A line such as "8." is commonly used as an empty drawing
                # placeholder. It must still reserve the next drawing part so
                # the following fill-in answers cannot slide into that slot.
                while cursor < len(ordered_parts) and ordered_parts[cursor].get('part_id') in used_ids:
                    cursor += 1
                if qno not in objective_qnos:
                    if not claim_pending_drawing(marker) and (
                        cursor < len(ordered_parts)
                        and ordered_parts[cursor].get('kind') == 'drawing'
                    ):
                        assign_sequential(['作图'], marker)
                continue
            if (
                sub_no is None
                and len(split_values) == 1
                and re.fullmatch(r'[A-D](?:\s*[,，、/／ ]?\s*[A-D])*', split_values[0], re.I)
            ):
                continue
            if all(is_drawing_placeholder(value) for value in split_values):
                # Drawing lines occupy their normal physical position exactly
                # like every other blank. Keeping one sequential cursor avoids
                # shifting every answer that follows a drawing item.
                assign_sequential(['作图'] * len(split_values), marker)
                continue
            # A complete pasted answer is authoritative. Existing labels may
            # come from another paper or an earlier bad import, so never use
            # them to jump to a physical blank here.
            assign_sequential(split_values, marker)
        for part in ordered_parts:
            part_id = part.get('part_id')
            if part.get('kind') == 'drawing' and part_id and part_id not in values:
                values[part_id] = '作图'
        return (values, label_updates) if capture_labels else values

    def sync_direct_paper_subjective_labels_from_answer_text(self, text):
        if not self.is_direct_paper_choice_template():
            return 0
        _values, labels_by_part_id = self.parse_direct_paper_subjective_answers(text, capture_labels=True)
        if not labels_by_part_id:
            return 0
        return self.apply_direct_subjective_answer_labels(labels_by_part_id)

    def apply_direct_subjective_answer_labels(self, labels_by_part_id):
        labels_by_part_id = {
            str(part_id): re.sub(r'\s+', '', unicodedata.normalize('NFKC', str(label or '')).strip())
            for part_id, label in (labels_by_part_id or {}).items()
            if str(part_id or '').strip() and str(label or '').strip()
        }
        if not labels_by_part_id:
            return 0
        line_config_path = self.direct_subjective_line_config_path()
        if not line_config_path.exists():
            return 0
        try:
            line_config = json.loads(line_config_path.read_text(encoding='utf-8-sig'))
        except Exception:
            return 0
        changed = 0
        drawing_labels = set()
        sides = line_config.get('sides') if isinstance(line_config.get('sides'), dict) else {}
        for side in ('front', 'back'):
            side_payload = sides.get(side) or {}
            ordered_lines = self.sort_direct_subjective_lines_reading_order(side_payload.get('lines') or [])
            prefix = 'F' if side == 'front' else 'B'
            for order, line in enumerate(ordered_lines, 1):
                source_index = int(line.get('index', order) or order)
                fill_part_id = f'q{prefix}{order:03d}_b1'
                drawing_part_id = f'q{prefix}{order:03d}_drawing_{source_index}'
                drawing_label = labels_by_part_id.get(drawing_part_id)
                label = labels_by_part_id.get(fill_part_id) or drawing_label
                if not label:
                    continue
                if drawing_label or str(line.get('kind') or '').strip().lower() == 'drawing':
                    drawing_labels.add(label)
                if str(line.get('answer_label') or '') != label:
                    line['answer_label'] = label
                    changed += 1
        if drawing_labels:
            for side in ('front', 'back'):
                side_payload = sides.get(side) or {}
                ordered_lines = self.sort_direct_subjective_lines_reading_order(side_payload.get('lines') or [])
                for line in ordered_lines:
                    if str(line.get('kind') or '').strip().lower() == 'drawing':
                        continue
                    if str(line.get('answer_label') or '').strip() in drawing_labels:
                        line['answer_label'] = ''
                        changed += 1
        if not changed:
            return 0
        line_config['updated_at'] = datetime.now().isoformat(timespec='seconds')
        atomic_write_json(line_config_path, line_config)
        self.sync_direct_subjective_lines_to_subjective_config(line_config)
        return changed

    def parse_bulk_answer_text(self, text, diagnostics=None):
        if diagnostics is None:
            diagnostics = {}
        duplicate_objective = diagnostics.setdefault('duplicate_objective_questions', [])
        unexpected_objective = diagnostics.setdefault('unexpected_objective_questions', [])
        subjective_overflow = diagnostics.setdefault('subjective_overflow', [])
        text = unicodedata.normalize('NFKC', str(text or ''))
        text = text.replace('\u3000', ' ')
        text = re.sub(
            r'(\d+(?:\.\d+)?)\s*[×xX*]\s*10\s*([+-]?\d+)',
            r'\1x10^\2',
            text,
        )
        text = re.sub(r'[ \t\r\f\v]+', ' ', text)
        text = re.sub(r'\s+\)', ')', text)
        text = re.sub(r'\(\s+', '(', text)
        text = re.sub(r'\n\s+', '\n', text).strip()
        answer_map = {}
        subjective_values = {}

        if self.is_direct_paper_choice_template():
            self.sync_direct_paper_choice_questions_from_answer_text(text)
            direct_choices = self.extract_direct_choice_answers_from_text(text)
            for qno, opts in direct_choices.items():
                if qno in answer_map and qno not in duplicate_objective:
                    duplicate_objective.append(qno)
                answer_map[qno] = opts

        objective_qnos = {
            int(qno)
            for qno in self.current_objective_question_numbers()
            if str(qno).isdigit()
        }
        subjective_qnos = set()
        for part in self.iter_subjective_parts():
            match = re.search(r'\d+', str(part.get('question_no') or part.get('label') or ''))
            if match:
                subjective_qnos.add(int(match.group()))
        objective_pattern = re.compile(
            r'(?<![\d^])(?:第\s*)?([1-9]\d{0,2})\s*(?:[.、,，:：]|题|答案|=|-)?\s*((?:[A-D]\s*[,，、/ ]?\s*){1,4})(?![a-zA-Z])',
            re.I,
        )
        for match in objective_pattern.finditer(text):
            qno = int(match.group(1))
            if qno in answer_map:
                continue
            if qno not in objective_qnos:
                if qno not in subjective_qnos and qno not in unexpected_objective:
                    unexpected_objective.append(qno)
                continue
            answer = ''.join(re.findall(r'[A-D]', match.group(2).upper()))
            if not answer:
                continue
            if qno in answer_map and qno not in duplicate_objective:
                duplicate_objective.append(qno)
            answer_map[qno] = list(answer)

        if self.is_direct_paper_choice_template():
            return answer_map, self.parse_direct_paper_subjective_answers(text, diagnostics=diagnostics)

        def part_sort_key(part):
            part_id = str(part.get('part_id') or '')
            sub_match = re.match(r'q(\d+)_s(\d+)_b(\d+)$', part_id)
            if sub_match:
                return tuple(int(item) for item in sub_match.groups())
            blank_match = re.match(r'q(\d+)_b(\d+)$', part_id)
            if blank_match:
                qno, blank_no = (int(item) for item in blank_match.groups())
                return (qno, 0, blank_no)
            return (999, 999, 999)

        parts_by_question = defaultdict(list)
        for part in self.iter_subjective_parts():
            if part.get('kind') == 'drawing':
                continue
            parts_by_question[part.get('question_no')].append(part)
        for qno in parts_by_question:
            parts_by_question[qno].sort(key=part_sort_key)
        question_ordered_parts = {
            qno: sorted(parts, key=part_sort_key)
            for qno, parts in parts_by_question.items()
        }
        used_subjective_part_ids = set()

        experiment_sequence = []
        for qno in range(20, 24):
            grouped = defaultdict(list)
            for part in parts_by_question.get(qno, []):
                match = re.match(r'q\d+_s(\d+)_b\d+$', str(part.get('part_id') or ''))
                if match:
                    grouped[int(match.group(1))].append(part)
            for sub_no in sorted(grouped):
                experiment_sequence.append((qno, sub_no, sorted(grouped[sub_no], key=part_sort_key)))

        # Question numbers are only treated as anchors at line starts. This
        # avoids answers such as "21.4" being parsed as "第21题".
        marker_pattern = re.compile(
            r'(?:'
            r'(?m:^\s*(1[3-8])\s*[.．、:：]\s*)'
            r'|'
            r'(?m:^\s*(2[0-3])\s*[.．、:：]?\s*(?:[（(]\s*([1-9])\s*[）)])?\s*)'
            r'|'
            r'[（(]([1-9])[）)]\s*[.．、:：]?\s*'
            r')'
        )
        markers = list(marker_pattern.finditer(text))
        implicit_cursor = 0
        current_experiment_question = None

        def explicit_value_count(segment):
            segment = self.normalize_bulk_answer_text(segment)
            values = [
                item.strip(' ：:，,；;')
                for item in re.split(r'[；;，,]+', segment)
                if item.strip(' ：:，,；;')
            ]
            return len(values)

        def expand_parts_for_values(qno, base_parts, needed_count):
            base_parts = list(base_parts or [])
            available_base_parts = [
                part for part in base_parts
                if part.get('part_id') not in used_subjective_part_ids
            ]
            if needed_count <= len(available_base_parts):
                return available_base_parts
            ordered = question_ordered_parts.get(qno, [])
            if not ordered:
                return available_base_parts or base_parts
            start_index = 0
            if base_parts:
                first_id = base_parts[0].get('part_id')
                for idx_part, ordered_part in enumerate(ordered):
                    if ordered_part.get('part_id') == first_id:
                        start_index = idx_part
                        break
            else:
                for idx_part, ordered_part in enumerate(ordered):
                    if ordered_part.get('part_id') not in used_subjective_part_ids:
                        start_index = idx_part
                        break
            expanded = []
            for ordered_part in ordered[start_index:]:
                part_id = ordered_part.get('part_id')
                if part_id in used_subjective_part_ids:
                    continue
                expanded.append(ordered_part)
                if len(expanded) >= needed_count:
                    break
            if len(expanded) >= needed_count:
                return expanded
            known_ids = {part.get('part_id') for part in expanded}
            for part in base_parts:
                if part.get('part_id') not in known_ids:
                    expanded.append(part)
                    if len(expanded) >= needed_count:
                        break
            return expanded

        for idx, marker in enumerate(markers):
            start = marker.end()
            end = markers[idx + 1].start() if idx + 1 < len(markers) else len(text)
            segment = text[start:end].strip()
            if marker.group(1):
                qno = int(marker.group(1))
                parts = parts_by_question.get(qno, [])
            elif marker.group(2):
                qno = int(marker.group(2))
                current_experiment_question = qno
                if not marker.group(3):
                    parts = []
                    for seq_index, (seq_qno, _seq_sub_no, seq_parts) in enumerate(experiment_sequence):
                        if seq_qno == qno:
                            parts = seq_parts
                            implicit_cursor = max(implicit_cursor, seq_index + 1)
                            break
                else:
                    sub_no = int(marker.group(3))
                    prefix = f'q{qno}_s{sub_no}_b'
                    parts = [part for part in parts_by_question.get(qno, []) if str(part.get('part_id', '')).startswith(prefix)]
                    parts.sort(key=part_sort_key)
                    for seq_index, (seq_qno, seq_sub_no, _seq_parts) in enumerate(experiment_sequence):
                        if seq_qno == qno and seq_sub_no == sub_no:
                            implicit_cursor = max(implicit_cursor, seq_index + 1)
                            break
            else:
                implicit_sub_no = int(marker.group(4))
                parts = []
                chosen_index = None
                if current_experiment_question in range(20, 24):
                    qno = current_experiment_question
                    prefix = f'q{qno}_s{implicit_sub_no}_b'
                    parts = [part for part in parts_by_question.get(qno, []) if str(part.get('part_id', '')).startswith(prefix)]
                    parts.sort(key=part_sort_key)
                    for seq_index, (seq_qno, seq_sub_no, _seq_parts) in enumerate(experiment_sequence):
                        if seq_qno == qno and seq_sub_no == implicit_sub_no:
                            chosen_index = seq_index
                            break
                else:
                    for seq_index in range(implicit_cursor, len(experiment_sequence)):
                        seq_qno, seq_sub_no, seq_parts = experiment_sequence[seq_index]
                        if seq_sub_no == implicit_sub_no:
                            parts = seq_parts
                            chosen_index = seq_index
                            break
                if not parts and implicit_cursor < len(experiment_sequence):
                    _seq_qno, _seq_sub_no, parts = experiment_sequence[implicit_cursor]
                    chosen_index = implicit_cursor
                if chosen_index is not None:
                    implicit_cursor = chosen_index + 1
            if not segment or not parts:
                continue
            wanted_count = max(len(parts), explicit_value_count(segment))
            if qno in question_ordered_parts:
                wanted_count = min(wanted_count, len(question_ordered_parts.get(qno) or parts))
            parts = expand_parts_for_values(qno, parts, wanted_count)
            pasted_count = explicit_value_count(segment)
            if pasted_count > len(parts):
                subjective_overflow.append({
                    'label': str(qno),
                    'provided': pasted_count,
                    'capacity': len(parts),
                })
            values = self.split_bulk_answer_values(segment, len(parts))
            for part, value in zip(parts, values):
                value = value.strip()
                if value:
                    subjective_values[part['part_id']] = value
                    used_subjective_part_ids.add(part['part_id'])

        return answer_map, subjective_values

    def open_integrated_answer_scheme_builder(self):
        if not self.context_change_allowed():
            return
        if self.current_template_mode != 'grader':
            messagebox.showinfo('提示', '当前模板是采集模式，不需要设置标准答案。')
            return
        remembered_path = Path(str(getattr(self, 'loaded_answer_key_scheme_path', '') or ''))
        remembered_payload = {}
        if not self.current_session and remembered_path.is_file():
            try:
                remembered_payload = json.loads(remembered_path.read_text(encoding='utf-8-sig'))
            except Exception:
                remembered_payload = {}

        if not self.has_standard_answers() and remembered_payload:
            remembered_answer_map = self.extract_answer_map(remembered_payload.get('answer_key') or {})
            if any(bool(values) for values in remembered_answer_map.values()):
                self.set_global_answer_map(remembered_answer_map)

        # 确保打开方案窗口时自动恢复知识点清单，不显示“未导入”
        if not self.normalize_knowledge_identity_payload(getattr(self, 'knowledge_identity_payload', {}) or {}):
            if remembered_payload.get('knowledge_identity'):
                self.knowledge_identity_payload = self.normalize_knowledge_identity_payload(
                    remembered_payload.get('knowledge_identity')
                )
            elif self.current_session and hasattr(self, 'session_answer_key_path'):
                try:
                    s_path = self.session_answer_key_path()
                    if s_path and s_path.exists():
                        s_payload = json.loads(s_path.read_text(encoding='utf-8-sig'))
                        if s_payload.get('knowledge_identity'):
                            self.knowledge_identity_payload = self.normalize_knowledge_identity_payload(
                                s_payload.get('knowledge_identity')
                            )
                except Exception:
                    pass
            if not self.normalize_knowledge_identity_payload(getattr(self, 'knowledge_identity_payload', {}) or {}) and getattr(self, 'selected_folder_path', None):
                try:
                    folder = Path(self.selected_folder_path)
                    csv_candidates = [p for p in folder.glob('*.csv') if '知识点' in p.stem and not p.name.startswith('~$')]
                    if csv_candidates:
                        csv_candidates.sort(key=lambda p: p.stat().st_mtime, reverse=True)
                        self.knowledge_identity_payload = self.read_knowledge_identity_csv(csv_candidates[0])
                except Exception:
                    pass

        self.refresh_current_template_config_from_disk()
        if self.is_direct_paper_choice_template() and getattr(self, 'selected_folder_path', None):
            try:
                folder = Path(self.selected_folder_path)
                match_res = self.find_folder_answer_template_files(folder)
                word_path = match_res.get('word')
                if word_path:
                    w_payload = self.read_word_answer_template(word_path)
                    if w_payload.get('answer_text'):
                        self.sync_direct_paper_choice_questions_from_answer_text(w_payload['answer_text'])
            except Exception:
                pass
        self.ensure_answer_scheme_matches_current_structure(persist=False)

        win = tk.Toplevel(self.root)
        win.title('一体化设置答案方案')
        self.track_context_window(win)
        win.geometry('1480x820')
        win.minsize(1180, 700)
        win.transient(self.root)
        self.answer_key_window = win

        top = ttk.Frame(win)
        top.pack(fill=tk.X, padx=12, pady=(10, 6))
        ttk.Label(top, text='方案名称：').pack(side=tk.LEFT)
        selected_folder_name = Path(self.selected_folder_path).name if self.selected_folder_path else ''
        scheme_var = tk.StringVar(
            value=selected_folder_name
            or getattr(self, 'loaded_answer_key_scheme_name', '')
            or datetime.now().strftime('%Y%m%d-%H%M%S')
        )
        ttk.Entry(top, textvariable=scheme_var, width=28).pack(side=tk.LEFT, padx=(4, 12))
        status_var = tk.StringVar(value='可以从 Word 答案直接复制粘贴，然后点“解析到下方”。')
        ttk.Label(top, textvariable=status_var, foreground='#555').pack(side=tk.LEFT, fill=tk.X, expand=True)
        structure_status_var = tk.StringVar()
        knowledge_status_var = tk.StringVar(value=self.knowledge_identity_summary())

        knowledge_bar = ttk.Frame(win)
        knowledge_bar.pack(fill=tk.X, padx=12, pady=(0, 4))
        knowledge_import_button = ttk.Button(knowledge_bar, text='导入知识点清单CSV')
        knowledge_import_button.pack(side=tk.RIGHT, padx=(8, 0))
        ttk.Label(
            knowledge_bar,
            textvariable=knowledge_status_var,
            foreground='#0B5CAD',
        ).pack(side=tk.LEFT, fill=tk.X, expand=True)

        calculation_text = None
        calculation_preview_var = tk.StringVar(win, value='')
        calculation_preview_label = None

        def update_calculation_preview(*_args):
            if calculation_text is None:
                return
            raw_val = calculation_text.get('1.0', tk.END).strip()
            if not raw_val:
                calculation_preview_var.set('（当前未设置计算题，留空表示本试卷无计算题）')
                if calculation_preview_label:
                    calculation_preview_label.config(foreground='#6b7280')
                return
            try:
                parsed_questions = self.parse_calculation_question_text(raw_val, allow_empty=True)
                if not parsed_questions:
                    calculation_preview_var.set('（当前未设置计算题，留空表示本试卷无计算题）')
                    if calculation_preview_label:
                        calculation_preview_label.config(foreground='#6b7280')
                    return
                parts_desc = []
                total_calc_score = 0.0
                for q in parsed_questions:
                    qno = q['question_no']
                    subs = q.get('sub_scores') or []
                    sub_desc = '、'.join(f"({s['sub_no']}){s['score']:g}分" for s in subs)
                    q_tot = q.get('max_score') or sum(s['score'] for s in subs)
                    total_calc_score += q_tot
                    parts_desc.append(f"第{qno}题（共{len(subs)}个小题：{sub_desc}，小计{q_tot:g}分）")
                summary_text = '✓ 已识别计算题：' + '；'.join(parts_desc) + f'  |  计算题总满分：{total_calc_score:g}分'
                calculation_preview_var.set(summary_text)
                if calculation_preview_label:
                    calculation_preview_label.config(foreground='#15803d')
            except Exception as e:
                calculation_preview_var.set(f'⚠ 格式提示：{e}')
                if calculation_preview_label:
                    calculation_preview_label.config(foreground='#dc2626')

        if self.is_direct_paper_choice_template() or self.is_mixed_objective_subjective_template():
            calculation_frame = ttk.LabelFrame(win, text='计算题（背面人工打分，不设置标准答案）')
            calculation_frame.pack(fill=tk.X, padx=12, pady=(0, 4))
            calculation_hint = (
                '每行一题，冒号后用逗号依次写各小题分值（写几个数字就生成几个小题）。'
                '例：15: 2, 2, 2 表示 15(1)满分2分、15(2)满分2分、15(3)满分2分；也可以分行写 15(1): 2、15(2): 2、15(3): 2。'
                '留空表示本方案没有计算题。'
            )
            if self.is_direct_paper_choice_template():
                if not self.direct_paper_has_calculation_structure():
                    calculation_hint += ' 【当前正反面结构未勾选背面计算题，导入Word时会自动略过Word中的计算题赋分】'
                else:
                    calculation_hint += ' 背面结构中启用计算题区域后，人工打分时会自动显示对应裁图。'
            ttk.Label(calculation_frame, text=calculation_hint, wraplength=1380).pack(anchor='w', padx=8, pady=(6, 2))
            calculation_text = scrolledtext.ScrolledText(calculation_frame, height=2, wrap=tk.WORD, font=('Consolas', 11))
            calculation_text.pack(fill=tk.X, padx=8, pady=(0, 3))
            calculation_preview_label = ttk.Label(
                calculation_frame,
                textvariable=calculation_preview_var,
                font=('Arial', 10, 'bold'),
                foreground='#15803d',
                wraplength=1380,
            )
            calculation_preview_label.pack(anchor='w', padx=8, pady=(0, 5))
            calculation_text.insert('1.0', self.format_calculation_question_config())
            calculation_text.bind('<KeyRelease>', update_calculation_preview)
            calculation_text.bind('<FocusOut>', update_calculation_preview)
            update_calculation_preview()

        paned = ttk.PanedWindow(win, orient=tk.VERTICAL)
        paned.pack(fill=tk.BOTH, expand=True, padx=12, pady=6)

        paste_frame = ttk.Frame(paned)
        paned.add(paste_frame, weight=1)
        ttk.Label(
            paste_frame,
            text='粘贴答案文本：选择题可写 1.B、2 D、3：C、11.BD、12. A B。主观题按题号/小题号写答案；逗号、中文逗号、分号都表示分到下一个空。同一空多个可接受答案请用 / 或“或”，如 增大/变大。',
            font=('Arial', 10, 'bold'),
        ).pack(anchor='w', pady=(0, 4))
        ttk.Label(
            paste_frame,
            textvariable=structure_status_var,
            foreground='#9A3412',
            wraplength=1400,
        ).pack(anchor='w', pady=(0, 4))
        answer_text = scrolledtext.ScrolledText(paste_frame, height=8, wrap=tk.WORD, font=('Consolas', 11))
        answer_text.pack(fill=tk.BOTH, expand=True)

        edit_frame = ttk.Frame(paned)
        paned.add(edit_frame, weight=3)

        objective_frame = ttk.LabelFrame(edit_frame, text='选择题答案')
        objective_frame.pack(side=tk.LEFT, fill=tk.Y, padx=(0, 8), pady=4)
        subjective_frame = ttk.LabelFrame(edit_frame, text='填空/实验题 OCR 空位设置（含【拆字判错】）')
        subjective_frame.pack(side=tk.LEFT, fill=tk.BOTH, expand=True, padx=(8, 0), pady=4)

        current_answers = self.extract_answer_map(self.answer_key or self.loaded_answer_key)
        answer_zone = self.merged_objective_answer_zone()
        objective_rows = {}

        def refresh_objective_buttons(button_map, selected_values):
            selected_set = {str(value).strip().upper() for value in selected_values}
            for key, btn in button_map.items():
                if key.upper() in selected_set:
                    btn.config(relief='sunken', bg='#4CAF50', fg='white')
                else:
                    btn.config(relief='raised', bg='SystemButtonFace', fg='black')

        grid = ttk.Frame(objective_frame)
        grid.pack(fill=tk.Y, padx=8, pady=8)

        def rebuild_objective_rows():
            for child in grid.winfo_children():
                child.destroy()
            objective_rows.clear()
            curr_answers = self.extract_answer_map(self.answer_key or self.loaded_answer_key)
            ans_zone = self.merged_objective_answer_zone()
            for row_idx, question in enumerate(ans_zone.get('questions', []), start=1):
                qno = int(question.get('question_no_in_zone'))
                ttk.Label(grid, text=f'{qno}.').grid(row=row_idx, column=0, padx=4, pady=3, sticky='e')
                holder = tk.Frame(grid)
                holder.grid(row=row_idx, column=1, padx=4, pady=3, sticky='w')
                options = list(question.get('options', {}).keys()) or ['A', 'B', 'C', 'D']
                selected = set(curr_answers.get(qno) or curr_answers.get(str(qno)) or [])
                state = {'selected': {str(item).upper() for item in selected}}
                buttons = {}
                is_single = self.question_type_for(qno, question) == 'single'

                def make_toggle(opt, state_ref=state, buttons_ref=buttons, single=is_single):
                    def _toggle():
                        opt_key = opt.upper()
                        if single:
                            state_ref['selected'] = set() if opt_key in state_ref['selected'] else {opt_key}
                        else:
                            if opt_key in state_ref['selected']:
                                state_ref['selected'].remove(opt_key)
                            else:
                                state_ref['selected'].add(opt_key)
                        refresh_objective_buttons(buttons_ref, state_ref['selected'])
                    return _toggle

                for opt in options:
                    btn = tk.Button(holder, text=opt, width=3, command=make_toggle(opt))
                    btn.pack(side=tk.LEFT, padx=2)
                    buttons[opt.upper()] = btn
                refresh_objective_buttons(buttons, state['selected'])
                objective_rows[qno] = {'state': state, 'buttons': buttons}

        rebuild_objective_rows()

        ocr_canvas = tk.Canvas(subjective_frame, bg='#f7f7f7')
        ocr_scroll = ttk.Scrollbar(subjective_frame, orient=tk.VERTICAL, command=ocr_canvas.yview)
        ocr_body = ttk.Frame(ocr_canvas)
        ocr_body.bind('<Configure>', lambda _e: ocr_canvas.configure(scrollregion=ocr_canvas.bbox('all')))
        ocr_canvas.create_window((0, 0), window=ocr_body, anchor='nw')
        ocr_canvas.configure(yscrollcommand=ocr_scroll.set)
        ocr_canvas.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
        ocr_scroll.pack(side=tk.RIGHT, fill=tk.Y)
        ocr_rows = {}

        def clean_integrated_ocr_config(part):
            if (part or {}).get('kind') == 'drawing':
                return self.subjective_part_setting_config(part)
            if getattr(self, 'loaded_answer_key_scheme_path', None):
                return self.normalize_ocr_config((part or {}).get('ocr'))
            config = self.default_ocr_config()
            existing = self.normalize_ocr_config((part or {}).get('ocr'))
            for key in ('pad_left', 'pad_right', 'pad_top', 'pad_bottom', 'low_confidence_threshold', 'single_char', 'unique_answer', 'choice_fill', 'split_char_check'):
                config[key] = existing.get(key, config.get(key))
            return self.normalize_ocr_config(config)

        def row_config_from_vars(vars_map):
            return self.normalize_ocr_config({
                'enabled': vars_map['enabled'].get(),
                'single_char': vars_map['single_char'].get(),
                'unique_answer': vars_map['unique_answer'].get() if 'unique_answer' in vars_map else False,
                'choice_fill': vars_map['choice_fill'].get() if 'choice_fill' in vars_map else False,
                'split_char_check': vars_map['split_char_check'].get() if 'split_char_check' in vars_map else True,
                'expected_answer': vars_map['expected_answer'].get(),
                'candidate_words': vars_map['candidate_words'].get() if 'candidate_words' in vars_map else '',
                'common_wrong_answers': vars_map['common_wrong_answers'].get(),
                'wrong_keywords': vars_map['wrong_keywords'].get(),
                'prefix': vars_map['prefix'].get(),
                'suffix': vars_map['suffix'].get(),
                'pad_left': vars_map['pad_left'].get(),
                'pad_right': vars_map['pad_right'].get(),
                'low_confidence_threshold': vars_map['low_confidence_threshold'].get(),
                'expected_keywords': vars_map['expected_keywords'].get(),
                'pad_top': 20,
                'pad_bottom': 20,
            })

        def ocr_config_has_answer_content(config):
            config = self.normalize_ocr_config(config)
            return bool(
                str(config.get('expected_answer') or '').strip()
                or str(config.get('candidate_words') or '').strip()
                or str(config.get('expected_keywords') or '').strip()
                or str(config.get('common_wrong_answers') or '').strip()
                or str(config.get('wrong_keywords') or '').strip()
            )

        def answer_text_keys(value):
            keys = []
            for answer in self.split_subjective_answers(value):
                key = self.normalize_subjective_answer_for_match(answer)
                if key and key not in keys:
                    keys.append(key)
            return keys

