    def install_text_context_menu(self, text_widget):
        menu = tk.Menu(text_widget, tearoff=0)
        menu.add_command(label='全选', command=lambda w=text_widget: self.select_all_text(w))
        menu.add_command(label='复制', command=lambda w=text_widget: self.copy_selected_text(w))

        def show_menu(event, w=text_widget, m=menu):
            try:
                w.focus_set()
                m.tk_popup(event.x_root, event.y_root)
            finally:
                m.grab_release()

        text_widget.bind('<Button-3>', show_menu)
        text_widget.bind('<Control-a>', lambda e, w=text_widget: (self.select_all_text(w), 'break')[1])
        text_widget.bind('<Control-A>', lambda e, w=text_widget: (self.select_all_text(w), 'break')[1])

    def select_all_text(self, text_widget):
        text_widget.tag_add('sel', '1.0', 'end-1c')
        text_widget.mark_set('insert', '1.0')
        text_widget.see('insert')
        return 'break'

    def copy_selected_text(self, text_widget):
        try:
            selected = text_widget.get('sel.first', 'sel.last')
        except tk.TclError:
            selected = text_widget.get('1.0', 'end-1c')
        self.root.clipboard_clear()
        self.root.clipboard_append(selected)
        return 'break'

    def normalize_answer(self, answer, question_no, question_meta=None):
        if answer is None:
            return ''
        if isinstance(answer, list):
            raw = ''.join(answer)
        else:
            raw = str(answer)
        raw = raw.strip().upper().replace('，', ',')
        if not raw or raw == '未判定':
            return ''
        if self.question_type_for(question_no, question_meta) == 'single':
            return raw[:1]
        if ',' in raw:
            parts = [p.strip() for p in raw.split(',') if p.strip()]
            return ''.join(sorted(set(parts)))
        return ''.join(sorted(set(raw)))

    def answers_equal(self, expected, actual, question_no, question_meta=None):
        return self.normalize_answer(expected, question_no, question_meta) == self.normalize_answer(actual, question_no, question_meta)

    def get_expected_answers_for_zone(self, zone_name):
        ordered = []
        for zone in self.answer_config.get('zones', []):
            if zone.get('zone_name') != zone_name:
                continue
            for question in zone.get('questions', []):
                qno = question.get('question_no_in_zone')
                val = self.expected_answers_for_question(qno)
                ordered.append(''.join(val) if val else '')
            break
        return ordered

    def subjective_items(self):
        return list((getattr(self, 'subjective_config', {}) or {}).get('items', []) or [])

    def optional_experiment_drawing_config(self):
        config = (getattr(self, 'subjective_config', {}) or {}).get('optional_experiment_drawing') or {}
        return {
            'enabled': False,
            'drawing_question_no': str(config.get('drawing_question_no') or '22-1-drawing'),
            'placeholder_part_id': str(config.get('placeholder_part_id') or 'q22_s1_b1'),
            'placeholder_normal_score': float(config.get('placeholder_normal_score') or 1),
        }

    def optional_experiment_drawing_enabled(self):
        return self.optional_experiment_drawing_config().get('enabled', False)

    def subjective_total_score(self):
        return sum(float(item.get('max_score') or 0) for item in self.subjective_items())

    def calculation_score_part_id(self, question_no, sub_no):
        return f'calc_q{question_no}_s{sub_no}'

    def calculation_score_parts(self):
        parts = []
        for question in self.calculation_question_config():
            qno = question.get('question_no')
            for item in question.get('sub_scores', []) or []:
                sub_no = item.get('sub_no')
                score = float(item.get('score') or 0)
                parts.append({
                    'part_id': self.calculation_score_part_id(qno, sub_no),
                    'question_no': qno,
                    'sub_no': sub_no,
                    'label': f'{qno}题({sub_no})',
                    'kind': 'calculation',
                    'score_category': 'calculation',
                    'region_name': 'calculation',
                    'score': score,
                    'max_score': score,
                    'manual_only': True,
                })
        return parts

    def subjective_score_parts(self, include_calculation=True):
        parts = [part for part in self.iter_subjective_parts() if float(part.get('score') or 0) > 0]
        if include_calculation and not self.mixed_template_single_side_mode_enabled():
            parts.extend([part for part in self.calculation_score_parts() if float(part.get('score') or 0) > 0])
        return parts

    def safe_file_part(self, value):
        text = re.sub(r'[\\/:*?"<>|]+', '_', str(value or '').strip())
        return text.strip(' .') or '未命名'

    def default_ocr_config(self):
        return {
            'enabled': False,
            'unique_answer': False,
            'choice_fill': False,
            'prefix': '',
            'suffix': '',
            'pad_left': 180,
            'pad_right': 180,
            'pad_top': 20,
            'pad_bottom': 20,
            'low_confidence_threshold': 0.6,
            'single_char': False,
            'split_char_check': True,
            'expected_keywords': '',
            'expected_answer': '',
            'candidate_words': '',
            'common_wrong_answers': '',
            'wrong_keywords': '',
        }

    def normalize_ocr_config(self, value):
        config = self.default_ocr_config()
        if isinstance(value, dict):
            config.update(value)
        config['enabled'] = bool(config.get('enabled'))
        config['unique_answer'] = bool(config.get('unique_answer', False))
        config['choice_fill'] = bool(config.get('choice_fill', False))
        for key in ('prefix', 'suffix'):
            config[key] = str(config.get(key) or '')
        config['expected_keywords'] = str(config.get('expected_keywords') or '')
        config['expected_answer'] = str(config.get('expected_answer') or '')
        config['candidate_words'] = str(config.get('candidate_words') or '').strip()
        config['common_wrong_answers'] = str(config.get('common_wrong_answers') or '')
        config['wrong_keywords'] = str(config.get('wrong_keywords') or '')
        config['single_char'] = bool(config.get('single_char'))
        config['split_char_check'] = bool(config.get('split_char_check', True))
        for key in ('pad_left', 'pad_right', 'pad_top', 'pad_bottom'):
            try:
                config[key] = max(0, int(config.get(key) or 0))
            except Exception:
                config[key] = self.default_ocr_config()[key]
        try:
            threshold = float(config.get('low_confidence_threshold'))
            config['low_confidence_threshold'] = max(0.0, min(1.0, threshold))
        except Exception:
            config['low_confidence_threshold'] = self.default_ocr_config()['low_confidence_threshold']
        return config

    def collect_ocr_settings_from_subjective_config(self, config):
        settings = {}
        for item in (config or {}).get('items', []) or []:
            qno = item.get('question_no')
            if item.get('kind') == 'drawing':
                part_id = item.get('part_id') or f'q{qno}'
                settings[part_id] = self.subjective_part_setting_config({
                    'kind': 'drawing',
                    'ocr': item.get('ocr') or {},
                })
                continue
            for blank in item.get('blanks', []) or []:
                part_id = f"q{qno}_b{blank.get('blank_no', 1)}"
                settings[part_id] = self.normalize_ocr_config(blank.get('ocr'))
            for sub in item.get('subquestions', []) or []:
                sub_no = sub.get('sub_no', 1)
                for blank in sub.get('blanks', []) or []:
                    part_id = f"q{qno}_s{sub_no}_b{blank.get('blank_no', 1)}"
                    settings[part_id] = self.normalize_ocr_config(blank.get('ocr'))
        return settings

    def read_loaded_answer_scheme_ocr_settings(self):
        if self.current_session:
            return self.get_subjective_ocr_settings_for_scheme()
        scheme_path = getattr(self, 'loaded_answer_key_scheme_path', None)
        if not scheme_path:
            return {}
        path = Path(scheme_path)
        if not path.exists():
            return {}
        try:
            payload = json.loads(path.read_text(encoding='utf-8-sig'))
        except Exception:
            return {}
        if payload.get('template_key') and payload.get('template_key') != self.current_template_key:
            return {}
        raw_settings = payload.get('subjective_ocr_settings') or {}
        if not isinstance(raw_settings, dict):
            return {}
        return {
            str(part_id): self.normalize_ocr_config(config)
            for part_id, config in raw_settings.items()
            if isinstance(config, dict)
        }

    def load_ocr_preference_memory(self):
        cache_key = str(OCR_PREFERENCE_MEMORY_PATH.resolve())
        if not OCR_PREFERENCE_MEMORY_PATH.exists():
            return {'version': 2, 'answers': {}, 'ocr_result_rules': {}}
        try:
            cache_mtime = OCR_PREFERENCE_MEMORY_PATH.stat().st_mtime_ns
        except OSError:
            cache_mtime = None
        if (
            getattr(self, '_ocr_preference_memory_cache_key', '') == cache_key
            and getattr(self, '_ocr_preference_memory_cache_mtime', None) == cache_mtime
            and isinstance(getattr(self, '_ocr_preference_memory_cache', None), dict)
        ):
            return copy.deepcopy(self._ocr_preference_memory_cache)
        try:
            data = json.loads(OCR_PREFERENCE_MEMORY_PATH.read_text(encoding='utf-8-sig'))
        except Exception:
            return {'version': 2, 'answers': {}, 'ocr_result_rules': {}}
        if not isinstance(data, dict):
            return {'version': 2, 'answers': {}, 'ocr_result_rules': {}}
        if not isinstance(data.get('answers'), dict):
            data['answers'] = {}
        if not isinstance(data.get('ocr_result_rules'), dict):
            data['ocr_result_rules'] = {}
        try:
            data['version'] = max(2, int(data.get('version') or 1))
        except (TypeError, ValueError):
            data['version'] = 2
        self._ocr_preference_memory_cache_key = cache_key
        self._ocr_preference_memory_cache_mtime = cache_mtime
        self._ocr_preference_memory_cache = copy.deepcopy(data)
        return data

    def save_ocr_preference_memory(self, data):
        atomic_write_json(OCR_PREFERENCE_MEMORY_PATH, data)
        self._ocr_preference_memory_cache_key = str(OCR_PREFERENCE_MEMORY_PATH.resolve())
        try:
            self._ocr_preference_memory_cache_mtime = OCR_PREFERENCE_MEMORY_PATH.stat().st_mtime_ns
        except OSError:
            self._ocr_preference_memory_cache_mtime = None
        self._ocr_preference_memory_cache = copy.deepcopy(data)

    def ocr_preference_answer_keys(self, expected_answer):
        keys = []
        for answer in self.split_subjective_answers(expected_answer):
            key = self.normalize_subjective_answer_for_match(answer)
            if key and key not in keys:
                keys.append(key)
        return keys

    def ocr_memory_fields(self):
        return (
            'enabled',
            'single_char',
            'unique_answer',
            'choice_fill',
            'split_char_check',
            'candidate_words',
            'common_wrong_answers',
            'wrong_keywords',
            'prefix',
            'suffix',
            'pad_left',
            'pad_right',
            'pad_top',
            'pad_bottom',
            'low_confidence_threshold',
            'expected_keywords',
        )

    def ocr_config_has_user_preferences(self, config):
        config = self.normalize_ocr_config(config)
        if config.get('enabled') or config.get('single_char') or config.get('unique_answer') or config.get('choice_fill') or not config.get('split_char_check', True):
            return True
        for key in ('candidate_words', 'common_wrong_answers', 'wrong_keywords', 'prefix', 'suffix', 'expected_keywords'):
            if str(config.get(key) or '').strip():
                return True
        defaults = self.default_ocr_config()
        for key in ('pad_left', 'pad_right', 'pad_top', 'pad_bottom', 'low_confidence_threshold'):
            if config.get(key) != defaults.get(key):
                return True
        return False

    def remember_ocr_preferences_from_settings(self, settings_by_part_id):
        memory = self.load_ocr_preference_memory()
        answers = memory.setdefault('answers', {})
        updated = 0
        for config in (settings_by_part_id or {}).values():
            config = self.normalize_ocr_config(config)
            for key in self.ocr_preference_answer_keys(config.get('expected_answer')):
                payload = {field: config.get(field) for field in self.ocr_memory_fields()}
                payload['display_answer'] = str(config.get('expected_answer') or '').strip()
                payload['updated_at'] = datetime.now().isoformat(timespec='seconds')
                answers[key] = payload
                updated += 1
        if updated:
            memory['updated_at'] = datetime.now().isoformat(timespec='seconds')
            self.save_ocr_preference_memory(memory)
        return updated

    def apply_ocr_memory_to_config(self, config, overwrite=False):
        config = self.normalize_ocr_config(config)
        keys = self.ocr_preference_answer_keys(config.get('expected_answer'))
        if not keys:
            return config
        memory = self.load_ocr_preference_memory().get('answers', {})
        remembered = None
        for key in keys:
            remembered = memory.get(key)
            if remembered:
                break
        if not isinstance(remembered, dict):
            return config
        fill_defaults = overwrite or not self.ocr_config_has_user_preferences(config)
        defaults = self.default_ocr_config()
        for field in self.ocr_memory_fields():
            if field not in remembered:
                continue
            if field in ('enabled', 'single_char', 'unique_answer', 'choice_fill', 'split_char_check'):
                if fill_defaults:
                    config[field] = bool(remembered.get(field, True if field == 'split_char_check' else False))
            elif field in ('pad_left', 'pad_right', 'pad_top', 'pad_bottom', 'low_confidence_threshold'):
                if overwrite or fill_defaults or config.get(field) == defaults.get(field):
                    config[field] = remembered.get(field)
            else:
                if overwrite or not str(config.get(field) or '').strip():
                    config[field] = remembered.get(field) or ''
        return self.normalize_ocr_config(config)

    def apply_ocr_memory_to_vars(self, vars_map, overwrite=False):
        raw = {
            'enabled': vars_map['enabled'].get(),
            'single_char': vars_map['single_char'].get(),
            'unique_answer': vars_map['unique_answer'].get() if 'unique_answer' in vars_map else False,
            'choice_fill': vars_map['choice_fill'].get() if 'choice_fill' in vars_map else False,
            'split_char_check': vars_map['split_char_check'].get() if 'split_char_check' in vars_map else True,
            'expected_answer': vars_map['expected_answer'].get(),
            'candidate_words': vars_map['candidate_words'].get() if 'candidate_words' in vars_map else '',
            'common_wrong_answers': vars_map['common_wrong_answers'].get(),
            'wrong_keywords': vars_map['wrong_keywords'].get(),
            'prefix': vars_map['prefix'].get(),
            'suffix': vars_map['suffix'].get(),
            'pad_left': vars_map['pad_left'].get(),
            'pad_right': vars_map['pad_right'].get(),
            'low_confidence_threshold': vars_map['low_confidence_threshold'].get(),
            'expected_keywords': vars_map['expected_keywords'].get(),
            'pad_top': 20,
            'pad_bottom': 20,
        }
        before = self.normalize_ocr_config(raw)
        after = self.apply_ocr_memory_to_config(before, overwrite=overwrite)
        if after == before:
            return False
        vars_map['enabled'].set(after.get('enabled', False))
        vars_map['single_char'].set(after.get('single_char', False))
        if 'unique_answer' in vars_map:
            vars_map['unique_answer'].set(after.get('unique_answer', False))
        if 'choice_fill' in vars_map:
            vars_map['choice_fill'].set(after.get('choice_fill', False))
        if 'split_char_check' in vars_map:
            vars_map['split_char_check'].set(after.get('split_char_check', True))
        if 'candidate_words' in vars_map:
            vars_map['candidate_words'].set(after.get('candidate_words', ''))
        vars_map['common_wrong_answers'].set(after.get('common_wrong_answers', ''))
        vars_map['wrong_keywords'].set(after.get('wrong_keywords', ''))
        vars_map['prefix'].set(after.get('prefix', ''))
        vars_map['suffix'].set(after.get('suffix', ''))
        vars_map['pad_left'].set(str(after.get('pad_left', 180)))
        vars_map['pad_right'].set(str(after.get('pad_right', 180)))
        vars_map['low_confidence_threshold'].set(str(after.get('low_confidence_threshold', 0.6)))
        vars_map['expected_keywords'].set(after.get('expected_keywords', ''))
        return True

    def ocr_result_memory_context_key(self, ocr_config):
        """Return a safe cross-paper key for learned OCR-result classifications."""
        config = self.normalize_ocr_config(ocr_config)
        answers = sorted({
            self.normalize_subjective_answer_for_match(value)
            for value in self.subjective_expected_answers_from_config(config)
            if self.normalize_subjective_answer_for_match(value)
        })
        if answers:
            payload = {'kind': 'answers', 'values': answers}
        else:
            keywords = sorted({
                self.normalize_subjective_answer_for_match(value)
                for value in self.split_expected_keywords(config.get('expected_keywords'))
                if self.normalize_subjective_answer_for_match(value)
            })
            if not keywords:
                return ''
            payload = {'kind': 'keywords', 'values': keywords}
        raw = json.dumps(payload, ensure_ascii=False, sort_keys=True, separators=(',', ':'))
        return hashlib.sha256(raw.encode('utf-8')).hexdigest()

    def remember_ocr_result_classification(self, ocr_config, ocr_text, action):
        valid_actions = {
            'alternate_answer',
            'correct_keyword',
            'wrong_answer',
            'wrong_keyword',
        }
        if action not in valid_actions:
            return False
        text_key = self.normalize_subjective_answer_for_match(ocr_text)
        if not text_key:
            return False
        memory = self.load_ocr_preference_memory()
        rules_map = memory.setdefault('ocr_result_rules', {})
        config = self.normalize_ocr_config(ocr_config)
        rule_payload = {
            'action': action,
            'display_text': str(ocr_text or '').strip(),
            'expected_answer': str(config.get('expected_answer') or '').strip(),
            'expected_keywords': str(config.get('expected_keywords') or '').strip(),
            'updated_at': datetime.now().isoformat(timespec='seconds'),
        }

        # 1. 记录在哈希上下文键中（兼容历史数据）
        context_key = self.ocr_result_memory_context_key(ocr_config)
        if context_key:
            rules_map.setdefault(context_key, {})[text_key] = rule_payload

        # 2. 长效关联到各个标准答案（只允许新的记忆覆盖）
        for ans in self.subjective_expected_answers_from_config(config):
            ans_norm = self.normalize_subjective_answer_for_match(ans)
            if ans_norm and ans_norm != text_key:
                rules_map.setdefault(f"ans:{ans_norm}", {})[text_key] = rule_payload

        for kw in self.split_expected_keywords(config.get('expected_keywords')):
            kw_norm = self.normalize_subjective_answer_for_match(kw)
            if kw_norm:
                rules_map.setdefault(f"kw:{kw_norm}", {})[text_key] = rule_payload

        memory['updated_at'] = datetime.now().isoformat(timespec='seconds')
        self.save_ocr_preference_memory(memory)
        return True

    def lookup_ocr_result_classification(self, ocr_config, ocr_text):
        text_key = self.normalize_subjective_answer_for_match(ocr_text)
        if not text_key:
            return ''
        memory = self.load_ocr_preference_memory()
        rules_map = memory.get('ocr_result_rules', {})
        if not isinstance(rules_map, dict):
            return ''

        valid_actions = {'alternate_answer', 'correct_keyword', 'wrong_answer', 'wrong_keyword'}

        # 1. 先查哈希上下文
        context_key = self.ocr_result_memory_context_key(ocr_config)
        if context_key and context_key in rules_map:
            rule = rules_map[context_key].get(text_key)
            if isinstance(rule, dict) and rule.get('action') in valid_actions:
                return rule['action']

        # 2. 长效记忆：查标准答案关联
        config = self.normalize_ocr_config(ocr_config)
        for ans in self.subjective_expected_answers_from_config(config):
            ans_norm = self.normalize_subjective_answer_for_match(ans)
            ans_key = f"ans:{ans_norm}"
            if ans_key in rules_map:
                rule = rules_map[ans_key].get(text_key)
                if isinstance(rule, dict) and rule.get('action') in valid_actions:
                    return rule['action']

        # 3. 长效记忆：查关键字关联
        for kw in self.split_expected_keywords(config.get('expected_keywords')):
            kw_norm = self.normalize_subjective_answer_for_match(kw)
            kw_key = f"kw:{kw_norm}"
            if kw_key in rules_map:
                rule = rules_map[kw_key].get(text_key)
                if isinstance(rule, dict) and rule.get('action') in valid_actions:
                    return rule['action']

        return ''

    def append_ocr_classification_to_config(self, ocr_config, ocr_text, action):
        field_by_action = {
            'alternate_answer': 'expected_answer',
            'correct_keyword': 'expected_keywords',
            'wrong_answer': 'common_wrong_answers',
            'wrong_keyword': 'wrong_keywords',
        }
        field = field_by_action.get(action)
        config = self.normalize_ocr_config(ocr_config)
        value = str(ocr_text or '').strip()
        if not field or not value:
            return config
        splitter = self.split_subjective_answers if field in ('expected_answer', 'common_wrong_answers') else self.split_expected_keywords
        values = splitter(config.get(field))
        normalized = {self.normalize_subjective_answer_for_match(item) for item in values}
        if self.normalize_subjective_answer_for_match(value) not in normalized:
            values.append(value)
        config[field] = ','.join(values)
        config['enabled'] = True
        return self.normalize_ocr_config(config)

    def remove_ocr_classification_from_config(self, ocr_config, ocr_text, action=None):
        field_by_action = {
            'alternate_answer': 'expected_answer',
            'correct_keyword': 'expected_keywords',
            'wrong_answer': 'common_wrong_answers',
            'wrong_keyword': 'wrong_keywords',
        }
        config = self.normalize_ocr_config(ocr_config)
        value = str(ocr_text or '').strip()
        if not value:
            return config
        norm_val = self.normalize_subjective_answer_for_match(value)
        if not norm_val:
            return config

        target_fields = [field_by_action[action]] if action in field_by_action else list(field_by_action.values())
        for field in target_fields:
            splitter = self.split_subjective_answers if field in ('expected_answer', 'common_wrong_answers') else self.split_expected_keywords
            values = splitter(config.get(field))
            remaining = [v for v in values if self.normalize_subjective_answer_for_match(v) != norm_val]
            if len(remaining) != len(values):
                config[field] = ','.join(remaining)
        return self.normalize_ocr_config(config)

    def forget_ocr_result_classification(self, ocr_config, ocr_text):
        text_key = self.normalize_subjective_answer_for_match(ocr_text)
        if not text_key:
            return False
        memory = self.load_ocr_preference_memory()
        rules_map = memory.get('ocr_result_rules', {})
        if not isinstance(rules_map, dict):
            return False
        changed = False

        context_key = self.ocr_result_memory_context_key(ocr_config)
        if context_key and context_key in rules_map:
            if text_key in rules_map[context_key]:
                rules_map[context_key].pop(text_key, None)
                changed = True
            if not rules_map[context_key]:
                rules_map.pop(context_key, None)

        config = self.normalize_ocr_config(ocr_config)
        for ans in self.subjective_expected_answers_from_config(config):
            ans_key = f"ans:{self.normalize_subjective_answer_for_match(ans)}"
            if ans_key in rules_map:
                if text_key in rules_map[ans_key]:
                    rules_map[ans_key].pop(text_key, None)
                    changed = True
                if not rules_map[ans_key]:
                    rules_map.pop(ans_key, None)

        for kw in self.split_expected_keywords(config.get('expected_keywords')):
            kw_key = f"kw:{self.normalize_subjective_answer_for_match(kw)}"
            if kw_key in rules_map:
                if text_key in rules_map[kw_key]:
                    rules_map[kw_key].pop(text_key, None)
                    changed = True
                if not rules_map[kw_key]:
                    rules_map.pop(kw_key, None)

        if changed:
            memory['updated_at'] = datetime.now().isoformat(timespec='seconds')
            self.save_ocr_preference_memory(memory)
        return changed

    def recognized_ocr_text_for_classification(self, record):
        if not isinstance(record, dict):
            return ''
        candidates = (
            record.get('ocr_manual_text'),
            record.get('ocr_text'),
            record.get('paddle_ocr_text'),
        )
        for value in candidates:
            text = re.sub(r'\s+', ' ', str(value or '')).strip()
            if text and text != '未识别到文字' and not text.startswith('识别失败：'):
                return text
        return ''

    def compact_ocr_text(self, text):
        text = str(text or '').strip()
        return re.sub(r'[\s，。！？、,.!?;；:：()（）\[\]【】{}<>《》"\'`~·_\-—=+\\/|]+', '', text)

    def split_expected_keywords(self, text):
        return [
            item.strip()
            for item in re.split(r'[\s,，、;；/|]+', str(text or ''))
            if item.strip()
        ]

    def split_subjective_answers(self, text):
        return [
            item.strip()
            for item in re.split(r'[\n,，、;；/|]+', str(text or ''))
            if item.strip()
        ]

    def evaluate_paddle_ocr_review(self, text, score, ocr_config=None):
        config = self.normalize_ocr_config(ocr_config)
        text = str(text or '').strip()
        reasons = []
        expected_answers = self.subjective_expected_answers_from_config(config)
        if expected_answers and self.any_subjective_answer_matches(text, expected_answers):
            return False, ''
        if self.subjective_keyword_matches(text, config):
            return False, ''

        if not text or text == '未识别到文字':
            reasons.append('未识别到文字')

        threshold = config.get('low_confidence_threshold', 0.6)
        if not isinstance(score, (int, float)):
            reasons.append('无置信度')
        elif score < threshold:
            reasons.append(f'置信度{score:.2f}<{threshold:.2f}')

        compact_text = self.compact_ocr_text(text)
        if config.get('single_char') and compact_text and len(compact_text) != 1:
            reasons.append('单字空疑似多字')

        keywords = self.split_expected_keywords(config.get('expected_keywords'))
        if keywords and text and text != '未识别到文字':
            if not any(keyword in text for keyword in keywords):
                reasons.append('未命中关键词')

        return bool(reasons), '；'.join(reasons)

    def normalize_subjective_answer_for_match(self, text):
        text = unicodedata.normalize('NFKC', str(text or '')).strip().lower()
        text = self.normalize_scientific_notation_text(text)
        return re.sub(r'[\s，。！？、;；:：()（）\[\]【】{}<>《》"\'`~·_]+', '', text)

    def normalize_scientific_notation_text(self, text):
        text = unicodedata.normalize('NFKC', str(text or '')).strip().lower()
        if not text:
            return ''

        superscript_map = str.maketrans({
            '⁰': '0', '¹': '1', '²': '2', '³': '3', '⁴': '4',
            '⁵': '5', '⁶': '6', '⁷': '7', '⁸': '8', '⁹': '9',
            '⁻': '-', '⁺': '+',
        })
        text = text.translate(superscript_map)
        text = text.replace('＊', '*').replace('×', 'x').replace('X', 'x')
        text = re.sub(r'\s+', '', text)
        text = re.sub(r'乘以?', 'x', text)
        text = re.sub(r'的([+-]?\d+)次方', r'^\1', text)
        text = re.sub(r'10\^?([+-]?\d+)', r'10^\1', text)
        text = re.sub(r'([+-]?(?:\d+(?:\.\d*)?|\.\d+))\s*[x*]\s*10\^?([+-]?\d+)', r'\1x10^\2', text)
        text = re.sub(r'([+-]?(?:\d+(?:\.\d*)?|\.\d+))10\^([+-]?\d+)', r'\1x10^\2', text)
        return text

    def parse_subjective_numeric_value(self, text):
        normalized = self.normalize_scientific_notation_text(text)
        normalized = re.sub(r'[,，]', '', normalized)
        sci_match = re.search(r'([+-]?(?:\d+(?:\.\d*)?|\.\d+))x10\^([+-]?\d+)', normalized)
        if sci_match:
            try:
                return float(sci_match.group(1)) * (10 ** int(sci_match.group(2)))
            except Exception:
                return None
        plain_match = re.search(r'(?<![\w.])([+-]?(?:\d+(?:\.\d*)?|\.\d+))(?![\w.])', normalized)
        if plain_match:
            try:
                return float(plain_match.group(1))
            except Exception:
                return None
        return None

    def subjective_numeric_values_equal(self, actual_text, expected_text):
        actual_value = self.parse_subjective_numeric_value(actual_text)
        expected_value = self.parse_subjective_numeric_value(expected_text)
        if actual_value is None or expected_value is None:
            return False
        tolerance = max(1e-9, abs(expected_value) * 1e-9)
        return abs(actual_value - expected_value) <= tolerance

    def subjective_expected_answer_from_config(self, ocr_config):
        config = self.normalize_ocr_config(ocr_config)
        answers = self.split_subjective_answers(config.get('expected_answer'))
        if answers:
            return answers[0]
        return ''

    def subjective_expected_answers_from_config(self, ocr_config):
        config = self.normalize_ocr_config(ocr_config)
        return self.split_subjective_answers(config.get('expected_answer'))

    def subjective_wrong_answers_from_config(self, ocr_config):
        config = self.normalize_ocr_config(ocr_config)
        return self.split_subjective_answers(config.get('common_wrong_answers'))

    def strip_leading_question_number(self, text):
        text = str(text or '').strip()
        return re.sub(r'^\s*\d+\s*[\.\、,，。:：]?\s*', '', text)

    def single_subjective_answer_matches(self, actual_text, expected_text):
        actual = self.normalize_subjective_answer_for_match(actual_text)
        expected = self.normalize_subjective_answer_for_match(expected_text)
        if not actual or not expected:
            return False
        if actual == expected:
            return True
        stripped_actual = self.normalize_subjective_answer_for_match(self.strip_leading_question_number(actual_text))
        if stripped_actual == expected:
            return True
        return self.subjective_numeric_values_equal(actual_text, expected_text)

    def unique_subjective_answer_matches(self, actual_text, expected_text):
        return self.single_subjective_answer_matches(actual_text, expected_text)

    def any_subjective_answer_matches(self, actual_text, expected_answers):
        return any(
            self.single_subjective_answer_matches(actual_text, expected)
            for expected in expected_answers
        )

    def subjective_keyword_matches(self, actual_text, ocr_config=None):
        config = self.normalize_ocr_config(ocr_config)
        keywords = self.split_expected_keywords(config.get('expected_keywords'))
        if not keywords:
            return False
        actual_raw = str(actual_text or '')
        actual_norm = self.normalize_subjective_answer_for_match(actual_raw)
        for keyword in keywords:
            keyword_norm = self.normalize_subjective_answer_for_match(keyword)
            if keyword and keyword in actual_raw:
                return True
            if keyword_norm and keyword_norm in actual_norm:
                return True
        return False

    def subjective_wrong_keyword_matches(self, actual_text, ocr_config=None):
        config = self.normalize_ocr_config(ocr_config)
        keywords = self.split_expected_keywords(config.get('wrong_keywords'))
        if not keywords:
            return False
        actual_raw = str(actual_text or '')
        actual_norm = self.normalize_subjective_answer_for_match(actual_raw)
        for keyword in keywords:
            keyword_norm = self.normalize_subjective_answer_for_match(keyword)
            if keyword and keyword in actual_raw:
                return True
            if keyword_norm and keyword_norm in actual_norm:
                return True
        return False

    def subjective_has_auto_rule(self, ocr_config=None):
        config = self.normalize_ocr_config(ocr_config)
        return bool(
            self.split_subjective_answers(config.get('expected_answer'))
            or self.split_expected_keywords(config.get('expected_keywords'))
            or self.split_subjective_answers(config.get('common_wrong_answers'))
            or self.split_expected_keywords(config.get('wrong_keywords'))
        )

    def apply_subjective_answer_auto_score(self, record, task, answer_text):
        if record.get('manual_graded'):
            return None

        ocr_config = task['part'].get('ocr')
        expected_answers = self.subjective_expected_answers_from_config(ocr_config)
        keyword_matched = self.subjective_keyword_matches(answer_text, ocr_config)
        remembered_action = self.lookup_ocr_result_classification(ocr_config, answer_text)
        remembered_correct = remembered_action in ('alternate_answer', 'correct_keyword')
        expected_text = ' / '.join(expected_answers) if expected_answers else '关键词：' + ' / '.join(self.split_expected_keywords((ocr_config or {}).get('expected_keywords')))
        if not expected_answers and not self.split_expected_keywords((ocr_config or {}).get('expected_keywords')) and not remembered_correct:
            if record.get('auto_graded'):
                for key in (
                    'score',
                    'max_score',
                    'auto_graded',
                    'auto_grade_match',
                    'auto_grade_expected',
                    'auto_grade_answer',
                    'auto_grade_updated_at',
                ):
                    record.pop(key, None)
            return None

        matched = self.any_subjective_answer_matches(answer_text, expected_answers) or keyword_matched or remembered_correct
        if not matched:
            if record.get('auto_graded'):
                for key in ('score', 'max_score', 'auto_graded'):
                    record.pop(key, None)
            record.update({
                'auto_grade_match': False,
                'auto_grade_expected': expected_text,
                'auto_grade_answer': str(answer_text or '').strip(),
                'auto_grade_updated_at': datetime.now().isoformat(timespec='seconds'),
            })
            return False

        max_score = float(task['part'].get('score') or 1)
        record.update({
            'score': max_score,
            'max_score': max_score,
            'auto_graded': True,
            'manual_graded': False,
            'auto_grade_match': matched,
            'auto_grade_expected': expected_text,
            'auto_grade_answer': str(answer_text or '').strip(),
            'auto_grade_reason': (
                '命中分类记忆'
                if remembered_correct and not keyword_matched and not self.any_subjective_answer_matches(answer_text, expected_answers)
                else ('命中关键词' if keyword_matched and not self.any_subjective_answer_matches(answer_text, expected_answers) else '')
            ),
            'auto_grade_updated_at': datetime.now().isoformat(timespec='seconds'),
            'label': task['part'].get('label', ''),
            'student_name': task['entry'].get('student_name', ''),
            'score_id': task['entry'].get('score_id', ''),
            'file': task['entry'].get('file', ''),
        })
        return matched

    def normalize_target_part_id(self, part_query):
        """将用户传入的各种形式题目标识符（如 q12_b1, 12-1, 12_1, 第12题-第1空, q20_s1_b2）规格化为标准 part_id"""
        if not part_query:
            return None
        query = str(part_query).strip()
        parts = list(self.iter_subjective_parts())
        part_ids = {p['part_id'] for p in parts}
        if query in part_ids:
            return query

        lower_query = query.lower()
        for p in parts:
            if p['part_id'].lower() == lower_query:
                return p['part_id']
            if p.get('label') and p['label'].strip() == query:
                return p['part_id']
            if p.get('label') and p['label'].replace(' ', '').replace('（', '(').replace('）', ')') == query.replace(' ', '').replace('（', '(').replace('）', ')'):
                return p['part_id']

        m = re.match(r'^[qQ]?(\d+)[-_bB](\d+)$', query)
        if m:
            candidate = f"q{m.group(1)}_b{m.group(2)}"
            if candidate in part_ids:
                return candidate

        m = re.match(r'^[qQ]?(\d+)(?:[-_sS]|\((\d+)\))(\d+)?[-_bB]?(\d+)$', query)
        if m:
            qno = m.group(1)
            sno = m.group(2) or m.group(3) or '1'
            bno = m.group(4)
            candidate = f"q{qno}_s{sno}_b{bno}"
            if candidate in part_ids:
                return candidate

        if query.isdigit():
            c1 = f"q{query}_b1"
            if c1 in part_ids:
                return c1
            c2 = f"q{query}"
            if c2 in part_ids:
                return c2

        return None

    def regrade_single_subjective_part(
        self,
        part_id: str,
        new_expected_answer: str,
        expected_keywords: str = None,
        override_manual: bool = False,
    ) -> dict:
        """
        根据更正后的标准答案，仅重判指定空位，基于前序已有 OCR 识别结果，无需重新切图或执行模型 OCR。
        同时自动持久化更新当前模板主观题配置，并同步回写至已加载的答案方案（Answer Scheme）文件。
        """
        norm_part_id = self.normalize_target_part_id(part_id)
        if not norm_part_id:
            return {'ok': False, 'error': f'未找到题目空位：{part_id}'}

        parts_map = {p['part_id']: p for p in self.iter_subjective_parts()}
        target_part = parts_map.get(norm_part_id)
        if not target_part:
            return {'ok': False, 'error': f'未找到题目空位：{norm_part_id}'}

        # Validate the old version BEFORE changing its answer. This action is
        # an explicit, single-part revision within the same test.
        payload = copy.deepcopy(self.load_subjective_score_payload())
        if (payload.get('session_id') != (self.current_session or {}).get('id')
                or not self.subjective_payload_matches_current_structure(payload)
                ):
            return {'ok': False, 'error': '已有成绩与当前测试或答案版本不一致；成绩已保留，请先恢复对应版本后更正单空。'}
        try:
            self.prepare_subjective_payload_for_grading(payload)
        except ValueError as exc:
            return {'ok': False, 'error': str(exc)}
        original_context = self.score_context_identity()
        unchanged_parts = {key: copy.deepcopy(value) for key, value in parts_map.items() if key != norm_part_id}
        self.archive_subjective_score_payload(payload, 'before_single_part_regrade')

        new_answer_str = str(new_expected_answer or '').strip()
        old_ocr_cfg = target_part.get('ocr') or {}
        old_expected_answer = str(old_ocr_cfg.get('expected_answer') or '')

        # 1. 更新当前题目配置中的标准答案与关键词
        updated_ocr_cfg = dict(old_ocr_cfg)
        updated_ocr_cfg['expected_answer'] = new_answer_str
        if expected_keywords is not None:
            updated_ocr_cfg['expected_keywords'] = str(expected_keywords).strip()
        updated_ocr_cfg['enabled'] = True  # 更正了答案说明该空允许OCR自动判分

        # 保存到当前模板主观题配置
        self.save_ocr_settings_for_parts({norm_part_id: updated_ocr_cfg})

        # 2. 同步写回当前加载的答案方案文件
        scheme_synced = False
        synced_count = self.sync_loaded_answer_scheme_ocr_settings()
        if synced_count > 0:
            scheme_synced = True

        # 如果当前有激活的测试会话，同时保存会话答案快照
        if getattr(self, 'current_session', None):
            try:
                self.save_session_answer_key_snapshot()
            except Exception:
                pass

        # 刷新 target_part 获取最新的 ocr 配置
        fresh_parts = {p['part_id']: p for p in self.iter_subjective_parts()}
        target_part = fresh_parts.get(norm_part_id, target_part)
        ocr_config = target_part.get('ocr') or {}

        # 3. 加载已有成绩 Payload 并执行单空重判
        all_scores = payload.setdefault('scores', {})

        entry_map = {}
        for entry in (self.summary_data or []):
            ek = self.subjective_entry_key(entry)
            if ek:
                entry_map[ek] = entry

        expected_answers = self.subjective_expected_answers_from_config(ocr_config)
        wrong_answers = self.subjective_wrong_answers_from_config(ocr_config)
        expected_text = ' / '.join(expected_answers) if expected_answers else ('关键词：' + ' / '.join(self.split_expected_keywords(ocr_config.get('expected_keywords'))))
        max_score = float(target_part.get('score') or 1.0)

        matched_count = 0
        zero_count = 0
        unmatched_count = 0
        skipped_manual = 0
        total_records = 0

        crop_map = {}
        try:
            _export_root, _saved, _errors, crop_map = self.generate_subjective_crops(reuse_existing=True)
        except Exception:
            crop_map = {}

        for entry_key, records in list(all_scores.items()):
            if not isinstance(records, dict) or norm_part_id not in records:
                continue
            record = records[norm_part_id]
            if not isinstance(record, dict):
                continue
            total_records += 1

            # 保护老师已有人工打分
            if record.get('manual_graded') and not override_manual:
                skipped_manual += 1
                continue

            # 提取历史有效 OCR 文本（严格排除“未识别到文字”、“空白”、“识别失败：”）
            ocr_manual = str(record.get('ocr_manual_text') or '').strip()
            v6_txt = str(record.get('ocr_text') or '').strip()
            paddle_txt = str(record.get('paddle_ocr_text') or '').strip()
            old_ans = str(record.get('auto_grade_answer') or '').strip()

            def _is_valid_txt(s):
                return bool(s and s not in ('未识别到文字', '空白') and not s.startswith('识别失败：'))

            valid_manual = ocr_manual if _is_valid_txt(ocr_manual) else ''
            valid_v6 = v6_txt if _is_valid_txt(v6_txt) else ''
            valid_paddle = paddle_txt if _is_valid_txt(paddle_txt) else ''
            valid_old = old_ans if _is_valid_txt(old_ans) else ''

            task = {
                'part': target_part,
                'entry': entry_map.get(entry_key, {}),
                'part_id': norm_part_id,
                'entry_key': entry_key,
                'crop_path': crop_map.get(entry_key, {}).get(norm_part_id) or record.get('crop_path') or '',
            }

            # 双层 OCR 智能仲裁（只要任意一层识别结果命中标准答案或关键词，坚决给满分，绝不因另一层未识别误杀）
            is_correct = False
            chosen_answer = ''
            reason = ''

            # 1. 人工修正文本最高优先
            if valid_manual:
                keyword_matched = self.subjective_keyword_matches(valid_manual, ocr_config)
                rem_action = self.lookup_ocr_result_classification(ocr_config, valid_manual)
                rem_correct = rem_action in ('alternate_answer', 'correct_keyword')
                if self.any_subjective_answer_matches(valid_manual, expected_answers) or keyword_matched or rem_correct:
                    is_correct = True
                    chosen_answer = valid_manual
                    reason = '人工修正文本命中'
                else:
                    chosen_answer = valid_manual

            # 2. 检查第二层高精 OCR (PaddleOCRv6) 是否命中
            if not is_correct and valid_v6:
                keyword_matched = self.subjective_keyword_matches(valid_v6, ocr_config)
                rem_action = self.lookup_ocr_result_classification(ocr_config, valid_v6)
                rem_correct = rem_action in ('alternate_answer', 'correct_keyword')
                if self.any_subjective_answer_matches(valid_v6, expected_answers) or keyword_matched or rem_correct:
                    is_correct = True
                    chosen_answer = valid_v6
                    reason = (
                        '命中分类记忆' if rem_correct and not keyword_matched and not self.any_subjective_answer_matches(valid_v6, expected_answers)
                        else ('命中关键词' if keyword_matched and not self.any_subjective_answer_matches(valid_v6, expected_answers) else '二层高精重判命中')
                    )

            # 3. 检查第一层 OCR (PaddleOCR) 是否命中
            if not is_correct and valid_paddle:
                keyword_matched = self.subjective_keyword_matches(valid_paddle, ocr_config)
                rem_action = self.lookup_ocr_result_classification(ocr_config, valid_paddle)
                rem_correct = rem_action in ('alternate_answer', 'correct_keyword')
                if self.any_subjective_answer_matches(valid_paddle, expected_answers) or keyword_matched or rem_correct:
                    is_correct = True
                    chosen_answer = valid_paddle
                    reason = (
                        '命中分类记忆' if rem_correct and not keyword_matched and not self.any_subjective_answer_matches(valid_paddle, expected_answers)
                        else ('命中关键词' if keyword_matched and not self.any_subjective_answer_matches(valid_paddle, expected_answers) else '一层OCR重判命中')
                    )

            # 4. 检查历史判定文本是否命中
            if not is_correct and valid_old:
                if self.any_subjective_answer_matches(valid_old, expected_answers):
                    is_correct = True
                    chosen_answer = valid_old
                    reason = '更正答案重判命中'

            # 若均未命中正确答案，选择最可靠的有效文本进行错题分析
            if not chosen_answer:
                chosen_answer = valid_manual or valid_v6 or valid_paddle or valid_old or ''

            answer_text = chosen_answer

            if is_correct:
                record.update({
                    'score': max_score,
                    'max_score': max_score,
                    'auto_graded': True,
                    'manual_graded': False,
                    'auto_grade_match': True,
                    'auto_grade_expected': expected_text,
                    'auto_grade_answer': answer_text,
                    'auto_grade_reason': reason,
                    'auto_grade_engine': '更正答案快速重判',
                    'auto_grade_updated_at': datetime.now().isoformat(timespec='seconds'),
                    'ocr_auto_need_manual': False,
                    'ocr_auto_reason': '',
                    'label': target_part.get('label', ''),
                    'student_name': task['entry'].get('student_name', ''),
                    'score_id': task['entry'].get('score_id', ''),
                    'file': task['entry'].get('file', ''),
                })
                matched_count += 1
            else:
                wrong_kw_matched = self.subjective_wrong_keyword_matches(answer_text, ocr_config) if answer_text else False
                rem_action = self.lookup_ocr_result_classification(ocr_config, answer_text) if answer_text else None
                rem_wrong = rem_action in ('wrong_answer', 'wrong_keyword')
                split_missing = (
                    bool(ocr_config.get('unique_answer') and ocr_config.get('split_char_check', True) and expected_answers and answer_text)
                    and self.check_subjective_split_char_missing(answer_text, expected_answers)[0]
                )

                if wrong_answers and answer_text and self.any_subjective_answer_matches(answer_text, wrong_answers):
                    self.mark_subjective_auto_zero_record(
                        record, task, answer_text, '更正答案快速重判', '命中常见错误答案'
                    )
                    zero_count += 1
                elif wrong_kw_matched or rem_wrong:
                    reason_lbl = '命中长效记忆错误' if rem_wrong else '命中错误关键词'
                    self.mark_subjective_auto_zero_record(
                        record, task, answer_text, '更正答案快速重判', reason_lbl
                    )
                    zero_count += 1
                elif split_missing:
                    exp_disp = ' / '.join(expected_answers)
                    self.mark_subjective_auto_zero_record(
                        record, task, answer_text, 'OCR拆字判错', f'拆字判错：完全未命中答案字（“{exp_disp}”）'
                    )
                    zero_count += 1
                elif not valid_manual and not valid_v6 and not valid_paddle and not valid_old:
                    res_status = self.handle_both_blank_with_recheck(
                        record, task, task.get('crop_path'), engine='更正答案快速重判'
                    )
                    if res_status == 'zero':
                        zero_count += 1
                    else:
                        unmatched_count += 1
                else:
                    for k in ('score', 'max_score', 'auto_graded', 'auto_grade_reason', 'auto_grade_engine'):
                        record.pop(k, None)
                    record.update({
                        'score': 0.0,
                        'max_score': max_score,
                        'auto_grade_match': False,
                        'auto_grade_expected': expected_text,
                        'auto_grade_answer': answer_text,
                        'auto_grade_updated_at': datetime.now().isoformat(timespec='seconds'),
                        'ocr_auto_need_manual': True,
                        'ocr_auto_reason': '未命中更正后的标准答案，待人工复核',
                        'label': target_part.get('label', ''),
                        'student_name': task['entry'].get('student_name', ''),
                        'score_id': task['entry'].get('score_id', ''),
                        'file': task['entry'].get('file', ''),
                    })
                    unmatched_count += 1

            try:
                from core.blank_recheck import get_blank_recheck_collector
                get_blank_recheck_collector().update_manual_judgment(
                    session_id=str((self.current_session or {}).get('id') or ''),
                    part_id=norm_part_id,
                    score_id_or_entry=str(task['entry'].get('score_id') or entry_key),
                    manual_score=record.get('score'),
                    manual_text=answer_text,
                )
            except Exception:
                pass

        # 4. 保存成绩 Payload 并刷新视图
        current_context = self.score_context_identity()
        other_parts = {p['part_id']: p for p in self.iter_subjective_parts() if p['part_id'] != norm_part_id}
        if (current_context[:2] != original_context[:2] or current_context[3] != original_context[3]
                or other_parts != unchanged_parts):
            raise ValueError('单空重判期间其他题目或测试发生变化，已保留原成绩，停止写入。')
        # Only this explicit operation may advance the answer version after
        # rejudging the selected part and proving all other parts unchanged.
        payload['subjective_answer_signature'] = self.subjective_answer_signature()
        payload['subjective_part_rules'][norm_part_id] = self.subjective_part_rules()[norm_part_id]
        payload['single_part_regrade'] = {'part_id': norm_part_id,
                                         'previous_answer_signature': original_context[2],
                                         'override_manual': bool(override_manual)}
        self.save_subjective_score_payload(payload)
        self._last_result_sync_error = ''
        self.refresh_main_result_views(payload)
        output_errors = list(getattr(self, '_last_result_view_errors', []))
        if getattr(self, '_last_result_sync_error', ''):
            output_errors.insert(0, '成绩文件已保存，数据库同步待重试：' + self._last_result_sync_error)

        # 若主观题批改窗口打开中，通知其刷新
        if hasattr(self, 'active_subjective_grading_refresh') and callable(self.active_subjective_grading_refresh):
            try:
                self.active_subjective_grading_refresh()
            except Exception:
                pass

        return {
            'ok': True,
            'part_id': norm_part_id,
            'label': target_part.get('label', norm_part_id),
            'old_expected_answer': old_expected_answer,
            'new_expected_answer': new_answer_str,
            'total_records': total_records,
            'matched_count': matched_count,
            'zero_count': zero_count,
            'unmatched_count': unmatched_count,
            'skipped_manual': skipped_manual,
            'scheme_synced': scheme_synced,
            'scheme_name': getattr(self, 'loaded_answer_key_scheme_name', ''),
            'scheme_path': getattr(self, 'loaded_answer_key_scheme_path', ''),
            'output_errors': output_errors,
        }

    def iter_subjective_parts(self):
        optional_drawing = self.optional_experiment_drawing_config()
        optional_enabled = optional_drawing.get('enabled', False)
        optional_drawing_question = optional_drawing.get('drawing_question_no', '')
        optional_placeholder_part = optional_drawing.get('placeholder_part_id', '')
        for item in self.subjective_items():
            qno = item.get('question_no')
            kind = item.get('kind', '')
            item_side = str(item.get('side') or 'front').lower()
            if kind == 'drawing':
                is_optional_experiment_drawing = str(qno) == optional_drawing_question
                if is_optional_experiment_drawing and not optional_enabled:
                    continue
                rect = item.get('rect')
                if rect:
                    yield {
                        'part_id': item.get('part_id') or f'q{qno}',
                        'question_no': qno,
                        'label': item.get('label') or f'第{qno}题',
                        'kind': kind,
                        'score_category': item.get('score_category') or kind,
                        'score': float(item.get('max_score') or 0),
                        'region_name': item.get('region_name') or 'drawing',
                        'rect': rect,
                        'side': item_side,
                        'ocr': self.normalize_ocr_config(item.get('ocr')),
                        'is_experiment_drawing': bool(item.get('optional_experiment_drawing')) or is_optional_experiment_drawing,
                    }
                continue

            for blank in item.get('blanks', []) or []:
                rect = blank.get('rect')
                if not rect:
                    continue
                blank_no = blank.get('blank_no', 1)
                yield {
                    'part_id': f'q{qno}_b{blank_no}',
                    'question_no': qno,
                    'label': f"第{qno}题-第{blank_no}空",
                    'label': blank.get('label') or item.get('label') or f'{qno}-{blank_no}',
                    'answer_label': blank.get('answer_label') or item.get('answer_label') or '',
                    'kind': kind,
                    'score_category': blank.get('score_category') or item.get('score_category') or kind,
                    'score': float(blank.get('score') or 1),
                    'region_name': blank.get('region_name') or item.get('region_name') or kind,
                    'rect': rect,
                    'side': str(blank.get('side') or item_side or 'front').lower(),
                    'ocr': self.normalize_ocr_config(blank.get('ocr')),
                }

            for sub in item.get('subquestions', []) or []:
                sub_side = str(sub.get('side') or item_side or 'front').lower()
                sub_no = sub.get('sub_no', 1)
                for blank in sub.get('blanks', []) or []:
                    rect = blank.get('rect')
                    if not rect:
                        continue
                    blank_no = blank.get('blank_no', 1)
                    part_id = f'q{qno}_s{sub_no}_b{blank_no}'
                    score = float(blank.get('score') or 1)
                    score_category = blank.get('score_category') or sub.get('score_category') or item.get('score_category') or kind
                    if (not optional_enabled) and part_id == optional_placeholder_part:
                        score = float(blank.get('normal_score') or optional_drawing.get('placeholder_normal_score') or 1)
                        score_category = kind
                    yield {
                        'part_id': part_id,
                        'question_no': qno,
                        'label': f"第{qno}题({sub_no})-第{blank_no}空",
                        'label': blank.get('label') or sub.get('label') or item.get('label') or f'{qno}({sub_no})-{blank_no}',
                        'answer_label': blank.get('answer_label') or sub.get('answer_label') or item.get('answer_label') or '',
                        'kind': kind,
                        'score_category': score_category,
                        'score': score,
                        'region_name': blank.get('region_name') or sub.get('region_name') or item.get('region_name') or kind,
                        'rect': rect,
                        'side': str(blank.get('side') or sub_side or 'front').lower(),
                        'ocr': self.normalize_ocr_config(blank.get('ocr')),
                    }

    def project_template_rect(self, matrix, rect):
        x = float(rect.get('x', 0))
        y = float(rect.get('y', 0))
        w = float(rect.get('w', 0))
        h = float(rect.get('h', 0))
        points = [
            apply_homography(matrix, (x, y)),
            apply_homography(matrix, (x + w, y)),
            apply_homography(matrix, (x + w, y + h)),
            apply_homography(matrix, (x, y + h)),
        ]
        xs = [p[0] for p in points]
        ys = [p[1] for p in points]
        return int(min(xs)), int(min(ys)), int(max(xs)), int(max(ys))

    def clip_template_rect_to_region(self, rect, region_name):
        regions = (getattr(self, 'subjective_config', {}) or {}).get('crop_regions', {}) or {}
        region = regions.get(region_name or '') or regions.get(str(region_name or '').replace('_blank', '')) or None
        if not region:
            return rect

        x = float(rect.get('x', 0))
        y = float(rect.get('y', 0))
        w = float(rect.get('w', 0))
        h = float(rect.get('h', 0))
        rx = float(region.get('x', 0))
        ry = float(region.get('y', 0))
        rw = float(region.get('w', 0))
        rh = float(region.get('h', 0))

        left = max(x, rx)
        top = max(y, ry)
        right = min(x + w, rx + rw)
        bottom = min(y + h, ry + rh)
        if right <= left or bottom <= top:
            return rect
        return {'x': left, 'y': top, 'w': right - left, 'h': bottom - top}

    def subjective_output_base_dir(self):
        return Path(
            getattr(self, 'default_export_dir', '')
            or getattr(self, 'selected_folder_path', '')
            or self.last_open_dir
            or PROJECT_DIR
        )

    def subjective_crops_root(self):
        base = self.subjective_output_base_dir() / '主观题裁图'
        session_id = (self.current_session or {}).get('id')
        if session_id:
            safe_id = re.sub(r'[^A-Za-z0-9_.-]+', '_', str(session_id)).strip('._-')
            if safe_id:
                return base / f'session_{safe_id}'
        return base / 'current'

    def resolve_task_crop_path(self, task, record=None):
        if isinstance(task, dict) and task.get('crop_path'):
            cp = Path(task['crop_path'])
            if cp.exists():
                return str(cp)
        if isinstance(record, dict) and record.get('crop_path'):
            cp = Path(record['crop_path'])
            if cp.exists():
                return str(cp)

        entry_key = (task or {}).get('entry_key') or (record or {}).get('file') or ''
        part_id = (task or {}).get('part_id') or (record or {}).get('part_id') or ''
        if entry_key and part_id:
            crop_map = getattr(self, '_cached_crop_map', None)
            if not crop_map:
                try:
                    _export_root, _saved, _errors, crop_map = self.generate_subjective_crops(reuse_existing=True)
                    self._cached_crop_map = crop_map
                except Exception:
                    crop_map = {}
            if crop_map:
                p = crop_map.get(entry_key, {}).get(part_id)
                if p and Path(p).exists():
                    return str(p)
                for ek, pmap in crop_map.items():
                    if entry_key == ek or Path(entry_key).name == Path(ek).name:
                        p = pmap.get(part_id)
                        if p and Path(p).exists():
                            return str(p)

        export_root = self.subjective_crops_root()
        if not export_root.exists():
            return ''

        parts = list(self.iter_subjective_parts())
        part_index = None
        target_part = None
        for idx, p in enumerate(parts, 1):
            if p.get('part_id') == part_id:
                part_index = idx
                target_part = p
                break

        entry = (task or {}).get('entry') or {}
        st_name = entry.get('student_name') or (record or {}).get('student_name') or ''
        sc_id = entry.get('score_id') or (record or {}).get('score_id') or ''
        f_name = entry.get('file') or (record or {}).get('file') or ''

        candidates = []
        for sdir in export_root.iterdir():
            if not sdir.is_dir():
                continue
            if sc_id and sc_id in sdir.name:
                candidates.append(sdir)
            elif st_name and st_name in sdir.name:
                candidates.append(sdir)
            elif f_name and Path(f_name).stem in sdir.name:
                candidates.append(sdir)

        target_dirs = candidates or [d for d in export_root.iterdir() if d.is_dir()]
        for sdir in target_dirs:
            if part_index is not None:
                for f in sdir.glob(f'{part_index:02d}_*.jpg'):
                    return str(f)
            label = (target_part or {}).get('label') or ((task or {}).get('part') or {}).get('label') or (record or {}).get('label') or ''
            if label:
                safe_lbl = self.safe_file_part(label)
                for f in sdir.glob(f'*_{safe_lbl}.jpg'):
                    return str(f)
        return ''

    def subjective_crop_manifest_path(self):
        return self.subjective_crops_root() / '_crop_manifest.json'

    def subjective_crop_manifest(self, parts):
        images = []
        for entry in self.summary_data or []:
            input_path = Path(entry.get('input_path') or '')
            stat = None
            if input_path.exists():
                try:
                    st = input_path.stat()
                    stat = {'size': st.st_size, 'mtime': int(st.st_mtime)}
                except Exception:
                    stat = None
            side_files = {}
            for side_name, side_path_value in (entry.get('side_files') or {}).items():
                side_path = Path(side_path_value or '')
                side_stat = None
                if side_path.exists():
                    try:
                        st = side_path.stat()
                        side_stat = {'size': st.st_size, 'mtime': int(st.st_mtime)}
                    except Exception:
                        side_stat = None
                side_files[side_name] = {'path': str(side_path), 'stat': side_stat}
            images.append({
                'entry_key': self.subjective_entry_key(entry),
                'input_path': str(input_path),
                'file': entry.get('file', ''),
                'score_id': entry.get('score_id', ''),
                'student_name': entry.get('student_name', ''),
                'stat': stat,
                'side_files': side_files,
                'orientation': entry.get('orientation') or '',
                'side_orientations': entry.get('side_orientations') or {},
            })
        return {
            'version': 3,
            'crop_algorithm': 'template_alignment_side_orientation_v8_direct_margin_versioned',
            'session_id': (self.current_session or {}).get('id', ''),
            'session_name': (self.current_session or {}).get('name', ''),
            'template_key': self.current_template_key,
            'template_name': self.current_template_name,
            'parts': [
                {
                    'part_id': part.get('part_id', ''),
                    'label': part.get('label', ''),
                    'kind': part.get('kind', ''),
                    'region_name': part.get('region_name', ''),
                    'side': str(part.get('side') or 'front').lower(),
                    'rect': part.get('rect') or {},
                    'effective_rect': self.clip_template_rect_to_region(
                        part.get('rect') or {},
                        part.get('region_name'),
                    ),
                }
                for part in parts
            ],
            'images': images,
        }

    def subjective_crop_manifest_matches(self, expected_manifest):
        path = self.subjective_crop_manifest_path()
        if not path.exists():
            return False
        try:
            current = json.loads(path.read_text(encoding='utf-8-sig'))
        except Exception:
            return False
        # Scores and OCR rules do not change crop pixels. Older manifests did
        # include a score field, so ignore it while comparing to avoid a full
        # re-crop after grading settings are edited.
        def crop_only(payload):
            normalized = copy.deepcopy(payload or {})
            for part in normalized.get('parts') or []:
                part.pop('score', None)
            return normalized

        return crop_only(current) == crop_only(expected_manifest)

