    def clear_answer_scheme_state(self):
        self.answer_key = {}
        self.loaded_answer_key = {}
        self.loaded_answer_key_scheme_path = None
        self.loaded_answer_key_scheme_name = ''
        self.knowledge_identity_payload = {}

    # -------------------------------------------------------------------------
    # 测试答案/模板结构快照保存读取 已抽离至 core.db_session.DatabaseSessionMixin
    # -------------------------------------------------------------------------

    def subjective_scores_path(self):
        session_path = self.session_subjective_scores_path()
        if session_path:
            return session_path
        return self.folder_subjective_scores_path()

    def subjective_entry_key(self, entry):
        return str(entry.get('input_path') or entry.get('file') or '').strip()

    def legacy_subjective_score_paths(self):
        paths = []

        def add_path(path_value):
            if not path_value:
                return
            try:
                path = Path(path_value)
            except Exception:
                return
            if path not in paths:
                paths.append(path)

        add_path(self.folder_subjective_scores_path())
        for entry in self.summary_data or []:
            subjective = entry.get('subjective') or {}
            add_path(subjective.get('score_file'))
            input_path = entry.get('input_path')
            if input_path:
                try:
                    add_path(Path(input_path).parent / '主观题批改结果.json')
                except Exception:
                    pass
        return paths

    def load_subjective_score_payload(self):
        path = self.subjective_scores_path()
        candidates = [path]
        if not self.current_session:
            candidates.extend([p for p in self.legacy_subjective_score_paths() if p != path])

        for candidate in candidates:
            if not candidate or not candidate.exists():
                continue
            try:
                payload = read_score_payload(candidate, {'scores': {}})
                if not isinstance(payload, dict):
                    raise ValueError('invalid payload')
                payload.setdefault('scores', {})
                if self.current_session:
                    if payload.get('session_id') and payload['session_id'] != self.current_session.get('id'):
                        raise ValueError('成绩文件属于其他测试，已停止加载。')
                    if payload.get('template_key') and payload['template_key'] != self.current_template_key:
                        raise ValueError('成绩文件模板与当前测试不一致，已停止加载。')
                    payload['session_id'] = self.current_session.get('id')
                    payload['session_name'] = self.current_session.get('name', '')
                if candidate != path:
                    self.filter_subjective_payload_to_current_entries(payload)
                    path.parent.mkdir(parents=True, exist_ok=True)
                    atomic_write_json(path, payload)
                elif self.current_session and not payload.get('legacy_merge_disabled'):
                    removed = self.filter_subjective_payload_to_current_entries(payload)
                    merged = self.merge_legacy_subjective_scores(payload, path)
                    if removed or merged:
                        atomic_write_json(path, payload)
                self.upgrade_subjective_rule_baseline(payload)
                return payload
            except Exception:
                if candidate == path:
                    raise
                continue

        payload = {
            'version': 1,
            'template_key': self.current_template_key,
            'template_name': self.current_template_name,
            'session_id': (self.current_session or {}).get('id', ''),
            'session_name': (self.current_session or {}).get('name', ''),
            'scores': {},
        }
        if self.current_session and path and not payload.get('legacy_merge_disabled'):
            merged = self.merge_legacy_subjective_scores(payload, path)
            if merged:
                payload['subjective_answer_signature'] = self.subjective_answer_signature()
                payload['subjective_structure_signature'] = self.subjective_structure_signature()
                payload['answer_scheme_name'] = getattr(self, 'loaded_answer_key_scheme_name', '')
                payload['answer_scheme_path'] = getattr(self, 'loaded_answer_key_scheme_path', '') or ''
                path.parent.mkdir(parents=True, exist_ok=True)
                atomic_write_json(path, payload)
        self.upgrade_subjective_rule_baseline(payload)
        return payload

    def filter_subjective_payload_to_current_entries(self, payload):
        if not self.current_session or not self.summary_data or not isinstance(payload, dict):
            return 0
        scores = payload.get('scores')
        if not isinstance(scores, dict):
            return 0
        valid_keys = {}
        basename_to_keys = defaultdict(list)
        for entry in self.summary_data:
            key = self.subjective_entry_key(entry)
            if not key:
                continue
            valid_keys[key] = key
            basename_to_keys[Path(key).name.lower()].append(key)
        if not valid_keys:
            return 0
        removed = 0
        for entry_key in list(scores.keys()):
            if entry_key in valid_keys:
                continue
            basename = Path(str(entry_key)).name.lower()
            source_parent = self.normalize_folder_path(Path(str(entry_key)).parent)
            matches = [
                key for key in (basename_to_keys.get(basename) or [])
                if self.normalize_folder_path(Path(key).parent) == source_parent
            ]
            if len(matches) == 1 and matches[0] not in scores:
                scores[matches[0]] = scores.pop(entry_key)
                payload['normalized_entry_keys_at'] = datetime.now().isoformat(timespec='seconds')
                continue
            if entry_key not in valid_keys:
                scores.pop(entry_key, None)
                removed += 1
        if removed:
            payload['filtered_to_current_session_at'] = datetime.now().isoformat(timespec='seconds')
            payload['filtered_removed_entries'] = int(payload.get('filtered_removed_entries') or 0) + removed
        return removed

    def merge_legacy_subjective_scores(self, payload, primary_path):
        merged = 0
        primary_scores = payload.setdefault('scores', {})
        valid_keys = set()
        basename_to_keys = defaultdict(list)
        for entry in self.summary_data:
            key = self.subjective_entry_key(entry)
            if not key:
                continue
            valid_keys.add(key)
            basename_to_keys[Path(key).name.lower()].append(key)
        # Identical scan names are common across classes. Without current
        # result entries, importing a folder score file would risk mixing tests.
        if not valid_keys:
            return 0
        for legacy_path in self.legacy_subjective_score_paths():
            if not legacy_path or legacy_path == primary_path or not legacy_path.exists():
                continue
            try:
                legacy = json.loads(legacy_path.read_text(encoding='utf-8-sig'))
                legacy_scores = legacy.get('scores', {}) if isinstance(legacy, dict) else {}
            except Exception:
                continue
            # A matching scan path/part number is not proof of test ownership.
            if self.current_session:
                if legacy.get('session_id') != self.current_session.get('id'):
                    continue
                if (legacy.get('template_key') != self.current_template_key
                        or legacy.get('subjective_answer_signature') != self.subjective_answer_signature()
                        or legacy.get('subjective_structure_signature') != self.subjective_structure_signature()):
                    continue
            for entry_key, entry_scores in legacy_scores.items():
                if not isinstance(entry_scores, dict):
                    continue
                target_key = entry_key
                if valid_keys and target_key not in valid_keys:
                    source_parent = self.normalize_folder_path(Path(str(entry_key)).parent)
                    matches = [
                        key for key in (basename_to_keys.get(Path(str(entry_key)).name.lower()) or [])
                        if self.normalize_folder_path(Path(key).parent) == source_parent
                    ]
                    if len(matches) != 1:
                        continue
                    target_key = matches[0]
                target_scores = primary_scores.setdefault(target_key, {})
                for part_id, record in entry_scores.items():
                    current_record = target_scores.get(part_id)
                    legacy_is_graded = isinstance(record, dict) and bool(
                        record.get('manual_graded')
                        or record.get('auto_graded')
                        or record.get('score') is not None
                    )
                    current_is_graded = isinstance(current_record, dict) and bool(
                        current_record.get('manual_graded')
                        or current_record.get('auto_graded')
                        or current_record.get('score') is not None
                    )
                    if part_id not in target_scores or (legacy_is_graded and not current_is_graded):
                        target_scores[part_id] = record
                        merged += 1
        if merged:
            payload['merged_legacy_scores_at'] = datetime.now().isoformat(timespec='seconds')
        return merged

    def save_subjective_score_payload(self, payload):
        current_id = (self.current_session or {}).get('id') or ''
        if payload.get('session_id') and payload['session_id'] != current_id:
            raise ValueError('拒绝保存：成绩来自其他测试，请重新打开批改窗口。')
        if payload.get('template_key') and payload['template_key'] != self.current_template_key:
            raise ValueError('拒绝保存：成绩模板与当前测试不同。')
        self.prepare_subjective_payload_for_grading(payload)
        payload['version'] = 2
        payload['template_key'] = self.current_template_key
        payload['template_name'] = self.current_template_name
        payload['subjective_answer_signature'] = self.subjective_answer_signature()
        payload['subjective_structure_signature'] = self.subjective_structure_signature()
        payload['answer_scheme_name'] = getattr(self, 'loaded_answer_key_scheme_name', '')
        payload['answer_scheme_path'] = getattr(self, 'loaded_answer_key_scheme_path', '') or ''
        scheme_path = getattr(self, 'loaded_answer_key_scheme_path', '') or ''
        if scheme_path:
            try:
                payload['answer_scheme_mtime'] = Path(scheme_path).stat().st_mtime
            except Exception:
                payload.pop('answer_scheme_mtime', None)
        if self.current_session:
            payload['session_id'] = self.current_session.get('id')
            payload['session_name'] = self.current_session.get('name', '')
            self.filter_subjective_payload_to_current_entries(payload)
        payload['updated_at'] = datetime.now().isoformat(timespec='seconds')
        path = self.subjective_scores_path()
        path.parent.mkdir(parents=True, exist_ok=True)
        atomic_write_json(path, payload)
        return path

    def archive_subjective_score_payload(self, payload, reason='before_rules_change'):
        path = self.subjective_scores_path()
        backup = path.with_name(f'{path.stem}.{reason}_{uuid.uuid4().hex}.json')
        atomic_write_json(backup, payload)
        return backup

    def prepare_subjective_payload_for_grading(self, payload):
        """One transition path for opening, saving, regrading and totals."""
        current_id = (self.current_session or {}).get('id') or ''
        if (payload.get('session_id') or '') != current_id:
            raise ValueError('成绩属于其他测试，不能在当前测试中使用。')
        if not self.subjective_payload_matches_current_structure(payload):
            raise ValueError('试卷结构已变化，成绩已保留，请加载对应试卷后批改。')
        self.upgrade_subjective_rule_baseline(payload)
        if not isinstance(payload.get('subjective_part_rules'), dict):
            raise ValueError('旧成绩缺少逐空规则记录，无法确定变更范围；成绩已保留。'
                             '请加载原答案版本后更正，或使用已有OCR结果重新判分。')
        current_rules = self.subjective_part_rules()
        if changed_parts(payload['subjective_part_rules'], current_rules):
            self.archive_subjective_score_payload(payload)
            reconcile_scores(payload, current_rules)
            payload['legacy_merge_disabled'] = True
        payload['subjective_answer_signature'] = self.subjective_answer_signature()
        return payload

    def prepare_subjective_payload_for_regrading(self, payload):
        """Explicit legacy regrade may invalidate auto marks, never manual work."""
        if (payload.get('session_id') or '') != ((self.current_session or {}).get('id') or ''):
            raise ValueError('不能在另一测试中重判旧窗口的识别结果。')
        if not self.subjective_payload_matches_current_structure(payload):
            raise ValueError('试卷结构已变化，请关闭窗口后重新裁图批改。')
        self.upgrade_subjective_rule_baseline(payload)
        if not isinstance(payload.get('subjective_part_rules'), dict):
            self.archive_subjective_score_payload(payload)
            # Unknown legacy rules: only this explicit regrade can transition.
            # Preserve manual judgments, using recorded maximum where known.
            rules = self.subjective_part_rules()
            payload['subjective_part_rules'] = {
                key: {'score': rule['score'], 'legacy_unknown': True}
                for key, rule in rules.items()}
        return self.prepare_subjective_payload_for_grading(payload)

    def subjective_part_rules(self):
        """Scoring semantics, independent of scheme names and OCR layout options."""
        rules = {}
        parts = list(self.iter_subjective_parts())
        if not self.mixed_template_single_side_mode_enabled():
            parts.extend(self.calculation_score_parts())
        for part in parts:
            ocr = self.normalize_ocr_config(part.get('ocr'))
            rules[part['part_id']] = {
                'score': float(part.get('score') or 0),
                'kind': part.get('kind') or '',
                'score_category': part.get('score_category') or '',
                'ocr': {key: ocr[key] for key in (
                    'expected_answer', 'expected_keywords', 'common_wrong_answers',
                    'wrong_keywords', 'unique_answer', 'choice_fill', 'split_char_check')},
            }
        return rules

    def upgrade_subjective_rule_baseline(self, payload):
        """Legacy marks get a baseline only when their old signature is proven."""
        if isinstance(payload.get('subjective_part_rules'), dict):
            return
        if not payload.get('scores') or (
                payload.get('subjective_answer_signature') == self.subjective_answer_signature()):
            payload['subjective_part_rules'] = self.subjective_part_rules()
            payload['version'] = 2

    def refresh_subjective_window_payload(self, payload, fresh_payload):
        """Refresh both records and version metadata without breaking callbacks."""
        if fresh_payload.get('session_id') != payload.get('session_id'):
            raise ValueError('不能用其他测试的成绩刷新当前批改窗口。')
        fresh = copy.deepcopy(fresh_payload)
        scores = payload.setdefault('scores', {})
        scores.clear()
        scores.update(fresh.pop('scores', {}))
        payload.clear()
        payload.update(fresh)
        payload['scores'] = scores
        return payload

    def subjective_answer_signature(self):
        parts = []
        for part in self.iter_subjective_parts():
            parts.append({
                'part_id': part.get('part_id'),
                'score': float(part.get('score') or 0),
                'kind': part.get('kind') or '',
                'score_category': part.get('score_category') or '',
                'ocr': self.normalize_ocr_config(part.get('ocr')),
            })
        payload = {
            'template_key': self.current_template_key,
            'parts': parts,
            'scheme_name': getattr(self, 'loaded_answer_key_scheme_name', ''),
        }
        raw = json.dumps(payload, ensure_ascii=False, sort_keys=True)
        return hashlib.sha256(raw.encode('utf-8')).hexdigest()

    def subjective_structure_signature(self):
        parts = []
        for part in self.iter_subjective_parts():
            rect = part.get('rect') or {}
            parts.append({
                'part_id': part.get('part_id'),
                'kind': part.get('kind') or '',
                'side': str(part.get('side') or 'front').lower(),
                'region_name': part.get('region_name') or '',
                'rect': {
                    key: round(float(rect.get(key) or 0), 3)
                    for key in ('x', 'y', 'w', 'h')
                },
            })
        raw = json.dumps({
            'template_key': self.current_template_key,
            'parts': parts,
        }, ensure_ascii=False, sort_keys=True)
        return hashlib.sha256(raw.encode('utf-8')).hexdigest()

    def subjective_payload_matches_current_structure(self, payload):
        if not isinstance(payload, dict):
            return False
        if payload.get('template_key') and payload.get('template_key') != self.current_template_key:
            return False
        signature = str(payload.get('subjective_structure_signature') or '')
        if signature:
            return signature == self.subjective_structure_signature()

        # Compatibility for progress files created before structure signatures
        # were added. Existing score keys must all still exist in this paper.
        current_ids = {str(part.get('part_id') or '') for part in self.iter_subjective_parts()}
        saved_ids = set()
        for entry_scores in (payload.get('scores') or {}).values():
            if isinstance(entry_scores, dict):
                saved_ids.update(str(part_id) for part_id in entry_scores)
        return not saved_ids or saved_ids.issubset(current_ids)

    def subjective_payload_matches_current_answers(self, payload):
        if not isinstance(payload, dict):
            return False
        if (payload.get('session_id') or '') != ((self.current_session or {}).get('id') or ''):
            return False
        if not self.subjective_payload_matches_current_structure(payload):
            return False
        scores = payload.get('scores') or {}
        if not scores:
            return True
        if isinstance(payload.get('subjective_part_rules'), dict):
            return payload['subjective_part_rules'] == self.subjective_part_rules()
        signature = str(payload.get('subjective_answer_signature') or '')
        if not signature:
            return False
        if signature != self.subjective_answer_signature():
            return False
        return True

    def generate_subjective_crops(self, reuse_existing=False):
        parts = list(self.iter_subjective_parts())
        calculation_part = self.direct_calculation_crop_part()
        if calculation_part:
            parts.append(calculation_part)
        if not parts:
            return self.subjective_crops_root(), 0, ['当前模板没有配置主观题区域。'], {}
        if not self.summary_data:
            return self.subjective_crops_root(), 0, ['请先完成批改，再导出主观题裁图。'], {}

        export_root = self.subjective_crops_root()
        export_root.mkdir(parents=True, exist_ok=True)
        expected_manifest = self.subjective_crop_manifest(parts)
        if reuse_existing and not self.subjective_crop_manifest_matches(expected_manifest):
            reuse_existing = False

        def newest_crop_dependency_mtime(entry):
            newest = 0.0
            dependency_paths = []
            input_path = Path(entry.get('input_path') or '')
            if input_path.exists():
                dependency_paths.append(input_path)
            for side_path_value in (entry.get('side_files') or {}).values():
                side_path = Path(side_path_value or '')
                if side_path.exists():
                    dependency_paths.append(side_path)
            for dependency_path in dependency_paths:
                try:
                    newest = max(newest, float(dependency_path.stat().st_mtime))
                except Exception:
                    pass
            return newest

        def existing_crops_are_fresh(expected_paths, entry):
            if not expected_paths or not all(path.exists() for path in expected_paths.values()):
                return False
            newest_dependency = newest_crop_dependency_mtime(entry)
            for crop_path in expected_paths.values():
                try:
                    # If the paper image or subjective structure was changed after
                    # the crop was generated, re-crop instead of silently reusing
                    # stale images from an earlier structure.
                    if float(crop_path.stat().st_mtime) + 0.5 < newest_dependency:
                        return False
                except Exception:
                    return False
            return True

        saved = 0
        errors = []
        crop_map = {}
        for entry in self.summary_data:
            input_path = Path(entry.get('input_path') or '')
            if not input_path.exists():
                errors.append(f"{entry.get('file', '')}: 找不到原图")
                continue

            try:
                student_label = self.safe_file_part(f"{entry.get('score_id', '未识别')}_{entry.get('student_name', '未匹配')}_{input_path.stem}")
                student_dir = export_root / student_label
                entry_key = self.subjective_entry_key(entry)
                crop_map.setdefault(entry_key, {})
                expected_paths = {}
                for index, part in enumerate(parts, 1):
                    side = str(part.get('side') or 'front').lower()
                    side_prefix = 'back_' if side == 'back' else ''
                    name = f"{index:02d}_{side_prefix}{self.safe_file_part(part['label'])}.jpg"
                    expected_paths[part.get('part_id') or str(index)] = student_dir / name
                if reuse_existing and existing_crops_are_fresh(expected_paths, entry):
                    for part_id, crop_path in expected_paths.items():
                        crop_map[entry_key][part_id] = str(crop_path)
                    continue

                student_dir.mkdir(parents=True, exist_ok=True)
                side_cache = {}

                for index, part in enumerate(parts, 1):
                    side = str(part.get('side') or 'front').lower()
                    side = 'back' if side == 'back' else 'front'
                    if side not in side_cache:
                        source_path = self.entry_image_path_for_side(entry, side)
                        if not source_path.exists():
                            errors.append(f"{entry.get('file', '')}: 找不到{side}面原图")
                            side_cache[side] = None
                            continue
                        oriented_image, _rotation_name = self.orient_entry_image_for_side(entry, source_path, side)
                        with tempfile.NamedTemporaryFile(suffix='.png', delete=False) as tmp:
                            oriented_temp_path = Path(tmp.name)
                        oriented_image.save(oriented_temp_path)
                        try:
                            homography_side = side if entry.get('side_files') else None
                            homography = self.entry_alignment_homography(entry, side)
                            if homography is None:
                                homography, _marker_payload = self.detect_scan_homography(
                                    oriented_temp_path,
                                    side=homography_side,
                                )
                            side_cache[side] = {
                                'image': oriented_image,
                                'homography': homography,
                                'size': oriented_image.size,
                            }
                        finally:
                            try:
                                oriented_temp_path.unlink(missing_ok=True)
                            except Exception:
                                pass
                    cached_side = side_cache.get(side)
                    if not cached_side:
                        continue
                    oriented_image = cached_side['image']
                    homography = cached_side['homography']
                    width, height = cached_side['size']
                    rect = self.clip_template_rect_to_region(part['rect'], part.get('region_name'))
                    left, top, right, bottom = self.project_template_rect(homography, rect)
                    left = max(0, min(width - 1, left))
                    top = max(0, min(height - 1, top))
                    right = max(left + 1, min(width, right))
                    bottom = max(top + 1, min(height, bottom))
                    crop = oriented_image.crop((left, top, right, bottom))
                    crop_path = expected_paths.get(part.get('part_id') or str(index))
                    crop.save(crop_path, quality=92)
                    crop_map[entry_key][part.get('part_id') or str(index)] = str(crop_path)
                    saved += 1
            except Exception as e:
                errors.append(f"{entry.get('file', '')}: {e}")

        try:
            self.subjective_crop_manifest_path().write_text(
                json.dumps(expected_manifest, ensure_ascii=False, indent=2),
                encoding='utf-8',
            )
        except Exception:
            pass

        return export_root, saved, errors, crop_map

    def export_subjective_crops(self):
        export_root, saved, errors, _crop_map = self.generate_subjective_crops()
        if errors and saved == 0:
            messagebox.showwarning('提示', '\n'.join(errors[:10]))
            return
        msg = f"已导出主观题裁图：{saved} 张\n目录：{export_root}"
        if errors:
            msg += f"\n\n失败 {len(errors)} 项：\n" + '\n'.join(errors[:10])
        messagebox.showinfo('导出完成', msg)
        if hasattr(self, 'status_var'):
            self.status_var.set(f'已导出主观题裁图：{saved} 张')

    # -------------------------------------------------------------------------
    # VPS网页端人工打分同步模块 已抽离至 core.web_sync.ManualWebSyncMixin
    # -------------------------------------------------------------------------

    def apply_subjective_scores_to_entries(self, payload=None):
        payload = payload or self.load_subjective_score_payload()
        # Never turn a version mismatch into an empty whole-class score view.
        # Reconcile known part revisions; unknown ownership/structure fails
        # before touching summary_data or its persisted totals.
        compatible_before = self.subjective_payload_matches_current_answers(payload)
        self.prepare_subjective_payload_for_grading(payload)
        if not compatible_before:
            self.save_subjective_score_payload(payload)
        score_parts = self.subjective_score_parts(include_calculation=True)
        part_map = {part['part_id']: part for part in score_parts}
        max_score = sum(float(part.get('score') or 0) for part in score_parts)
        category_max_scores = defaultdict(float)
        special_max_scores = defaultdict(float)
        for part in score_parts:
            category = part.get('score_category') or part.get('kind') or part.get('region_name') or 'other'
            category_max_scores[category] += float(part.get('score') or 0)
            if part.get('is_experiment_drawing'):
                special_max_scores['experiment_drawing'] += float(part.get('score') or 0)
        payload_compatible = self.subjective_payload_matches_current_answers(payload)
        all_scores = payload.get('scores', {}) if isinstance(payload, dict) and payload_compatible else {}

        for entry in self.summary_data:
            entry_key = self.subjective_entry_key(entry)
            entry_scores = all_scores.get(entry_key, {})
            raw_score = 0.0
            graded_count = 0
            saved_scores = {}
            category_scores = defaultdict(float)
            category_graded_counts = defaultdict(int)
            special_scores = defaultdict(float)
            special_graded_counts = defaultdict(int)
            for part_id, part in part_map.items():
                record = entry_scores.get(part_id)
                if isinstance(record, dict) and record.get('score') is not None:
                    part_max_score = max(0.0, float(part.get('score') or 0))
                    value = max(0.0, min(part_max_score, float(record.get('score') or 0)))
                    if value != float(record.get('score') or 0) or float(record.get('max_score') or 0) != part_max_score:
                        record = dict(record)
                        record['score'] = value
                        record['max_score'] = part_max_score
                    raw_score += value
                    graded_count += 1
                    saved_scores[part_id] = record
                    category = part.get('score_category') or part.get('kind') or part.get('region_name') or 'other'
                    category_scores[category] += value
                    category_graded_counts[category] += 1
                    if part.get('is_experiment_drawing'):
                        special_scores['experiment_drawing'] += value
                        special_graded_counts['experiment_drawing'] += 1

            category_payload = {}
            for category, category_max in category_max_scores.items():
                category_payload[category] = {
                    'raw_score': round(category_scores.get(category, 0.0), 2),
                    'max_score': round(category_max, 2),
                    'graded_count': int(category_graded_counts.get(category, 0)),
                }

            special_payload = {}
            for special_key, special_max in special_max_scores.items():
                special_payload[special_key] = {
                    'raw_score': round(special_scores.get(special_key, 0.0), 2),
                    'max_score': round(special_max, 2),
                    'graded_count': int(special_graded_counts.get(special_key, 0)),
                }

            objective_raw = float(entry.get('raw_score') or 0)
            objective_max = float(entry.get('max_total_score') or 0)
            combined_raw = objective_raw + raw_score
            combined_max = objective_max + max_score
            combined_percentage = (combined_raw / combined_max * 100) if combined_max else 0.0

            subjective = entry.get('subjective') or {}
            subjective.update({
                'configured': bool(score_parts) and payload_compatible and graded_count > 0,
                'score_payload_compatible': bool(payload_compatible),
                'item_count': len(self.subjective_items()),
                'total_parts': len(score_parts),
                'graded_count': graded_count,
                'raw_score': round(raw_score, 2),
                'max_score': round(max_score, 2),
                'score_percentage': round((raw_score / max_score * 100) if max_score else 0.0, 2),
                'category_scores': category_payload,
                'special_scores': special_payload,
                'scores': saved_scores,
                'score_file': str(self.subjective_scores_path()),
                'include_in_total_score': False,
            })
            entry['subjective'] = subjective
            if payload_compatible and graded_count > 0:
                entry['combined_raw_score'] = round(combined_raw, 2)
                entry['combined_max_score'] = round(combined_max, 2)
                entry['combined_score'] = round(combined_percentage, 2)
            else:
                entry.pop('combined_raw_score', None)
                entry.pop('combined_max_score', None)
                entry.pop('combined_score', None)

        if self.current_session and self.summary_data and not getattr(self, '_suppress_subjective_autosave', False):
            self._applying_subjective_totals = True
            try:
                self.save_results_to_database()
                self._last_result_sync_error = ''
            except Exception as exc:
                # The JSON progress file is still the primary safety net; DB sync should never block grading.
                self._last_result_sync_error = str(exc)
            finally:
                self._applying_subjective_totals = False

        return payload

    def scan_rect_to_template_rect(self, matrix, rect):
        x = float(rect.get('x', 0))
        y = float(rect.get('y', 0))
        w = float(rect.get('w', 0))
        h = float(rect.get('h', 0))
        points = [
            apply_homography(matrix, (x, y)),
            apply_homography(matrix, (x + w, y)),
            apply_homography(matrix, (x + w, y + h)),
            apply_homography(matrix, (x, y + h)),
        ]
        xs = [p[0] for p in points]
        ys = [p[1] for p in points]
        return {
            'x': round(float(min(xs)), 1),
            'y': round(float(min(ys)), 1),
            'w': round(float(max(xs) - min(xs)), 1),
            'h': round(float(max(ys) - min(ys)), 1),
        }

    def merge_detected_line_boxes(self, boxes):
        merged = []
        for box in sorted(boxes, key=lambda item: (item['cy'], item['x'])):
            target = None
            for existing in merged:
                same_row = abs(existing['cy'] - box['cy']) <= 5
                gap = box['x'] - (existing['x'] + existing['w'])
                overlaps = not (box['x'] > existing['x'] + existing['w'] + 20 or existing['x'] > box['x'] + box['w'] + 20)
                if same_row and (overlaps or 0 <= gap <= 18):
                    target = existing
                    break
            if target is None:
                merged.append(dict(box))
                continue
            left = min(target['x'], box['x'])
            top = min(target['y'], box['y'])
            right = max(target['x'] + target['w'], box['x'] + box['w'])
            bottom = max(target['y'] + target['h'], box['y'] + box['h'])
            target.update({
                'x': left,
                'y': top,
                'w': right - left,
                'h': bottom - top,
                'cy': (top + bottom) / 2.0,
            })
        return sorted(merged, key=lambda item: (item['cy'], item['x']))

    def sort_experiment_detected_lines_for_assignment(self, lines):
        if not lines:
            return []
        rows = self.group_experiment_detected_lines_by_row(lines)
        result = []
        for row in rows:
            items = sorted(row['items'], key=lambda item: item['scan_box']['x'])
            result.extend(items)
        return result

    def group_experiment_detected_lines_by_row(self, lines, tolerance=32):
        if not lines:
            return []
        sorted_lines = sorted(lines, key=lambda item: (item['scan_box']['cy'], item['scan_box']['x']))
        rows = []
        for line in sorted_lines:
            cy = line['scan_box']['cy']
            if not rows or abs(rows[-1]['cy'] - cy) > tolerance:
                rows.append({'cy': cy, 'items': [line]})
            else:
                rows[-1]['items'].append(line)
                rows[-1]['cy'] = sum(item['scan_box']['cy'] for item in rows[-1]['items']) / len(rows[-1]['items'])
        return rows

    def detect_experiment_lines_from_blank(self, image_path):
        region = ((getattr(self, 'subjective_config', {}) or {}).get('crop_regions', {}) or {}).get('experiment')
        if not region:
            raise RuntimeError('当前模板还没有实验题锁定区域，不能自动识别横线。')

        oriented_image, _rotation_name = self.auto_orient_image(image_path)
        with tempfile.NamedTemporaryFile(suffix='.png', delete=False) as tmp:
            oriented_temp_path = Path(tmp.name)
        oriented_image.save(oriented_temp_path)
        try:
            homography, _marker_payload = self.detect_scan_homography(oriented_temp_path)
        finally:
            try:
                oriented_temp_path.unlink(missing_ok=True)
            except Exception:
                pass

        inv_homography = np.linalg.inv(np.asarray(homography, dtype=float)).tolist()
        left, top, right, bottom = self.project_template_rect(homography, region)
        width, height = oriented_image.size
        left = max(0, min(width - 1, left))
        top = max(0, min(height - 1, top))
        right = max(left + 1, min(width, right))
        bottom = max(top + 1, min(height, bottom))

        gray = cv2.cvtColor(np.array(oriented_image), cv2.COLOR_RGB2GRAY)
        roi = gray[top:bottom, left:right]
        if roi.size == 0:
            raise RuntimeError('实验题区域裁剪失败，请确认空白模板定位块清晰。')

        blurred = cv2.GaussianBlur(roi, (3, 3), 0)
        binary = cv2.adaptiveThreshold(
            blurred,
            255,
            cv2.ADAPTIVE_THRESH_MEAN_C,
            cv2.THRESH_BINARY_INV,
            31,
            12,
        )
        kernel_width = 45
        kernel = cv2.getStructuringElement(cv2.MORPH_RECT, (kernel_width, 2))
        opened = cv2.morphologyEx(binary, cv2.MORPH_OPEN, kernel)
        opened = cv2.dilate(opened, cv2.getStructuringElement(cv2.MORPH_RECT, (7, 3)), iterations=1)
        contours, _hierarchy = cv2.findContours(opened, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)

        boxes = []
        for contour in contours:
            x, y, w, h = cv2.boundingRect(contour)
            if w < 50 or h > 28:
                continue
            if w / max(1, h) < 8:
                continue
            gx = int(left + x)
            gy = int(top + y)
            boxes.append({
                'x': gx,
                'y': gy,
                'w': int(w),
                'h': int(h),
                'cy': gy + h / 2.0,
            })

        boxes = self.merge_detected_line_boxes(boxes)
        policy = (getattr(self, 'subjective_config', {}) or {}).get('crop_policy', {}) or {}
        top_margin = int(policy.get('line_top_margin') or 92)
        bottom_margin = int(policy.get('line_bottom_margin') or 22)
        lines = []
        sorted_boxes = [
            item['scan_box']
            for item in self.sort_experiment_detected_lines_for_assignment([
                {'scan_box': box}
                for box in boxes
            ])
        ]
        for index, box in enumerate(sorted_boxes, 1):
            x_margin = 8
            scan_rect = {
                'x': max(0, box['x'] - x_margin),
                'y': max(0, box['cy'] - top_margin),
                'w': box['w'] + x_margin * 2,
                'h': top_margin + bottom_margin,
            }
            template_rect = self.scan_rect_to_template_rect(inv_homography, scan_rect)
            lines.append({
                'index': index,
                'scan_box': box,
                'scan_rect': scan_rect,
                'template_rect': template_rect,
            })

        preview = oriented_image.copy()
        draw = ImageDraw.Draw(preview)
        try:
            label_font = ImageFont.truetype('arial.ttf', 34)
        except Exception:
            label_font = ImageFont.load_default()
        for line in lines:
            rect = line['scan_rect']
            x1 = int(rect['x'])
            y1 = int(rect['y'])
            x2 = int(rect['x'] + rect['w'])
            y2 = int(rect['y'] + rect['h'])
            draw.rectangle((x1, y1, x2, y2), outline='red', width=4)
            label = str(line['index'])
            label_box = (x1 + 4, y1 + 4, x1 + 62, y1 + 44)
            draw.rectangle(label_box, fill='yellow', outline='red', width=2)
            draw.text((x1 + 12, y1 + 6), label, fill='red', font=label_font)
        preview_crop = preview.crop((left, top, right, bottom))
        preview_crop.thumbnail((460, 620), Image.LANCZOS)
        return lines, preview_crop

    def default_experiment_assignment_text(self, lines):
        row_groups = self.group_experiment_detected_lines_by_row(lines)
        text_lines = [
            '# 默认按同一行归为同一个小题。',
            '# 例如 20(1): 1,2,3 表示第20题第1小题包含编号1到3的空。',
            '# 13-18题是填空题，这里不用设置。',
            '',
        ]
        if len(row_groups) == 18:
            row_template_groups = [
                (20, 1), (20, 2), (20, 3), (20, 4),
                (21, 1), (21, 2), (21, 3), (21, 4), (21, 5),
                (22, 1), (22, 2), (22, 3), (22, 4),
                (23, 1), (23, 2), (23, 3), (23, 4), (23, 5),
            ]
            for (question_no, sub_no), row in zip(row_template_groups, row_groups):
                nums = [str(item['index']) for item in sorted(row['items'], key=lambda item: item['scan_box']['x'])]
                if nums:
                    text_lines.append(f'{question_no}({sub_no}): {",".join(nums)}')
            return '\n'.join(text_lines)

        current_question = 20
        sub_no = 1
        for row in row_groups:
            nums = [str(item['index']) for item in sorted(row['items'], key=lambda item: item['scan_box']['x'])]
            if nums:
                text_lines.append(f'{current_question}({sub_no}): {",".join(nums)}')
            sub_no += 1
            if sub_no > 5:
                current_question += 1
                sub_no = 1
            if current_question > 23:
                break
        return '\n'.join(text_lines)

    def parse_experiment_assignment_text(self, text, lines):
        line_map = {line['index']: line for line in lines}
        assignments = defaultdict(list)
        for raw in text.splitlines():
            line = raw.strip()
            if not line or line.startswith('#'):
                continue
            match = re.match(r'^(\d+)\s*(?:题)?\s*(?:[（(]\s*(\d+)\s*[）)])?\s*[:：]\s*(.+)$', line)
            if not match:
                continue
            question_no = int(match.group(1))
            if question_no < 20 or question_no > 23:
                continue
            sub_no = int(match.group(2) or (len(assignments[question_no]) + 1))
            nums = [int(n) for n in re.findall(r'\d+', match.group(3))]
            blanks = []
            for num in nums:
                detected = line_map.get(num)
                if detected:
                    blanks.append(detected)
            if blanks:
                assignments[question_no].append({'sub_no': sub_no, 'lines': blanks})
        return assignments

    def save_ocr_settings_for_parts(self, settings_by_part_id):
        config_path = getattr(self, 'subjective_config_path', None)
        if not config_path or not Path(config_path).exists():
            raise RuntimeError('找不到当前模板的主观题配置文件。')

        config = copy.deepcopy(self.subjective_config or {})
        for item in config.get('items', []) or []:
            qno = item.get('question_no')
            for blank in item.get('blanks', []) or []:
                part_id = f"q{qno}_b{blank.get('blank_no', 1)}"
                if part_id in settings_by_part_id:
                    blank['ocr'] = self.normalize_ocr_config(settings_by_part_id[part_id])
            for sub in item.get('subquestions', []) or []:
                sub_no = sub.get('sub_no', 1)
                for blank in sub.get('blanks', []) or []:
                    part_id = f"q{qno}_s{sub_no}_b{blank.get('blank_no', 1)}"
                    if part_id in settings_by_part_id:
                        blank['ocr'] = self.normalize_ocr_config(settings_by_part_id[part_id])

        config['updated_at'] = datetime.now().isoformat(timespec='seconds')
        atomic_write_json(config_path, config)
        self.subjective_config = config

    def save_drawing_settings_for_parts(self, settings_by_part_id):
        config_path = getattr(self, 'subjective_config_path', None)
        if not config_path or not Path(config_path).exists():
            raise RuntimeError('找不到当前模板的主观题配置文件。')
        if not isinstance(settings_by_part_id, dict):
            return

        config_path = Path(config_path)
        config = json.loads(config_path.read_text(encoding='utf-8-sig'))
        changed = False
        for item in config.get('items', []) or []:
            if item.get('kind') != 'drawing':
                continue
            part_id = item.get('part_id') or f"q{item.get('question_no')}"
            settings = settings_by_part_id.get(part_id) or settings_by_part_id.get(f"q{item.get('question_no')}")
            if not settings:
                continue
            try:
                max_score = float(settings.get('max_score') or 0)
            except Exception:
                max_score = 0.0
            item['max_score'] = max_score
            item['manual_only'] = True
            item['score_category'] = settings.get('score_category') or 'drawing'
            changed = True

        if changed:
            config['updated_at'] = datetime.now().isoformat(timespec='seconds')
            atomic_write_json(config_path, config)
            self.subjective_config = config

    def subjective_part_setting_config(self, part):
        config = self.normalize_ocr_config((part or {}).get('ocr'))
        if (part or {}).get('kind') == 'drawing':
            config.update({
                'enabled': False,
                'single_char': False,
                'split_char_check': False,
                'expected_answer': '作图',
                'expected_keywords': '',
                'common_wrong_answers': '',
                'wrong_keywords': '',
                'prefix': '',
                'suffix': '',
            })
        return config

    def get_subjective_ocr_settings_for_scheme(self):
        settings = {}
        for part in self.iter_subjective_parts():
            settings[part['part_id']] = self.subjective_part_setting_config(part)
        return settings

    def apply_subjective_ocr_settings_from_scheme(self, settings_by_part_id):
        if not isinstance(settings_by_part_id, dict) or not settings_by_part_id:
            return 0
        parts_by_id = {
            part['part_id']: part
            for part in self.iter_subjective_parts()
        }
        settings = {
            part_id: self.subjective_part_setting_config({
                **parts_by_id[part_id],
                'ocr': config,
            })
            for part_id, config in settings_by_part_id.items()
            if part_id in parts_by_id
        }
        if not settings:
            return 0
        non_drawing_settings = {
            part_id: config
            for part_id, config in settings.items()
            if parts_by_id[part_id].get('kind') != 'drawing'
        }
        if non_drawing_settings:
            self.save_ocr_settings_for_parts(non_drawing_settings)
        return len(settings)

    def open_regrade_single_subjective_part_dialog(self, default_part_id=None, parent_win=None):
        parts = list(self.iter_subjective_parts())
        if not parts:
            messagebox.showinfo('提示', '当前模板没有配置主观题空位。', parent=parent_win or self.root)
            return

        dialog = tk.Toplevel(parent_win or self.root)
        dialog.title('⚡ 更正单空答案并快速重判 (免重新跑OCR)')
        dialog.geometry('680x500')
        dialog.minsize(580, 440)
        dialog.transient(parent_win or self.root)
        dialog.grab_set()

        content = ttk.Frame(dialog, padding=16)
        content.pack(fill=tk.BOTH, expand=True)

        ttk.Label(
            content,
            text='🎯 更正单空答案并免重新OCR重判',
            font=('Arial', 13, 'bold'),
        ).pack(anchor='w', pady=(0, 4))

        ttk.Label(
            content,
            text='适用于自动判分后发现某个空的标准答案配错：\n'
                 '只需更正该空答案，系统将基于前序已有的 OCR 识别结果极速重新判分，\n'
                 '同时保存当前测试的答案，更新总分和排名；主动导出时生成最新课件和透打。',
            font=('Arial', 9),
            foreground='#555555',
            justify=tk.LEFT,
        ).pack(anchor='w', pady=(0, 12))

        form = ttk.LabelFrame(content, text='更正设置', padding=12)
        form.pack(fill=tk.BOTH, expand=True, pady=(0, 12))

        ttk.Label(form, text='选择题目空位：', font=('Arial', 10, 'bold')).grid(row=0, column=0, sticky='w', pady=6)
        part_combobox = ttk.Combobox(form, state='readonly', width=45)
        part_combobox.grid(row=0, column=1, sticky='ew', pady=6, padx=(8, 0))

        combo_values = []
        part_by_index = {}
        target_idx = 0
        norm_default = self.normalize_target_part_id(default_part_id) if default_part_id else None

        for idx, part in enumerate(parts):
            ocr_c = part.get('ocr') or {}
            curr_ans = str(ocr_c.get('expected_answer') or '未设置')
            disp = f"[{part['part_id']}] {part.get('label', part['part_id'])} (当前答案: {curr_ans})"
            combo_values.append(disp)
            part_by_index[idx] = part
            if norm_default and part['part_id'] == norm_default:
                target_idx = idx

        part_combobox['values'] = combo_values
        part_combobox.current(target_idx)

        old_ans_var = tk.StringVar()
        ttk.Label(form, text='原标准答案：').grid(row=1, column=0, sticky='w', pady=6)
        old_ans_label = ttk.Label(form, textvariable=old_ans_var, font=('Arial', 10, 'italic'), foreground='#666')
        old_ans_label.grid(row=1, column=1, sticky='w', pady=6, padx=(8, 0))

        new_ans_var = tk.StringVar()
        ttk.Label(form, text='更正后的标准答案：', font=('Arial', 10, 'bold')).grid(row=2, column=0, sticky='w', pady=6)
        new_ans_entry = ttk.Entry(form, textvariable=new_ans_var, width=45, font=('Arial', 10))
        new_ans_entry.grid(row=2, column=1, sticky='ew', pady=6, padx=(8, 0))
        ttk.Label(form, text='* 支持多个正确答案，用“/”分隔，如：加速 / 加速运动', foreground='#888', font=('Arial', 8)).grid(row=3, column=1, sticky='w', padx=(8, 0))

        new_kw_var = tk.StringVar()
        ttk.Label(form, text='采分关键词(可选)：').grid(row=4, column=0, sticky='w', pady=6)
        new_kw_entry = ttk.Entry(form, textvariable=new_kw_var, width=45, font=('Arial', 10))
        new_kw_entry.grid(row=4, column=1, sticky='ew', pady=6, padx=(8, 0))
        ttk.Label(form, text='* 包含任一关键词即判对，多个关键词用空格分隔', foreground='#888', font=('Arial', 8)).grid(row=5, column=1, sticky='w', padx=(8, 0))

        override_var = tk.BooleanVar(value=False)
        ttk.Checkbutton(
            form,
            text='已有人工打分的记录也用新答案重新判分 (默认不勾选，保护人工成绩)',
            variable=override_var,
        ).grid(row=6, column=0, columnspan=2, sticky='w', pady=(10, 4))

        form.columnconfigure(1, weight=1)

        def on_part_selected(event=None):
            sel_idx = part_combobox.current()
            selected_part = part_by_index.get(sel_idx)
            if selected_part:
                ocr_c = selected_part.get('ocr') or {}
                cur_ans = str(ocr_c.get('expected_answer') or '')
                cur_kw = str(ocr_c.get('expected_keywords') or '')
                old_ans_var.set(cur_ans if cur_ans else '(暂无设置)')
                new_ans_var.set(cur_ans)
                new_kw_var.set(cur_kw)

        part_combobox.bind('<<ComboboxSelected>>', on_part_selected)
        on_part_selected()
        new_ans_entry.focus_set()

        status_var = tk.StringVar()
        status_label = ttk.Label(content, textvariable=status_var, font=('Arial', 9))
        status_label.pack(anchor='w', pady=(0, 8))

        button_row = ttk.Frame(content)
        button_row.pack(fill=tk.X)

        def do_regrade():
            sel_idx = part_combobox.current()
            selected_part = part_by_index.get(sel_idx)
            if not selected_part:
                messagebox.showwarning('提示', '请选择要更正的题目空位。', parent=dialog)
                return
            new_ans = new_ans_var.get().strip()
            if not new_ans and not new_kw_var.get().strip():
                if not messagebox.askyesno('确认', '标准答案和采分关键词均为空，确认继续吗？（此空将被判定为未命中）', parent=dialog):
                    return

            target_pid = selected_part['part_id']
            status_var.set('正在重新判分中...')
            dialog.update_idletasks()

            try:
                res = self.regrade_single_subjective_part(
                    part_id=target_pid,
                    new_expected_answer=new_ans,
                    expected_keywords=new_kw_var.get().strip(),
                    override_manual=override_var.get(),
                )
                if not res.get('ok'):
                    messagebox.showerror('更正重判失败', res.get('error', '未知错误'), parent=dialog)
                    status_var.set('')
                    return

                scheme_msg = '\n• 答案已保存到当前测试快照。' if self.current_session else '\n• 答案已保存到当前配置。'
                msg = (
                    f"✅ 更正重判成功！\n\n"
                    f"• 题目空位：{res.get('label')} ({res.get('part_id')})\n"
                    f"• 新标准答案：{res.get('new_expected_answer')}\n"
                    f"• 重判试卷总数：{res.get('total_records')} 份\n"
                    f"• 命中满分：{res.get('matched_count')} 份\n"
                    f"• 判为零分/未识别：{res.get('zero_count')} 份\n"
                    f"• 未命中/待复核：{res.get('unmatched_count')} 份\n"
                    f"• 跳过已人工打分：{res.get('skipped_manual')} 份"
                    f"{scheme_msg}"
                )
                msg += '\n• 总分、排名和预览已刷新；需要新课件或透打文件时，请主动导出。'
                if res.get('output_errors'):
                    msg += '\n以下同步尚未完成，请按提示处理：\n' + '\n'.join(res['output_errors'])
                msg += '\n已打印或另行复制的旧文件需重新打印或替换。'
                messagebox.showinfo('重判完成', msg, parent=dialog)
                dialog.destroy()
            except Exception as e:
                messagebox.showerror('错误', f'重判过程中出现异常：\n{e}', parent=dialog)
                status_var.set('')

        submit_btn = ttk.Button(button_row, text='🚀 提交更正并快速重判', command=do_regrade)
        submit_btn.pack(side=tk.LEFT, padx=(0, 8))
        cancel_btn = ttk.Button(button_row, text='取消', command=dialog.destroy)
        cancel_btn.pack(side=tk.LEFT)

    def classify_subjective_grading_basis(self, rec: dict) -> tuple:
        """
        根据主观题评分记录研判其判分依据层级与具体来源。
        返回: (tier_key, tier_name, tier_rank, badge_color)
        排序权重严格遵循用户要求：
          tier_rank = 1: 🥇 第一层 OCR (排在最前面)
          tier_rank = 2: 🥈 第二层 高精 OCR (排在中间)
          tier_rank = 3: 🤖 大模型视觉批改 (排在下一个)
          tier_rank = 4: ✍️ 教师人工打分 (排在最后)
          tier_rank = 5: ⚠️ 待人工复核/未批出 (补充兜底)
        """
        if not isinstance(rec, dict):
            return ('pending', '⚠️ 待人工复核/未批', 5, '#DC2626')

        engine = str(rec.get('auto_grade_engine') or '').strip()
        engine_lower = engine.lower()
        reason = str(rec.get('auto_grade_reason') or rec.get('ocr_auto_reason') or rec.get('manual_reason') or '').strip()
        sec_engine = str(rec.get('secondary_ocr_engine') or '').strip()
        is_manual = bool(rec.get('manual_graded'))
        is_auto = bool(rec.get('auto_graded'))
        score_val = rec.get('score')
        has_score = score_val is not None and str(score_val).strip() != ''
        is_pending = bool(rec.get('ocr_auto_need_manual')) and not is_manual

        # 检查是否为教师显式改判或教师直接打分
        is_teacher_override = (
            rec.get('teacher_regraded') is True
            or '教师改判' in reason
            or '教师人工' in reason
            or '人工改判' in reason
        )

        # 1. 教师人工打分 (Tier 4) - 如果显式改判，归入人工
        if is_teacher_override:
            return ('manual', '✍️ 教师人工(改判)', 4, '#059669')

        if is_manual:
            # 大模型批改结果保存在 manual_graded 中，需准确识别大模型
            if ('大模型' in engine or 'qwen' in engine_lower or 'llm' in engine_lower or rec.get('llm_graded')):
                return ('llm', f'🤖 大模型批改 ({engine or "Vision-LLM"})', 3, '#D97706')
            tag = f'✍️ 教师人工 ({engine})' if engine and engine not in ('人工', 'manual') else '✍️ 教师人工打分'
            return ('manual', tag, 4, '#059669')

        if engine in ('人工', '教师人工', '网页人工打分', '看图打分', '手工打分'):
            return ('manual', f'✍️ 教师人工 ({engine})', 4, '#059669')

        # 2. 大模型智能批改 (Tier 3)
        if ('大模型' in engine or 'qwen' in engine_lower or 'llm' in engine_lower or rec.get('llm_graded')):
            return ('llm', f'🤖 大模型批改 ({engine or "Vision-LLM"})', 3, '#D97706')

        # 3. 第二层 高精 OCR (Tier 2)
        # 判定依据来自 PaddleOCRv6 / 高精复核
        is_second_tier = (
            'paddleocrv6' in engine_lower
            or 'v6' in engine_lower
            or '高精' in engine_lower
            or ('paddleocrv6' in sec_engine.lower() and engine_lower in ('', 'ocr', 'paddleocrv6', 'ocr自动判分'))
            or (is_auto and str(rec.get('auto_grade_answer') or '').strip() == str(rec.get('ocr_text') or '').strip() and str(rec.get('ocr_engine') or '').lower() == 'paddleocrv6')
        )
        if is_second_tier and is_auto:
            eng_lbl = engine or sec_engine or 'PaddleOCRv6'
            return ('second_tier_ocr', f'🥈 第二层 高精OCR ({eng_lbl})', 2, '#7C3AED')

        # 4. 第一层 OCR (Tier 1)
        # 包含 PaddleOCR (第一轮), RapidOCR, OCR自动判分, 更正答案快速重判, OCR结果分类, OCR分类记忆, 单字判分, 通用规则判分等
        is_first_tier = (
            'paddleocr' in engine_lower
            or 'paddle' in engine_lower
            or is_auto
            or any(kw in engine for kw in ('OCR', 'RapidOCR', '单字', '重判', '记忆', '分类', '拆字'))
            or (has_score and not is_pending and not is_manual)
        )
        if is_first_tier and has_score and not is_pending:
            eng_lbl = engine or '轻量通用OCR'
            return ('first_tier_ocr', f'🥇 第一层 OCR ({eng_lbl})', 1, '#0284C7')

        # 5. 待人工复核 / 未判出 (Tier 5)
        return ('pending', '⚠️ 待人工复核/未批', 5, '#DC2626')

    def format_ocr_intermediate_comparison(self, rec: dict) -> dict:
        if not isinstance(rec, dict):
            return {
                'has_first': False,
                'has_second': False,
                'first_text': '',
                'first_conf_str': '',
                'first_engine': '',
                'second_text': '',
                'second_conf_str': '',
                'review_reason': '',
                'comp_type': 'none',
                'display_line': '未识别到有效文字',
            }

        # 第一层：PaddleOCR（基础轻量识别）
        t1 = str(rec.get('paddle_ocr_text') or '').strip()
        c1 = rec.get('paddle_ocr_score')
        c1_str = f"{float(c1):.2f}" if c1 is not None and str(c1).strip() != '' else ""
        e1 = 'PaddleOCR'

        # 第二层：PaddleOCRv6（高精复核识别）
        t2 = str(rec.get('ocr_text') or '').strip()
        c2 = rec.get('ocr_score')
        c2_str = f"{float(c2):.2f}" if c2 is not None and str(c2).strip() != '' else ""
        e2 = str(rec.get('ocr_engine') or '').strip() or 'PaddleOCRv6'

        review_reason = str(rec.get('paddle_ocr_review_reason') or rec.get('ocr_auto_reason') or '').strip()

        has_t1 = bool(t1)
        has_t2 = bool(t2)

        if has_t1 and has_t2:
            if t1 == t2:
                comp_type = 'match'
                display_line = f"两层一致: 【{t1}】" + (f" (置信度 {c1_str or c2_str})" if (c1_str or c2_str) else "")
            else:
                comp_type = 'diff'
                p1_str = f"【{t1}】" + (f"({c1_str})" if c1_str else "")
                p2_str = f"【{t2}】" + (f"({c2_str})" if c2_str else "")
                if t2 in ('未识别到文字', '空白'):
                    display_line = f"一层{p1_str} ➔ 二层高精【未识别到文字】"
                elif t1 in ('未识别到文字', '空白'):
                    display_line = f"一层【未识别到文字】 ➔ 二层高精纠偏{p2_str}"
                else:
                    display_line = f"一层{p1_str} ➔ 二层高精纠偏{p2_str}"
        elif has_t1:
            comp_type = 'first_only'
            display_line = f"一层OCR: 【{t1}】" + (f" (置信度 {c1_str})" if c1_str else "")
        elif has_t2:
            comp_type = 'second_only'
            display_line = f"二层高精: 【{t2}】" + (f" (置信度 {c2_str})" if c2_str else "")
        else:
            comp_type = 'none'
            display_line = "未识别到有效文字"

        return {
            'has_first': has_t1,
            'has_second': has_t2,
            'first_text': t1,
            'first_conf_str': c1_str,
            'first_engine': e1,
            'second_text': t2,
            'second_conf_str': c2_str,
            'review_reason': review_reason,
            'comp_type': comp_type,
            'display_line': display_line,
        }

    def open_grading_basis_audit_dialog(
        self,
        parent_win=None,
        tasks=None,
        all_scores=None,
        payload=None,
        refresh_callback=None,
    ):
        if payload is None:
            payload = self.load_subjective_score_payload()
        if all_scores is None:
            all_scores = payload.setdefault('scores', {})

        if not self.summary_data:
            if self.is_direct_paper_choice_template() and self.image_paths:
                if messagebox.askyesno(
                    '先生成学生结果',
                    '主观题判分依据回看需要先知道每张卷子对应哪个学生。\n\n是否现在先自动处理一遍？',
                    parent=parent_win or self.root,
                ):
                    self.process_all()
                    if not self.summary_data:
                        return
                else:
                    return
            else:
                messagebox.showwarning('提示', '请先选择图片/文件夹并生成一次学生批改结果。', parent=parent_win or self.root)
                return

        parts = [p for p in self.iter_subjective_parts() if float(p.get('score') or 0) > 0]
        parts.extend(self.direct_calculation_manual_parts())
        if not parts:
            messagebox.showinfo('提示', '当前模板没有需要计分的主观题空位。', parent=parent_win or self.root)
            return

        if tasks is None:
            _export_root, _saved, _errors, crop_map = self.generate_subjective_crops(reuse_existing=True)
            built_tasks = []
            for entry in self.summary_data:
                entry_key = self.subjective_entry_key(entry)
                for part in parts:
                    part_id = part.get('part_id')
                    crop_id = 'calculation_back_region' if part.get('kind') == 'calculation' else part_id
                    crop_path = crop_map.get(entry_key, {}).get(crop_id)
                    built_tasks.append({
                        'entry': entry,
                        'entry_key': entry_key,
                        'part': part,
                        'part_id': part_id,
                        'crop_path': crop_path or '',
                    })
            tasks = built_tasks

        if not tasks:
            messagebox.showinfo('提示', '当前没有找到可回看的主观题任务。', parent=parent_win or self.root)
            return

        part_display_list = []
        part_id_by_display = {}
        display_by_part_id = {}
        part_obj_by_id = {p.get('part_id'): p for p in parts}
        label_counts = {}
        for p in parts:
            lbl = str(p.get('label') or p.get('part_id'))
            label_counts[lbl] = label_counts.get(lbl, 0) + 1

        seen_counts = {}
        for p in parts:
            pid = p.get('part_id')
            lbl = str(p.get('label') or pid)
            ms = float(p.get('score') or 1.0)
            seen_counts[lbl] = seen_counts.get(lbl, 0) + 1
            if label_counts[lbl] > 1:
                disp = f"第 {lbl} 题 - 第 {seen_counts[lbl]} 空  ({pid}，满分{ms:g}分)"
            else:
                disp = f"第 {lbl} 题  ({pid}，满分{ms:g}分)"
            part_display_list.append(disp)
            part_id_by_display[disp] = pid
            display_by_part_id[pid] = disp

        all_parts_disp = "📌 全部题位 (全卷汇总平铺)"
        part_display_list.append(all_parts_disp)
        part_id_by_display[all_parts_disp] = 'all'

        entry_map = {self.subjective_entry_key(e): e for e in self.summary_data}
        part_index_map = {p.get('part_id'): i for i, p in enumerate(parts)}
        entry_index_map = {self.subjective_entry_key(e): i for i, e in enumerate(self.summary_data)}

        audit_items = []
        for t in tasks:
            entry_key = t.get('entry_key', '')
            part_id = t.get('part_id', '')
            part = t.get('part', {})
            entry = t.get('entry') or entry_map.get(entry_key, {})
            crop_path = t.get('crop_path', '')
            student_name = entry.get('student_name', '') or '未命名'
            score_id = str(entry.get('score_id', '') or '')
            label = part.get('label', part_id)
            max_score = float(part.get('score') or 1.0)

            ocr_cfg = self.normalize_ocr_config(part.get('ocr'))
            std_answers = self.subjective_expected_answers_from_config(ocr_cfg)
            std_ans_text = ' / '.join(std_answers) if std_answers else (ocr_cfg.get('expected_keywords') or '')

            rec = all_scores.setdefault(entry_key, {}).setdefault(part_id, {})
            if not std_ans_text:
                std_ans_text = str(rec.get('auto_grade_expected') or '')

            ocr_text = (
                rec.get('ocr_manual_text')
                or rec.get('ocr_text')
                or rec.get('paddle_ocr_text')
                or rec.get('auto_grade_answer')
                or ''
            )
            ocr_text = str(ocr_text or '').strip()

            tier_key, tier_name, tier_rank, badge_color = self.classify_subjective_grading_basis(rec)
            inter_info = self.format_ocr_intermediate_comparison(rec)

            curr_score = rec.get('score')
            if curr_score is not None:
                try:
                    curr_score = float(curr_score)
                except Exception:
                    curr_score = None

            reason = (
                rec.get('auto_grade_reason')
                or rec.get('ocr_auto_reason')
                or rec.get('manual_reason')
                or rec.get('zero_reason')
                or ''
            )

            audit_items.append({
                'task': t,
                'entry_key': entry_key,
                'part_id': part_id,
                'part': part,
                'entry': entry,
                'label': label,
                'student_name': student_name,
                'score_id': score_id,
                'max_score': max_score,
                'score': curr_score,
                'std_ans': std_ans_text,
                'ocr_text': ocr_text,
                'crop_path': crop_path,
                'tier_key': tier_key,
                'tier_name': tier_name,
                'tier_rank': tier_rank,
                'badge_color': badge_color,
                'inter_info': inter_info,
                'reason': reason,
                'record': rec,
                'updated_at': rec.get('auto_grade_updated_at') or rec.get('updated_at') or '',
            })

        def _score_sort_key(it):
            """每一个类别都把判为1分（正得分）的放在前面，判为0分的放在后面，方便教师排查"""
            s = it.get('score')
            if s is not None and s > 0:
                group_prio = 0
                score_val = -float(s)
            elif s is not None and s == 0:
                group_prio = 1
                score_val = 0.0
            else:
                group_prio = 2
                score_val = 0.0
            return (group_prio, score_val, str(it.get('score_id') or ''), str(it.get('student_name') or ''))

        win = tk.Toplevel(parent_win or self.root)
        win.title('🔍 主观题判分依据回看与全图平铺画廊 (第一层OCR ➔ 高精OCR ➔ 大模型 ➔ 教师人工)')
        win.geometry('1600x900')
        win.minsize(980, 580)
        win.transient(parent_win or self.root)
        try:
            win.state('zoomed')
        except Exception:
            try:
                win.attributes('-zoomed', True)
            except Exception:
                pass
        try:
            win.update_idletasks()
        except Exception:
            pass

        win.gallery_photo_refs = []
        win.current_gallery_cards = []

        initial_part_id = parts[0].get('part_id')
        initial_part_disp = part_display_list[0]
        current_selected_part_id = tk.StringVar(value=initial_part_id)
        current_part_disp_var = tk.StringVar(value=initial_part_disp)
        win.current_selected_part_id = current_selected_part_id

        content = ttk.Frame(win, padding=10)
        content.pack(fill=tk.BOTH, expand=True)

        top_bar = ttk.Frame(content)
        top_bar.pack(fill=tk.X, pady=(0, 6))

        nav_left = ttk.Frame(top_bar)
        nav_left.pack(side=tk.LEFT, fill=tk.X, expand=True)

        ttk.Label(nav_left, text='【选择题位】: ', font=('Microsoft YaHei', 10, 'bold')).pack(side=tk.LEFT, padx=(0, 2))
        part_combo = ttk.Combobox(nav_left, textvariable=current_part_disp_var, values=part_display_list, state='readonly', width=32)
        part_combo.pack(side=tk.LEFT, padx=3)

        def on_part_combo_change(event=None):
            disp = current_part_disp_var.get()
            pid = part_id_by_display.get(disp, 'all')
            current_selected_part_id.set(pid)
            update_top_info_for_part()
            render_gallery_for_current_part()
            refresh_summary_counts()
            repopulate_tree()

        part_combo.bind('<<ComboboxSelected>>', on_part_combo_change)

        def go_prev_part():
            curr_disp = current_part_disp_var.get()
            try:
                idx = part_display_list.index(curr_disp)
                new_idx = max(0, idx - 1)
                current_part_disp_var.set(part_display_list[new_idx])
                on_part_combo_change()
            except ValueError:
                pass

        def go_next_part():
            curr_disp = current_part_disp_var.get()
            try:
                idx = part_display_list.index(curr_disp)
                new_idx = min(len(part_display_list) - 2, idx + 1)
                current_part_disp_var.set(part_display_list[new_idx])
                on_part_combo_change()
            except ValueError:
                pass

        btn_prev = ttk.Button(nav_left, text='◀ 上一题', command=go_prev_part)
        btn_prev.pack(side=tk.LEFT, padx=2)
        btn_next = ttk.Button(nav_left, text='下一题 ▶', command=go_next_part)
        btn_next.pack(side=tk.LEFT, padx=2)

        current_std_ans_var = tk.StringVar(value='')
        current_max_score_var = tk.StringVar(value='')
        ans_box = ttk.Frame(nav_left)
        ans_box.pack(side=tk.LEFT, padx=(12, 4))

        ttk.Label(ans_box, text='标准参考答案: ', font=('Microsoft YaHei', 9, 'bold'), foreground='#0F766E').pack(side=tk.LEFT)
        std_ans_lbl = tk.Label(ans_box, textvariable=current_std_ans_var, font=('Microsoft YaHei', 9, 'bold'), bg='#CCFBF1', fg='#0F766E', padx=6, pady=2, relief='flat')
        std_ans_lbl.pack(side=tk.LEFT, padx=(0, 8))

        ttk.Label(ans_box, text='满分: ', font=('Microsoft YaHei', 9, 'bold')).pack(side=tk.LEFT)
        max_score_lbl = tk.Label(ans_box, textvariable=current_max_score_var, font=('Microsoft YaHei', 9, 'bold'), bg='#E2E8F0', fg='#1E293B', padx=6, pady=2, relief='flat')
        max_score_lbl.pack(side=tk.LEFT)

        def update_top_info_for_part():
            pid = current_selected_part_id.get()
            if pid == 'all':
                current_std_ans_var.set('（全卷汇总模式）')
                current_max_score_var.set('多题')
            else:
                p = part_obj_by_id.get(pid, {})
                ms = float(p.get('score') or 1.0)
                current_max_score_var.set(f"{ms:g}分")
                ans = ''
                for it in audit_items:
                    if it['part_id'] == pid and it['std_ans']:
                        ans = it['std_ans']
                        break
                current_std_ans_var.set(f"【{ans or '未设置'}】")

        update_top_info_for_part()

        def export_audit_csv():
            f_path = filedialog.asksaveasfilename(
                title='导出全卷判分依据与改判清单',
                defaultextension='.csv',
                initialfile=f"主观题判分依据回看_{datetime.now().strftime('%Y%m%d_%H%M%S')}.csv",
                filetypes=[('CSV表格文件', '*.csv'), ('所有文件', '*.*')],
                parent=win,
            )
            if not f_path:
                return
            try:
                with open(f_path, 'w', encoding='utf-8-sig', newline='') as fp:
                    writer = csv.writer(fp)
                    writer.writerow([
                        '序号', '判分依据分类', '排序权重', '题位', '学生姓名', '学号',
                        '识别文字', '当前得分', '满分', '标准答案', '一层OCR', '二层高精OCR', '判定详细理由', '时间戳', '切片路径'
                    ])
                    sorted_export = sorted(
                        audit_items,
                        key=lambda it: (part_index_map.get(it['part_id'], 999), it.get('tier_rank', 99), _score_sort_key(it))
                    )
                    for i, it in enumerate(sorted_export, 1):
                        s_str = f"{it['score']:g}" if it['score'] is not None else "未批"
                        inter = it.get('inter_info', {})
                        writer.writerow([
                            i,
                            it['tier_name'],
                            it['tier_rank'],
                            it['label'],
                            it['student_name'],
                            it['score_id'],
                            it['ocr_text'],
                            s_str,
                            f"{it['max_score']:g}",
                            it['std_ans'],
                            inter.get('first_text', ''),
                            inter.get('second_text', ''),
                            it['reason'],
                            it['updated_at'],
                            it['crop_path'],
                        ])
                messagebox.showinfo('导出成功', f'全卷判分依据表已导出至：\n{f_path}', parent=win)
            except Exception as e:
                messagebox.showerror('导出失败', f'导出CSV出错：{e}', parent=win)

        ttk.Button(top_bar, text='📊 导出为CSV', command=export_audit_csv).pack(side=tk.RIGHT, padx=2)

        sub_bar = ttk.Frame(content)
        sub_bar.pack(fill=tk.X, pady=(0, 6))

        def get_current_part_items():
            pid = current_selected_part_id.get()
            if pid == 'all':
                return audit_items
            return [it for it in audit_items if it['part_id'] == pid]

        def count_current_tiers():
            items = get_current_part_items()
            return Counter(it['tier_key'] for it in items), len(items)

        chip_all_var = tk.StringVar(value='📌 全部 (0)')
        chip_t1_var = tk.StringVar(value='🥇 第一层 OCR (0)')
        chip_t2_var = tk.StringVar(value='🥈 第二层 高精OCR (0)')
        chip_t3_var = tk.StringVar(value='🤖 大模型 (0)')
        chip_t4_var = tk.StringVar(value='✍️ 教师人工 (0)')
        chip_t5_var = tk.StringVar(value='⚠️ 待复核 (0)')

        section_anchor_y = {}

        def scroll_to_tier_section(tier_rank):
            frac = section_anchor_y.get(tier_rank)
            if frac is not None and hasattr(win, 'gallery_canvas'):
                win.gallery_canvas.yview_moveto(frac)

        tk.Label(sub_bar, textvariable=chip_all_var, font=('Microsoft YaHei', 9, 'bold'), bg='#F1F5F9', fg='#334155', padx=6, pady=2).pack(side=tk.LEFT, padx=2)
        b_c1 = tk.Button(sub_bar, textvariable=chip_t1_var, font=('Microsoft YaHei', 9), bg='#E0F2FE', fg='#0369A1', relief='flat', bd=0, padx=6, pady=2, cursor='hand2', command=lambda: scroll_to_tier_section(1))
        b_c1.pack(side=tk.LEFT, padx=2)
        b_c2 = tk.Button(sub_bar, textvariable=chip_t2_var, font=('Microsoft YaHei', 9), bg='#F3E8FF', fg='#6D28D9', relief='flat', bd=0, padx=6, pady=2, cursor='hand2', command=lambda: scroll_to_tier_section(2))
        b_c2.pack(side=tk.LEFT, padx=2)
        b_c3 = tk.Button(sub_bar, textvariable=chip_t3_var, font=('Microsoft YaHei', 9), bg='#FEF3C7', fg='#B45309', relief='flat', bd=0, padx=6, pady=2, cursor='hand2', command=lambda: scroll_to_tier_section(3))
        b_c3.pack(side=tk.LEFT, padx=2)
        b_c4 = tk.Button(sub_bar, textvariable=chip_t4_var, font=('Microsoft YaHei', 9), bg='#DCFCE7', fg='#15803D', relief='flat', bd=0, padx=6, pady=2, cursor='hand2', command=lambda: scroll_to_tier_section(4))
        b_c4.pack(side=tk.LEFT, padx=2)
        b_c5 = tk.Button(sub_bar, textvariable=chip_t5_var, font=('Microsoft YaHei', 9), bg='#FEE2E2', fg='#B91C1C', relief='flat', bd=0, padx=6, pady=2, cursor='hand2', command=lambda: scroll_to_tier_section(5))
        b_c5.pack(side=tk.LEFT, padx=2)

        def refresh_summary_counts():
            c, tot = count_current_tiers()
            chip_all_var.set(f"📌 全部 ({tot})")
            chip_t1_var.set(f"🥇 第一层 OCR ({c.get('first_tier_ocr', 0)})")
            chip_t2_var.set(f"🥈 第二层 高精OCR ({c.get('second_tier_ocr', 0)})")
            chip_t3_var.set(f"🤖 大模型 ({c.get('llm', 0)})")
            chip_t4_var.set(f"✍️ 教师人工 ({c.get('manual', 0)})")
            chip_t5_var.set(f"⚠️ 待复核 ({c.get('pending', 0)})")

        notebook = ttk.Notebook(content)
        notebook.pack(fill=tk.BOTH, expand=True, pady=(2, 0))

        tab_gallery = ttk.Frame(notebook)
        notebook.add(tab_gallery, text='  🖼️ 平铺大图画廊 (默认，选定题位全班图片一次平铺展开)  ')

        tab_table = ttk.Frame(notebook)
        notebook.add(tab_table, text='  📋 全卷数据表格 (表格明细与批量改判)  ')

        canvas_outer = ttk.Frame(tab_gallery)
        canvas_outer.pack(fill=tk.BOTH, expand=True)

        gallery_canvas = tk.Canvas(canvas_outer, bg='#F8FAFC', highlightthickness=0)
        sb_gallery = ttk.Scrollbar(canvas_outer, orient=tk.VERTICAL, command=gallery_canvas.yview)
        gallery_canvas.configure(yscrollcommand=sb_gallery.set)

        gallery_canvas.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
        sb_gallery.pack(side=tk.RIGHT, fill=tk.Y)

        gallery_frame = tk.Frame(gallery_canvas, bg='#F8FAFC')
        gallery_window_id = gallery_canvas.create_window((0, 0), window=gallery_frame, anchor='nw')

        win.gallery_canvas = gallery_canvas
        last_rendered_cols = [0]

        def on_canvas_configure(event):
            gallery_canvas.itemconfig(gallery_window_id, width=event.width)
            new_avail_w = max(300, event.width - 24)
            new_cols = max(1, new_avail_w // 240)
            if last_rendered_cols[0] > 0 and new_cols != last_rendered_cols[0]:
                render_gallery_for_current_part()
            else:
                gallery_canvas.configure(scrollregion=gallery_canvas.bbox('all'))

        def on_frame_configure(event):
            gallery_canvas.configure(scrollregion=gallery_canvas.bbox('all'))

        gallery_canvas.bind('<Configure>', on_canvas_configure)
        gallery_frame.bind('<Configure>', on_frame_configure)

        def _on_mousewheel(event):
            if gallery_canvas.winfo_exists():
                gallery_canvas.yview_scroll(int(-1 * (event.delta / 120)), 'units')

        def bind_mousewheel_recursively(widget):
            widget.bind('<MouseWheel>', _on_mousewheel, add='+')
            for child in widget.winfo_children():
                bind_mousewheel_recursively(child)

        gallery_canvas.bind('<MouseWheel>', _on_mousewheel)
        gallery_frame.bind('<MouseWheel>', _on_mousewheel)

        def show_large_image_popup(p, title):
            if not p or not os.path.exists(p):
                messagebox.showinfo('提示', '作答切片文件不存在或已被移动。', parent=win)
                return
            pop = tk.Toplevel(win)
            pop.title(f"🔍 作答切片原图特写 — {title}")
            pop.geometry("820x520")
            pop.transient(win)
            try:
                orig = Image.open(p)
                w, h = orig.size
                scale = min(780 / max(1, w), 440 / max(1, h))
                tw, th = max(1, int(w * scale)), max(1, int(h * scale))
                orig_res = orig.resize((tw, th), Image.LANCZOS)
                photo_pop = ImageTk.PhotoImage(orig_res)

                box = tk.Frame(pop, bg='#0F172A')
                box.pack(fill=tk.BOTH, expand=True, padx=10, pady=10)
                lbl_pop = tk.Label(box, image=photo_pop, bg='#0F172A')
                lbl_pop.image = photo_pop
                lbl_pop.pack(expand=True)

                ttk.Button(pop, text='关闭', command=pop.destroy).pack(pady=(0, 10))
            except Exception as e:
                tk.Label(pop, text=f"加载失败: {e}").pack(pady=20)

        def prompt_custom_score(item, card_dict):
            ms = float(item['max_score'])
            curr = item['score']
            init_val = f"{curr:g}" if curr is not None else ""

            prompt_win = tk.Toplevel(win)
            prompt_win.title(f"自定义判分 — {item['student_name']}")
            prompt_win.geometry("320x150")
            prompt_win.transient(win)
            prompt_win.grab_set()

            ttk.Label(prompt_win, text=f"输入学生【{item['student_name']}】的得分 (满分 {ms:g}分):").pack(pady=(15, 6), padx=10)
            val_var = tk.StringVar(value=init_val)
            ent = ttk.Entry(prompt_win, textvariable=val_var, width=12)
            ent.pack(pady=4)
            ent.focus()

            def do_ok():
                txt = val_var.get().strip()
                if not txt:
                    return
                try:
                    val = float(txt)
                    apply_gallery_card_regrade(item, val, card_dict)
                    prompt_win.destroy()
                except Exception:
                    messagebox.showerror('输入错误', '请输入有效的数字分值。', parent=prompt_win)

            ent.bind('<Return>', lambda e: do_ok())
            btn_box = ttk.Frame(prompt_win)
            btn_box.pack(pady=10)
            ttk.Button(btn_box, text='确定', command=do_ok).pack(side=tk.LEFT, padx=4)
            ttk.Button(btn_box, text='取消', command=prompt_win.destroy).pack(side=tk.LEFT, padx=4)

        def apply_gallery_card_regrade(it, new_score, card_dict):
            rec = it['record']
            max_s = float(it['max_score'])
            try:
                ns = max(0.0, min(max_s, float(new_score)))
            except Exception:
                return

            score_disp = f"{int(ns)}分" if ns.is_integer() else f"{ns:g}分"
            old_basis_name = it['tier_name']
            rec['score'] = ns
            rec['manual_graded'] = True
            rec['teacher_regraded'] = True
            rec['ocr_auto_need_manual'] = False
            rec['auto_grade_reason'] = f"{it['reason']}（教师从【{old_basis_name}】改判为{score_disp}）".strip(' ；')
            rec['auto_grade_updated_at'] = datetime.now().isoformat(timespec='seconds')

            it['score'] = ns
            it['reason'] = rec['auto_grade_reason']
            it['tier_key'] = 'manual'
            it['tier_name'] = '✍️ 教师人工(改判)'
            it['tier_rank'] = 4
            it['badge_color'] = '#059669'

            self.save_subjective_score_payload(payload)
            self.refresh_main_result_views(payload)
            if callable(refresh_callback):
                try:
                    refresh_callback()
                except Exception:
                    pass

            badge_lbl = card_dict.get('badge_lbl')
            if badge_lbl and badge_lbl.winfo_exists():
                if ns >= max_s:
                    badge_lbl.configure(text=f"⭐ {score_disp} (满分)", bg='#10B981', fg='#FFFFFF')
                elif ns <= 0:
                    badge_lbl.configure(text=f"❌ {score_disp}", bg='#EF4444', fg='#FFFFFF')
                else:
                    badge_lbl.configure(text=f"✔ {score_disp}", bg='#3B82F6', fg='#FFFFFF')

            info_f = card_dict.get('info_f')
            if info_f and info_f.winfo_exists():
                regrade_lbl = card_dict.get('regrade_lbl')
                if not regrade_lbl or not regrade_lbl.winfo_exists():
                    regrade_lbl = tk.Label(info_f, text=f"✍️ 教师已改判: {score_disp}", font=('Microsoft YaHei', 8, 'bold'), bg='#FFFFFF', fg='#059669', anchor='w')
                    regrade_lbl.pack(fill=tk.X)
                    card_dict['regrade_lbl'] = regrade_lbl
                else:
                    regrade_lbl.configure(text=f"✍️ 教师已改判: {score_disp}")

            iid = it.get('_iid')
            if iid and tree.exists(iid):
                ms_str = f"{int(max_s)}" if max_s.is_integer() else f"{max_s:g}"
                tree.item(
                    iid,
                    values=(
                        tree.item(iid, 'values')[0],
                        it['tier_name'],
                        it['label'],
                        it['student_name'],
                        it['score_id'],
                        it['ocr_text'],
                        f"{score_disp} / {ms_str}",
                        it['std_ans'],
                        it['reason'],
                    ),
                    tags=('tier_4',),
                )

            refresh_summary_counts()

        win.apply_gallery_card_regrade = apply_gallery_card_regrade

        tier_banner_configs = {
            1: ('🥇 第一层 OCR 判定区', 'RapidOCR / 轻量通用规则自动给分', '#E0F2FE', '#0369A1', '#0284C7'),
            2: ('🥈 第二层 高精 OCR 判定区', 'PaddleOCRv6 高精复核 [含一层与二层识别中间对比]', '#F3E8FF', '#6D28D9', '#7C3AED'),
            3: ('🤖 大模型视觉批改判定区', 'Vision-LLM 智能图像理解打分', '#FEF3C7', '#B45309', '#D97706'),
            4: ('✍️ 教师人工评阅/改判区', '教师现场评阅或就地改判打分', '#DCFCE7', '#15803D', '#059669'),
            5: ('⚠️ 待人工复核/未批区', '字迹存疑、涂改严重或超出规则', '#FEE2E2', '#B91C1C', '#DC2626'),
        }

        def render_gallery_for_current_part():
            for child in gallery_frame.winfo_children():
                child.destroy()
            win.gallery_photo_refs.clear()
            win.current_gallery_cards.clear()
            section_anchor_y.clear()

            items = get_current_part_items()
            if not items:
                tk.Label(gallery_frame, text='当前题位没有学生作答数据。', font=('Microsoft YaHei', 12), bg='#F8FAFC', fg='#64748B').pack(pady=40)
                return

            grouped_tiers = {1: [], 2: [], 3: [], 4: [], 5: []}
            for it in items:
                grouped_tiers.setdefault(it['tier_rank'], []).append(it)

            avail_w = gallery_canvas.winfo_width()
            if avail_w < 300:
                try:
                    win.update_idletasks()
                except Exception:
                    pass
                avail_w = gallery_canvas.winfo_width()
            if avail_w < 300:
                avail_w = win.winfo_width() - 30
            if avail_w < 300:
                avail_w = 1880

            cols = max(1, avail_w // 240)
            last_rendered_cols[0] = cols

            total_sections_rendered = 0

            def render_single_card(grid_parent, card_idx, it, rank):
                row_idx = card_idx // cols
                col_idx = card_idx % cols

                card = tk.Frame(
                    grid_parent,
                    bg='#FFFFFF',
                    bd=1,
                    relief='solid',
                    highlightthickness=1,
                    highlightbackground='#CBD5E1',
                    padx=5,
                    pady=4,
                )
                card.grid(row=row_idx, column=col_idx, padx=3, pady=3, sticky='nsew')

                def on_card_enter(e, c=card):
                    try:
                        c.configure(highlightbackground='#3B82F6', highlightthickness=2)
                    except Exception:
                        pass

                def on_card_leave(e, c=card):
                    try:
                        c.configure(highlightbackground='#CBD5E1', highlightthickness=1)
                    except Exception:
                        pass

                card.bind('<Enter>', on_card_enter)
                card.bind('<Leave>', on_card_leave)

                header_f = tk.Frame(card, bg='#FFFFFF')
                header_f.pack(fill=tk.X, pady=(0, 4))

                tk.Label(
                    header_f,
                    text=it['student_name'],
                    font=('Microsoft YaHei', 10, 'bold'),
                    bg='#FFFFFF',
                    fg='#0F172A',
                ).pack(side=tk.LEFT)

                tk.Label(
                    header_f,
                    text=f" ({it['score_id']})",
                    font=('Microsoft YaHei', 9),
                    bg='#FFFFFF',
                    fg='#64748B',
                ).pack(side=tk.LEFT)

                s = it['score']
                ms = it['max_score']
                if s is not None and s >= ms:
                    b_bg, b_fg, b_txt = '#10B981', '#FFFFFF', f"⭐ {s:g}分 (满分)"
                elif s is not None and s <= 0:
                    b_bg, b_fg, b_txt = '#EF4444', '#FFFFFF', f"❌ 0分"
                elif s is not None:
                    b_bg, b_fg, b_txt = '#3B82F6', '#FFFFFF', f"✔ {s:g}分"
                else:
                    b_bg, b_fg, b_txt = '#94A3B8', '#FFFFFF', "待批"

                badge_lbl = tk.Label(
                    header_f,
                    text=b_txt,
                    font=('Microsoft YaHei', 8, 'bold'),
                    bg=b_bg,
                    fg=b_fg,
                    padx=6,
                    pady=2,
                )
                badge_lbl.pack(side=tk.RIGHT)

                crop_p = it['crop_path']
                photo = None
                if crop_p and os.path.exists(crop_p):
                    try:
                        im = Image.open(crop_p)
                        w, h = im.size
                        scale = min(250 / max(1, w), 72 / max(1, h))
                        tw, th = max(1, int(w * scale)), max(1, int(h * scale))
                        im_res = im.resize((tw, th), Image.LANCZOS)
                        photo = ImageTk.PhotoImage(im_res)
                        win.gallery_photo_refs.append(photo)
                    except Exception:
                        photo = None

                if photo:
                    img_box = tk.Label(card, image=photo, bg='#F8FAFC', cursor='hand2', relief='groove', bd=1)
                    img_box.pack(fill=tk.X, pady=(1, 4))
                    t_str = f"{it['student_name']} - {it['label']}"
                    img_box.bind('<Button-1>', lambda e, p=crop_p, title=t_str: show_large_image_popup(p, title))
                else:
                    img_box = tk.Label(card, text='（无切片原图）', bg='#F1F5F9', fg='#94A3B8', height=3)
                    img_box.pack(fill=tk.X, pady=(1, 4))

                info_f = tk.Frame(card, bg='#FFFFFF')
                info_f.pack(fill=tk.X, pady=(0, 4))

                inter = it.get('inter_info') or self.format_ocr_intermediate_comparison(it['record'])
                c1_str = f"({inter['first_conf_str']})" if inter.get('first_conf_str') else ""
                c2_str = f"({inter['second_conf_str']})" if inter.get('second_conf_str') else ""

                if rank == 2:
                    if inter['comp_type'] == 'diff':
                        tk.Label(
                            info_f,
                            text=f"一层: 【{inter['first_text']}】{c1_str}",
                            font=('Microsoft YaHei', 8),
                            bg='#FFFFFF',
                            fg='#475569',
                            anchor='w',
                        ).pack(fill=tk.X)
                        tk.Label(
                            info_f,
                            text=f"二层高精: 【{inter['second_text']}】{c2_str} [纠偏]",
                            font=('Microsoft YaHei', 8, 'bold'),
                            bg='#FFFFFF',
                            fg='#7C3AED',
                            anchor='w',
                        ).pack(fill=tk.X)
                    elif inter['comp_type'] == 'match':
                        tk.Label(
                            info_f,
                            text=f"两层一致: 【{inter['second_text']}】{c2_str}",
                            font=('Microsoft YaHei', 8),
                            bg='#FFFFFF',
                            fg='#059669',
                            anchor='w',
                        ).pack(fill=tk.X)
                    else:
                        tk.Label(
                            info_f,
                            text=f"高精OCR: 【{inter['second_text']}】{c2_str}",
                            font=('Microsoft YaHei', 8),
                            bg='#FFFFFF',
                            fg='#7C3AED',
                            anchor='w',
                        ).pack(fill=tk.X)

                    if inter.get('review_reason'):
                        tk.Label(
                            info_f,
                            text=f"复核原因: {inter['review_reason']}",
                            font=('Microsoft YaHei', 8),
                            bg='#FFFFFF',
                            fg='#D97706',
                            anchor='w',
                        ).pack(fill=tk.X)
                elif rank == 1:
                    t1_txt = inter['first_text'] or it['ocr_text'] or '未识别'
                    tk.Label(
                        info_f,
                        text=f"一层OCR: 【{t1_txt}】{c1_str}",
                        font=('Microsoft YaHei', 8),
                        bg='#FFFFFF',
                        fg='#0284C7',
                        anchor='w',
                    ).pack(fill=tk.X)
                    if it['reason']:
                        tk.Label(
                            info_f,
                            text=f"规则: {it['reason']}",
                            font=('Microsoft YaHei', 8),
                            bg='#FFFFFF',
                            fg='#64748B',
                            anchor='w',
                        ).pack(fill=tk.X)
                elif rank == 3:
                    tk.Label(
                        info_f,
                        text=f"大模型识别: 【{it['ocr_text']}】",
                        font=('Microsoft YaHei', 8),
                        bg='#FFFFFF',
                        fg='#D97706',
                        anchor='w',
                    ).pack(fill=tk.X)
                    if it['reason']:
                        tk.Label(
                            info_f,
                            text=f"理由: {it['reason']}",
                            font=('Microsoft YaHei', 8),
                            bg='#FFFFFF',
                            fg='#64748B',
                            anchor='w',
                        ).pack(fill=tk.X)
                elif rank == 4:
                    tk.Label(
                        info_f,
                        text=f"教师人工打分: {it['score']:g}分",
                        font=('Microsoft YaHei', 8, 'bold'),
                        bg='#FFFFFF',
                        fg='#059669',
                        anchor='w',
                    ).pack(fill=tk.X)
                    if it['reason']:
                        tk.Label(
                            info_f,
                            text=f"理由: {it['reason']}",
                            font=('Microsoft YaHei', 8),
                            bg='#FFFFFF',
                            fg='#64748B',
                            anchor='w',
                        ).pack(fill=tk.X)
                else:
                    tk.Label(
                        info_f,
                        text=f"待复核: {it['reason'] or '字迹模糊，请人工确认'}",
                        font=('Microsoft YaHei', 8),
                        bg='#FFFFFF',
                        fg='#DC2626',
                        anchor='w',
                    ).pack(fill=tk.X)

                btn_f = tk.Frame(card, bg='#FFFFFF')
                btn_f.pack(fill=tk.X, pady=(4, 0))

                card_dict = {
                    'item': it,
                    'card': card,
                    'badge_lbl': badge_lbl,
                    'info_f': info_f,
                }
                win.current_gallery_cards.append(card_dict)

                b0 = tk.Button(
                    btn_f,
                    text='❌ 0分',
                    font=('Microsoft YaHei', 8),
                    bg='#FEE2E2',
                    fg='#991B1B',
                    relief='flat',
                    bd=0,
                    padx=5,
                    pady=2,
                    cursor='hand2',
                    command=lambda item=it, c=card_dict: apply_gallery_card_regrade(item, 0.0, c),
                )
                b0.pack(side=tk.LEFT, padx=1)

                if ms >= 1.0:
                    b1 = tk.Button(
                        btn_f,
                        text='✔ 1分',
                        font=('Microsoft YaHei', 8),
                        bg='#E0F2FE',
                        fg='#0369A1',
                        relief='flat',
                        bd=0,
                        padx=5,
                        pady=2,
                        cursor='hand2',
                        command=lambda item=it, c=card_dict: apply_gallery_card_regrade(item, 1.0, c),
                    )
                    b1.pack(side=tk.LEFT, padx=1)

                if ms != 1.0 or ms > 1.0:
                    bfull = tk.Button(
                        btn_f,
                        text=f'⭐ 满分({ms:g}分)',
                        font=('Microsoft YaHei', 8),
                        bg='#DCFCE7',
                        fg='#166534',
                        relief='flat',
                        bd=0,
                        padx=5,
                        pady=2,
                        cursor='hand2',
                        command=lambda item=it, c=card_dict, m=ms: apply_gallery_card_regrade(item, m, c),
                    )
                    bfull.pack(side=tk.LEFT, padx=1)

                b_custom = tk.Button(
                    btn_f,
                    text='✏ 改分',
                    font=('Microsoft YaHei', 8),
                    bg='#F1F5F9',
                    fg='#475569',
                    relief='flat',
                    bd=0,
                    padx=4,
                    pady=2,
                    cursor='hand2',
                    command=lambda item=it, c=card_dict: prompt_custom_score(item, c),
                )
                b_custom.pack(side=tk.RIGHT, padx=1)

            for rank in [1, 2, 3, 4, 5]:
                tier_items = grouped_tiers.get(rank, [])
                if not tier_items:
                    continue

                # 核心排序：每一个类别都把判为1分（正得分）的放在前面，判为0分的放在后面
                tier_items.sort(key=_score_sort_key)

                count_1 = sum(1 for x in tier_items if x.get('score') is not None and x.get('score') > 0)
                count_0 = sum(1 for x in tier_items if x.get('score') is not None and x.get('score') == 0)
                count_none = len(tier_items) - count_1 - count_0

                stat_parts = []
                if count_1 > 0:
                    stat_parts.append(f"⭐ 1分: {count_1}份")
                if count_0 > 0:
                    stat_parts.append(f"❌ 0分: {count_0}份")
                if count_none > 0:
                    stat_parts.append(f"待批: {count_none}份")
                stat_str = f"  [ {' | '.join(stat_parts)} ]" if stat_parts else ""

                total_sections_rendered += 1
                title_prefix, desc, bg_color, fg_color, border_color = tier_banner_configs.get(
                    rank, (f'第 {rank} 分区', '', '#F1F5F9', '#334155', '#94A3B8')
                )

                section_frame = tk.Frame(gallery_frame, bg=bg_color, bd=0, padx=8, pady=3)
                section_frame.pack(fill=tk.X, padx=6, pady=(8, 3))

                section_anchor_y[rank] = max(0.0, min(1.0, (total_sections_rendered - 1) / max(1, len(items) // max(1, cols) + 1)))

                tk.Frame(section_frame, bg=border_color, width=4).pack(side=tk.LEFT, fill=tk.Y, padx=(0, 6))

                title_lbl = tk.Label(
                    section_frame,
                    text=f"{title_prefix}  (本题共 {len(tier_items)} 份{stat_str})",
                    font=('Microsoft YaHei', 10, 'bold'),
                    bg=bg_color,
                    fg=fg_color,
                )
                title_lbl.pack(side=tk.LEFT)

                desc_lbl = tk.Label(
                    section_frame,
                    text=f" — {desc}",
                    font=('Microsoft YaHei', 8),
                    bg=bg_color,
                    fg='#475569',
                )
                desc_lbl.pack(side=tk.LEFT, padx=(4, 0))

                sub_groups = []
                items_1 = [it for it in tier_items if it.get('score') is not None and it.get('score') > 0]
                items_0 = [it for it in tier_items if it.get('score') is not None and it.get('score') == 0]
                items_none = [it for it in tier_items if it.get('score') is None]

                if items_1:
                    sub_groups.append(('⭐ 判为 1 分 (满分/得分区)', items_1, '#ECFDF5', '#065F46', '#10B981'))
                if items_0:
                    sub_groups.append(('❌ 判为 0 分 (零分区)', items_0, '#FEF2F2', '#991B1B', '#EF4444'))
                if items_none:
                    sub_groups.append(('⚠️ 待人工复核 / 未判分区', items_none, '#FFFBEB', '#92400E', '#F59E0B'))

                for sub_title, sub_items, sub_bg, sub_fg, sub_border in sub_groups:
                    if len(sub_groups) > 1:
                        sub_bar = tk.Frame(gallery_frame, bg=sub_bg, padx=8, pady=2)
                        sub_bar.pack(fill=tk.X, padx=8, pady=(4, 2))
                        tk.Frame(sub_bar, bg=sub_border, width=3).pack(side=tk.LEFT, fill=tk.Y, padx=(0, 6))
                        tk.Label(
                            sub_bar,
                            text=f"{sub_title} — 共 {len(sub_items)} 份",
                            font=('Microsoft YaHei', 9, 'bold'),
                            bg=sub_bg,
                            fg=sub_fg,
                        ).pack(side=tk.LEFT)

                    grid_container = tk.Frame(gallery_frame, bg='#F8FAFC')
                    grid_container.pack(fill=tk.X, padx=4, pady=(0, 6))

                    for col_idx in range(cols):
                        grid_container.columnconfigure(col_idx, weight=1, uniform='card_col')

                    for card_idx, it in enumerate(sub_items):
                        render_single_card(grid_container, card_idx, it, rank)

            bind_mousewheel_recursively(gallery_frame)
            gallery_canvas.yview_moveto(0.0)

        tab2_top = ttk.Frame(tab_table)
        tab2_top.pack(fill=tk.X, pady=(6, 4))

        filter_tier_var = tk.StringVar(value='all')
        search_var = tk.StringVar()

        r_all = ttk.Radiobutton(tab2_top, text="📌 全部", variable=filter_tier_var, value='all')
        r_all.pack(side=tk.LEFT, padx=3)
        r_t1 = ttk.Radiobutton(tab2_top, text="🥇 第一层 OCR", variable=filter_tier_var, value='first_tier_ocr')
        r_t1.pack(side=tk.LEFT, padx=3)
        r_t2 = ttk.Radiobutton(tab2_top, text="🥈 第二层 高精OCR", variable=filter_tier_var, value='second_tier_ocr')
        r_t2.pack(side=tk.LEFT, padx=3)
        r_t3 = ttk.Radiobutton(tab2_top, text="🤖 大模型", variable=filter_tier_var, value='llm')
        r_t3.pack(side=tk.LEFT, padx=3)
        r_t4 = ttk.Radiobutton(tab2_top, text="✍️ 教师人工", variable=filter_tier_var, value='manual')
        r_t4.pack(side=tk.LEFT, padx=3)
        r_t5 = ttk.Radiobutton(tab2_top, text="⚠️ 待复核", variable=filter_tier_var, value='pending')
        r_t5.pack(side=tk.LEFT, padx=3)

        ttk.Label(tab2_top, text='  搜索:').pack(side=tk.LEFT, padx=(10, 2))
        search_entry = ttk.Entry(tab2_top, textvariable=search_var, width=16)
        search_entry.pack(side=tk.LEFT, padx=2)

        tree_cols = ('#', 'tier', 'part', 'student', 'id', 'ocr_text', 'score', 'std_ans', 'reason')
        tree = ttk.Treeview(tab_table, columns=tree_cols, show='headings', selectmode='extended')
        tree.heading('#', text='#')
        tree.heading('tier', text='判分依据')
        tree.heading('part', text='题位')
        tree.heading('student', text='学生')
        tree.heading('id', text='学号')
        tree.heading('ocr_text', text='提取文字')
        tree.heading('score', text='得分')
        tree.heading('std_ans', text='标准答案')
        tree.heading('reason', text='判定详细理由')

        tree.column('#', width=40, anchor='center')
        tree.column('tier', width=135, anchor='center')
        tree.column('part', width=80, anchor='center')
        tree.column('student', width=80, anchor='center')
        tree.column('id', width=60, anchor='center')
        tree.column('ocr_text', width=110, anchor='w')
        tree.column('score', width=65, anchor='center')
        tree.column('std_ans', width=90, anchor='w')
        tree.column('reason', width=220, anchor='w')

        tree.tag_configure('tier_1', background='#F0F9FF')
        tree.tag_configure('tier_2', background='#F5F3FF')
        tree.tag_configure('tier_3', background='#FFFBEB')
        tree.tag_configure('tier_4', background='#ECFDF5')
        tree.tag_configure('tier_5', background='#FEF2F2')

        sb_tree_v = ttk.Scrollbar(tab_table, orient=tk.VERTICAL, command=tree.yview)
        tree.configure(yscrollcommand=sb_tree_v.set)
        tree.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
        sb_tree_v.pack(side=tk.RIGHT, fill=tk.Y)

        item_iid_map = {}

        def repopulate_tree():
            tree.delete(*tree.get_children())
            item_iid_map.clear()
            f_tier = filter_tier_var.get()
            q_search = search_var.get().strip().lower()
            current_pid = current_selected_part_id.get()

            filtered_items = []
            for it in audit_items:
                if current_pid != 'all' and it['part_id'] != current_pid:
                    continue
                if f_tier != 'all' and it['tier_key'] != f_tier:
                    continue
                if q_search:
                    corpus = f"{it['student_name']} {it['score_id']} {it['label']} {it['ocr_text']} {it['reason']} {it['tier_name']}".lower()
                    if q_search not in corpus:
                        continue
                filtered_items.append(it)

            # 每个类别内均把判为1分的放在前面，判为0分的放在后面
            filtered_items.sort(key=lambda it: (it.get('tier_rank', 99), _score_sort_key(it)))

            for count, it in enumerate(filtered_items, 1):
                iid = f"item_{count}"
                item_iid_map[iid] = it
                it['_iid'] = iid

                s = it['score']
                ms = it['max_score']
                s_str = f"{int(s)}" if s is not None and s.is_integer() else (f"{s:g}" if s is not None else "-")
                ms_str = f"{int(ms)}" if ms.is_integer() else f"{ms:g}"
                score_col = f"{s_str} / {ms_str}"

                tree.insert(
                    '',
                    tk.END,
                    iid=iid,
                    values=(
                        count,
                        it['tier_name'],
                        it['label'],
                        it['student_name'],
                        it['score_id'],
                        it['ocr_text'],
                        score_col,
                        it['std_ans'],
                        it['reason'],
                    ),
                    tags=(f"tier_{it['tier_rank']}",),
                )

        r_all.configure(command=repopulate_tree)
        r_t1.configure(command=repopulate_tree)
        r_t2.configure(command=repopulate_tree)
        r_t3.configure(command=repopulate_tree)
        r_t4.configure(command=repopulate_tree)
        r_t5.configure(command=repopulate_tree)
        search_entry.bind('<KeyRelease>', lambda e: repopulate_tree())

        def on_tree_double_click(event):
            sel = tree.selection()
            if not sel:
                return
            it = item_iid_map.get(sel[0])
            if it and it['crop_path']:
                show_large_image_popup(it['crop_path'], f"{it['student_name']} - {it['label']}")

        tree.bind('<Double-Button-1>', on_tree_double_click)

        def bulk_regrade_selected_table(new_score_val):
            sel_iids = tree.selection()
            if not sel_iids:
                messagebox.showinfo('提示', '请先在表格中选中一道或多道题目。', parent=win)
                return
            targets = [item_iid_map[iid] for iid in sel_iids if iid in item_iid_map]
            if not targets:
                return
            score_lbl = "满分" if new_score_val == 'full' else f"{new_score_val}分"
            if len(targets) > 1:
                if not messagebox.askyesno('批量改判确认', f'确定要将选中的 {len(targets)} 项题目全部改判为【{score_lbl}】吗？', parent=win):
                    return
            for it in targets:
                score_to_apply = it['max_score'] if new_score_val == 'full' else new_score_val
                rec = it['record']
                ns = max(0.0, min(float(it['max_score']), float(score_to_apply)))
                score_disp = f"{int(ns)}分" if ns.is_integer() else f"{ns:g}分"
                old_basis_name = it['tier_name']
                rec['score'] = ns
                rec['manual_graded'] = True
                rec['teacher_regraded'] = True
                rec['ocr_auto_need_manual'] = False
                rec['auto_grade_reason'] = f"{it['reason']}（教师从【{old_basis_name}】改判为{score_disp}）".strip(' ；')
                rec['auto_grade_updated_at'] = datetime.now().isoformat(timespec='seconds')
                it['score'] = ns
                it['reason'] = rec['auto_grade_reason']
                it['tier_key'] = 'manual'
                it['tier_name'] = '✍️ 教师人工(改判)'
                it['tier_rank'] = 4
                it['badge_color'] = '#059669'

            self.save_subjective_score_payload(payload)
            self.refresh_main_result_views(payload)
            if callable(refresh_callback):
                try:
                    refresh_callback()
                except Exception:
                    pass
            repopulate_tree()
            refresh_summary_counts()
            render_gallery_for_current_part()
            messagebox.showinfo('完成', f'已成功批量改判 {len(targets)} 项题目！', parent=win)

        def show_tree_menu(event):
            sel = tree.selection()
            count = len(sel) if sel else 0
            m = tk.Menu(win, tearoff=0)
            if count > 0:
                m.add_command(label=f"⭐ 将选中的 {count} 项批量改判为 满分", command=lambda: bulk_regrade_selected_table('full'))
                m.add_command(label=f"❌ 将选中的 {count} 项批量改判为 0分", command=lambda: bulk_regrade_selected_table(0.0))
                m.add_command(label=f"✔ 将选中的 {count} 项批量改判为 1分", command=lambda: bulk_regrade_selected_table(1.0))
                m.add_separator()
            m.add_command(label="☑ 全选表格项", command=lambda: tree.selection_set(tree.get_children()))
            try:
                m.tk_popup(event.x_root, event.y_root)
            finally:
                m.grab_release()

        tree.bind('<Button-3>', show_tree_menu)
        tree.bind('<Button-2>', show_tree_menu)

        bottom_bar = ttk.Frame(content)
        bottom_bar.pack(fill=tk.X, pady=(6, 0))

        ttk.Label(
            bottom_bar,
            text='💡 提示：在【平铺大图画廊】中，已为您一次性平铺全班该题原图；点击每张图片下方的 [0分]/[1分]/[满分] 即可就地极速改判。',
            font=('Microsoft YaHei', 9),
            foreground='#64748B',
        ).pack(side=tk.LEFT)

        ttk.Button(bottom_bar, text='关闭', command=win.destroy).pack(side=tk.RIGHT, padx=4)

        refresh_summary_counts()
        render_gallery_for_current_part()
        repopulate_tree()


    def open_subjective_ocr_settings(self):
        parts = list(self.iter_subjective_parts())
        if not parts:
            messagebox.showinfo('提示', '当前模板没有主观题空位。')
            return

        setting_win = tk.Toplevel(self.root)
        setting_win.title('OCR空位设置')
        self.track_context_window(setting_win)
        setting_win.geometry('1780x660')
        setting_win.minsize(1180, 520)
        setting_win.transient(self.root)

        ttk.Label(
            setting_win,
            text='这些设置会保存到当前模板，也会随“答案方案”一起另存和加载。',
            font=('Arial', 10, 'bold'),
        ).pack(fill=tk.X, padx=12, pady=(12, 6))

        canvas = tk.Canvas(setting_win, bg='#f7f7f7')
        scrollbar = ttk.Scrollbar(setting_win, orient=tk.VERTICAL, command=canvas.yview)
        body = ttk.Frame(canvas)
        body.bind('<Configure>', lambda _e: canvas.configure(scrollregion=canvas.bbox('all')))
        canvas.create_window((0, 0), window=body, anchor='nw')
        canvas.configure(yscrollcommand=scrollbar.set)
        canvas.pack(side=tk.LEFT, fill=tk.BOTH, expand=True, padx=(12, 0), pady=6)
        scrollbar.pack(side=tk.RIGHT, fill=tk.Y, pady=6)

        headers = ['OCR', '单字', '空位', '标准答案', '唯一答案', '选填题', '拆字判错', '常见错答案', '错误关键词', '前诱导字', '后诱导字/单位', '左留白', '右留白', '低置信度', '关键词']
        for col, header in enumerate(headers):
            ttk.Label(body, text=header, font=('Arial', 9, 'bold')).grid(row=0, column=col, padx=4, pady=4, sticky='w')

        row_vars = {}
        for row, part in enumerate(parts, 1):
            is_drawing = part.get('kind') == 'drawing'
            config = (
                self.subjective_part_setting_config(part)
                if is_drawing
                else self.apply_ocr_memory_to_config(part.get('ocr'))
            )
            exp_ans_str = str(config.get('expected_answer', '')).strip()
            cands_str = str(config.get('candidate_words', '')).strip()
            init_choice = bool(config.get('choice_fill', False)) or bool(cands_str)
            init_unique = bool(config.get('unique_answer', False)) or init_choice or self.is_dedicated_physics_terminology(exp_ans_str)
            if is_drawing:
                init_split = False
            elif 'split_char_check' in config:
                init_split = bool(config.get('split_char_check'))
            else:
                init_split = init_unique and not self.should_disable_split_char_check(
                    exp_ans_str,
                    candidate_words=cands_str,
                    is_drawing=is_drawing,
                )[0]

            vars_map = {
                'enabled': tk.BooleanVar(value=config.get('enabled', False)),
                'single_char': tk.BooleanVar(value=config.get('single_char', False)),
                'unique_answer': tk.BooleanVar(value=init_unique),
                'choice_fill': tk.BooleanVar(value=init_choice),
                'split_char_check': tk.BooleanVar(value=init_split),
                'expected_answer': tk.StringVar(value=config.get('expected_answer', '')),
                'candidate_words': tk.StringVar(value=config.get('candidate_words', '')),
                'common_wrong_answers': tk.StringVar(value=config.get('common_wrong_answers', '')),
                'wrong_keywords': tk.StringVar(value=config.get('wrong_keywords', '')),
                'prefix': tk.StringVar(value=config.get('prefix', '')),
                'suffix': tk.StringVar(value=config.get('suffix', '')),
                'pad_left': tk.StringVar(value=str(config.get('pad_left', 180))),
                'pad_right': tk.StringVar(value=str(config.get('pad_right', 180))),
                'low_confidence_threshold': tk.StringVar(value=str(config.get('low_confidence_threshold', 0.6))),
                'expected_keywords': tk.StringVar(value=config.get('expected_keywords', '')),
            }
            row_vars[part['part_id']] = vars_map
            enabled_check = ttk.Checkbutton(body, variable=vars_map['enabled'])
            enabled_check.grid(row=row, column=0, padx=4, pady=3, sticky='w')
            single_char_check = ttk.Checkbutton(body, variable=vars_map['single_char'])
            single_char_check.grid(row=row, column=1, padx=4, pady=3, sticky='w')
            if is_drawing:
                enabled_check.state(['disabled'])
                single_char_check.state(['disabled'])
            ttk.Label(body, text=part.get('label', ''), width=18).grid(row=row, column=2, padx=4, pady=3, sticky='w')
            expected_entry = ttk.Entry(body, textvariable=vars_map['expected_answer'], width=18)
            expected_entry.grid(row=row, column=3, padx=4, pady=3, sticky='w')
            if is_drawing:
                expected_entry.state(['readonly'])
            else:
                expected_entry.bind('<FocusOut>', lambda _e, m=vars_map: self.apply_ocr_memory_to_vars(m))
                expected_entry.bind('<Return>', lambda _e, m=vars_map: self.apply_ocr_memory_to_vars(m))

            unique_cb = ttk.Checkbutton(body, variable=vars_map['unique_answer'])
            unique_cb.grid(row=row, column=4, padx=4, pady=3, sticky='w')
            choice_cb = ttk.Checkbutton(body, variable=vars_map['choice_fill'])
            choice_cb.grid(row=row, column=5, padx=4, pady=3, sticky='w')
            split_char_cb = ttk.Checkbutton(body, variable=vars_map['split_char_check'])
            split_char_cb.grid(row=row, column=6, padx=4, pady=3, sticky='w')
            if is_drawing:
                unique_cb.state(['disabled'])
                choice_cb.state(['disabled'])
                split_char_cb.state(['disabled'])
            else:
                def make_toggle(vmap):
                    def on_toggle():
                        if not vmap['unique_answer'].get():
                            vmap['split_char_check'].set(False)
                        else:
                            ans = vmap['expected_answer'].get().strip()
                            cands = vmap['candidate_words'].get().strip() if 'candidate_words' in vmap else ''
                            dis, _ = self.should_disable_split_char_check(ans, candidate_words=cands)
                            vmap['split_char_check'].set(not dis)
                    return on_toggle
                unique_cb.configure(command=make_toggle(vars_map))

                def make_choice_toggle(vmap):
                    def on_choice():
                        if vmap['choice_fill'].get():
                            vmap['unique_answer'].set(True)
                            vmap['split_char_check'].set(True)
                    return on_choice
                choice_cb.configure(command=make_choice_toggle(vars_map))

            ttk.Entry(body, textvariable=vars_map['common_wrong_answers'], width=16).grid(row=row, column=7, padx=4, pady=3, sticky='w')
            ttk.Entry(body, textvariable=vars_map['wrong_keywords'], width=16).grid(row=row, column=8, padx=4, pady=3, sticky='w')
            ttk.Entry(body, textvariable=vars_map['prefix'], width=14).grid(row=row, column=9, padx=4, pady=3, sticky='w')
            ttk.Entry(body, textvariable=vars_map['suffix'], width=14).grid(row=row, column=10, padx=4, pady=3, sticky='w')
            ttk.Entry(body, textvariable=vars_map['pad_left'], width=8).grid(row=row, column=11, padx=4, pady=3, sticky='w')
            ttk.Entry(body, textvariable=vars_map['pad_right'], width=8).grid(row=row, column=12, padx=4, pady=3, sticky='w')
            ttk.Entry(body, textvariable=vars_map['low_confidence_threshold'], width=8).grid(row=row, column=13, padx=4, pady=3, sticky='w')
            ttk.Entry(body, textvariable=vars_map['expected_keywords'], width=18).grid(row=row, column=14, padx=4, pady=3, sticky='w')

        def save_settings():
            settings = {}
            for part_id, vars_map in row_vars.items():
                settings[part_id] = self.normalize_ocr_config({
                    'enabled': vars_map['enabled'].get(),
                    'single_char': vars_map['single_char'].get(),
                    'unique_answer': vars_map['unique_answer'].get(),
                    'choice_fill': vars_map['choice_fill'].get(),
                    'split_char_check': vars_map['split_char_check'].get() if 'split_char_check' in vars_map else True,
                    'expected_answer': vars_map['expected_answer'].get(),
                    'candidate_words': vars_map['candidate_words'].get() if 'candidate_words' in vars_map else '',
                    'common_wrong_answers': vars_map['common_wrong_answers'].get(),
                    'wrong_keywords': vars_map['wrong_keywords'].get(),
                    'prefix': vars_map['prefix'].get(),
                    'suffix': vars_map['suffix'].get(),
                    'pad_left': vars_map['pad_left'].get(),
                    'pad_right': vars_map['pad_right'].get(),
                    'low_confidence_threshold': vars_map['low_confidence_threshold'].get(),
                    'expected_keywords': vars_map['expected_keywords'].get(),
                    'pad_top': 20,
                    'pad_bottom': 20,
            })
            try:
                self.save_ocr_settings_for_parts(settings)
                synced_count = self.sync_loaded_answer_scheme_ocr_settings()
                sync_text = f'\n已同步到当前答案方案：{self.loaded_answer_key_scheme_name}' if synced_count else ''
                messagebox.showinfo('保存完成', f'OCR空位设置已保存到当前模板。{sync_text}', parent=setting_win)
                setting_win.destroy()
            except Exception as e:
                messagebox.showerror('保存失败', str(e), parent=setting_win)

        footer = ttk.Frame(setting_win)
        footer.pack(fill=tk.X, padx=12, pady=(4, 12))
        ttk.Button(footer, text='保存设置', command=save_settings).pack(side=tk.LEFT, padx=4)
        ttk.Button(footer, text='取消', command=setting_win.destroy).pack(side=tk.LEFT, padx=4)
        setting_win.protocol('WM_DELETE_WINDOW', save_settings)

    def save_experiment_structure_from_assignments(self, assignments):
        config_path = getattr(self, 'subjective_config_path', None)
        if not config_path or not Path(config_path).exists():
            raise RuntimeError('找不到当前模板的主观题配置文件。')

        backup_path = Path(config_path).with_name(
            f"{Path(config_path).stem}.backup_{datetime.now().strftime('%Y%m%d_%H%M%S')}.json"
        )
        shutil.copy2(config_path, backup_path)
        config = json.loads(Path(config_path).read_text(encoding='utf-8-sig'))
        preserved_ocr_settings = self.collect_ocr_settings_from_subjective_config(config)
        preserved_ocr_settings.update(self.read_loaded_answer_scheme_ocr_settings())
        items = config.get('items', [])
        for item in items:
            question_no = item.get('question_no')
            if question_no not in assignments:
                continue
            subquestions = []
            for sub in sorted(assignments[question_no], key=lambda payload: payload['sub_no']):
                blanks = []
                for blank_index, detected in enumerate(sub['lines'], 1):
                    part_id = f"q{question_no}_s{sub['sub_no']}_b{blank_index}"
                    ocr_config = preserved_ocr_settings.get(part_id)
                    blank_payload = {
                        'blank_no': blank_index,
                        'score': 1,
                        'region_name': 'experiment',
                        'rect': detected['template_rect'],
                    }
                    if ocr_config:
                        blank_payload['ocr'] = self.normalize_ocr_config(ocr_config)
                    blanks.append({
                        **blank_payload,
                    })
                subquestions.append({
                    'sub_no': sub['sub_no'],
                    'region_name': 'experiment',
                    'blanks': blanks,
                })
            item['kind'] = 'experiment'
            item['region_name'] = 'experiment'
            item['subquestions'] = subquestions
            item['max_score'] = sum(len(sub['blanks']) for sub in subquestions)

        config['updated_at'] = datetime.now().isoformat(timespec='seconds')
        config['experiment_structure_source'] = 'blank_template_line_detection'
        Path(config_path).write_text(json.dumps(config, ensure_ascii=False, indent=2), encoding='utf-8')
        self.subjective_config = config
        return backup_path

    def get_subjective_config_for_scheme(self):
        config = copy.deepcopy(getattr(self, 'subjective_config', {}) or {})
        if not isinstance(config, dict) or not config:
            return {}
        config.pop('_session_snapshot', None)
        config['_answer_scheme_snapshot'] = {
            'template_key': self.current_template_key,
            'template_name': self.current_template_name,
            'saved_at': datetime.now().isoformat(timespec='seconds'),
        }
        return config

    def answer_scheme_asset_dir(self, scheme_path):
        if not scheme_path:
            return None
        path = Path(scheme_path)
        return path.parent / '_scheme_assets' / path.stem

    def get_template_structure_for_scheme(self, scheme_path=None):
        if not self.is_mixed_objective_subjective_template():
            return {}
        structure = {
            'version': 1,
            'template_key': self.current_template_key,
            'template_name': self.current_template_name,
            'answer_config': copy.deepcopy(getattr(self, 'answer_config', {}) or {}),
            'marker_config': copy.deepcopy(getattr(self, 'marker_config', {}) or {}),
            'student_config': copy.deepcopy(getattr(self, 'student_config', {}) or {}),
            'template_images': {},
            'saved_at': datetime.now().isoformat(timespec='seconds'),
        }
        asset_dir = self.answer_scheme_asset_dir(scheme_path)
        if not asset_dir:
            return structure

        asset_dir.mkdir(parents=True, exist_ok=True)
        paths = getattr(self, 'current_template_paths', {}) or {}
        candidates = {}
        for key, config_name in (
            ('answer_template', 'answer_config'),
            ('student_template', 'student_config'),
        ):
            config = structure.get(config_name) or {}
            image_info = config.get('template_image') if isinstance(config.get('template_image'), dict) else {}
            if image_info.get('path'):
                candidates[key] = image_info.get('path')
        if paths.get('template_image'):
            candidates.setdefault('template', str(paths.get('template_image')))

        copied = {}
        for key, source_value in candidates.items():
            try:
                source = Path(source_value)
            except Exception:
                continue
            if not source.exists():
                continue
            suffix = source.suffix or '.jpg'
            dest = asset_dir / f'{key}{suffix}'
            try:
                shutil.copy2(source, dest)
                copied[key] = str(dest)
                structure['template_images'][key] = str(dest)
            except Exception:
                continue

        if copied.get('answer_template'):
            answer_config = structure.get('answer_config') or {}
            answer_config.setdefault('template_image', {})
            answer_config['template_image']['path'] = copied['answer_template']
        if copied.get('student_template'):
            student_config = structure.get('student_config') or {}
            student_config.setdefault('template_image', {})
            student_config['template_image']['path'] = copied['student_template']
        if copied.get('template'):
            structure['template_images']['template'] = copied['template']
        return structure

    def apply_template_structure_from_scheme(self, structure):
        if not self.is_mixed_objective_subjective_template():
            return False
        if not isinstance(structure, dict) or not structure:
            return False
        if structure.get('template_key') and structure.get('template_key') != self.current_template_key:
            return False
        paths = getattr(self, 'current_template_paths', {}) or {}
        answer_path = Path(paths.get('answer_config') or '')
        marker_path = Path(paths.get('marker_config') or '')
        student_path = Path(paths.get('student_id_config') or '')
        template_path = Path(paths.get('template_image') or '')
        if not answer_path or not marker_path:
            return False

        template_images = structure.get('template_images') if isinstance(structure.get('template_images'), dict) else {}

        def copy_template_image(source_value, target):
            if not source_value or not target:
                return False
            try:
                source = Path(source_value)
                target = Path(target)
            except Exception:
                return False
            if not source.is_file():
                raise ValueError(f'方案模板图不存在：{source}。不能沿用上一试卷的模板图。')
            try:
                target.parent.mkdir(parents=True, exist_ok=True)
                if source.resolve() == target.resolve():
                    return True
                if target.exists():
                    shutil.copy2(target, target.with_name(f"{target.stem}.backup_{datetime.now().strftime('%Y%m%d_%H%M%S')}_load_scheme{target.suffix}"))
                shutil.copy2(source, target)
                return True
            except Exception as exc:
                raise ValueError(f'方案模板图恢复失败：{source}') from exc

        if template_path:
            copy_template_image(template_images.get('template') or template_images.get('answer_template'), template_path)

        answer_config = copy.deepcopy(structure.get('answer_config') or {})
        if isinstance(answer_config, dict) and answer_config:
            if template_path:
                answer_config.setdefault('template_image', {})
                answer_config['template_image']['path'] = str(template_path)
                if template_path.exists():
                    try:
                        with Image.open(template_path) as image:
                            answer_config['template_image']['width'], answer_config['template_image']['height'] = image.size
                    except Exception:
                        pass
            try:
                if answer_path.exists():
                    shutil.copy2(answer_path, answer_path.with_name(f"{answer_path.stem}.backup_{datetime.now().strftime('%Y%m%d_%H%M%S')}_load_scheme.json"))
            except Exception:
                pass
            atomic_write_json(answer_path, answer_config)
            self.answer_config = answer_config

        marker_config = copy.deepcopy(structure.get('marker_config') or {})
        if isinstance(marker_config, dict) and marker_config:
            try:
                if marker_path.exists():
                    shutil.copy2(marker_path, marker_path.with_name(f"{marker_path.stem}.backup_{datetime.now().strftime('%Y%m%d_%H%M%S')}_load_scheme.json"))
            except Exception:
                pass
            atomic_write_json(marker_path, marker_config)
            self.marker_config = marker_config

        student_config = copy.deepcopy(structure.get('student_config') or {})
        if isinstance(student_config, dict) and student_config and student_path:
            if template_path:
                student_config.setdefault('template_image', {})
                student_config['template_image']['path'] = str(template_path)
            try:
                if student_path.exists():
                    shutil.copy2(student_path, student_path.with_name(f"{student_path.stem}.backup_{datetime.now().strftime('%Y%m%d_%H%M%S')}_load_scheme.json"))
            except Exception:
                pass
            atomic_write_json(student_path, student_config)
            self.student_config = student_config

        self.available_zone_names = [
            zone.get('zone_name', f'zone{i + 1}')
            for i, zone in enumerate((self.answer_config or {}).get('zones', []))
        ]
        self.selected_zones = self.available_zone_names[:1] if self.available_zone_names else []
        self.template_marker_points = self.get_template_marker_points()
        self.update_template_ui_state()
        return True

    def get_direct_paper_structure_for_scheme(self, scheme_path=None):
        if not self.is_direct_paper_choice_template():
            return {}
        config = copy.deepcopy(getattr(self, 'answer_config', {}) or {})
        if not isinstance(config, dict) or config.get('mode') != 'direct_paper_choice':
            return {}
        structure = {
            'version': 1,
            'template_key': self.current_template_key,
            'template_name': self.current_template_name,
            'answer_config': config,
            'marker_config': copy.deepcopy(getattr(self, 'marker_config', {}) or {}),
            'template_images': {},
            'saved_at': datetime.now().isoformat(timespec='seconds'),
        }
        line_path = self.direct_subjective_line_config_path()
        if line_path.is_file():
            structure['subjective_line_config'] = json.loads(line_path.read_text(encoding='utf-8-sig'))
        asset_dir = self.answer_scheme_asset_dir(scheme_path)
        if not asset_dir:
            return structure

        asset_dir.mkdir(parents=True, exist_ok=True)
        side_sources = {}
        top_image = config.get('template_image') if isinstance(config.get('template_image'), dict) else {}
        if top_image.get('path'):
            side_sources['front'] = top_image.get('path')
        sides = config.get('sides') if isinstance(config.get('sides'), dict) else {}
        for side, payload in sides.items():
            side_key = 'back' if str(side).lower() == 'back' else 'front'
            image_info = payload.get('template_image') if isinstance(payload, dict) else {}
            if isinstance(image_info, dict) and image_info.get('path'):
                side_sources[side_key] = image_info.get('path')

        paths = getattr(self, 'current_template_paths', {}) or {}
        if 'front' not in side_sources and paths.get('template_image'):
            side_sources['front'] = str(paths.get('template_image'))
        if 'back' in sides and 'back' not in side_sources and paths.get('template_image'):
            back_candidate = Path(paths.get('template_image')).with_name('template_back.jpg')
            if back_candidate.exists():
                side_sources['back'] = str(back_candidate)

        copied = {}
        for side, source_value in side_sources.items():
            try:
                source = Path(source_value)
            except Exception:
                continue
            if not source.exists():
                continue
            suffix = source.suffix or '.jpg'
            dest = asset_dir / f'direct_{side}_template{suffix}'
            try:
                shutil.copy2(source, dest)
                copied[side] = str(dest)
                structure['template_images'][side] = str(dest)
            except Exception:
                continue

        config_copy = structure['answer_config']
        if copied.get('front'):
            config_copy.setdefault('template_image', {})
            config_copy['template_image']['path'] = copied['front']
        sides_copy = config_copy.get('sides') if isinstance(config_copy.get('sides'), dict) else {}
        for side, copied_path in copied.items():
            side_payload = sides_copy.get(side)
            if isinstance(side_payload, dict):
                side_payload.setdefault('template_image', {})
                side_payload['template_image']['path'] = copied_path
        config_copy['sides'] = sides_copy
        return structure

    def marker_payload_from_direct_config(self, config):
        markers = {}
        if isinstance(config, dict):
            sides = config.get('sides') if isinstance(config.get('sides'), dict) else {}
            front_payload = sides.get('front') if isinstance(sides.get('front'), dict) else {}
            markers = front_payload.get('markers') or config.get('markers') or {}
        payload = {'markers': {}}
        for name in ('top_left', 'top_right', 'bottom_left', 'bottom_right'):
            point = markers.get(name) if isinstance(markers, dict) else None
            if not isinstance(point, dict):
                continue
            if 'center' in point and isinstance(point.get('center'), dict):
                center = point['center']
                x = center.get('x')
                y = center.get('y')
            else:
                x = point.get('x')
                y = point.get('y')
            if x is None or y is None:
                continue
            payload['markers'][name] = {'center': {'x': float(x), 'y': float(y)}}
        return payload if len(payload['markers']) == 4 else {}

    def apply_direct_paper_structure_from_scheme(self, structure):
        if not self.is_direct_paper_choice_template():
            return False
        if not isinstance(structure, dict) or not structure:
            return False
        if structure.get('template_key') and structure.get('template_key') != self.current_template_key:
            return False
        config = copy.deepcopy(structure.get('answer_config') or {})
        if not isinstance(config, dict) or config.get('mode') != 'direct_paper_choice':
            return False

        paths = getattr(self, 'current_template_paths', {}) or {}
        answer_str = str(paths.get('answer_config') or '').strip()
        marker_str = str(paths.get('marker_config') or '').strip()
        front_str = str(paths.get('template_image') or '').strip()
        if not answer_str or not marker_str or not front_str:
            return False
        answer_path = Path(answer_str)
        marker_path = Path(marker_str)
        front_template_path = Path(front_str)
        try:
            back_template_path = front_template_path.with_name('template_back.jpg')
        except Exception:
            back_template_path = front_template_path.parent / 'template_back.jpg'
        template_images = structure.get('template_images') if isinstance(structure.get('template_images'), dict) else {}

        sides = config.get('sides') if isinstance(config.get('sides'), dict) else {}
        side_targets = {'front': front_template_path, 'back': back_template_path}
        for side in side_targets:
            side_payload = sides.get(side) or {}
            source_value = (template_images.get(side) or (side_payload.get('template_image') or {}).get('path')
                            or ((config.get('template_image') or {}).get('path') if side == 'front' else None))
            if side == 'front' or side in sides:
                if not source_value or not Path(source_value).is_file():
                    raise ValueError(f'答案方案的{side}模板图缺失，已停止恢复，不能沿用其他试卷模板图。')
        for side, target in side_targets.items():
            source_value = template_images.get(side)
            if not source_value:
                side_payload = sides.get(side) if isinstance(sides.get(side), dict) else {}
                image_info = side_payload.get('template_image') if isinstance(side_payload.get('template_image'), dict) else {}
                source_value = image_info.get('path')
            if not source_value and side == 'front':
                image_info = config.get('template_image') if isinstance(config.get('template_image'), dict) else {}
                source_value = image_info.get('path')
            try:
                source = Path(source_value) if source_value else None
            except Exception:
                source = None
            if source and source.exists():
                try:
                    target.parent.mkdir(parents=True, exist_ok=True)
                    if source.resolve() != target.resolve():
                        if target.exists():
                            backup = target.with_name(f"{target.stem}.backup_{datetime.now().strftime('%Y%m%d_%H%M%S')}_load_scheme{target.suffix}")
                            shutil.copy2(target, backup)
                        shutil.copy2(source, target)
                except Exception as exc:
                    raise ValueError(f'答案方案的{side}模板图恢复失败。') from exc
            if side == 'front':
                config.setdefault('template_image', {})
                config['template_image']['path'] = str(front_template_path)
                if front_template_path.exists():
                    try:
                        with Image.open(front_template_path) as image:
                            config['template_image']['width'], config['template_image']['height'] = image.size
                    except Exception:
                        pass
            side_payload = sides.get(side)
            if isinstance(side_payload, dict):
                side_payload.setdefault('template_image', {})
                side_payload['template_image']['path'] = str(target)
                if target.exists():
                    try:
                        with Image.open(target) as image:
                            side_payload['template_image']['width'], side_payload['template_image']['height'] = image.size
                    except Exception:
                        pass
        config['sides'] = sides

        try:
            if answer_path.exists():
                shutil.copy2(answer_path, answer_path.with_name(f"{answer_path.stem}.backup_{datetime.now().strftime('%Y%m%d_%H%M%S')}_load_scheme.json"))
        except Exception:
            pass
        atomic_write_json(answer_path, config)

        marker_payload = copy.deepcopy(structure.get('marker_config') or {})
        if not isinstance(marker_payload, dict) or not marker_payload.get('markers'):
            marker_payload = self.marker_payload_from_direct_config(config)
        if marker_payload:
            try:
                if marker_path.exists():
                    shutil.copy2(marker_path, marker_path.with_name(f"{marker_path.stem}.backup_{datetime.now().strftime('%Y%m%d_%H%M%S')}_load_scheme.json"))
            except Exception:
                pass
            atomic_write_json(marker_path, marker_payload)

        atomic_write_json(self.direct_subjective_line_config_path(),
                          copy.deepcopy(structure.get('subjective_line_config') or {}))
        self.answer_config = config
        # A loaded scheme may replace the template files at the same paths.
        self._session_requires_structure = False
        # Never reuse pixels/features cached from the previously loaded paper.
        self._direct_choice_template_gray_cache = {}
        self._direct_feature_template_cache = {}
        if marker_payload:
            self.marker_config = marker_payload
        self.available_zone_names = [
            zone.get('zone_name', f'zone{i + 1}')
            for i, zone in enumerate((self.answer_config or {}).get('zones', []))
        ]
        self.selected_zones = list(self.available_zone_names)
        self.template_marker_points = self.get_template_marker_points()
        self.update_template_ui_state()
        return True

    def normalize_direct_subjective_scoring(self, config):
        normalized = copy.deepcopy(config or {})
        total = 0.0
        for item in normalized.get('items') or []:
            is_drawing = str(item.get('kind') or '').strip().lower() == 'drawing'
            score = 2.0 if is_drawing else 1.0
            item['max_score'] = score
            if not is_drawing:
                for blank in item.get('blanks') or []:
                    blank['score'] = 1.0
            total += score if is_drawing else sum(
                float(blank.get('score') or 1.0) for blank in (item.get('blanks') or [])
            )
        scoring = normalized.setdefault('scoring', {})
        scoring['default_blank_score'] = 1
        scoring['max_score'] = total
        return normalized

    def apply_subjective_config_from_scheme(self, config):
        if not isinstance(config, dict) or not config:
            return False
        config_path = getattr(self, 'subjective_config_path', None)
        if not config_path:
            return False
        config_path = Path(config_path)
        if not config_path.exists():
            return False
        scheme_snapshot = copy.deepcopy(config)
        scheme_snapshot.pop('_session_snapshot', None)
        meta = scheme_snapshot.get('_answer_scheme_snapshot') or {}
        if meta.get('template_key') and meta.get('template_key') != self.current_template_key:
            return False
        if self.is_direct_paper_choice_template() or self.is_mixed_objective_subjective_template():
            snapshot = copy.deepcopy(scheme_snapshot)
        else:
            try:
                current_snapshot = json.loads(config_path.read_text(encoding='utf-8-sig'))
            except Exception:
                current_snapshot = {}
            snapshot = self.merge_subjective_scheme_into_template_config(current_snapshot, scheme_snapshot)
        if self.is_direct_paper_choice_template():
            snapshot = self.normalize_direct_subjective_scoring(snapshot)
        backup_path = config_path.with_name(
            f"{config_path.stem}.backup_{datetime.now().strftime('%Y%m%d_%H%M%S')}_load_answer_scheme.json"
        )
        try:
            shutil.copy2(config_path, backup_path)
        except Exception:
            pass
        snapshot['updated_at'] = datetime.now().isoformat(timespec='seconds')
        atomic_write_json(config_path, snapshot)
        self.subjective_config = snapshot
        # Saved geometry belongs to this paper. The shared line detection file
        # may belong to another test, so never rebuild a snapshot from it.
        if getattr(self, 'current_session', None):
            self.save_session_template_config_snapshot()
        return True

    def merge_subjective_scheme_into_template_config(self, template_config, scheme_config):
        if not isinstance(template_config, dict) or not template_config.get('items'):
            merged = copy.deepcopy(scheme_config)
            merged.pop('_session_snapshot', None)
            return merged
        merged = copy.deepcopy(template_config)

        def part_key(item, sub=None, blank=None):
            qno = item.get('question_no')
            if item.get('kind') == 'fill_blank' and blank is not None:
                return f"q{qno}_b{blank.get('blank_no')}"
            if item.get('kind') == 'experiment' and sub is not None and blank is not None:
                return f"q{qno}_s{sub.get('sub_no')}_b{blank.get('blank_no')}"
            if item.get('kind') == 'drawing':
                return str(qno)
            return str(qno)

        scheme_parts = {}
        for item in scheme_config.get('items', []) or []:
            if item.get('kind') == 'fill_blank':
                for blank in item.get('blanks', []) or []:
                    scheme_parts[part_key(item, blank=blank)] = blank
            elif item.get('kind') == 'experiment':
                for sub in item.get('subquestions', []) or []:
                    for blank in sub.get('blanks', []) or []:
                        scheme_parts[part_key(item, sub=sub, blank=blank)] = blank
            elif item.get('kind') == 'drawing':
                scheme_parts[part_key(item)] = item

        for item in merged.get('items', []) or []:
            if item.get('kind') == 'fill_blank':
                for blank in item.get('blanks', []) or []:
                    source = scheme_parts.get(part_key(item, blank=blank)) or {}
                    self.merge_subjective_blank_answer_settings(blank, source)
            elif item.get('kind') == 'experiment':
                for sub in item.get('subquestions', []) or []:
                    for blank in sub.get('blanks', []) or []:
                        source = scheme_parts.get(part_key(item, sub=sub, blank=blank)) or {}
                        self.merge_subjective_blank_answer_settings(blank, source)
            elif item.get('kind') == 'drawing':
                source = scheme_parts.get(part_key(item)) or {}
                for key in ('max_score', 'manual_only', 'score_category', 'normal_score'):
                    if key in source:
                        item[key] = source[key]

        for key in ('scoring', 'optional_experiment_drawing', 'calculation_questions', 'direct_calculation_region'):
            if key in scheme_config:
                merged[key] = copy.deepcopy(scheme_config[key])
        merged['_answer_scheme_snapshot'] = copy.deepcopy(scheme_config.get('_answer_scheme_snapshot') or {})
        return merged

    def merge_subjective_blank_answer_settings(self, target, source):
        if not isinstance(target, dict) or not isinstance(source, dict):
            return
        for key in ('score', 'normal_score', 'score_category', 'manual_only'):
            if key in source:
                target[key] = source[key]
        source_ocr = source.get('ocr')
        if isinstance(source_ocr, dict):
            target_ocr = target.get('ocr')
            if not isinstance(target_ocr, dict):
                target_ocr = {}
                target['ocr'] = target_ocr
            target_ocr.update(copy.deepcopy(source_ocr))

    def open_optional_experiment_drawing_settings(self):
        config_path = getattr(self, 'subjective_config_path', None)
        if not config_path or not Path(config_path).exists():
            messagebox.showinfo('提示', '当前模板没有主观题配置。')
            return

        config = json.loads(Path(config_path).read_text(encoding='utf-8-sig'))
        current = (config.get('optional_experiment_drawing') or {})
        enabled_var = tk.BooleanVar(value=bool(current.get('enabled', False)))

        win = tk.Toplevel(self.root)
        win.title('实验作图开关')
        self.track_context_window(win)
        win.geometry('560x260')
        win.minsize(520, 240)
        win.transient(self.root)

        ttk.Label(
            win,
            text='默认关闭：实验题所有空正常计分，作图题按6分。\n打开后：指定实验空跳过，右下角实验作图加入作图题，作图题按7分。',
            font=('Arial', 10, 'bold'),
            wraplength=520,
        ).pack(anchor='w', padx=16, pady=(16, 10))
        ttk.Checkbutton(
            win,
            text='启用右下角实验作图（把1分从实验空转到作图题）',
            variable=enabled_var,
        ).pack(anchor='w', padx=16, pady=(0, 10))
        ttk.Label(
            win,
            text='当前模板约定：右下角作图区为“22题(1) 实验作图”；对应实验空默认为 q22_s1_b1。以后如果位置变化，可以再调整这个模板约定。',
            wraplength=520,
        ).pack(anchor='w', padx=16, pady=(0, 12))

        def save_setting():
            fresh = json.loads(Path(config_path).read_text(encoding='utf-8-sig'))
            fresh['optional_experiment_drawing'] = {
                'enabled': bool(enabled_var.get()),
                'drawing_question_no': str(current.get('drawing_question_no') or '22-1-drawing'),
                'placeholder_part_id': str(current.get('placeholder_part_id') or 'q22_s1_b1'),
                'placeholder_normal_score': float(current.get('placeholder_normal_score') or 1),
            }
            for item in fresh.get('items', []):
                if str(item.get('question_no')) == fresh['optional_experiment_drawing']['drawing_question_no']:
                    item['optional_experiment_drawing'] = True
                    item['score_category'] = 'drawing'
                    item['max_score'] = 1
                if item.get('question_no') == 22:
                    for sub in item.get('subquestions', []) or []:
                        if sub.get('sub_no') == 1:
                            for blank in sub.get('blanks', []) or []:
                                if blank.get('blank_no') == 1:
                                    blank['normal_score'] = fresh['optional_experiment_drawing']['placeholder_normal_score']
                                    blank['score_category'] = 'ignore'
                                    blank['score'] = 0
            fresh['updated_at'] = datetime.now().isoformat(timespec='seconds')
            fresh['latest_template_note'] = (
                '实验作图开关已保存：'
                + ('启用，右下角实验作图计入作图题，实验对应空跳过。' if enabled_var.get() else '关闭，右下角实验作图不裁，实验空正常计分。')
            )
            backup_path = Path(config_path).with_name(
                f"{Path(config_path).stem}.backup_{datetime.now().strftime('%Y%m%d_%H%M%S')}_optional_exp_drawing.json"
            )
            shutil.copy2(config_path, backup_path)
            Path(config_path).write_text(json.dumps(fresh, ensure_ascii=False, indent=2), encoding='utf-8')
            self.subjective_config = fresh
            if self.summary_data:
                self.apply_subjective_scores_to_entries()
                self.update_summary_display()
                self.update_analysis_display()
            messagebox.showinfo('保存完成', '实验作图开关已保存。重新进入主观题批改会按新规则裁图和统计。', parent=win)
            win.destroy()

        footer = ttk.Frame(win)
        footer.pack(fill=tk.X, padx=16, pady=(4, 14))
        ttk.Button(footer, text='保存', command=save_setting).pack(side=tk.LEFT, padx=4)
        ttk.Button(footer, text='取消', command=win.destroy).pack(side=tk.LEFT, padx=4)

    def calculation_question_config(self):
        if self.is_direct_paper_choice_template() and not self.direct_paper_has_calculation_structure():
            return []
        config = (getattr(self, 'subjective_config', {}) or {}).get('calculation_questions') or {}
        if isinstance(config, dict) and config.get('enabled') is False:
            return []
        questions = config.get('questions') if isinstance(config, dict) else []
        if not isinstance(questions, list):
            return []
        cleaned = []
        for question in questions:
            try:
                question_no = int(question.get('question_no'))
            except Exception:
                continue
            sub_scores = []
            for item in question.get('sub_scores', []) or []:
                try:
                    sub_no = int(item.get('sub_no'))
                    score = float(item.get('score') or 0)
                except Exception:
                    continue
                if sub_no > 0 and score > 0:
                    sub_scores.append({'sub_no': sub_no, 'score': score})
            if sub_scores:
                cleaned.append({
                    'question_no': question_no,
                    'sub_scores': sorted(sub_scores, key=lambda item: item['sub_no']),
                    'max_score': round(sum(item['score'] for item in sub_scores), 2),
                })
        return sorted(cleaned, key=lambda item: item['question_no'])

    def direct_calculation_region_config(self):
        if not self.is_direct_paper_choice_template():
            return {}
        payload = (getattr(self, 'subjective_config', {}) or {}).get('direct_calculation_region') or {}
        if not isinstance(payload, dict) or not payload.get('enabled'):
            return {}
        rect = payload.get('rect') or {}
        try:
            normalized_rect = {
                'x': float(rect.get('x', 0)),
                'y': float(rect.get('y', 0)),
                'w': float(rect.get('w', 0)),
                'h': float(rect.get('h', 0)),
            }
        except Exception:
            return {}
        if normalized_rect['w'] <= 0 or normalized_rect['h'] <= 0:
            return {}
        normalized = copy.deepcopy(payload)
        normalized['side'] = 'back'
        normalized['rect'] = normalized_rect
        return normalized

    def direct_calculation_crop_part(self):
        """Expose the back-page calculation area to the shared crop cache.

        It deliberately stays outside ``iter_subjective_parts``: calculation
        questions have no answer key and must never be sent to OCR.
        """
        if not self.direct_paper_has_calculation_structure():
            return None
        region = self.direct_calculation_region_config()
        if not region or not self.calculation_question_config():
            return None
        return {
            'part_id': 'calculation_back_region',
            'label': '计算题区域',
            'kind': 'calculation',
            'side': 'back',
            'region_name': '',
            'rect': copy.deepcopy(region.get('rect') or {}),
            'score': 0.0,
        }

    def build_direct_calculation_region(self, lines, image_width, image_height, top_offset=0, boxes=None):
        width = float(image_width or 0)
        height = float(image_height or 0)
        if width <= 0 or height <= 0:
            raise ValueError('模板图片尺寸无效，不能生成计算题区域。')
        retained = list(lines or [])
        retained_boxes = list(boxes or [])
        left_margin = max(24.0, width * 0.025)
        right_margin = max(24.0, width * 0.025)
        base_gap = max(12.0, height * 0.006)
        if retained:
            last_bottom = max(
                float((item.get('template_rect') or {}).get('y', item.get('y', 0)))
                + float((item.get('template_rect') or {}).get('h', item.get('h', 0)))
                for item in retained
            )
            top = last_bottom + base_gap + float(top_offset or 0)
            source = 'last_retained_line_to_page_bottom'
        elif retained_boxes:
            last_bottom = max(
                float((item.get('template_rect') or {}).get('y', item.get('y', 0)))
                + float((item.get('template_rect') or {}).get('h', item.get('h', 0)))
                for item in retained_boxes
            )
            top = last_bottom + base_gap + float(top_offset or 0)
            source = 'last_retained_box_to_page_bottom'
        else:
            top = max(36.0, height * 0.045) + float(top_offset or 0)
            source = 'full_page_content_area'

        # Keep the registration blocks out of the crop while retaining as much
        # vertical working area as possible.
        bottom = height - max(36.0, height * 0.045)
        top = max(0.0, min(bottom - 1.0, top))
        if bottom - top < max(120.0, height * 0.08):
            raise ValueError('计算题区域高度不足。请检查页面设置或调整上边界微调。')
        return {
            'enabled': True,
            'side': 'back',
            'source': source,
            'top_offset': round(float(top_offset or 0), 2),
            'rect': {
                'x': round(left_margin, 2),
                'y': round(top, 2),
                'w': round(width - left_margin - right_margin, 2),
                'h': round(bottom - top, 2),
            },
            'template_width': round(width, 2),
            'template_height': round(height, 2),
        }

    def ensure_direct_calculation_region_for_questions(self, questions):
        """Create the back-page calculation crop as soon as scores are configured."""
        if not self.is_direct_paper_choice_template() or not questions:
            return {}
        line_path = self.direct_subjective_line_config_path()
        if not line_path.exists():
            raise RuntimeError('没有找到正反面主观横线结构，不能自动建立计算题裁图区域。')
        line_config = json.loads(line_path.read_text(encoding='utf-8-sig'))
        sides = line_config.get('sides') if isinstance(line_config.get('sides'), dict) else {}
        back = sides.get('back') if isinstance(sides.get('back'), dict) else {}
        calc_reg = back.get('calculation_region')
        if isinstance(calc_reg, dict) and calc_reg.get('enabled') is False:
            return {}
        existing = self.direct_calculation_region_config()
        if existing:
            return existing
        lines = back.get('lines') or []
        boxes = []
        choice_path = self.direct_choice_config_path()
        if choice_path.exists():
            try:
                choice_config = json.loads(choice_path.read_text(encoding='utf-8-sig'))
                c_sides = choice_config.get('sides') if isinstance(choice_config.get('sides'), dict) else {}
                c_back = c_sides.get('back') if isinstance(c_sides.get('back'), dict) else {}
                boxes = c_back.get('boxes') or []
            except Exception:
                boxes = []
        image_info = back.get('template_image') if isinstance(back.get('template_image'), dict) else {}
        width = float(image_info.get('width') or 0)
        height = float(image_info.get('height') or 0)
        if width <= 0 or height <= 0:
            image_path = Path(image_info.get('path') or '')
            if not image_path.exists() and choice_path.exists():
                c_img = c_back.get('template_image') if isinstance(c_back.get('template_image'), dict) else {}
                image_path = Path(c_img.get('path') or '')
            if image_path.exists():
                with Image.open(image_path) as image:
                    width, height = image.size
        if width <= 0 or height <= 0:
            pair = self.find_direct_paper_structure_template_pair()
            back_file = pair.get('back')
            if back_file and Path(back_file).exists():
                with Image.open(back_file) as image:
                    width, height = image.size
        region = self.build_direct_calculation_region(lines, width, height, boxes=boxes)
        back['calculation_region'] = copy.deepcopy(region)
        sides['back'] = back
        line_config['sides'] = sides
        line_config['updated_at'] = datetime.now().isoformat(timespec='seconds')
        atomic_write_json(line_path, line_config)
        self.sync_direct_subjective_lines_to_subjective_config(line_config)
        return region

    def direct_calculation_crop_for_entry(self, entry, back_path):
        region = self.direct_calculation_region_config()
        if not region:
            raise RuntimeError('当前答案方案没有设置背面计算题区域。')
        back_path = Path(back_path)
        oriented_image, _rotation_name = self.orient_entry_image_for_side(entry, back_path, 'back')
        matrix = self.entry_alignment_homography(entry, 'back')
        if matrix is None:
            with tempfile.NamedTemporaryFile(suffix='.png', delete=False) as tmp:
                temp_path = Path(tmp.name)
            oriented_image.save(temp_path)
            try:
                matrix, _marker_payload = self.detect_scan_homography(temp_path, side='back')
            finally:
                try:
                    temp_path.unlink(missing_ok=True)
                except Exception:
                    pass
        left, top, right, bottom = self.project_template_rect(matrix, region['rect'])
        width, height = oriented_image.size
        left = max(0, min(width - 1, left))
        top = max(0, min(height - 1, top))
        right = max(left + 1, min(width, right))
        bottom = max(top + 1, min(height, bottom))
        return oriented_image.crop((left, top, right, bottom))

    def format_calculation_question_config(self):
        if self.is_direct_paper_choice_template() and not self.direct_paper_has_calculation_structure():
            return ''
        questions = self.calculation_question_config()
        if not questions:
            if self.is_direct_paper_choice_template():
                return ''
            return '24: 3,3,4\n25: 2,2,3,3'
        lines = []
        for question in questions:
            scores = ','.join(f"{float(item.get('score') or 0):g}" for item in question.get('sub_scores', []))
            lines.append(f"{question.get('question_no')}: {scores}")
        return '\n'.join(lines)

    def parse_calculation_question_text(self, text, allow_empty=False):
        raw = str(text or '')
        circle_map = {
            '①': ' (1) ', '②': ' (2) ', '③': ' (3) ', '④': ' (4) ', '⑤': ' (5) ',
            '⑥': ' (6) ', '⑦': ' (7) ', '⑧': ' (8) ', '⑨': ' (9) ', '⑩': ' (10) '
        }
        for c, r in circle_map.items():
            raw = raw.replace(c, r)
        raw_text = unicodedata.normalize('NFKC', raw).strip()
        if not raw_text:
            if allow_empty:
                return []
            raise ValueError('请至少填写一道计算题，例如：24: 3,3,4')

        questions_map = defaultdict(list)

        for raw_line in raw_text.splitlines():
            line = raw_line.strip()
            if not line or line.startswith('#'):
                continue

            single_sub_match = re.match(
                r'^(?:第)?\s*(\d+)\s*(?:题)?\s*(?:[（(\-_.]\s*([1-9]\d*)\s*[）)]?|第\s*([1-9]\d*)\s*(?:小题|题)?)\s*[:：=＝]?\s*([+-]?\d+(?:\.\d+)?)\s*(?:分)?$',
                line,
            )
            if single_sub_match:
                qno = int(single_sub_match.group(1))
                sub_no = int(single_sub_match.group(2) or single_sub_match.group(3))
                score = float(single_sub_match.group(4))
                if score <= 0:
                    raise ValueError(f'第{qno}题第({sub_no})小题分值必须大于0。')
                questions_map[qno].append({'sub_no': sub_no, 'score': score})
                continue

            main_match = re.match(r'^(?:第)?\s*(\d+)\s*(?:题)?\s*[:：=＝.]\s*(.+)$', line)
            if not main_match:
                raise ValueError(f'格式不正确：{raw_line}\n请按类似“24: 3,3,4”或“24(1): 3”的格式填写。')

            qno = int(main_match.group(1))
            score_text = main_match.group(2).strip()

            explicit_subs = re.findall(
                r'[（(]\s*([1-9]\d*)\s*[）)]\s*[:：=＝]?\s*([+-]?\d+(?:\.\d+)?)\s*(?:分)?',
                score_text,
            )
            if explicit_subs:
                for sub_str, score_str in explicit_subs:
                    sub_no = int(sub_str)
                    score = float(score_str)
                    if score <= 0:
                        raise ValueError(f'第{qno}题第({sub_no})小题分值必须大于0。')
                    questions_map[qno].append({'sub_no': sub_no, 'score': score})
                continue

            cleaned_score_text = re.sub(r'(?<=\d)\s*分', '', score_text)
            values = [v for v in re.split(r'[,，、;；/+\s]+', cleaned_score_text) if v]
            if not values:
                raise ValueError(f'第{qno}题没有填写小题分值。')

            start_sub_no = len(questions_map[qno]) + 1
            for index, val in enumerate(values, start_sub_no):
                try:
                    score = float(val)
                except Exception:
                    raise ValueError(f'第{qno}题分值不是数字：{val}')
                if score <= 0:
                    raise ValueError(f'第{qno}题分值必须大于0：{score}')
                questions_map[qno].append({'sub_no': index, 'score': score})

        if not questions_map:
            if allow_empty:
                return []
            raise ValueError('请至少填写一道计算题，例如：24: 3,3,4')

        result = []
        for qno, sub_list in sorted(questions_map.items()):
            seen_subs = set()
            normalized_subs = []
            for item in sub_list:
                s_no = item['sub_no']
                if s_no in seen_subs:
                    s_no = max(seen_subs) + 1
                seen_subs.add(s_no)
                normalized_subs.append({'sub_no': s_no, 'score': item['score']})
            normalized_subs.sort(key=lambda x: x['sub_no'])
            for idx, item in enumerate(normalized_subs, 1):
                item['sub_no'] = idx

            result.append({
                'question_no': qno,
                'sub_scores': normalized_subs,
                'max_score': round(sum(x['score'] for x in normalized_subs), 2),
            })
        return result

    def open_calculation_question_settings(self):
        if self.is_direct_paper_choice_template():
            self.open_integrated_answer_scheme_builder()
            return
        config_path = getattr(self, 'subjective_config_path', None)
        if not config_path or not Path(config_path).exists():
            messagebox.showinfo('提示', '当前模板没有可保存计算题设置的配置文件。')
            return
        if self.is_direct_paper_choice_template() and not self.direct_calculation_region_config():
            messagebox.showinfo(
                '计算题区域尚未设置',
                '可以先填写题号和分值，但正式批改前还要进入“正反面结构”，\n'
                '设置背面并勾选“启用计算题区域”。\n\n计算题不需要标准答案。',
            )

        win = tk.Toplevel(self.root)
        win.title('设置计算题小题分值')
        self.track_context_window(win)
        win.geometry('620x430')
        win.minsize(560, 360)
        win.transient(self.root)

        ttk.Label(
            win,
            text=(
                '支持多种输入格式（系统会自动识别小题）：\n'
                '① 逗号分隔：24: 3, 3, 4（冒号后写几个数字就生成几个小题）\n'
                '② 带小题号分行：24(1): 3分，下一行写 24(2): 3分、24(3): 4分\n'
                '③ 同行写小题：24: (1)3分 (2)3分 (3)4分 或 24: ①3分 ②3分 ③4分\n'
                '计算题不设置标准答案，不走 OCR，批改时直接查看背面裁图并人工打分。'
            ),
            font=('Arial', 10, 'bold'),
            wraplength=580,
        ).pack(anchor='w', padx=16, pady=(16, 8))

        text = scrolledtext.ScrolledText(win, height=9, wrap=tk.WORD, font=('Consolas', 12))
        text.pack(fill=tk.BOTH, expand=True, padx=16, pady=(0, 8))
        text.insert('1.0', self.format_calculation_question_config())

        status_var = tk.StringVar(value='设置会保存到当前模板，也会随答案方案和测试进度一起保存。')
        ttk.Label(win, textvariable=status_var, foreground='#555').pack(anchor='w', padx=16, pady=(0, 8))

        def save_setting():
            try:
                questions = self.parse_calculation_question_text(text.get('1.0', tk.END))
                fresh = json.loads(Path(config_path).read_text(encoding='utf-8-sig'))
                backup_path = Path(config_path).with_name(
                    f"{Path(config_path).stem}.backup_{datetime.now().strftime('%Y%m%d_%H%M%S')}_calculation_questions.json"
                )
                shutil.copy2(config_path, backup_path)
                fresh['calculation_questions'] = {
                    'enabled': True,
                    'mode': 'back_region_manual' if self.is_direct_paper_choice_template() else 'back_page_manual_whole_page',
                    'questions': questions,
                    'max_score': round(sum(question['max_score'] for question in questions), 2),
                    'updated_at': datetime.now().isoformat(timespec='seconds'),
                }
                fresh['updated_at'] = datetime.now().isoformat(timespec='seconds')
                Path(config_path).write_text(json.dumps(fresh, ensure_ascii=False, indent=2), encoding='utf-8')
                self.subjective_config = fresh
                self.ensure_answer_scheme_matches_current_structure(persist=True)
                if self.current_session:
                    self.save_session_template_config_snapshot()
                self.update_template_ui_state()
                total = fresh['calculation_questions']['max_score']
                status_var.set(f'已保存：{len(questions)} 道计算题，总分 {total:g} 分。')
                messagebox.showinfo('保存完成', f'计算题结构已保存。\n总分：{total:g} 分', parent=win)
                win.destroy()
            except Exception as e:
                messagebox.showerror('保存失败', str(e), parent=win)

        footer = ttk.Frame(win)
        footer.pack(fill=tk.X, padx=16, pady=(4, 14))
        ttk.Button(footer, text='保存', command=save_setting).pack(side=tk.LEFT, padx=4)
        ttk.Button(footer, text='取消', command=win.destroy).pack(side=tk.LEFT, padx=4)
        win.bind('<Control-s>', lambda _e: save_setting())
        win.protocol('WM_DELETE_WINDOW', win.destroy)

    def open_calculation_score_entry(self):
        if not self.require_current_session_for_grading('计算题批改与批注'):
            return
        if self.mixed_template_single_side_mode_enabled():
            messagebox.showinfo('提示', '当前是混合模板单面模式，不需要输入计算题分数。')
            return
        questions = self.calculation_question_config()
        if not questions:
            if messagebox.askyesno('提示', '还没有设置计算题小题分值。\n\n现在去设置吗？'):
                self.open_calculation_question_settings()
            return
        if not self.summary_data:
            messagebox.showwarning('提示', '请先完成正面批改，再进行计算题批注与批改。')
            return

        def infer_back_path(entry):
            side_files = entry.get('side_files') or {}
            raw_back = side_files.get('back')
            if raw_back and Path(raw_back).exists():
                return Path(raw_back)
            raw_front = side_files.get('front') or entry.get('input_path') or entry.get('file')
            if not raw_front:
                return None
            front = Path(raw_front)
            if not front.is_absolute() and getattr(self, 'selected_folder_path', ''):
                front = Path(self.selected_folder_path) / front
            if not front.exists():
                return None
            candidates = []
            stem = front.stem
            if stem.endswith('.1'):
                candidates.append(front.with_name(stem[:-2] + '.2' + front.suffix))
            match = re.search(r'(\d+)$', stem)
            if match:
                number = match.group(1)
                prefix = stem[:match.start(1)]
                candidates.append(front.with_name(f"{prefix}{int(number) + 1:0{len(number)}d}{front.suffix}"))
            for candidate in candidates:
                if candidate.exists():
                    side_files['front'] = str(front)
                    side_files['back'] = str(candidate)
                    entry['side_files'] = side_files
                    entry['source_kind'] = 'image_pair'
                    return candidate
            return None

        entries = [entry for entry in self.summary_data if infer_back_path(entry)]
        if not entries:
            entries = [entry for entry in self.summary_data if entry.get('input_path') or entry.get('file')]
            if not entries:
                messagebox.showwarning('提示', '当前结果里没有找到可批改的试卷图片。')
                return

        self.status_var.set('正在打开计算题工作台...')
        self.root.update_idletasks()

        payload = self.load_subjective_score_payload()
        if not isinstance(payload, dict):
            payload = {}
        payload.setdefault('version', 1)
        payload.setdefault('template_key', self.current_template_key)
        payload.setdefault('template_name', self.current_template_name)
        payload.setdefault('scores', {})
        payload.setdefault('calculation_annotations', {})
        all_scores = payload['scores']
        all_annotations = payload['calculation_annotations']

        win = tk.Toplevel(self.root)
        win.title('计算题整大题集中批改与试卷批注工作台')
        win.geometry('1520x940')
        win.minsize(1150, 720)
        win.transient(self.root)
        win.lift()
        win.focus_force()
        self.status_var.set('就绪：已进入计算题集中批改与批注工作台')

        state = {
            'question_index': 0,
            'entry_index': 0,
            'photo': None,
            'scale': 1.0,
            'dirty': False,
            'current_image_obj': None,
            'canvas_items': [],
        }

        anno_state = {
            'tool': 'view',  # 'view', 'line', 'check', 'cross', 'stamp'
            'stamp_text': '',
            'drawing': False,
            'temp_line_pts': [],
            'temp_line_id': None,
        }

        # ----------------- 顶部全局导航栏 -----------------
        header = ttk.Frame(win)
        header.pack(fill=tk.X, padx=12, pady=(8, 4))

        title_var = tk.StringVar()
        progress_var = tk.StringVar()
        tool_hint_var = tk.StringVar(value='💡 提示：在右侧打分面板赋分；在下方点选批注符号或印章后点击试卷页面盖印；最后点击【提交并跳到下一题】。')

        ttk.Label(header, textvariable=title_var, font=('Arial', 13, 'bold'), foreground='#1E3A8A').pack(side=tk.LEFT)
        ttk.Label(header, textvariable=progress_var, foreground='#4B5563', font=('Arial', 10)).pack(side=tk.LEFT, padx=(16, 0))

        # 题目快速切换下拉框
        q_options = [f"第 {q.get('question_no')} 题 (满分 {sum(float(s.get('score') or 0) for s in (q.get('sub_scores') or [])):g} 分)" for q in questions]
        q_combo_var = tk.StringVar()
        if q_options:
            q_combo_var.set(q_options[0])

        def on_q_combo_select(_e=None):
            sel = q_combo_box.current()
            if 0 <= sel < len(questions) and sel != state['question_index']:
                if state['dirty'] and save_safely(show_status=False) is None:
                    q_combo_box.current(state['question_index'])
                    return
                state['question_index'] = sel
                refresh_view()

        ttk.Label(header, text='跳转大题:').pack(side=tk.LEFT, padx=(24, 4))
        q_combo_box = ttk.Combobox(header, textvariable=q_combo_var, values=q_options, state='readonly', width=22)
        q_combo_box.pack(side=tk.LEFT)
        q_combo_box.bind('<<ComboboxSelected>>', on_q_combo_select)

        # 学生快速切换下拉框
        def _format_sid(val, default_idx):
            if val is not None and str(val).strip():
                s = str(val).strip()
                return s.zfill(2) if s.isdigit() else s
            return f"{default_idx:02d}"

        student_options = [f"{_format_sid(e.get('score_id'), idx + 1)} - {e.get('student_name') or '未匹配'}" for idx, e in enumerate(entries)]
        s_combo_var = tk.StringVar()
        if student_options:
            s_combo_var.set(student_options[0])

        def on_s_combo_select(_e=None):
            sel = s_combo_box.current()
            if 0 <= sel < len(entries) and sel != state['entry_index']:
                if state['dirty'] and save_safely(show_status=False) is None:
                    s_combo_box.current(state['entry_index'])
                    return
                state['entry_index'] = sel
                refresh_view()

        ttk.Label(header, text='跳转学生:').pack(side=tk.LEFT, padx=(18, 4))
        s_combo_box = ttk.Combobox(header, textvariable=s_combo_var, values=student_options, state='readonly', width=20)
        s_combo_box.pack(side=tk.LEFT)
        s_combo_box.bind('<<ComboboxSelected>>', on_s_combo_select)

        # ----------------- 主体分栏：左侧试卷，右侧固定控制区 -----------------
        main_container = ttk.Frame(win)
        main_container.pack(fill=tk.BOTH, expand=True, padx=10, pady=4)

        # 右侧：固定宽度 480 像素，包含打分(上)、批注与批语工具(中)、提交按钮(下)
        right_panel = ttk.Frame(main_container, width=500)
        right_panel.pack(side=tk.RIGHT, fill=tk.Y, padx=(6, 0), pady=2)
        right_panel.pack_propagate(False)  # 保持固定宽度，防止被挤压

        # 左侧：试卷大图与 Canvas 批注区
        left_box = ttk.Frame(main_container)
        left_box.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)

        hint_bar = ttk.Frame(left_box)
        hint_bar.pack(fill=tk.X, pady=(0, 4))
        ttk.Label(hint_bar, textvariable=tool_hint_var, foreground='#1D4ED8', font=('Arial', 10, 'bold')).pack(side=tk.LEFT)

        zoom_bar = ttk.Frame(hint_bar)
        zoom_bar.pack(side=tk.RIGHT)
        zoom_var = tk.StringVar(value='100%')
        ttk.Label(zoom_bar, text='缩放:').pack(side=tk.LEFT, padx=(4, 2))
        ttk.Label(zoom_bar, textvariable=zoom_var, font=('Arial', 9, 'bold'), width=5).pack(side=tk.LEFT)
        tk.Button(zoom_bar, text='➕ 放大', font=('Arial', 9), command=lambda: zoom_in()).pack(side=tk.LEFT, padx=1)
        tk.Button(zoom_bar, text='➖ 缩小', font=('Arial', 9), command=lambda: zoom_out()).pack(side=tk.LEFT, padx=1)
        tk.Button(zoom_bar, text='↔️ 适宽', font=('Arial', 9), command=lambda: zoom_fit_width()).pack(side=tk.LEFT, padx=1)
        tk.Button(zoom_bar, text='100%', font=('Arial', 9), command=lambda: zoom_original()).pack(side=tk.LEFT, padx=1)

        canvas_container = ttk.Frame(left_box)
        canvas_container.pack(fill=tk.BOTH, expand=True)

        image_canvas = tk.Canvas(canvas_container, bg='#1E293B', highlightthickness=0)
        x_scroll = ttk.Scrollbar(canvas_container, orient=tk.HORIZONTAL, command=image_canvas.xview)
        y_scroll = ttk.Scrollbar(canvas_container, orient=tk.VERTICAL, command=image_canvas.yview)
        image_canvas.configure(xscrollcommand=x_scroll.set, yscrollcommand=y_scroll.set)
        image_canvas.grid(row=0, column=0, sticky='nsew')
        y_scroll.grid(row=0, column=1, sticky='ns')
        x_scroll.grid(row=1, column=0, sticky='ew')
        canvas_container.rowconfigure(0, weight=1)
        canvas_container.columnconfigure(0, weight=1)

        # ----------------- 右侧面板内部可滚动区域 -----------------
        r_canvas = tk.Canvas(right_panel, highlightthickness=0)
        r_scroll = ttk.Scrollbar(right_panel, orient=tk.VERTICAL, command=r_canvas.yview)
        score_panel = ttk.Frame(r_canvas)

        score_panel.bind('<Configure>', lambda e: r_canvas.configure(scrollregion=r_canvas.bbox('all')))
        r_canvas_window = r_canvas.create_window((0, 0), window=score_panel, anchor='nw')
        r_canvas.configure(yscrollcommand=r_scroll.set)

        def _on_r_canvas_configure(e):
            r_canvas.itemconfig(r_canvas_window, width=e.width)
        r_canvas.bind('<Configure>', _on_r_canvas_configure)

        r_canvas.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
        r_scroll.pack(side=tk.RIGHT, fill=tk.Y)

        student_var = tk.StringVar()
        file_var = tk.StringVar()
        back_var = tk.StringVar()

        info_frame = ttk.LabelFrame(score_panel, text='当前学生信息', padding=(8, 4))
        info_frame.pack(fill=tk.X, pady=(0, 6))
        ttk.Label(info_frame, textvariable=student_var, font=('Arial', 11, 'bold'), foreground='#1E40AF').pack(anchor='w')
        ttk.Label(info_frame, textvariable=file_var, foreground='#6B7280', font=('Arial', 9)).pack(anchor='w')
        ttk.Label(info_frame, textvariable=back_var, foreground='#6B7280', font=('Arial', 9)).pack(anchor='w')

        # =========================================================================
        # 1. 最上方：本大题打分（第一小问一行，第二小问第二行，第三小问第三行；等级为1分无0.5分）
        # =========================================================================
        score_box = ttk.LabelFrame(score_panel, text=' 📝 本大题各小问赋分 (等级为1分整分) ', padding=(8, 6))
        score_box.pack(fill=tk.X, pady=(0, 8))

        # 整大题快捷一键
        quick_score_row = ttk.Frame(score_box)
        quick_score_row.pack(fill=tk.X, pady=(2, 6))

        def fill_all_full():
            question = current_question()
            for item in question.get('sub_scores', []) or []:
                sub_no = item.get('sub_no')
                max_score = float(item.get('score') or 0)
                part_id = self.calculation_score_part_id(question.get('question_no'), sub_no)
                var = score_vars.get(part_id, (None, None))[0]
                if var:
                    var.set(format_score_value(max_score))
                    refresh_score_buttons(part_id)
            state['dirty'] = True
            tool_hint_var.set(f"已赋【全题满分】，批阅完成后点击右下方【提交并跳到下一题】")

        def fill_all_zero():
            question = current_question()
            for item in question.get('sub_scores', []) or []:
                sub_no = item.get('sub_no')
                part_id = self.calculation_score_part_id(question.get('question_no'), sub_no)
                var = score_vars.get(part_id, (None, None))[0]
                if var:
                    var.set('0')
                    refresh_score_buttons(part_id)
            state['dirty'] = True
            tool_hint_var.set(f"已赋【全题0分】，批阅完成后点击右下方【提交并跳到下一题】")

        tk.Button(
            quick_score_row,
            text='⭐ 整大题全部满分',
            font=('Arial', 10, 'bold'),
            bg='#ECFDF5',
            fg='#047857',
            activebackground='#D1FAE5',
            command=fill_all_full,
        ).pack(side=tk.LEFT, fill=tk.X, expand=True, padx=2)

        tk.Button(
            quick_score_row,
            text='❌ 全部0分',
            font=('Arial', 10),
            bg='#FEF2F2',
            fg='#B91C1C',
            activebackground='#FEE2E2',
            command=fill_all_zero,
        ).pack(side=tk.LEFT, fill=tk.X, expand=True, padx=2)

        score_vars = {}
        score_button_groups = {}
        score_sub_body = ttk.Frame(score_box)
        score_sub_body.pack(fill=tk.X, pady=(2, 4))

        def current_question():
            return questions[state['question_index']]

        def current_entry():
            return entries[state['entry_index']]

        def current_entry_scores(entry):
            entry_key = self.subjective_entry_key(entry)
            return all_scores.setdefault(entry_key, {})

        def clear_score_widgets():
            for child in score_sub_body.winfo_children():
                child.destroy()
            score_vars.clear()
            score_button_groups.clear()

        # 赋分等级为 1 分，没有 0.5 分！
        def score_choices(max_score):
            values = []
            current = 0
            # 步长严格为 1
            max_int = int(max_score)
            while current <= max_int:
                values.append(current)
                current += 1
            if abs(max_score - max_int) > 1e-4:
                values.append(round(max_score, 1))
            return values

        def format_score_value(value):
            return f'{float(value):g}'

        def refresh_score_buttons(part_id):
            var = score_vars.get(part_id, (None, None))[0]
            selected = var.get().strip() if var else ''
            for value, button in score_button_groups.get(part_id, []):
                if selected == format_score_value(value):
                    button.configure(relief=tk.SUNKEN, bg='#93C5FD', fg='#1E3A8A')
                else:
                    button.configure(relief=tk.RAISED, bg='#F9FAFB', fg='#1F2937')

        def choose_score(part_id, value):
            var = score_vars.get(part_id, (None, None))[0]
            if not var:
                return
            var.set(format_score_value(value))
            state['dirty'] = True
            refresh_score_buttons(part_id)

        def load_score_widgets():
            clear_score_widgets()
            question = current_question()
            entry = current_entry()
            entry_scores = current_entry_scores(entry)
            # 每一小问占独立一行！
            for row_idx, item in enumerate(question.get('sub_scores', []) or []):
                sub_no = item.get('sub_no')
                max_score = float(item.get('score') or 0)
                part_id = self.calculation_score_part_id(question.get('question_no'), sub_no)
                record = entry_scores.get(part_id, {}) if isinstance(entry_scores, dict) else {}
                value = ''
                if isinstance(record, dict) and record.get('score') is not None:
                    value = f"{float(record.get('score') or 0):g}"
                var = tk.StringVar(value=value)
                score_vars[part_id] = (var, item)

                row_frame = ttk.Frame(score_sub_body)
                row_frame.pack(fill=tk.X, pady=3)

                # 小问标题：第一小问、第二小问、第三小问
                lbl_text = f"第({sub_no})问 [{max_score:g}分]:"
                ttk.Label(row_frame, text=lbl_text, font=('Arial', 10, 'bold'), width=13).pack(side=tk.LEFT)

                # 各 1 分整步长按钮横排在这一行
                score_button_groups[part_id] = []
                choices = score_choices(max_score)
                for choice in choices:
                    b = tk.Button(
                        row_frame,
                        text=str(choice),
                        width=3,
                        font=('Arial', 10, 'bold'),
                        command=lambda pid=part_id, val=choice: choose_score(pid, val),
                    )
                    b.pack(side=tk.LEFT, padx=1)
                    score_button_groups[part_id].append((choice, b))

                # 清空按钮
                tk.Button(
                    row_frame,
                    text='清空',
                    font=('Arial', 9),
                    command=lambda pid=part_id: (score_vars[pid][0].set(''), state.__setitem__('dirty', True), refresh_score_buttons(pid)),
                ).pack(side=tk.LEFT, padx=(3, 6))

                # 当前分文本框
                ttk.Label(row_frame, text='得分:').pack(side=tk.LEFT)
                score_entry = ttk.Entry(row_frame, textvariable=var, width=5, font=('Arial', 10, 'bold'))
                score_entry.pack(side=tk.LEFT, padx=1)
                var.trace_add('write', lambda *args, pid=part_id: (state.__setitem__('dirty', True), refresh_score_buttons(pid)))

                refresh_score_buttons(part_id)

        # =========================================================================
        # 2. 排在打分下面的是：常用的划线、打叉、打勾、批语这些工具
        # =========================================================================
        anno_frame = ttk.LabelFrame(score_panel, text=' 🎨 试卷批注与常见错误批语印章 (点击后在试卷上点击盖印) ', padding=(8, 6))
        anno_frame.pack(fill=tk.X, pady=(0, 8))

        tool_buttons = {}
        tool_row = ttk.Frame(anno_frame)
        tool_row.pack(fill=tk.X, pady=(2, 6))

        def update_tool_button_styles():
            for t_name, btn in tool_buttons.items():
                if anno_state['tool'] == t_name:
                    btn.configure(relief=tk.SUNKEN, bg='#93C5FD')
                else:
                    btn.configure(relief=tk.RAISED, bg='#F3F4F6')

        def set_tool(t_name, stamp_text=''):
            anno_state['tool'] = t_name
            anno_state['stamp_text'] = stamp_text
            update_tool_button_styles()
            update_stamp_button_styles()
            if t_name == 'view':
                image_canvas.config(cursor='arrow')
                tool_hint_var.set('当前模式：【🖱️浏览】支持拖拽和滚轮缩放。')
            elif t_name == 'line':
                image_canvas.config(cursor='crosshair')
                tool_hint_var.set('当前模式：【✏️划线】在左侧试卷上按住鼠标左键自由划线。')
            elif t_name == 'check':
                image_canvas.config(cursor='crosshair')
                tool_hint_var.set('当前模式：【✔打勾】点击试卷任意步骤位置盖上绿勾。')
            elif t_name == 'cross':
                image_canvas.config(cursor='crosshair')
                tool_hint_var.set('当前模式：【❌打叉】点击试卷任意步骤位置盖上红叉。')
            elif t_name == 'stamp':
                image_canvas.config(cursor='crosshair')
                tool_hint_var.set(f'当前模式：【批语印章】点击试卷任意步骤位置盖印 [{stamp_text}]。')

        tool_buttons['view'] = tk.Button(tool_row, text='🖱️ 浏览', font=('Arial', 10), command=lambda: set_tool('view'))
        tool_buttons['view'].pack(side=tk.LEFT, padx=2)

        tool_buttons['line'] = tk.Button(tool_row, text='✏️ 划线', font=('Arial', 10, 'bold'), fg='#DC2626', command=lambda: set_tool('line'))
        tool_buttons['line'].pack(side=tk.LEFT, padx=2)

        tool_buttons['cross'] = tk.Button(tool_row, text='❌ 打叉', font=('Arial', 10, 'bold'), fg='#DC2626', command=lambda: set_tool('cross'))
        tool_buttons['cross'].pack(side=tk.LEFT, padx=2)

        tool_buttons['check'] = tk.Button(tool_row, text='✔ 打勾', font=('Arial', 10, 'bold'), fg='#16A34A', command=lambda: set_tool('check'))
        tool_buttons['check'].pack(side=tk.LEFT, padx=2)

        def undo_last_annotation():
            qno_key = str(current_question().get('question_no'))
            entry_key = self.subjective_entry_key(current_entry())
            q_annos = all_annotations.setdefault(entry_key, {}).setdefault(qno_key, [])
            if q_annos:
                popped = q_annos.pop()
                state['dirty'] = True
                redraw_annotations()
                tool_hint_var.set(f"已撤销上一步批注：{popped.get('type')}")

        def clear_current_annotations():
            qno_key = str(current_question().get('question_no'))
            entry_key = self.subjective_entry_key(current_entry())
            q_annos = all_annotations.setdefault(entry_key, {}).setdefault(qno_key, [])
            if q_annos:
                if messagebox.askyesno('清空批注', f'确定要清空第 {qno_key} 题试卷上的所有批注吗？', parent=win):
                    q_annos.clear()
                    state['dirty'] = True
                    redraw_annotations()
                    tool_hint_var.set('已清空当前题目的所有批注。')

        tk.Button(tool_row, text='↩️ 撤销', font=('Arial', 9), command=undo_last_annotation).pack(side=tk.LEFT, padx=(6, 2))
        tk.Button(tool_row, text='🗑️ 清空', font=('Arial', 9), fg='#9CA3AF', command=clear_current_annotations).pack(side=tk.LEFT, padx=2)

        ttk.Label(anno_frame, text='点选常见错误批语 ➔ 点击试卷对应位置盖印：', font=('Arial', 9), foreground='#4B5563').pack(anchor='w', pady=(4, 2))

        # 常见错误批语印章网格
        stamps_grid = ttk.Frame(anno_frame)
        stamps_grid.pack(fill=tk.X, pady=(2, 4))

        common_stamps = [
            '没有原始公式', '没有单位',
            '没有下标',     '公式错误',
            '没有文字说明', '计算错误',
            '步骤缺失',     '数值代入错误',
            '符号不规范',   '单位换算错误',
            '有效数字不符', '结果未化简',
        ]

        stamp_buttons = {}

        def update_stamp_button_styles():
            for st_text, btn in stamp_buttons.items():
                if anno_state['tool'] == 'stamp' and anno_state['stamp_text'] == st_text:
                    btn.configure(relief=tk.SUNKEN, bg='#FEE2E2', fg='#B91C1C', activebackground='#FEE2E2')
                else:
                    btn.configure(relief=tk.RAISED, bg='#FFF1F2', fg='#BE123C', activebackground='#FDE8E8')

        for idx, st_text in enumerate(common_stamps):
            r = idx // 2
            c = idx % 2
            btn = tk.Button(
                stamps_grid,
                text=st_text,
                font=('Arial', 10, 'bold'),
                bg='#FFF1F2',
                fg='#BE123C',
                activebackground='#FDE8E8',
                command=lambda t=st_text: set_tool('stamp', stamp_text=t),
            )
            btn.grid(row=r, column=c, padx=3, pady=2, sticky='ew')
            stamps_grid.columnconfigure(c, weight=1)
            stamp_buttons[st_text] = btn

        # =========================================================================
        # 3. 排在最下面的是：提交按钮（“当我点完之后，再点提交，才跳到下一题”）
        # =========================================================================
        submit_box = ttk.Frame(score_panel)
        submit_box.pack(fill=tk.X, pady=(10, 10))

        def save_current(show_status=True):
            question = current_question()
            entry = current_entry()
            entry_scores = current_entry_scores(entry)
            changed = 0
            for part_id, (var, item) in score_vars.items():
                text = var.get().strip()
                if text == '':
                    if part_id in entry_scores:
                        entry_scores.pop(part_id, None)
                        changed += 1
                    continue
                try:
                    score = float(text)
                except Exception:
                    raise ValueError(f'第{question.get("question_no")}题({item.get("sub_no")}) 的分数不是数字：{text}')
                max_score = float(item.get('score') or 0)
                if score < 0 or score > max_score:
                    raise ValueError(f'第{question.get("question_no")}题({item.get("sub_no")}) 应在 0 到 {max_score:g} 分之间。')
                part_id = self.calculation_score_part_id(question.get('question_no'), item.get('sub_no'))
                entry_scores[part_id] = {
                    'score': score,
                    'max_score': max_score,
                    'manual_graded': True,
                    'auto_graded': False,
                    'label': f"{question.get('question_no')}题({item.get('sub_no')})",
                    'kind': 'calculation',
                    'score_category': 'calculation',
                    'student_name': entry.get('student_name', ''),
                    'score_id': entry.get('score_id', ''),
                    'file': entry.get('file', ''),
                    'updated_at': datetime.now().isoformat(timespec='seconds'),
                }
                changed += 1
            self.save_subjective_score_payload(payload)
            self.apply_subjective_scores_to_entries(payload)
            self.detail_text.delete(1.0, tk.END)
            for result_entry in self.summary_data:
                self.display_single_result(result_entry)
            self.update_summary_display()
            self.update_analysis_display()
            self.save_results_to_database()
            state['dirty'] = False
            if show_status:
                tool_hint_var.set(f'已保存第 {question.get("question_no")} 题：{entry.get("score_id") or ""} {entry.get("student_name") or ""}')
                self.status_var.set('计算题分数及批注已保存')
            return changed

        def save_safely(show_status=True):
            try:
                return save_current(show_status=show_status)
            except Exception as exc:
                messagebox.showerror('保存失败', str(exc), parent=win)
                return None

        # 核心提交函数：点完提交，才跳到下一题！
        def submit_and_next():
            if save_safely() is None:
                return
            if state['entry_index'] < len(entries) - 1:
                state['entry_index'] += 1
                refresh_view()
                return
            if state['question_index'] < len(questions) - 1:
                finished_qno = current_question().get('question_no')
                state['question_index'] += 1
                state['entry_index'] = 0
                refresh_view()
                messagebox.showinfo('进入下一大题', f'第 {finished_qno} 题已批完全班。\n现在开始批改第 {current_question().get("question_no")} 题。', parent=win)
                return
            messagebox.showinfo('完成', '全部计算题批改和批注已提交完成！', parent=win)

        def previous_entry():
            if state['dirty'] and save_safely(show_status=False) is None:
                return
            if state['entry_index'] > 0:
                state['entry_index'] -= 1
                refresh_view()
            elif state['question_index'] > 0:
                state['question_index'] -= 1
                state['entry_index'] = len(entries) - 1
                refresh_view()

        def next_question():
            if state['dirty'] and save_safely(show_status=False) is None:
                return
            if state['question_index'] < len(questions) - 1:
                state['question_index'] += 1
                state['entry_index'] = 0
                refresh_view()

        def previous_question():
            if state['dirty'] and save_safely(show_status=False) is None:
                return
            if state['question_index'] > 0:
                state['question_index'] -= 1
                state['entry_index'] = 0
                refresh_view()

        def close_window():
            if state['dirty']:
                if save_safely(show_status=False) is None:
                    return
            win.destroy()

        # 大号提交按钮（亮蓝色加粗，高度46px）
        submit_btn = tk.Button(
            submit_box,
            text='💾 提交并跳到下一题 (Enter) ➡️',
            font=('Arial', 12, 'bold'),
            bg='#2563EB',
            fg='white',
            activebackground='#1D4ED8',
            activeforeground='white',
            height=2,
            relief=tk.RAISED,
            command=submit_and_next,
        )
        submit_btn.pack(fill=tk.X, pady=(2, 6))

        nav_row = ttk.Frame(submit_box)
        nav_row.pack(fill=tk.X, pady=2)
        tk.Button(nav_row, text='⬅️ 上一题 / 上一份', font=('Arial', 10), command=previous_entry).pack(side=tk.LEFT, fill=tk.X, expand=True, padx=2)
        tk.Button(nav_row, text='仅保存当前', font=('Arial', 10), command=lambda: save_safely(True)).pack(side=tk.LEFT, fill=tk.X, expand=True, padx=2)

        ttk.Separator(submit_box).pack(fill=tk.X, pady=6)
        q_nav_row = ttk.Frame(submit_box)
        q_nav_row.pack(fill=tk.X)
        ttk.Button(q_nav_row, text='⏮️ 上一大题', command=previous_question).pack(side=tk.LEFT, fill=tk.X, expand=True, padx=2)
        ttk.Button(q_nav_row, text='⏭️ 下一大题', command=next_question).pack(side=tk.LEFT, fill=tk.X, expand=True, padx=2)

        ttk.Separator(submit_box).pack(fill=tk.X, pady=6)
        ttk.Button(submit_box, text='保存并关闭窗口', command=close_window).pack(fill=tk.X, pady=2)

        # ----------------- 画布绘制与批注渲染 -----------------
        def render_current_image():
            image = state.get('current_image_obj')
            if not image:
                return
            scale = max(0.1, min(5.0, float(state.get('scale') or 1.0)))
            state['scale'] = scale
            display_size = (max(1, int(image.width * scale)), max(1, int(image.height * scale)))
            display = image.resize(display_size, Image.LANCZOS)
            photo = ImageTk.PhotoImage(display)
            state['photo'] = photo
            image_canvas.image = photo  # 保持引用，彻底防止GC导致白屏
            image_canvas.delete('paper_img')
            image_canvas.create_image(0, 0, image=photo, anchor='nw', tags='paper_img')
            image_canvas.tag_lower('paper_img')
            image_canvas.configure(scrollregion=(0, 0, display_size[0], display_size[1]))
            zoom_var.set(f"{int(round(scale * 100))}%")
            redraw_annotations()

        def zoom_in():
            if state.get('current_image_obj'):
                state['scale'] = min(5.0, state['scale'] * 1.25)
                render_current_image()

        def zoom_out():
            if state.get('current_image_obj'):
                state['scale'] = max(0.15, state['scale'] * 0.8)
                render_current_image()

        def zoom_fit_width():
            image = state.get('current_image_obj')
            if not image:
                return
            cw = image_canvas.winfo_width()
            if cw < 100:
                cw = 1000
            state['scale'] = (cw - 20) / max(1, image.width)
            render_current_image()

        def zoom_original():
            if state.get('current_image_obj'):
                state['scale'] = 1.0
                render_current_image()

        def load_back_image():
            image_canvas.delete('all')
            state['canvas_items'].clear()
            entry = current_entry()
            back_path = infer_back_path(entry)
            if not back_path:
                raw_front = (entry.get('side_files') or {}).get('front') or entry.get('input_path') or entry.get('file')
                if raw_front:
                    fp = Path(raw_front)
                    if not fp.is_absolute() and getattr(self, 'selected_folder_path', ''):
                        fp = Path(self.selected_folder_path) / fp
                    if fp.exists():
                        back_path = fp

            if not back_path or not Path(back_path).exists():
                image_canvas.create_text(30, 30, text='没有找到该学生的试卷图片', anchor='nw', fill='red', font=('Arial', 18, 'bold'))
                state['photo'] = None
                state['current_image_obj'] = None
                return
            try:
                image = None
                if self.is_direct_paper_choice_template():
                    try:
                        image = self.direct_calculation_crop_for_entry(entry, back_path)
                    except Exception:
                        image = None
                if image is None:
                    image = Image.open(back_path).convert('RGB')
                state['current_image_obj'] = image

                target_width = 1500
                scale = target_width / max(1, image.width)
                if scale <= 0:
                    scale = 1.0
                state['scale'] = scale

                render_current_image()
                image_canvas.xview_moveto(0)
                image_canvas.yview_moveto(0)
            except Exception as exc:
                image_canvas.create_text(
                    30, 30,
                    text=f'计算题图像加载失败：{exc}',
                    anchor='nw', fill='red', font=('Arial', 14, 'bold'),
                )
                state['photo'] = None
                state['current_image_obj'] = None

        def redraw_annotations():
            for item_id in state['canvas_items']:
                try:
                    image_canvas.delete(item_id)
                except Exception:
                    pass
            state['canvas_items'].clear()

            img = state['current_image_obj']
            scale = state['scale']
            if not img:
                return

            w = img.width * scale
            h = img.height * scale

            qno_key = str(current_question().get('question_no'))
            entry_key = self.subjective_entry_key(current_entry())
            annos = all_annotations.get(entry_key, {}).get(qno_key, [])

            for item in annos:
                if not isinstance(item, dict):
                    continue
                itype = item.get('type')
                if itype == 'line':
                    pts = item.get('points') or []
                    if len(pts) >= 2:
                        flat_pts = []
                        for u, v in pts:
                            flat_pts.extend([u * w, v * h])
                        cid = image_canvas.create_line(flat_pts, fill=item.get('color', '#DC2626'), width=int(item.get('width', 3)), capstyle=tk.ROUND, joinstyle=tk.ROUND)
                        state['canvas_items'].append(cid)
                elif itype == 'check':
                    cx = item.get('u', 0) * w
                    cy = item.get('v', 0) * h
                    sz = item.get('size', 24)
                    cid1 = image_canvas.create_line(cx - sz * 0.45, cy - sz * 0.05, cx - sz * 0.1, cy + sz * 0.4, fill='#16A34A', width=3, capstyle=tk.ROUND)
                    cid2 = image_canvas.create_line(cx - sz * 0.1, cy + sz * 0.4, cx + sz * 0.55, cy - sz * 0.45, fill='#16A34A', width=3, capstyle=tk.ROUND)
                    state['canvas_items'].extend([cid1, cid2])
                elif itype == 'cross':
                    cx = item.get('u', 0) * w
                    cy = item.get('v', 0) * h
                    sz = item.get('size', 22)
                    cid1 = image_canvas.create_line(cx - sz * 0.4, cy - sz * 0.4, cx + sz * 0.4, cy + sz * 0.4, fill='#DC2626', width=3, capstyle=tk.ROUND)
                    cid2 = image_canvas.create_line(cx - sz * 0.4, cy + sz * 0.4, cx + sz * 0.4, cy - sz * 0.4, fill='#DC2626', width=3, capstyle=tk.ROUND)
                    state['canvas_items'].extend([cid1, cid2])
                elif itype == 'stamp':
                    cx = item.get('u', 0) * w
                    cy = item.get('v', 0) * h
                    text = str(item.get('text') or '').strip()
                    font_spec = ('Arial', 10, 'bold')
                    tid = image_canvas.create_text(cx, cy, text=f" {text} ", fill='#DC2626', font=font_spec, anchor='c')
                    bbox = image_canvas.bbox(tid)
                    if bbox:
                        bx1, by1, bx2, by2 = bbox
                        rid = image_canvas.create_rectangle(bx1 - 3, by1 - 2, bx2 + 3, by2 + 2, fill='#FEF2F2', outline='#F87171', width=1)
                        image_canvas.tag_lower(rid, tid)
                        state['canvas_items'].extend([rid, tid])
                    else:
                        state['canvas_items'].append(tid)

        def add_annotation(item):
            qno_key = str(current_question().get('question_no'))
            entry_key = self.subjective_entry_key(current_entry())
            q_annos = all_annotations.setdefault(entry_key, {}).setdefault(qno_key, [])
            q_annos.append(item)
            state['dirty'] = True
            redraw_annotations()

        def on_canvas_b1_press(event):
            img = state['current_image_obj']
            scale = state['scale']
            if not img or scale <= 0:
                return
            cx = image_canvas.canvasx(event.x)
            cy = image_canvas.canvasy(event.y)
            w = img.width * scale
            h = img.height * scale
            u = max(0.0, min(1.0, cx / w))
            v = max(0.0, min(1.0, cy / h))

            tool = anno_state['tool']
            if tool == 'view':
                image_canvas.scan_mark(event.x, event.y)
            elif tool == 'line':
                anno_state['drawing'] = True
                anno_state['temp_line_pts'] = [(u, v)]
                if anno_state['temp_line_id']:
                    image_canvas.delete(anno_state['temp_line_id'])
                anno_state['temp_line_id'] = image_canvas.create_line(cx, cy, cx, cy, fill='#DC2626', width=3, capstyle=tk.ROUND)
            elif tool == 'check':
                add_annotation({'type': 'check', 'u': u, 'v': v, 'color': '#16A34A', 'size': 24})
            elif tool == 'cross':
                add_annotation({'type': 'cross', 'u': u, 'v': v, 'color': '#DC2626', 'size': 22})
            elif tool == 'stamp':
                if anno_state['stamp_text']:
                    add_annotation({'type': 'stamp', 'u': u, 'v': v, 'text': anno_state['stamp_text'], 'color': '#DC2626'})

        def on_canvas_b1_motion(event):
            img = state['current_image_obj']
            scale = state['scale']
            if not img or scale <= 0:
                return
            tool = anno_state['tool']
            if tool == 'view':
                image_canvas.scan_dragto(event.x, event.y, gain=1)
            elif tool == 'line' and anno_state['drawing']:
                cx = image_canvas.canvasx(event.x)
                cy = image_canvas.canvasy(event.y)
                w = img.width * scale
                h = img.height * scale
                u = max(0.0, min(1.0, cx / w))
                v = max(0.0, min(1.0, cy / h))
                anno_state['temp_line_pts'].append((u, v))
                flat = []
                for tu, tv in anno_state['temp_line_pts']:
                    flat.extend([tu * w, tv * h])
                if len(flat) >= 4:
                    image_canvas.coords(anno_state['temp_line_id'], *flat)

        def on_canvas_b1_release(event):
            if anno_state['tool'] == 'line' and anno_state['drawing']:
                anno_state['drawing'] = False
                if anno_state['temp_line_id']:
                    image_canvas.delete(anno_state['temp_line_id'])
                    anno_state['temp_line_id'] = None
                pts = anno_state['temp_line_pts']
                if len(pts) >= 2:
                    add_annotation({'type': 'line', 'points': pts, 'color': '#DC2626', 'width': 3})
                anno_state['temp_line_pts'] = []

        image_canvas.bind('<Button-1>', on_canvas_b1_press)
        image_canvas.bind('<B1-Motion>', on_canvas_b1_motion)
        image_canvas.bind('<ButtonRelease-1>', on_canvas_b1_release)

        # ----------------- 视图刷新 -----------------
        def refresh_view():
            question = current_question()
            entry = current_entry()
            qno = question.get('question_no')
            max_total = sum(float(s.get('score') or 0) for s in (question.get('sub_scores') or []))
            title_var.set(f'正在批改：第 {qno} 题 (整大题满分 {max_total:g} 分)')
            progress_var.set(f'学生 {state["entry_index"] + 1}/{len(entries)} 份 | 计算大题 {state["question_index"] + 1}/{len(questions)}')
            q_combo_box.current(state['question_index'])
            s_combo_box.current(state['entry_index'])

            student_var.set(f"{entry.get('score_id') or '未识别学号'}  {entry.get('student_name') or '未匹配'}")
            file_var.set(f"正面：{entry.get('file') or Path(str(entry.get('input_path') or '')).name}")
            back_path = infer_back_path(entry)
            back_var.set(f"背面：{Path(back_path).name if back_path else '未找到'}")

            load_score_widgets()
            load_back_image()
            r_canvas.yview_moveto(0)
            state['dirty'] = False

        def on_r_mousewheel(event):
            delta = -1 if event.delta > 0 else 1
            r_canvas.yview_scroll(delta * 2, 'units')

        r_canvas.bind('<MouseWheel>', on_r_mousewheel)
        score_panel.bind('<MouseWheel>', on_r_mousewheel)

        def on_image_mousewheel(event):
            if event.state & 0x0004:  # Ctrl pressed -> Zoom!
                if event.delta > 0:
                    zoom_in()
                else:
                    zoom_out()
                return 'break'
            delta = -1 if event.delta > 0 else 1
            image_canvas.yview_scroll(delta * 3, 'units')

        image_canvas.bind('<MouseWheel>', on_image_mousewheel)
        win.bind('<Control-plus>', lambda _e: zoom_in())
        win.bind('<Control-equal>', lambda _e: zoom_in())
        win.bind('<Control-minus>', lambda _e: zoom_out())
        win.bind('<plus>', lambda _e: zoom_in())
        win.bind('<equal>', lambda _e: zoom_in())
        win.bind('<minus>', lambda _e: zoom_out())
        win.bind('<Control-s>', lambda _e: save_safely(True))
        win.bind('<Control-z>', lambda _e: undo_last_annotation())
        win.bind('<Return>', lambda _e: submit_and_next())
        win.protocol('WM_DELETE_WINDOW', close_window)

        refresh_view()

    def detect_direct_choice_boxes_from_blank(self, image_path, include_top=False):
        image_path = Path(image_path)
        data = np.fromfile(str(image_path), dtype=np.uint8)
        gray = cv2.imdecode(data, cv2.IMREAD_GRAYSCALE)
        if gray is None:
            raise RuntimeError('无法读取模板图片。')
        height, width = gray.shape[:2]
        _thr, binary = cv2.threshold(gray, 120, 255, cv2.THRESH_BINARY_INV)
        num_labels, labels, stats, centroids = cv2.connectedComponentsWithStats(binary, 8)

        def finalize_choice_boxes(items):
            items = self.sort_direct_choice_boxes_reading_order(items)
            for index, item in enumerate(items, 1):
                item['index'] = index
                item['template_rect'] = {
                    'x': float(item['x']), 'y': float(item['y']),
                    'w': float(item['w']), 'h': float(item['h']),
                }
                item['template_pixel'] = {
                    'x': round(float(item['cx']), 2),
                    'y': round(float(item['cy']), 2),
                }
            return items

        def merge_nearby(items, x_gap=18, y_gap=18):
            items = sorted(items, key=lambda item: (-item.get('match_score', 0), item['cy'], item['cx']))
            merged_items = []
            for item in items:
                if any(abs(item['cx'] - old['cx']) < x_gap and abs(item['cy'] - old['cy']) < y_gap for old in merged_items):
                    continue
                merged_items.append(item)
            return merged_items

        strict = []
        min_y = height * (0.03 if include_top else 0.18)
        for idx in range(1, num_labels):
            x, y, w, h, area = stats[idx]
            if y < min_y or y > height - 80:
                continue
            # Light scans can leave an otherwise complete option box a few pixels
            # below the old area floor. Hollow/edge checks below still reject text.
            if not (22 <= w <= 38 and 22 <= h <= 38 and 210 <= area <= 560):
                continue
            ratio = float(w) / float(h or 1)
            if not (0.78 <= ratio <= 1.28):
                continue
            patch = (binary[max(0, y - 1): min(height, y + h + 1), max(0, x - 1): min(width, x + w + 1)] // 255).astype(np.uint8)
            ph, pw = patch.shape[:2]
            if ph <= 14 or pw <= 14:
                continue
            edge = np.concatenate([patch[:4, :].ravel(), patch[-4:, :].ravel(), patch[:, :4].ravel(), patch[:, -4:].ravel()])
            inner = patch[7:max(8, ph - 7), 7:max(8, pw - 7)]
            if float(edge.mean()) < 0.45 or float(inner.mean()) > 0.08:
                continue
            strict.append({
                'x': int(x), 'y': int(y), 'w': int(w), 'h': int(h),
                'cx': float(centroids[idx][0]), 'cy': float(centroids[idx][1]),
                'match_score': 1.0,
            })

        square_boxes = []
        if strict:
            # A back page may contain only one cross-page option. Expanding from a
            # single sample can match chart grids, so keep that confirmed box only.
            if len(strict) == 1:
                square_boxes = strict
                return finalize_choice_boxes(square_boxes)
            ref = sorted(strict, key=lambda item: (item['cy'], item['cx']))[0]
            pad = 3
            rx1 = max(0, ref['x'] - pad)
            ry1 = max(0, ref['y'] - pad)
            rx2 = min(width, ref['x'] + ref['w'] + pad)
            ry2 = min(height, ref['y'] + ref['h'] + pad)
            template = binary[ry1:ry2, rx1:rx2]
            matches = []
            if template.size:
                result = cv2.matchTemplate(binary, template, cv2.TM_CCOEFF_NORMED)
                for yy, xx in zip(*np.where(result >= 0.57)):
                    if yy < min_y or yy > height - 80:
                        continue
                    matches.append({
                        'x': int(xx), 'y': int(yy),
                        'w': int(template.shape[1]), 'h': int(template.shape[0]),
                        'cx': float(xx + template.shape[1] / 2),
                        'cy': float(yy + template.shape[0] / 2),
                        'match_score': round(float(result[yy, xx]), 3),
                        'shape': 'square',
                    })
            # Use the confirmed square as a template and keep template matches only.
            # The strict contour pass is good for finding a sample, but by itself it can
            # mistake printed letters such as "D" for square boxes.
            square_boxes = merge_nearby(matches if matches else strict)

        if square_boxes:
            return finalize_choice_boxes(square_boxes)
        raise RuntimeError('没有自动找到选择题小框。请确认空白模板里有清晰的“□A/□B/□C/□D”。')

    def direct_red_template_mask(self, bgr):
        """Return only the red ink from a colour structure template."""
        hsv = cv2.cvtColor(bgr, cv2.COLOR_BGR2HSV)
        # Scanners can shift printed red toward orange or magenta. Keep both
        # ends of the HSV hue range, while requiring enough colour saturation.
        low_red = cv2.inRange(hsv, np.array([0, 55, 35]), np.array([22, 255, 255]))
        high_red = cv2.inRange(hsv, np.array([158, 55, 35]), np.array([180, 255, 255]))
        mask = cv2.bitwise_or(low_red, high_red)
        # Black printing in a JPEG scan can carry a small warm tint. Hue alone
        # would then mistake dark black lines for red. Real red guide ink has a
        # clear red-channel lead over both blue and green channels.
        blue, green, red = cv2.split(bgr)
        red_lead = (red.astype(np.int16) - np.maximum(blue, green).astype(np.int16)) >= 25
        # A thick black illustration line can become slightly warm after a
        # scan/JPEG pass. It remains dark, unlike printed red guide ink.
        # Requiring a modest brightness floor removes those false red lines
        # without affecting ordinary red answer underlines.
        bright_red = hsv[:, :, 2] >= 160
        mask[~(red_lead & bright_red)] = 0
        return cv2.morphologyEx(mask, cv2.MORPH_CLOSE, np.ones((3, 3), np.uint8), iterations=1)

    def load_direct_red_template_mask(self, image_path):
        image_path = Path(image_path)
        data = np.fromfile(str(image_path), dtype=np.uint8)
        bgr = cv2.imdecode(data, cv2.IMREAD_COLOR)
        if bgr is None:
            raise RuntimeError('无法读取红色模板图片。')
        return bgr, self.direct_red_template_mask(bgr)

    def detect_direct_choice_boxes_from_red_template(self, image_path, include_top=False):
        """Detect option squares from red ink only, ignoring printed black text."""
        _bgr, red_mask = self.load_direct_red_template_mask(image_path)
        height, width = red_mask.shape[:2]
        num_labels, _labels, stats, centroids = cv2.connectedComponentsWithStats(red_mask, 8)
        # Red ink already separates option boxes from the black student-ID and
        # name areas, so do not discard questions printed high on the front page.
        min_y = height * (0.03 if include_top else 0.10)
        boxes = []
        for idx in range(1, num_labels):
            x, y, w, h, area = stats[idx]
            if y < min_y or y > height - 80:
                continue
            if not (14 <= w <= 76 and 14 <= h <= 76 and area >= 45):
                continue
            ratio = float(w) / float(h or 1)
            if not (0.70 <= ratio <= 1.35):
                continue
            patch = (red_mask[max(0, y - 1):min(height, y + h + 1), max(0, x - 1):min(width, x + w + 1)] > 0).astype(np.uint8)
            ph, pw = patch.shape[:2]
            if ph < 12 or pw < 12:
                continue
            edge_width = max(2, min(4, min(ph, pw) // 4))
            edge = np.concatenate([
                patch[:edge_width, :].ravel(), patch[-edge_width:, :].ravel(),
                patch[:, :edge_width].ravel(), patch[:, -edge_width:].ravel(),
            ])
            inner_pad = max(4, min(ph, pw) // 4)
            inner = patch[inner_pad:max(inner_pad + 1, ph - inner_pad), inner_pad:max(inner_pad + 1, pw - inner_pad)]
            if float(edge.mean()) < 0.22 or (inner.size and float(inner.mean()) > 0.20):
                continue
            boxes.append({
                'x': int(x), 'y': int(y), 'w': int(w), 'h': int(h),
                'cx': float(centroids[idx][0]), 'cy': float(centroids[idx][1]),
                'match_score': 1.0,
            })

        boxes = self.sort_direct_choice_boxes_reading_order(boxes)
        for index, item in enumerate(boxes, 1):
            item['index'] = index
            item['template_rect'] = {'x': float(item['x']), 'y': float(item['y']), 'w': float(item['w']), 'h': float(item['h'])}
            item['template_pixel'] = {'x': round(float(item['cx']), 2), 'y': round(float(item['cy']), 2)}
        if not boxes:
            raise RuntimeError('没有在红色模板中找到选择题小框。请确认小框确实使用了红色打印。')
        return boxes

    def sort_direct_choice_boxes_reading_order(self, boxes, row_tolerance=None):
        if not boxes:
            return []
        heights = [float(item.get('h') or item.get('template_rect', {}).get('h') or 30) for item in boxes]
        median_height = float(np.median(heights)) if heights else 30.0
        tolerance = float(row_tolerance or max(36.0, median_height * 1.35))
        rows = []
        for item in sorted(boxes, key=lambda payload: (float(payload.get('cy', payload.get('template_pixel', {}).get('y', 0))), float(payload.get('cx', payload.get('template_pixel', {}).get('x', 0))))):
            cy = float(item.get('cy', item.get('template_pixel', {}).get('y', 0)))
            placed = False
            for row in rows:
                if abs(row['cy'] - cy) <= tolerance:
                    row['items'].append(item)
                    row['cy'] = sum(float(v.get('cy', v.get('template_pixel', {}).get('y', 0))) for v in row['items']) / len(row['items'])
                    placed = True
                    break
            if not placed:
                rows.append({'cy': cy, 'items': [item]})
        ordered = []
        for row in sorted(rows, key=lambda payload: payload['cy']):
            ordered.extend(sorted(row['items'], key=lambda payload: float(payload.get('cx', payload.get('template_pixel', {}).get('x', 0)))))
        return ordered

    def make_direct_choice_boxes_preview(self, image_path, boxes, used_indices=None, keep_indices=None):
        image = Image.open(image_path).convert('RGB')
        draw = ImageDraw.Draw(image)
        used_indices = {int(value) for value in used_indices or []}
        keep_indices = {int(value) for value in keep_indices} if keep_indices is not None else {int(box.get('index', 0)) for box in boxes}
        for box in boxes:
            rect = box['template_rect']
            x = rect['x']; y = rect['y']; w = rect['w']; h = rect['h']
            idx = int(box['index'])
            is_kept = idx in keep_indices
            is_used = is_kept and ((not used_indices) or idx in used_indices)
            color = 'red' if is_used else '#ff9800' if is_kept else '#888888'
            width = 4 if is_used else 3 if is_kept else 2
            draw.rectangle((x, y, x + w, y + h), outline=color, width=width)
            if not is_kept:
                draw.line((x, y, x + w, y + h), fill=color, width=2)
                draw.line((x + w, y, x, y + h), fill=color, width=2)
            draw.text((x, max(0, y - 44)), str(box['index']) if is_kept else f"x{box['index']}", fill=color)
        max_w, max_h = 760, 900
        scale = min(max_w / image.width, max_h / image.height, 1.0)
        if scale < 1.0:
            image = image.resize((int(image.width * scale), int(image.height * scale)), Image.Resampling.LANCZOS)
        return image

    def make_direct_choice_structure_preview(self, image_path, questions, max_w=620, max_h=760):
        image = Image.open(image_path).convert('RGB')
        draw = ImageDraw.Draw(image)
        try:
            font = ImageFont.truetype('arialbd.ttf', 34)
        except Exception:
            try:
                font = ImageFont.truetype('msyhbd.ttc', 34)
            except Exception:
                font = ImageFont.load_default()
        for question in questions or []:
            qno = question.get('question_no_in_zone', '')
            for opt, option_data in sorted((question.get('options') or {}).items()):
                rect = option_data.get('template_rect') or {}
                try:
                    x = float(rect.get('x', 0))
                    y = float(rect.get('y', 0))
                    w = float(rect.get('w', 0))
                    h = float(rect.get('h', 0))
                except Exception:
                    continue
                label = f'{qno}{opt}'
                draw.rectangle((x, y, x + w, y + h), outline=(220, 0, 0), width=5)
                text_x = x + w + 8
                text_y = max(0, y - 9)
                bbox = draw.textbbox((text_x, text_y), label, font=font)
                draw.rectangle((bbox[0] - 3, bbox[1] - 2, bbox[2] + 3, bbox[3] + 2), fill=(255, 245, 120))
                draw.text((text_x, text_y), label, fill=(220, 0, 0), font=font)
        scale = min(max_w / image.width, max_h / image.height, 1.0)
        if scale < 1.0:
            image = image.resize((int(image.width * scale), int(image.height * scale)), Image.Resampling.LANCZOS)
        return image

    def confirm_direct_choice_structure_preview(self, side_specs, summary_text):
        win = tk.Toplevel(self.root)
        win.title('确认选择题结构预览')
        win.geometry('1320x860')
        win.minsize(1080, 720)
        win.transient(self.root)
        result = {'ok': False}

        def confirm():
            result['ok'] = True
            win.destroy()

        ttk.Label(
            win,
            text='请检查题号和选项是否对应正确，确认后才会保存结构。',
            font=('Arial', 13, 'bold'),
        ).pack(anchor='w', padx=14, pady=(12, 4))
        ttk.Label(win, text=summary_text, wraplength=1200).pack(anchor='w', padx=14, pady=(0, 8))

        top_buttons = ttk.Frame(win)
        top_buttons.pack(fill=tk.X, padx=14, pady=(0, 6))
        ttk.Button(top_buttons, text='确认保存', command=confirm).pack(side=tk.LEFT, padx=4)
        ttk.Button(top_buttons, text='返回修改/取消', command=win.destroy).pack(side=tk.LEFT, padx=4)

        body = ttk.Frame(win)
        body.pack(fill=tk.BOTH, expand=True, padx=12, pady=6)
        photos = []
        for side_label, image_path, questions in side_specs:
            frame = ttk.LabelFrame(body, text=side_label)
            frame.pack(side=tk.LEFT, fill=tk.BOTH, expand=True, padx=6)
            preview = self.make_direct_choice_structure_preview(image_path, questions)
            photo = ImageTk.PhotoImage(preview)
            photos.append(photo)
            label = ttk.Label(frame, image=photo, anchor='center')
            label.image = photo
            label.pack(fill=tk.BOTH, expand=True, padx=6, pady=6)
            q_text = self.direct_choice_question_option_summary(questions)
            ttk.Label(frame, text=q_text, wraplength=560).pack(anchor='w', padx=8, pady=(0, 6))
        win._preview_photos = photos

        buttons = ttk.Frame(win)
        buttons.pack(fill=tk.X, padx=14, pady=(4, 12))
        ttk.Button(buttons, text='确认保存', command=confirm).pack(side=tk.LEFT, padx=4)
        ttk.Button(buttons, text='返回修改/取消', command=win.destroy).pack(side=tk.LEFT, padx=4)
        win.protocol('WM_DELETE_WINDOW', win.destroy)
        win.bind('<Return>', lambda _event: confirm())
        win.bind('<Control-s>', lambda _event: confirm())
        win.bind('<Control-S>', lambda _event: confirm())
        win.grab_set()
        self.root.wait_window(win)
        return result['ok']

    def direct_choice_question_option_summary(self, questions):
        parts = []
        for question in questions or []:
            qno = question.get('question_no_in_zone', '')
            opts = ''.join(sorted((question.get('options') or {}).keys()))
            parts.append(f'{qno}:{opts}')
        return '；'.join(parts) if parts else '无题位'

    def merge_direct_subjective_line_segments(self, items):
        items = sorted(items or [], key=lambda item: (float(item.get('cy', 0)), float(item.get('x', 0))))
        merged = []
        for item in items:
            placed = False
            for old in merged:
                same_row = abs(float(item.get('cy', 0)) - float(old.get('cy', 0))) <= max(
                    5.0,
                    min(float(item.get('h', 0)), float(old.get('h', 0))) + 4.0,
                )
                gap = float(item.get('x', 0)) - (float(old.get('x', 0)) + float(old.get('w', 0)))
                overlap = min(
                    float(item.get('x', 0)) + float(item.get('w', 0)),
                    float(old.get('x', 0)) + float(old.get('w', 0)),
                ) - max(float(item.get('x', 0)), float(old.get('x', 0)))
                if same_row and (-12 <= gap <= 28 or overlap >= -8):
                    x1 = min(float(old.get('x', 0)), float(item.get('x', 0)))
                    y1 = min(float(old.get('y', 0)), float(item.get('y', 0)))
                    x2 = max(float(old.get('x', 0)) + float(old.get('w', 0)), float(item.get('x', 0)) + float(item.get('w', 0)))
                    y2 = max(float(old.get('y', 0)) + float(old.get('h', 0)), float(item.get('y', 0)) + float(item.get('h', 0)))
                    old.update({
                        'x': int(round(x1)),
                        'y': int(round(y1)),
                        'w': int(round(x2 - x1)),
                        'h': int(round(y2 - y1)),
                        'cx': round((x1 + x2) / 2, 2),
                        'cy': round((y1 + y2) / 2, 2),
                        'area': int(old.get('area', 0)) + int(item.get('area', 0)),
                    })
                    placed = True
                    break
            if not placed:
                merged.append(dict(item))
        return merged

    def sort_direct_subjective_lines_reading_order(self, lines, row_tolerance=None):
        if not lines:
            return []
        heights = [
            float((item.get('template_rect') or {}).get('h') or item.get('h') or 4)
            for item in lines
        ]
        median_height = float(np.median(heights)) if heights else 4.0
        tolerance = float(row_tolerance or max(22.0, min(32.0, median_height * 6.0)))

        def center_y(item):
            rect = item.get('template_rect') or {}
            if rect and 'y' in rect and 'h' in rect:
                return float(rect.get('y', 0)) + float(rect.get('h', 0)) / 2.0
            if 'cy' in item:
                return float(item.get('cy', 0))
            return float(item.get('y', 0)) + float(item.get('h', 0)) / 2.0

        def left_x(item):
            rect = item.get('template_rect') or {}
            if rect and 'x' in rect:
                return float(rect.get('x', 0))
            return float(item.get('x', 0))

        def y_span(item):
            rect = item.get('template_rect') or {}
            if rect and 'y' in rect and 'h' in rect:
                y = float(rect.get('y', 0))
                h = float(rect.get('h', 4))
            else:
                y = float(item.get('y', 0))
                h = float(item.get('h', 4))
            return y, y + h

        def in_same_row(item1, item2):
            y1_a, y1_b = y_span(item1)
            y2_a, y2_b = y_span(item2)
            overlap = max(0.0, min(y1_b, y2_b) - max(y1_a, y2_a))
            min_h = max(1.0, min(y1_b - y1_a, y2_b - y2_a))
            # Substantial vertical overlap (e.g. parallel side-by-side drawing boxes)
            if overlap / min_h >= 0.35:
                return True
            return abs(center_y(item1) - center_y(item2)) <= tolerance

        rows = []
        for item in sorted(lines, key=lambda payload: (center_y(payload), left_x(payload))):
            cy = center_y(item)
            placed = False
            for row in rows:
                if any(in_same_row(item, existing) for existing in row['items']):
                    row['items'].append(item)
                    row['cy'] = sum(center_y(v) for v in row['items']) / len(row['items'])
                    placed = True
                    break
            if not placed:
                rows.append({'cy': cy, 'items': [item]})

        ordered = []
        for row in sorted(rows, key=lambda payload: payload['cy']):
            ordered.extend(sorted(row['items'], key=left_x))
        return ordered

    def direct_subjective_line_is_name_area(self, item, width, height, side='front'):
        if str(side or '').lower() == 'back':
            return False
        x = float(item.get('x', 0))
        y = float(item.get('y', 0))
        w = float(item.get('w', 0))
        cx = x + w / 2.0
        # The front page has a handwritten-name underline near the top, to the
        # right of the student-id area. It looks like a fill blank but should not
        # become an OCR scoring blank.
        return (
            y < height * 0.16
            and width * 0.40 <= cx <= width * 0.78
            and 80 <= w <= width * 0.28
        )

    def detect_direct_subjective_lines_from_blank(self, image_path, side='front'):
        image_path = Path(image_path)
        data = np.fromfile(str(image_path), dtype=np.uint8)
        gray = cv2.imdecode(data, cv2.IMREAD_GRAYSCALE)
        if gray is None:
            raise RuntimeError('无法读取模板图片。')
        height, width = gray.shape[:2]
        blur = cv2.GaussianBlur(gray, (3, 3), 0)
        binary = cv2.adaptiveThreshold(
            blur,
            255,
            cv2.ADAPTIVE_THRESH_MEAN_C,
            cv2.THRESH_BINARY_INV,
            41,
            13,
        )
        horizontal_kernel = cv2.getStructuringElement(cv2.MORPH_RECT, (45, 1))
        horizontal = cv2.morphologyEx(binary, cv2.MORPH_OPEN, horizontal_kernel, iterations=1)
        horizontal = cv2.dilate(horizontal, cv2.getStructuringElement(cv2.MORPH_RECT, (5, 1)), iterations=1)

        num_labels, _labels, stats, centroids = cv2.connectedComponentsWithStats(horizontal, 8)
        candidates = []
        for idx in range(1, num_labels):
            x, y, w, h, area = stats[idx]
            if y < 55 or y > height - 70:
                continue
            if self.direct_subjective_line_is_name_area({'x': x, 'y': y, 'w': w, 'h': h}, width, height, side=side):
                continue
            # Some direct-paper blanks start very close to the page margin after
            # printing/scanning. Keep a small edge guard, but do not drop valid
            # left-margin blanks such as a wrapped fill line near question text.
            if x < 4 or x + w > width - 4:
                continue
            if w < 80 or w > width * 0.78:
                continue
            if h > 14 or (float(w) / float(h or 1)) < 12:
                continue
            candidates.append({
                'x': int(x),
                'y': int(y),
                'w': int(w),
                'h': int(h),
                'area': int(area),
                'cx': round(float(centroids[idx][0]), 2),
                'cy': round(float(centroids[idx][1]), 2),
            })

        candidates = self.merge_direct_subjective_line_segments(candidates)
        accepted = []
        suspicious = []
        rejected = []
        for item in candidates:
            x = int(item.get('x', 0))
            y = int(item.get('y', 0))
            w = int(item.get('w', 0))
            h = int(item.get('h', 0))
            top_band = binary[max(0, y - 38):max(0, y - 5), max(0, x + 4):min(width, x + w - 4)]
            top_black_ratio = float((top_band > 0).mean()) if top_band.size else 1.0
            around = binary[max(0, y - 70):min(height, y + 18), max(0, x - 10):min(width, x + w + 10)]
            around_black_ratio = float((around > 0).mean()) if around.size else 1.0
            line_roi = horizontal[max(0, y - 2):min(height, y + h + 2), max(0, x):min(width, x + w)]
            line_density = float((line_roi > 0).mean()) if line_roi.size else 0.0
            item.update({
                'top_black_ratio': round(top_black_ratio, 3),
                'around_black_ratio': round(around_black_ratio, 3),
                'line_density': round(line_density, 3),
                'template_rect': {'x': float(x), 'y': float(y), 'w': float(w), 'h': float(h)},
                'template_pixel': {'x': round(float(item.get('cx', x + w / 2)), 2), 'y': round(float(item.get('cy', y + h / 2)), 2)},
            })
            if top_black_ratio <= 0.075 and around_black_ratio <= 0.23:
                accepted.append(item)
            elif top_black_ratio <= 0.12 and around_black_ratio <= 0.30:
                suspicious.append(item)
            else:
                rejected.append(item)

        ordered = self.sort_direct_subjective_lines_reading_order(accepted + suspicious)
        for index, item in enumerate(ordered, 1):
            item['index'] = index
            item['status'] = 'accepted' if item in accepted else 'suspicious'
        rejected = self.sort_direct_subjective_lines_reading_order(rejected)
        return ordered, rejected

    def direct_blue_template_mask(self, bgr):
        """Return blue guide ink used to mark drawing questions."""
        hsv = cv2.cvtColor(bgr, cv2.COLOR_BGR2HSV)
        # Printed blue guide ink on paper has clear brightness (V >= 95).
        # Requiring a brightness floor prevents dark black/gray text anti-aliasing
        # edge pixels (which can carry slight cool/blue chromatic aberration after scanning)
        # from being mistaken for blue guide ink and connecting to drawing boxes.
        mask = cv2.inRange(hsv, np.array([85, 20, 95]), np.array([140, 255, 255]))
        blue, green, red = cv2.split(bgr)
        blue_lead = (blue.astype(np.int16) - np.maximum(green, red).astype(np.int16)) >= 10
        mask[~blue_lead] = 0
        return cv2.morphologyEx(mask, cv2.MORPH_CLOSE, np.ones((3, 3), np.uint8), iterations=1)

    def detect_direct_drawing_boxes_from_blue_mask(self, blue_mask):
        """Find large hollow blue rectangles that define complete drawing areas."""
        height, width = blue_mask.shape[:2]
        count, _labels, stats, centroids = cv2.connectedComponentsWithStats(blue_mask, 8)
        boxes = []
        for idx in range(1, count):
            x, y, w, h, area = stats[idx]
            ratio = float(w) / float(h or 1)
            if x < 20 or y < 40 or x + w > width - 20 or y + h > height - 35:
                continue
            if w < 80 or h < 60 or w > width * 0.90 or h > height * 0.72:
                continue
            if not (0.18 <= ratio <= 5.5) or float(area) / float(w * h or 1) > 0.35:
                continue
            patch = (blue_mask[max(0, y - 1):min(height, y + h + 1), max(0, x - 1):min(width, x + w + 1)] > 0).astype(np.uint8)
            ph, pw = patch.shape[:2]
            edge_width = max(3, min(7, min(ph, pw) // 9))
            if ph <= edge_width * 2 or pw <= edge_width * 2:
                continue

            # In scanned tests, rectangles may be slightly tilted (0.5~1.5 deg),
            # or connected to small speckles/noise that expand the component bbox.
            # Search within the outer margins (up to 28px or 1/6 dimension) for
            # the best horizontal and vertical border bands rather than assuming
            # the borders strictly occupy rows/cols 0..edge_width.
            max_y_search = max(edge_width, min(28, ph // 6))
            max_x_search = max(edge_width, min(28, pw // 6))

            top_densities = [patch[r : r + edge_width, :].mean() for r in range(max_y_search - edge_width + 1)]
            best_top_idx = int(np.argmax(top_densities))
            best_top = float(top_densities[best_top_idx])

            bottom_densities = [patch[ph - r - edge_width : ph - r, :].mean() for r in range(max_y_search - edge_width + 1)]
            best_bottom_idx = int(np.argmax(bottom_densities))
            best_bottom = float(bottom_densities[best_bottom_idx])

            left_densities = [patch[:, c : c + edge_width].mean() for c in range(max_x_search - edge_width + 1)]
            best_left_idx = int(np.argmax(left_densities))
            best_left = float(left_densities[best_left_idx])

            right_densities = [patch[:, pw - c - edge_width : pw - c].mean() for c in range(max_x_search - edge_width + 1)]
            best_right_idx = int(np.argmax(right_densities))
            best_right = float(right_densities[best_right_idx])

            inner_top = best_top_idx + edge_width
            inner_bottom = ph - best_bottom_idx - edge_width
            inner_left = best_left_idx + edge_width
            inner_right = pw - best_right_idx - edge_width

            if inner_bottom > inner_top and inner_right > inner_left:
                inner = patch[inner_top:inner_bottom, inner_left:inner_right]
                inner_mean = float(inner.mean()) if inner.size else 0.0
            else:
                inner_mean = 1.0

            if min(best_top, best_bottom, best_left, best_right) < 0.16 or inner_mean > 0.12:
                continue

            ref_x = max(0, x - 1 + best_left_idx)
            ref_y = max(0, y - 1 + best_top_idx)
            ref_w = max(1, (pw - best_right_idx) - best_left_idx)
            ref_h = max(1, (ph - best_bottom_idx) - best_top_idx)

            boxes.append({
                'x': int(ref_x), 'y': int(ref_y), 'w': int(ref_w), 'h': int(ref_h),
                'area': int(area),
                'cx': round(float(ref_x + ref_w / 2.0), 2),
                'cy': round(float(ref_y + ref_h / 2.0), 2),
                'kind': 'drawing', 'ink_color': 'blue', 'answer_label': '作图',
                'status': 'accepted',
            })
        return self.sort_direct_subjective_lines_reading_order(boxes)

    def direct_template_guide_ink_mask(self, bgr):
        """Keep only line-like red/blue guide ink when normalising a template."""
        coloured = cv2.bitwise_or(self.direct_red_template_mask(bgr), self.direct_blue_template_mask(bgr))
        count, labels, stats, _centroids = cv2.connectedComponentsWithStats(coloured, 8)
        guide = np.zeros_like(coloured)
        height, width = coloured.shape[:2]
        for idx in range(1, count):
            x, y, w, h, area = stats[idx]
            ratio = float(w) / float(h or 1)
            # Keep the thin answer/drawing lines, but never turn a broad blue
            # or red illustration block into black on the saved scoring image.
            is_line = w >= 45 and h <= 14 and ratio >= 10
            is_box = False
            if 14 <= w <= 76 and 14 <= h <= 76 and 0.70 <= ratio <= 1.35:
                patch = (coloured[max(0, y - 1):min(height, y + h + 1), max(0, x - 1):min(width, x + w + 1)] > 0).astype(np.uint8)
                ph, pw = patch.shape[:2]
                edge_width = max(2, min(4, min(ph, pw) // 4))
                inner_pad = max(4, min(ph, pw) // 4)
                if ph >= 12 and pw >= 12:
                    edge = np.concatenate([
                        patch[:edge_width, :].ravel(), patch[-edge_width:, :].ravel(),
                        patch[:, :edge_width].ravel(), patch[:, -edge_width:].ravel(),
                    ])
                    inner = patch[inner_pad:max(inner_pad + 1, ph - inner_pad), inner_pad:max(inner_pad + 1, pw - inner_pad)]
                    is_box = float(edge.mean()) >= 0.22 and (not inner.size or float(inner.mean()) <= 0.20)
            if is_line or is_box:
                guide[labels == idx] = 255
        # A large blue outline is a drawing-area boundary, not a coloured
        # illustration block. Keep only its thin border for normalisation.
        blue_mask = self.direct_blue_template_mask(bgr)
        for rect in self.detect_direct_drawing_boxes_from_blue_mask(blue_mask):
            x, y, w, h = int(rect['x']), int(rect['y']), int(rect['w']), int(rect['h'])
            band = max(3, min(7, min(w, h) // 9))
            for left, top, right, bottom in (
                (x, y, x + w, y + band),
                (x, y + h - band, x + w, y + h),
                (x, y, x + band, y + h),
                (x + w - band, y, x + w, y + h),
            ):
                source = blue_mask[top:bottom, left:right]
                target = guide[top:bottom, left:right]
                target[source > 0] = 255
        return cv2.dilate(guide, cv2.getStructuringElement(cv2.MORPH_RECT, (3, 3)), iterations=1)

    def detect_direct_colored_subjective_lines(self, mask, side='front', kind='fill_blank', ink_color='red'):
        """Extract thin answer underlines from one already-isolated ink colour."""
        height, width = mask.shape[:2]
        horizontal_kernel = cv2.getStructuringElement(cv2.MORPH_RECT, (45, 1))
        horizontal = cv2.morphologyEx(mask, cv2.MORPH_OPEN, horizontal_kernel, iterations=1)
        horizontal = cv2.dilate(horizontal, cv2.getStructuringElement(cv2.MORPH_RECT, (5, 1)), iterations=1)
        num_labels, _labels, stats, centroids = cv2.connectedComponentsWithStats(horizontal, 8)
        candidates = []
        for idx in range(1, num_labels):
            x, y, w, h, area = stats[idx]
            if y < 55 or y > height - 70:
                continue
            if self.direct_subjective_line_is_name_area({'x': x, 'y': y, 'w': w, 'h': h}, width, height, side=side):
                continue
            if x < 4 or x + w > width - 4 or w < 45 or w > width * 0.78:
                continue
            # Coloured illustrations can contain similar colours, but answer
            # blanks are thin and long rather than filled coloured blocks.
            if h > 14 or (float(w) / float(h or 1)) < 10:
                continue
            candidates.append({
                'x': int(x), 'y': int(y), 'w': int(w), 'h': int(h),
                'area': int(area), 'cx': round(float(centroids[idx][0]), 2),
                'cy': round(float(centroids[idx][1]), 2),
                'top_black_ratio': 0.0, 'around_black_ratio': 0.0,
                'line_density': 1.0, 'status': 'accepted',
                'kind': kind, 'ink_color': ink_color,
                'answer_label': '作图' if kind == 'drawing' else '',
            })
        return self.merge_direct_subjective_line_segments(candidates)

    def detect_direct_subjective_lines_from_red_template(self, image_path, side='front'):
        """Detect red fill blanks and complete blue drawing-area boxes."""
        bgr, red_mask = self.load_direct_red_template_mask(image_path)
        red_lines = self.detect_direct_colored_subjective_lines(red_mask, side=side)
        drawing_boxes = self.detect_direct_drawing_boxes_from_blue_mask(self.direct_blue_template_mask(bgr))
        # A red underline inside a blue drawing box belongs to the drawing
        # region and must not become a second OCR blank.
        def inside_drawing_box(line):
            cx = float(line.get('cx', line.get('x', 0) + line.get('w', 0) / 2))
            cy = float(line.get('cy', line.get('y', 0) + line.get('h', 0) / 2))
            return any(
                float(box['x']) <= cx <= float(box['x']) + float(box['w'])
                and float(box['y']) <= cy <= float(box['y']) + float(box['h'])
                for box in drawing_boxes
            )
        red_lines = [line for line in red_lines if not inside_drawing_box(line)]
        ordered = self.sort_direct_subjective_lines_reading_order(red_lines + drawing_boxes)
        for index, item in enumerate(ordered, 1):
            x, y, w, h = int(item['x']), int(item['y']), int(item['w']), int(item['h'])
            item['index'] = index
            item['template_rect'] = {'x': float(x), 'y': float(y), 'w': float(w), 'h': float(h)}
            item['template_pixel'] = {'x': round(float(item.get('cx', x + w / 2)), 2), 'y': round(float(item.get('cy', y + h / 2)), 2)}
            if str(item.get('kind') or '').lower() == 'drawing':
                item['drawing_rect'] = dict(item['template_rect'])
        return ordered, []

    def make_direct_subjective_line_preview(
        self,
        image_path,
        lines,
        keep_indices=None,
        rejected=None,
        max_w=900,
        max_h=1180,
        display_index_by_index=None,
        calculation_rect=None,
    ):
        image = Image.open(image_path).convert('RGB')
        draw = ImageDraw.Draw(image)
        try:
            font = ImageFont.truetype('msyhbd.ttc', 34)
            small_font = ImageFont.truetype('msyhbd.ttc', 24)
        except Exception:
            font = ImageFont.load_default()
            small_font = ImageFont.load_default()
        keep_indices = {int(value) for value in keep_indices} if keep_indices is not None else {int(item.get('index')) for item in lines}
        display_index_by_index = {int(k): int(v) for k, v in (display_index_by_index or {}).items()}
        for item in rejected or []:
            rect = item.get('template_rect') or {}
            x = float(rect.get('x', item.get('x', 0)))
            y = float(rect.get('y', item.get('y', 0)))
            w = float(rect.get('w', item.get('w', 0)))
            h = float(rect.get('h', item.get('h', 0)))
            draw.rectangle((x, y - 8, x + w, y + h + 8), outline=(170, 170, 170), width=1)
        for item in lines:
            idx = int(item.get('index', 0))
            rect = item.get('template_rect') or {}
            x = float(rect.get('x', item.get('x', 0)))
            y = float(rect.get('y', item.get('y', 0)))
            w = float(rect.get('w', item.get('w', 0)))
            h = float(rect.get('h', item.get('h', 0)))
            kept = idx in keep_indices
            suspicious = item.get('status') == 'suspicious'
            is_drawing = str(item.get('kind') or '').lower() == 'drawing'
            color = (25, 85, 220) if kept and is_drawing else (220, 0, 0) if kept and not suspicious else (255, 145, 0) if kept else (120, 120, 120)
            line_width = 5 if kept else 2
            draw.rectangle((x, y - 14, x + w, y + h + 14), outline=color, width=line_width)
            label = (f'作图 {display_index_by_index.get(idx, idx)}' if is_drawing else str(display_index_by_index.get(idx, idx))) if kept else f'x{idx}'
            draw.text((x, max(0, y - 54)), label, fill=color, font=font if kept else small_font)
        if calculation_rect:
            x = float(calculation_rect.get('x', 0))
            y = float(calculation_rect.get('y', 0))
            w = float(calculation_rect.get('w', 0))
            h = float(calculation_rect.get('h', 0))
            if w > 0 and h > 0:
                color = (150, 35, 210)
                draw.rectangle((x, y, x + w, y + h), outline=color, width=8)
                draw.text((x + 8, y + 8), '计算题人工评分区域', fill=color, font=font)
        scale = min(max_w / image.width, max_h / image.height, 1.0)
        if scale < 1:
            image = image.resize((int(image.width * scale), int(image.height * scale)), Image.Resampling.LANCZOS)
        return image

    def direct_subjective_line_config_path(self):
        session_id = (getattr(self, 'current_session', None) or {}).get('id')
        if session_id:
            safe_id = re.sub(r'[^A-Za-z0-9_.-]+', '_', str(session_id)).strip('._-')
            return SESSION_TEMPLATE_CONFIGS_DIR / f'{safe_id}_direct_subjective_lines.json'
        paths = getattr(self, 'current_template_paths', {}) or {}
        raw = paths.get('answer_config')
        if raw and str(raw).strip():
            answer_path = Path(raw)
            if answer_path.name:
                return answer_path.with_name('direct_subjective_lines.json')
        return PROJECT_DIR / 'direct_subjective_lines.json'

    def direct_subjective_generated_config_path(self):
        paths = getattr(self, 'current_template_paths', {}) or {}
        raw = paths.get('answer_config')
        if raw and str(raw).strip():
            answer_path = Path(raw)
            if answer_path.name:
                return answer_path.with_name('subjective_config.json')
        return PROJECT_DIR / 'direct_subjective_subjective_config.json'

    def copy_direct_template_for_scoring(self, image_path, template_path):
        """Copy a template and turn red structure ink black for later matching."""
        image_path = Path(image_path)
        template_path = Path(template_path)
        data = np.fromfile(str(image_path), dtype=np.uint8)
        bgr = cv2.imdecode(data, cv2.IMREAD_COLOR)
        if bgr is None:
            shutil.copy2(image_path, template_path)
            return False
        guide_mask = self.direct_template_guide_ink_mask(bgr)
        if int(cv2.countNonZero(guide_mask)) < 30:
            shutil.copy2(image_path, template_path)
            return False
        # Student papers are printed in black. Normalising only the red/blue
        # guide ink keeps the saved template compatible with grayscale
        # alignment and template-difference scoring, while all coordinates
        # stay unchanged.
        bgr[guide_mask > 0] = (0, 0, 0)
        extension = template_path.suffix.lower()
        if extension not in {'.jpg', '.jpeg', '.png', '.bmp', '.webp', '.tif', '.tiff'}:
            extension = '.jpg'
        ok, encoded = cv2.imencode(extension, bgr)
        if not ok:
            shutil.copy2(image_path, template_path)
            return False
        encoded.tofile(str(template_path))
        return True

    def update_direct_side_template_metadata(self, image_path, side='front'):
        """Keep direct-paper side template markers in sync even when that side has no choices."""
        if (getattr(self, 'answer_config', {}) or {}).get('mode') != 'direct_paper_choice':
            return None
        paths = getattr(self, 'current_template_paths', {}) or {}
        answer_path = Path(paths.get('answer_config') or '')
        base_template_path = Path(paths.get('template_image') or '')
        marker_path = Path(paths.get('marker_config') or '')
        if not answer_path or not answer_path.exists() or not base_template_path:
            return None

        side = 'back' if str(side or '').lower() == 'back' else 'front'
        image_path = Path(image_path)
        template_path = base_template_path if side == 'front' else base_template_path.with_name('template_back.jpg')
        template_path.parent.mkdir(parents=True, exist_ok=True)
        try:
            if image_path.resolve() != template_path.resolve():
                if template_path.exists():
                    shutil.copy2(template_path, template_path.with_name(f"{template_path.stem}.backup_{datetime.now().strftime('%Y%m%d_%H%M%S')}{template_path.suffix}"))
                self.copy_direct_template_for_scoring(image_path, template_path)
        except Exception:
            return None

        marker_payload = None
        if (getattr(self, 'answer_config', {}) or {}).get('mode') == 'direct_paper_choice':
            try:
                marker_payload = self.detect_direct_back_corner_markers_robust(template_path)
            except Exception:
                marker_payload = None
        if not marker_payload:
            marker_payload = detect_corner_markers(template_path)

        markers = {
            name: {'x': round(float(marker_payload['markers'][name]['center']['x']), 2), 'y': round(float(marker_payload['markers'][name]['center']['y']), 2)}
            for name in ['top_left', 'top_right', 'bottom_right', 'bottom_left']
        }
        xs = [markers[name]['x'] for name in ['top_left', 'top_right', 'bottom_right', 'bottom_left']]
        ys = [markers[name]['y'] for name in ['top_left', 'top_right', 'bottom_right', 'bottom_left']]
        marker_diag = round(float(np.hypot(max(xs) - min(xs), max(ys) - min(ys))), 4)
        with Image.open(template_path) as image:
            width, height = image.size

        config = copy.deepcopy(self.answer_config or {})
        sides = config.get('sides') if isinstance(config.get('sides'), dict) else {}
        sides[side] = {
            'template_image': {'path': str(template_path), 'width': width, 'height': height},
            'markers': markers,
            'marker_diag': marker_diag,
        }
        config['sides'] = sides
        if side == 'front':
            config['template_image'] = {'path': str(template_path), 'width': width, 'height': height}
            config['markers'] = markers
            config['marker_diag'] = marker_diag
            if marker_path:
                try:
                    atomic_write_json(marker_path, marker_payload)
                except Exception:
                    pass
        config['updated_at'] = datetime.now().isoformat(timespec='seconds')
        atomic_write_json(answer_path, config)
        self.answer_config = config
        self._session_requires_structure = False
        self.template_marker_points = self.get_template_marker_points()
        return {'path': template_path, 'width': width, 'height': height, 'markers': markers}

    def direct_subjective_question_no(self, side, order):
        prefix = 'F' if str(side or '').lower() != 'back' else 'B'
        return f'{prefix}{int(order):03d}'

    def is_direct_subjective_drawing_label(self, label):
        normalized = unicodedata.normalize('NFKC', str(label or '')).strip().lower()
        normalized = re.sub(r'\s+', '', normalized)
        return bool(normalized and ('作图' in normalized or 'drawing' in normalized or 'draw' in normalized))

    def direct_subjective_drawing_question_no(self, label, fallback_qno):
        # "作图" is only a property of this detected blank line.  The real
        # question number should continue to follow the normal direct-paper
        # ordering / pasted-answer mapping, so do not parse numbers from labels
        # such as "7作图".
        return fallback_qno

    def direct_subjective_line_crop_rect(self, line_rect, image_width=None, image_height=None, is_drawing=False):
        x = float(line_rect.get('x', 0))
        y = float(line_rect.get('y', 0))
        w = float(line_rect.get('w', 0))
        h = float(line_rect.get('h', 0))
        # The direct-paper template now leaves spaces on both sides of blanks,
        # so include a little surrounding handwriting context for OCR.
        pad_x = min(70.0, max(24.0, w * 0.18)) if is_drawing else min(42.0, max(24.0, w * 0.12))
        inner_shrink_x = 0.0
        # Shift the crop area upward so student handwriting above the line is fully captured
        # without cutting off tall characters, while keeping the bottom edge close to the line.
        policy = (getattr(self, 'subjective_config', {}) or {}).get('crop_policy', {}) or {}
        default_top_margin = 420.0 if is_drawing else 65.0
        default_bottom_margin = 24.0 if is_drawing else 3.0
        top_margin = float(policy.get('drawing_top_margin' if is_drawing else 'line_top_margin') or default_top_margin)
        bottom_margin = float(policy.get('drawing_bottom_margin' if is_drawing else 'line_bottom_margin') or default_bottom_margin)
        left = x - pad_x + inner_shrink_x
        top = y - top_margin
        right = x + w + pad_x - inner_shrink_x
        bottom = y + h + bottom_margin
        if image_width:
            left = max(0.0, min(float(image_width) - 1.0, left))
            right = max(left + 1.0, min(float(image_width), right))
        if image_height:
            top = max(0.0, min(float(image_height) - 1.0, top))
            bottom = max(top + 1.0, min(float(image_height), bottom))
        return {
            'x': round(left, 2),
            'y': round(top, 2),
            'w': round(right - left, 2),
            'h': round(bottom - top, 2),
        }

    def saved_direct_structure_preview_payload(self):
        scheme_path = getattr(self, 'loaded_answer_key_scheme_path', None)
        scheme_name = getattr(self, 'loaded_answer_key_scheme_name', '') or '当前配置'
        payload = {}
        if scheme_path:
            try:
                path = Path(scheme_path)
                if path.exists():
                    payload = json.loads(path.read_text(encoding='utf-8-sig'))
                    scheme_name = str(payload.get('name') or scheme_name)
            except Exception:
                payload = {}

        structure = payload.get('direct_paper_structure') if isinstance(payload, dict) else {}
        structure = structure if isinstance(structure, dict) else {}
        answer_config = structure.get('answer_config') if isinstance(structure.get('answer_config'), dict) else {}
        if not answer_config:
            answer_config = copy.deepcopy(getattr(self, 'answer_config', {}) or {})
        subjective_config = payload.get('subjective_config') if isinstance(payload, dict) else {}
        if not isinstance(subjective_config, dict) or not subjective_config.get('items'):
            subjective_config = copy.deepcopy(getattr(self, 'subjective_config', {}) or {})
        return scheme_name, structure, answer_config, subjective_config

    def direct_structure_preview_template_path(self, side, structure, answer_config):
        side = 'back' if str(side or '').lower() == 'back' else 'front'
        template_images = structure.get('template_images') if isinstance(structure, dict) else {}
        candidate = (template_images or {}).get(side)
        sides = answer_config.get('sides') if isinstance(answer_config, dict) else {}
        side_payload = (sides or {}).get(side) if isinstance((sides or {}).get(side), dict) else {}
        if not candidate:
            image_info = side_payload.get('template_image') if isinstance(side_payload.get('template_image'), dict) else {}
            candidate = image_info.get('path')
        if not candidate and side == 'front':
            image_info = answer_config.get('template_image') if isinstance(answer_config.get('template_image'), dict) else {}
            candidate = image_info.get('path')
        if not candidate:
            paths = getattr(self, 'current_template_paths', {}) or {}
            base = Path(paths.get('template_image') or '')
            if base:
                candidate = base.with_name('template_back.jpg') if side == 'back' else base
        try:
            path = Path(candidate) if candidate else None
        except Exception:
            path = None
        return path if path and path.exists() else None

    def direct_structure_preview_subjective_parts(self, subjective_config, side):
        parts = []
        side = 'back' if str(side or '').lower() == 'back' else 'front'
        for item in (subjective_config.get('items') or []):
            if str(item.get('side') or 'front').lower() != side:
                continue
            kind = str(item.get('kind') or 'fill_blank').lower()
            label = str(item.get('answer_label') or item.get('label') or item.get('question_no') or '').strip()
            if kind == 'drawing':
                rect = item.get('rect') or {}
                if rect:
                    parts.append({
                        'part_id': str(item.get('part_id') or item.get('question_no') or ''),
                        'label': label or '作图',
                        'kind': 'drawing',
                        'rect': rect,
                        'score': float(item.get('max_score') or 2),
                    })
                continue
            for blank in (item.get('blanks') or []):
                rect = blank.get('rect') or {}
                if not rect:
                    continue
                parts.append({
                    'part_id': f"q{item.get('question_no')}_b{blank.get('blank_no', 1)}",
                    'label': str(blank.get('answer_label') or blank.get('label') or label).strip(),
                    'kind': 'fill_blank',
                    'rect': rect,
                    'score': float(blank.get('score') or item.get('max_score') or 1),
                })
        if side == 'back':
            calculation_region = subjective_config.get('direct_calculation_region') or {}
            rect = calculation_region.get('rect') if isinstance(calculation_region, dict) else {}
            if isinstance(calculation_region, dict) and calculation_region.get('enabled') and rect:
                calculation_questions = subjective_config.get('calculation_questions') or {}
                parts.append({
                    'part_id': 'direct_back_calculation',
                    'label': '计算题（无标准答案）',
                    'kind': 'calculation',
                    'rect': copy.deepcopy(rect),
                    'score': float(calculation_questions.get('max_score') or 0),
                })
        return parts

    def direct_calculation_manual_parts(self):
        """Turn each configured calculation sub-question into a local manual task."""
        if not self.is_direct_paper_choice_template() or not self.direct_calculation_region_config():
            return []
        parts = []
        for item in self.calculation_score_parts():
            parts.append({
                'part_id': item['part_id'],
                'label': item['label'],
                'kind': 'calculation',
                'score': float(item['score']),
                'side': 'back',
                'manual_only': True,
                'ocr': {'enabled': False},
            })
        return parts

    def direct_structure_preview_choice_items(self, answer_config, side):
        side = 'back' if str(side or '').lower() == 'back' else 'front'
        choices = []
        for zone in (answer_config.get('zones') or []):
            zone_side = str(zone.get('side') or ('back' if 'back' in str(zone.get('zone_name') or '').lower() else 'front')).lower()
            if zone_side != side:
                continue
            for question in (zone.get('questions') or []):
                qno = question.get('question_no_in_zone') or question.get('question_label') or ''
                for option, option_data in (question.get('options') or {}).items():
                    rect = option_data.get('template_rect') or {}
                    if rect:
                        choices.append({'label': f'{qno}{option}', 'rect': rect})
        return choices

    def make_saved_direct_structure_overview(self, template_path, choices, parts, max_width=980):
        image = Image.open(template_path).convert('RGB')
        draw = ImageDraw.Draw(image)
        try:
            font = ImageFont.truetype('msyhbd.ttc', 26)
        except Exception:
            font = ImageFont.load_default()

        def draw_labeled_rect(rect, color, label, width):
            x = float(rect.get('x', 0))
            y = float(rect.get('y', 0))
            w = float(rect.get('w', 0))
            h = float(rect.get('h', 0))
            draw.rectangle((x, y, x + w, y + h), outline=color, width=width)
            if not label:
                return
            text = str(label)
            bbox = draw.textbbox((0, 0), text, font=font)
            tw = bbox[2] - bbox[0]
            th = bbox[3] - bbox[1]
            tx = max(0, min(image.width - tw - 8, x + 3))
            ty = max(0, y - th - 8)
            draw.rectangle((tx - 2, ty - 2, tx + tw + 4, ty + th + 4), fill=(255, 255, 255))
            draw.text((tx, ty), text, fill=color, font=font)

        for item in choices:
            draw_labeled_rect(item.get('rect') or {}, (0, 120, 255), item.get('label'), 4)
        for index, part in enumerate(parts, 1):
            is_drawing = part.get('kind') == 'drawing'
            is_calculation = part.get('kind') == 'calculation'
            color = (150, 35, 210) if is_calculation else (255, 90, 0) if is_drawing else (220, 0, 0)
            kind_text = '计算题' if is_calculation else '作图' if is_drawing else '空'
            draw_labeled_rect(
                part.get('rect') or {},
                color,
                f'{index}.{part.get("label") or kind_text} {kind_text}',
                8 if is_calculation else 7 if is_drawing else 4,
            )

        scale = min(1.0, float(max_width) / max(1, image.width))
        if scale < 1.0:
            image = image.resize((max(1, int(image.width * scale)), max(1, int(image.height * scale))), Image.Resampling.LANCZOS)
        return image

    def open_saved_direct_paper_structure_preview(self):
        if not self.is_direct_paper_choice_template():
            messagebox.showinfo('提示', '“查看结构/裁图”用于试卷直接批改模板。')
            return
        scheme_name, structure, answer_config, subjective_config = self.saved_direct_structure_preview_payload()
        side_payloads = []
        for side, side_name in (('front', '正面'), ('back', '背面')):
            template_path = self.direct_structure_preview_template_path(side, structure, answer_config)
            choices = self.direct_structure_preview_choice_items(answer_config, side)
            parts = self.direct_structure_preview_subjective_parts(subjective_config, side)
            if template_path or choices or parts:
                side_payloads.append((side, side_name, template_path, choices, parts))
        if not side_payloads:
            messagebox.showwarning('没有结构', '当前答案方案还没有保存正反面结构。')
            return

        win = tk.Toplevel(self.root)
        win.title(f'查看已保存结构/裁图 - {scheme_name}')
        win.geometry('1320x900')
        win.minsize(1000, 720)
        win.transient(self.root)
        win.preview_photos = []

        header = ttk.Frame(win)
        header.pack(fill=tk.X, padx=12, pady=(10, 4))
        ttk.Label(header, text=f'答案方案：{scheme_name}', font=('Arial', 13, 'bold')).pack(side=tk.LEFT)
        ttk.Label(
            header,
            text='蓝框=选择题小框  红框=填空实际裁图  橙框=作图实际裁图  紫框=计算题人工评分区域',
            foreground='#6b1d86',
        ).pack(side=tk.LEFT, padx=18)
        ttk.Button(header, text='关闭', command=win.destroy).pack(side=tk.RIGHT)

        side_tabs = ttk.Notebook(win)
        side_tabs.pack(fill=tk.BOTH, expand=True, padx=12, pady=(4, 12))

        def bind_mousewheel(canvas):
            canvas.bind('<MouseWheel>', lambda event, target=canvas: target.yview_scroll(-1 if event.delta > 0 else 1, 'units'))

        for side, side_name, template_path, choices, parts in side_payloads:
            side_frame = ttk.Frame(side_tabs)
            side_tabs.add(side_frame, text=f'{side_name}（选择 {len(choices)} 框，主观 {len(parts)} 项）')
            if not template_path:
                ttk.Label(side_frame, text=f'{side_name}模板图片不存在，无法显示裁图。', foreground='red', font=('Arial', 14, 'bold')).pack(padx=20, pady=20)
                continue
            inner_tabs = ttk.Notebook(side_frame)
            inner_tabs.pack(fill=tk.BOTH, expand=True)

            overview_tab = ttk.Frame(inner_tabs)
            crops_tab = ttk.Frame(inner_tabs)
            inner_tabs.add(overview_tab, text='整页范围')
            inner_tabs.add(crops_tab, text='逐项裁图')

            overview_canvas = tk.Canvas(overview_tab, bg='#2c2c2c', highlightthickness=0)
            overview_vbar = ttk.Scrollbar(overview_tab, orient=tk.VERTICAL, command=overview_canvas.yview)
            overview_hbar = ttk.Scrollbar(overview_tab, orient=tk.HORIZONTAL, command=overview_canvas.xview)
            overview_canvas.configure(yscrollcommand=overview_vbar.set, xscrollcommand=overview_hbar.set)
            overview_canvas.grid(row=0, column=0, sticky='nsew')
            overview_vbar.grid(row=0, column=1, sticky='ns')
            overview_hbar.grid(row=1, column=0, sticky='ew')
            overview_tab.rowconfigure(0, weight=1)
            overview_tab.columnconfigure(0, weight=1)
            overview_image = self.make_saved_direct_structure_overview(template_path, choices, parts)
            overview_photo = ImageTk.PhotoImage(overview_image)
            win.preview_photos.append(overview_photo)
            overview_canvas.create_image(0, 0, image=overview_photo, anchor='nw')
            overview_canvas.configure(scrollregion=(0, 0, overview_image.width, overview_image.height))
            bind_mousewheel(overview_canvas)

            crop_canvas = tk.Canvas(crops_tab, bg='#ececec', highlightthickness=0)
            crop_vbar = ttk.Scrollbar(crops_tab, orient=tk.VERTICAL, command=crop_canvas.yview)
            crop_canvas.configure(yscrollcommand=crop_vbar.set)
            crop_canvas.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
            crop_vbar.pack(side=tk.RIGHT, fill=tk.Y)
            crop_body = ttk.Frame(crop_canvas)
            crop_window = crop_canvas.create_window((0, 0), window=crop_body, anchor='nw')
            crop_body.bind('<Configure>', lambda _event, canvas=crop_canvas: canvas.configure(scrollregion=canvas.bbox('all')))
            crop_canvas.bind('<Configure>', lambda event, canvas=crop_canvas, item=crop_window: canvas.itemconfigure(item, width=max(200, event.width)))
            bind_mousewheel(crop_canvas)

            source = Image.open(template_path).convert('RGB')
            if not parts:
                ttk.Label(crop_body, text=f'{side_name}没有保存主观题裁图。', font=('Arial', 14, 'bold')).pack(padx=20, pady=20)
            for index, part in enumerate(parts, 1):
                rect = part.get('rect') or {}
                left = max(0, int(round(float(rect.get('x', 0)))))
                top = max(0, int(round(float(rect.get('y', 0)))))
                right = min(source.width, int(round(float(rect.get('x', 0)) + float(rect.get('w', 0)))))
                bottom = min(source.height, int(round(float(rect.get('y', 0)) + float(rect.get('h', 0)))))
                if right <= left or bottom <= top:
                    continue
                crop = source.crop((left, top, right, bottom))
                max_w = 920
                max_h = 620 if part.get('kind') == 'calculation' else 520 if part.get('kind') == 'drawing' else 250
                scale = min(max_w / max(1, crop.width), max_h / max(1, crop.height), 2.0)
                if abs(scale - 1.0) > 0.01:
                    crop = crop.resize((max(1, int(crop.width * scale)), max(1, int(crop.height * scale))), Image.Resampling.LANCZOS)
                photo = ImageTk.PhotoImage(crop)
                win.preview_photos.append(photo)
                item_frame = ttk.LabelFrame(
                    crop_body,
                    text=(
                        f'{index}. {part.get("label") or "未命名"} | '
                        f'{"计算题" if part.get("kind") == "calculation" else "作图" if part.get("kind") == "drawing" else "填空"} | '
                        f'{part.get("score", 0):g}分'
                    ),
                )
                item_frame.pack(fill=tk.X, padx=12, pady=8)
                tk.Label(item_frame, image=photo, bg='white').pack(anchor='w', padx=8, pady=8)
            source.close()

    def collect_existing_direct_subjective_settings(self, config):
        settings = {}
        if not isinstance(config, dict):
            return settings
        for item in config.get('items', []) or []:
            side = str(item.get('side') or 'front').lower()
            line_index = item.get('source_line_index')
            if item.get('kind') == 'drawing':
                payload = {
                    'kind': 'drawing',
                    'score': item.get('max_score'),
                    'score_category': item.get('score_category') or 'drawing',
                    'manual_only': item.get('manual_only', True),
                }
                if line_index is not None:
                    settings[(side, str(line_index))] = payload
                qno = str(item.get('question_no') or '')
                if qno:
                    settings[('qno', qno)] = payload
                continue
            blank = None
            if (item.get('blanks') or []):
                blank = (item.get('blanks') or [None])[0]
            if not isinstance(blank, dict):
                continue
            payload = {
                'kind': item.get('kind') or 'fill_blank',
                'score': blank.get('score'),
                'score_category': blank.get('score_category'),
                'ocr': copy.deepcopy(blank.get('ocr') or {}),
            }
            if line_index is not None:
                settings[(side, str(line_index))] = payload
            qno = str(item.get('question_no') or '')
            if qno:
                settings[('qno', qno)] = payload
        return settings

    def ensure_direct_subjective_config_registered(self, config_path):
        registry_path = PROJECT_DIR / 'template_registry.json'
        try:
            manifest = json.loads(registry_path.read_text(encoding='utf-8-sig'))
            templates = manifest.setdefault('templates', {})
            entry = templates.setdefault(self.current_template_key, {})
            relative = str(Path(config_path).resolve().relative_to(PROJECT_DIR)).replace('/', '\\')
            if entry.get('subjective_config') == relative:
                return False
            entry['subjective_config'] = relative
            atomic_write_json(registry_path, manifest)
            self.template_manifest = manifest
            self.template_entries = templates
            if isinstance(getattr(self, 'current_template_entry', None), dict):
                self.current_template_entry['subjective_config'] = relative
            return True
        except Exception:
            return False

    def sync_direct_subjective_lines_to_subjective_config(self, line_config=None):
        if line_config is None:
            line_config_path = self.direct_subjective_line_config_path()
            if not line_config_path.exists():
                return None
            line_config = json.loads(line_config_path.read_text(encoding='utf-8-sig'))
        config_path = self.direct_subjective_generated_config_path()
        existing = copy.deepcopy(getattr(self, 'subjective_config', {}) or {})
        if not getattr(self, 'current_session', None) and config_path.exists():
            try:
                existing = json.loads(config_path.read_text(encoding='utf-8-sig'))
            except Exception:
                existing = {}
        preserved = self.collect_existing_direct_subjective_settings(existing)
        calculation_questions = copy.deepcopy(existing.get('calculation_questions') or {})

        items = []
        crop_regions = {}
        scoring_total = 0.0
        direct_calculation_region = copy.deepcopy(existing.get('direct_calculation_region') or {})
        sides = line_config.get('sides') if isinstance(line_config, dict) else {}
        for side in ('front', 'back'):
            side_payload = (sides or {}).get(side) or {}
            image_info = side_payload.get('template_image') or {}
            width = float(image_info.get('width') or 0)
            height = float(image_info.get('height') or 0)
            if width > 0 and height > 0:
                crop_regions[f'direct_{side}'] = {'x': 0, 'y': 0, 'w': width, 'h': height}
            if side == 'back':
                raw_calculation = side_payload.get('calculation_region') or {}
                raw_rect = raw_calculation.get('rect') if isinstance(raw_calculation, dict) else {}
                try:
                    calculation_rect = {
                        'x': float((raw_rect or {}).get('x', 0)),
                        'y': float((raw_rect or {}).get('y', 0)),
                        'w': float((raw_rect or {}).get('w', 0)),
                        'h': float((raw_rect or {}).get('h', 0)),
                    }
                except Exception:
                    calculation_rect = {}
                if 'calculation_region' in side_payload and not raw_calculation.get('enabled'):
                    direct_calculation_region = {'enabled': False, 'side': 'back'}
                    calculation_questions = {
                        'enabled': False,
                        'mode': 'back_region_manual',
                        'questions': [],
                        'max_score': 0,
                    }
                    crop_regions.pop('direct_back_calculation', None)
                elif (
                    isinstance(raw_calculation, dict)
                    and raw_calculation.get('enabled')
                    and calculation_rect.get('w', 0) > 0
                    and calculation_rect.get('h', 0) > 0
                ):
                    direct_calculation_region = copy.deepcopy(raw_calculation)
                    direct_calculation_region['enabled'] = True
                    direct_calculation_region['side'] = 'back'
                    direct_calculation_region['rect'] = calculation_rect
                    crop_regions['direct_back_calculation'] = copy.deepcopy(calculation_rect)
            lines = side_payload.get('lines') or []
            ordered_lines = self.sort_direct_subjective_lines_reading_order(lines)
            side_label = '正面' if side == 'front' else '背面'
            for order, line in enumerate(ordered_lines, 1):
                line_rect = line.get('template_rect') or {}
                source_index = int(line.get('index', order) or order)
                qno = self.direct_subjective_question_no(side, order)
                answer_label = unicodedata.normalize('NFKC', str(line.get('answer_label') or '')).strip()
                answer_label = re.sub(r'\s+', '', answer_label)
                line_kind = str(line.get('kind') or '').strip().lower()
                is_drawing_line = line_kind == 'drawing' or self.is_direct_subjective_drawing_label(answer_label)
                label = answer_label or ('作图' if is_drawing_line else f'{side_label}横线{order}')
                drawing_qno = self.direct_subjective_drawing_question_no(answer_label, qno) if is_drawing_line else qno
                old = (
                    preserved.get((side, str(source_index)))
                    or preserved.get(('qno', drawing_qno if is_drawing_line else qno))
                    or preserved.get(('qno', qno))
                    or {}
                )
                # Direct-paper scoring is fixed by item type. Do not preserve a
                # stale score from a line that previously occupied this index;
                # changing a drawing line back to a normal blank must also
                # change its score from 2 to 1.
                score = 2.0 if is_drawing_line else 1.0
                scoring_total += score
                saved_drawing_rect = line.get('drawing_rect') if is_drawing_line else None
                if isinstance(saved_drawing_rect, dict):
                    try:
                        rect = {
                            'x': float(saved_drawing_rect.get('x', 0)),
                            'y': float(saved_drawing_rect.get('y', 0)),
                            'w': float(saved_drawing_rect.get('w', 0)),
                            'h': float(saved_drawing_rect.get('h', 0)),
                        }
                    except Exception:
                        rect = {}
                    if rect.get('w', 0) <= 0 or rect.get('h', 0) <= 0:
                        rect = self.direct_subjective_line_crop_rect(line_rect, width, height, is_drawing=True)
                else:
                    rect = self.direct_subjective_line_crop_rect(line_rect, width, height, is_drawing=is_drawing_line)
                if is_drawing_line:
                    part_id = f'q{drawing_qno}_drawing_{source_index}'
                    items.append({
                        'part_id': part_id,
                        'question_no': drawing_qno,
                        'label': label,
                        'answer_label': answer_label,
                        'kind': 'drawing',
                        'side': side,
                        'region_name': f'direct_{side}',
                        'source': 'direct_subjective_lines',
                        'source_line_index': source_index,
                        'max_score': score,
                        'manual_only': True,
                        'score_category': 'drawing',
                        'rect': rect,
                    })
                    continue
                ocr = self.normalize_ocr_config(old.get('ocr') or {})
                items.append({
                    'question_no': qno,
                    'label': label,
                    'answer_label': answer_label,
                    'kind': 'fill_blank',
                    'side': side,
                    'region_name': f'direct_{side}',
                    'source': 'direct_subjective_lines',
                    'source_line_index': source_index,
                    'max_score': score,
                    'blanks': [{
                        'blank_no': 1,
                        'score': score,
                        'score_category': 'direct_subjective',
                        'side': side,
                        'region_name': f'direct_{side}',
                        'rect': rect,
                        'label': label,
                        'answer_label': answer_label,
                        'ocr': ocr,
                    }],
                })

        if direct_calculation_region.get('enabled') and direct_calculation_region.get('rect'):
            crop_regions['direct_back_calculation'] = copy.deepcopy(direct_calculation_region['rect'])

        generated = {
            'version': 1,
            'crop_geometry_version': DIRECT_SUBJECTIVE_CROP_GEOMETRY_VERSION,
            'template_key': self.current_template_key,
            'template_name': self.current_template_name,
            'display_name': '试卷直接批改模板主观横线配置',
            'source': 'direct_subjective_lines',
            'updated_at': datetime.now().isoformat(timespec='seconds'),
            'scoring': {
                'default_blank_score': 1,
                'include_in_total_score': True,
                'max_score': scoring_total,
            },
            'crop_regions': crop_regions,
            'items': items,
        }
        if calculation_questions:
            generated['calculation_questions'] = calculation_questions
        if direct_calculation_region:
            generated['direct_calculation_region'] = direct_calculation_region
        atomic_write_json(config_path, generated)
        self.subjective_config_path = config_path
        self.subjective_config = generated
        self.ensure_direct_subjective_config_registered(config_path)
        return config_path

    def save_direct_subjective_line_structure(self, image_path, lines, side='front'):
        return self.save_direct_subjective_line_structure_with_labels(image_path, lines, side=side, labels_by_index=None)

    def default_direct_subjective_label_text(self, lines):
        values = [
            '# 可选：给横线绑定真实题号，格式如 1=13、2=14、5=20(1)。左边是红框编号。',
            '# 作图题写法：3=作图。这里只标记这个空是作图，不需要写题号；答案导入时仍按原来的题号逻辑走。',
            '# 不填写也可以，程序会继续按 F001/F002 这类横线顺序编号。',
        ]
        for item in lines or []:
            idx = int(item.get('index', 0) or 0)
            if idx:
                label = str(item.get('answer_label') or item.get('label') or '').strip()
                values.append(f'{idx}={label}')
        return '\n'.join(values)

    def parse_direct_subjective_label_map(self, text, lines):
        valid = {int(item.get('index')) for item in lines or []}
        labels = {}
        for raw in str(text or '').splitlines():
            line = raw.strip()
            if not line or line.startswith('#'):
                continue
            match = re.match(r'^(\d+)\s*(?:=|:|：|\s)\s*(.*?)\s*$', line)
            if not match:
                raise ValueError(f'题号对应格式不正确：{raw}\n请写成“红框编号=题号”，例如 5=20(1)。')
            index = int(match.group(1))
            if index not in valid:
                raise ValueError(f'题号对应里引用了不存在的红框编号：{index}')
            label = unicodedata.normalize('NFKC', match.group(2)).strip()
            label = re.sub(r'\s+', '', label)
            if label:
                if self.is_direct_subjective_drawing_label(label):
                    label = '作图'
                labels[index] = label
        return labels

    def save_direct_subjective_line_structure_with_labels(
        self,
        image_path,
        lines,
        side='front',
        labels_by_index=None,
        calculation_region=None,
    ):
        config_path = self.direct_subjective_line_config_path()
        config_path.parent.mkdir(parents=True, exist_ok=True)
        if config_path.exists():
            backup = config_path.with_name(f"{config_path.stem}.backup_{datetime.now().strftime('%Y%m%d_%H%M%S')}.json")
            shutil.copy2(config_path, backup)
            try:
                config = json.loads(config_path.read_text(encoding='utf-8-sig'))
            except Exception:
                config = {}
        else:
            backup = None
            config = {}
        with Image.open(image_path) as image:
            width, height = image.size
        side = 'back' if str(side or '').lower() == 'back' else 'front'
        side_template = self.update_direct_side_template_metadata(image_path, side=side)
        if side_template:
            image_path = side_template['path']
            width = side_template['width']
            height = side_template['height']
        labels_by_index = labels_by_index or {}
        config['version'] = 1
        config['template_key'] = self.current_template_key
        config['template_name'] = self.current_template_name
        config['updated_at'] = datetime.now().isoformat(timespec='seconds')
        sides = config.get('sides') if isinstance(config.get('sides'), dict) else {}
        previous_side_payload = sides.get(side) if isinstance(sides.get(side), dict) else {}
        side_payload = {
            'side': side,
            'template_image': {'path': str(image_path), 'width': width, 'height': height},
            'lines': [
                {
                    'index': int(item.get('index', pos)),
                    'template_rect': item.get('template_rect') or {
                        'x': float(item.get('x', 0)),
                        'y': float(item.get('y', 0)),
                        'w': float(item.get('w', 0)),
                        'h': float(item.get('h', 0)),
                    },
                    'template_pixel': item.get('template_pixel') or {
                        'x': float(item.get('cx', 0)),
                        'y': float(item.get('cy', 0)),
                    },
                    'status': item.get('status', 'accepted'),
                    'kind': 'drawing' if self.is_direct_subjective_drawing_label(labels_by_index.get(int(item.get('index', pos)))) or str(item.get('kind') or '').lower() == 'drawing' else 'fill_blank',
                    'answer_label': labels_by_index.get(int(item.get('index', pos))) or str(item.get('answer_label') or '').strip(),
                    'drawing_rect': item.get('drawing_rect') if str(item.get('kind') or '').lower() == 'drawing' and isinstance(item.get('drawing_rect'), dict) else None,
                }
                for pos, item in enumerate(lines, 1)
            ],
        }
        if side == 'back':
            if calculation_region is None:
                previous_region = previous_side_payload.get('calculation_region')
                if isinstance(previous_region, dict):
                    side_payload['calculation_region'] = copy.deepcopy(previous_region)
            elif isinstance(calculation_region, dict) and calculation_region.get('enabled'):
                side_payload['calculation_region'] = copy.deepcopy(calculation_region)
            elif isinstance(calculation_region, dict) and 'enabled' in calculation_region:
                side_payload['calculation_region'] = {'enabled': False, 'side': 'back'}
        sides[side] = side_payload
        config['sides'] = sides
        atomic_write_json(config_path, config)
        self.sync_direct_subjective_lines_to_subjective_config(config)
        self.update_template_ui_state()
        return config_path, backup

    def clear_direct_paper_side_structure(self, side_to_clear):
        side_to_clear = 'back' if str(side_to_clear or '').lower() == 'back' else 'front'
        changed = {'choice': False, 'subjective': False}

        paths = getattr(self, 'current_template_paths', {}) or {}
        answer_path = Path(paths.get('answer_config') or '')
        if answer_path.exists():
            config = json.loads(answer_path.read_text(encoding='utf-8-sig'))
            zones = [
                zone for zone in (config.get('zones') or [])
                if str(zone.get('side') or 'front').lower() != side_to_clear
            ]
            if len(zones) != len(config.get('zones') or []):
                backup = answer_path.with_name(f"{answer_path.stem}.backup_{datetime.now().strftime('%Y%m%d_%H%M%S')}_clear_{side_to_clear}.json")
                shutil.copy2(answer_path, backup)
                config['zones'] = zones
                sides = config.get('sides') if isinstance(config.get('sides'), dict) else {}
                sides.pop(side_to_clear, None)
                config['sides'] = sides
                config['double_sided'] = any(str(zone.get('side') or '').lower() == 'back' for zone in zones)
                config['updated_at'] = datetime.now().isoformat(timespec='seconds')
                atomic_write_json(answer_path, config)
                self.answer_config = config
                self.available_zone_names = [zone.get('zone_name', f'zone{i + 1}') for i, zone in enumerate(zones)]
                self.selected_zones = list(self.available_zone_names)
                changed['choice'] = True

        line_config_path = self.direct_subjective_line_config_path()
        if line_config_path.exists():
            line_config = json.loads(line_config_path.read_text(encoding='utf-8-sig'))
            sides = line_config.get('sides') if isinstance(line_config.get('sides'), dict) else {}
            if side_to_clear in sides:
                backup = line_config_path.with_name(f"{line_config_path.stem}.backup_{datetime.now().strftime('%Y%m%d_%H%M%S')}_clear_{side_to_clear}.json")
                shutil.copy2(line_config_path, backup)
                sides.pop(side_to_clear, None)
                line_config['sides'] = sides
                line_config['updated_at'] = datetime.now().isoformat(timespec='seconds')
                atomic_write_json(line_config_path, line_config)
                self.sync_direct_subjective_lines_to_subjective_config(line_config)
                changed['subjective'] = True

        self.update_template_ui_state()
        return changed

    def parse_direct_subjective_keep_indices(self, text, lines):
        valid = {int(item.get('index')) for item in lines}
        found = []
        for value in re.split(r'[,，、\s]+', str(text or '').strip()):
            if not value:
                continue
            if not value.isdigit():
                raise ValueError(f'保留编号里有不是数字的内容：{value}')
            number = int(value)
            if number not in valid:
                raise ValueError(f'编号不存在：{number}')
            found.append(number)
        return set(found)

    def open_direct_subjective_line_setup(self):
        if not self.is_direct_paper_choice_template():
            messagebox.showinfo('提示', '当前模板不是“试卷直接批改”模板。')
            return
        side_result = {'side': None}
        side_win = tk.Toplevel(self.root)
        side_win.title('选择设置哪一面')
        side_win.geometry('360x160')
        side_win.resizable(False, False)
        side_win.transient(self.root)
        ttk.Label(
            side_win,
            text='请选择要设置主观横线结构的页面：',
            font=('Arial', 12, 'bold'),
        ).pack(fill=tk.X, padx=18, pady=(18, 12))

        def choose_side(value):
            side_result['side'] = value
            side_win.destroy()

        button_row = ttk.Frame(side_win)
        button_row.pack(fill=tk.X, padx=18, pady=8)
        ttk.Button(button_row, text='设置正面', command=lambda: choose_side('front')).pack(side=tk.LEFT, expand=True, fill=tk.X, padx=(0, 8))
        ttk.Button(button_row, text='设置背面', command=lambda: choose_side('back')).pack(side=tk.LEFT, expand=True, fill=tk.X, padx=(8, 0))
        ttk.Button(side_win, text='取消', command=side_win.destroy).pack(pady=(4, 0))
        side_win.protocol('WM_DELETE_WINDOW', side_win.destroy)
        side_win.grab_set()
        self.root.wait_window(side_win)
        side = side_result.get('side')
        if not side:
            return
        image_file = filedialog.askopenfilename(
            title='选择背面试卷模板图片' if side == 'back' else '选择正面试卷模板图片',
            initialdir=self.last_open_dir,
            filetypes=[('图片文件', '*.jpg;*.jpeg;*.png;*.bmp;*.webp;*.tif;*.tiff'), ('所有文件', '*.*')],
        )
        if not image_file:
            return
        self.last_open_dir = str(Path(image_file).parent)
        try:
            lines, rejected = self.detect_direct_subjective_lines_from_blank(Path(image_file), side=side)
        except Exception as e:
            messagebox.showerror('识别失败', str(e))
            return
        if not lines:
            if side == 'back':
                messagebox.showinfo('提示', '背面没有识别到横线。\n\n若背面只有计算题或无填空题，属于正常情况，无需单独设置横线结构；请使用“正反面结构”或在计算题设置中直接启用计算题大题。')
            else:
                messagebox.showwarning('识别结果', '没有识别到可用横线。')
            return

        win = tk.Toplevel(self.root)
        win.title('设置主观题横线结构（删除误抓横线）')
        self.track_context_window(win)
        win.geometry('1380x900')
        win.minsize(1120, 720)
        win.transient(self.root)

        left = ttk.Frame(win)
        left.pack(side=tk.LEFT, fill=tk.BOTH, expand=True, padx=12, pady=12)
        right = ttk.Frame(win)
        right.pack(side=tk.RIGHT, fill=tk.BOTH, padx=(0, 12), pady=12)

        info_var = tk.StringVar(value=f'{"背面" if side == "back" else "正面"}：识别到 {len(lines)} 条候选横线。红色为可靠，橙色为可疑。')
        ttk.Label(left, textvariable=info_var, font=('Arial', 11, 'bold')).pack(anchor='w')
        preview_frame = ttk.Frame(left)
        preview_frame.pack(fill=tk.BOTH, expand=True, pady=(8, 0))
        preview_canvas = tk.Canvas(preview_frame, bg='#333333', highlightthickness=0)
        preview_vbar = ttk.Scrollbar(preview_frame, orient=tk.VERTICAL, command=preview_canvas.yview)
        preview_hbar = ttk.Scrollbar(preview_frame, orient=tk.HORIZONTAL, command=preview_canvas.xview)
        preview_canvas.configure(yscrollcommand=preview_vbar.set, xscrollcommand=preview_hbar.set)
        preview_canvas.grid(row=0, column=0, sticky='nsew')
        preview_vbar.grid(row=0, column=1, sticky='ns')
        preview_hbar.grid(row=1, column=0, sticky='ew')
        preview_frame.rowconfigure(0, weight=1)
        preview_frame.columnconfigure(0, weight=1)

        ttk.Label(
            right,
            text='保留编号：把误抓的编号删掉即可。\n例如图里的线、图片边缘、姓名线不要保留。\n保存后只记录保留下来的横线，暂时不影响选择题批改。',
            wraplength=420,
            font=('Arial', 12, 'bold'),
        ).pack(anchor='w', pady=(0, 8))
        keep_text = scrolledtext.ScrolledText(right, width=36, height=12, font=('Consolas', 15), wrap=tk.WORD)
        keep_text.pack(fill=tk.BOTH, expand=True)
        keep_text.insert('1.0', '\n'.join(str(item.get('index')) for item in lines))
        ttk.Label(
            right,
            text='题号对应（可选）：左边写红框编号，右边写真实题号/小题号。例：1=13，2=20(1)。',
            wraplength=420,
            font=('Arial', 10, 'bold'),
        ).pack(anchor='w', pady=(8, 4))
        label_text = scrolledtext.ScrolledText(right, width=36, height=8, font=('Consolas', 13), wrap=tk.WORD)
        label_text.pack(fill=tk.BOTH, expand=True)
        label_text.insert('1.0', self.default_direct_subjective_label_text(lines))
        status_var = tk.StringVar()
        ttk.Label(right, textvariable=status_var, foreground='#8a4b00', wraplength=420).pack(anchor='w', pady=(8, 0))

        with Image.open(image_file) as source_preview_image:
            source_image_size = source_preview_image.size
        photo_holder = {'photo': None, 'scale': 1.0, 'image_id': None}

        def set_keep_indices(indices):
            keep_text.delete('1.0', tk.END)
            keep_text.insert('1.0', '\n'.join(str(value) for value in sorted(indices)))

        def current_keep_indices():
            return self.parse_direct_subjective_keep_indices(keep_text.get('1.0', tk.END), lines)

        def refresh_preview():
            try:
                keep_indices = current_keep_indices()
            except Exception as e:
                status_var.set(str(e))
                return
            preview = self.make_direct_subjective_line_preview(
                Path(image_file),
                lines,
                keep_indices=keep_indices,
                rejected=rejected,
                max_w=1000,
                max_h=2200,
            )
            photo = ImageTk.PhotoImage(preview)
            photo_holder['photo'] = photo
            photo_holder['scale'] = preview.width / float(source_image_size[0] or preview.width)
            preview_canvas.delete('all')
            photo_holder['image_id'] = preview_canvas.create_image(0, 0, image=photo, anchor='nw')
            preview_canvas.configure(scrollregion=(0, 0, preview.width, preview.height))
            removed_count = len(lines) - len(keep_indices)
            status_var.set(f'当前保留 {len(keep_indices)} 条，删除 {removed_count} 条。灰色为已删除；可直接点击图中红框/橙框删除或恢复。')

        def toggle_line_at_canvas(event):
            try:
                keep_indices = current_keep_indices()
            except Exception as e:
                status_var.set(str(e))
                return
            scale = float(photo_holder.get('scale') or 1.0)
            if scale <= 0:
                return
            image_x = preview_canvas.canvasx(event.x) / scale
            image_y = preview_canvas.canvasy(event.y) / scale
            hit_index = None
            for item in reversed(lines):
                idx = int(item.get('index', 0))
                rect = item.get('template_rect') or {}
                x = float(rect.get('x', item.get('x', 0)))
                y = float(rect.get('y', item.get('y', 0)))
                w = float(rect.get('w', item.get('w', 0)))
                h = float(rect.get('h', item.get('h', 0)))
                if x - 12 <= image_x <= x + w + 12 and y - 24 <= image_y <= y + h + 24:
                    hit_index = idx
                    break
            if hit_index is None:
                return
            if hit_index in keep_indices:
                keep_indices.remove(hit_index)
            else:
                keep_indices.add(hit_index)
            set_keep_indices(keep_indices)
            refresh_preview()

        def on_preview_mousewheel(event):
            preview_canvas.yview_scroll(-1 if event.delta > 0 else 1, 'units')

        preview_canvas.bind('<Button-1>', toggle_line_at_canvas)
        preview_canvas.bind('<MouseWheel>', on_preview_mousewheel)

        def save_structure():
            try:
                keep_indices = current_keep_indices()
                kept = [item for item in lines if int(item.get('index')) in keep_indices]
                labels_by_index = self.parse_direct_subjective_label_map(label_text.get('1.0', tk.END), kept) if kept else {}
                config_path, backup = self.save_direct_subjective_line_structure_with_labels(Path(image_file), kept, side=side, labels_by_index=labels_by_index)
                sync_info = self.ensure_answer_scheme_matches_current_structure()
                backup_text = f'\n旧配置备份：{backup}' if backup else ''
                messagebox.showinfo(
                    '保存完成',
                    f'已保存主观横线结构：{len(kept)} 条\n'
                    f'答案设置已同步：选择题 {sync_info["objective_questions"]} 题，主观空 {sync_info["subjective_blanks"]} 个\n'
                    f'位置：{config_path}{backup_text}',
                    parent=win,
                )
                win.destroy()
            except Exception as e:
                messagebox.showerror('保存失败', str(e), parent=win)

        buttons = ttk.Frame(right)
        buttons.pack(fill=tk.X, pady=(10, 0))
        ttk.Button(buttons, text='预览保留结果', command=refresh_preview).pack(side=tk.LEFT, padx=4)
        ttk.Button(buttons, text='保存结构', command=save_structure).pack(side=tk.LEFT, padx=4)
        ttk.Button(buttons, text='取消', command=win.destroy).pack(side=tk.LEFT, padx=4)
        refresh_preview()

    def make_direct_paper_structure_preview(
        self,
        image_path,
        boxes,
        lines,
        choice_keep_indices=None,
        choice_display_index_by_index=None,
        line_keep_indices=None,
        line_display_index_by_index=None,
        calculation_rect=None,
        max_w=1000,
        max_h=2200,
    ):
        """Render choice squares and subjective regions on one editable page."""
        image = Image.open(image_path).convert('RGB')
        draw = ImageDraw.Draw(image)
        try:
            font = ImageFont.truetype('msyhbd.ttc', 30)
            small_font = ImageFont.truetype('msyhbd.ttc', 22)
        except Exception:
            font = ImageFont.load_default()
            small_font = ImageFont.load_default()
        choice_keep_indices = {int(value) for value in choice_keep_indices} if choice_keep_indices is not None else {int(item.get('index', 0)) for item in boxes}
        line_keep_indices = {int(value) for value in line_keep_indices} if line_keep_indices is not None else {int(item.get('index', 0)) for item in lines}
        choice_display_map = {int(key): int(value) for key, value in (choice_display_index_by_index or {}).items()}
        display_map = {int(key): int(value) for key, value in (line_display_index_by_index or {}).items()}

        for item in boxes:
            rect = item.get('template_rect') or {}
            x = float(rect.get('x', item.get('x', 0))); y = float(rect.get('y', item.get('y', 0)))
            w = float(rect.get('w', item.get('w', 0))); h = float(rect.get('h', item.get('h', 0)))
            index = int(item.get('index', 0))
            kept = index in choice_keep_indices
            color = (220, 0, 0) if kept else (120, 120, 120)
            draw.rectangle((x - 5, y - 5, x + w + 5, y + h + 5), outline=color, width=4 if kept else 2)
            if not kept:
                draw.line((x - 3, y - 3, x + w + 3, y + h + 3), fill=color, width=2)
                draw.line((x + w + 3, y - 3, x - 3, y + h + 3), fill=color, width=2)
            shown = choice_display_map.get(index, index)
            draw.text((x, max(0, y - 38)), str(shown) if kept else f'x{shown}', fill=color, font=small_font)

        for item in lines:
            rect = item.get('template_rect') or {}
            x = float(rect.get('x', item.get('x', 0))); y = float(rect.get('y', item.get('y', 0)))
            w = float(rect.get('w', item.get('w', 0))); h = float(rect.get('h', item.get('h', 0)))
            index = int(item.get('index', 0))
            kept = index in line_keep_indices
            is_drawing = str(item.get('kind') or '').lower() == 'drawing'
            color = (25, 85, 220) if kept and is_drawing else (220, 0, 0) if kept else (120, 120, 120)
            pad_y = 10 if is_drawing else 14
            draw.rectangle((x, y - pad_y, x + w, y + h + pad_y), outline=color, width=6 if kept else 2)
            if not kept:
                draw.line((x, y - pad_y, x + w, y + h + pad_y), fill=color, width=2)
                draw.line((x + w, y - pad_y, x, y + h + pad_y), fill=color, width=2)
            shown = display_map.get(index, index)
            text = f'作图 {shown}' if is_drawing else str(shown)
            draw.text((x, max(0, y - 48)), text if kept else f'x{shown}', fill=color, font=font if kept else small_font)

        if calculation_rect:
            x = float(calculation_rect.get('x', 0)); y = float(calculation_rect.get('y', 0))
            w = float(calculation_rect.get('w', 0)); h = float(calculation_rect.get('h', 0))
            if w > 0 and h > 0:
                draw.rectangle((x, y, x + w, y + h), outline=(150, 35, 210), width=8)
        scale = min(max_w / image.width, max_h / image.height, 1.0)
        if scale < 1.0:
            image = image.resize((int(image.width * scale), int(image.height * scale)), Image.Resampling.LANCZOS)
        return image

    def choose_direct_paper_side(self):
        side_result = {'side': None}
        side_win = tk.Toplevel(self.root)
        side_win.title('选择设置页面')
        side_win.geometry('360x160')
        side_win.resizable(False, False)
        side_win.transient(self.root)
        ttk.Label(side_win, text='这次要设置哪一面？', font=('Arial', 12, 'bold')).pack(fill=tk.X, padx=18, pady=(18, 12))

        def choose_side(value):
            side_result['side'] = value
            side_win.destroy()

        button_row = ttk.Frame(side_win)
        button_row.pack(fill=tk.X, padx=18, pady=8)
        ttk.Button(button_row, text='设置正面', command=lambda: choose_side('front')).pack(side=tk.LEFT, expand=True, fill=tk.X, padx=(0, 8))
        ttk.Button(button_row, text='设置背面', command=lambda: choose_side('back')).pack(side=tk.LEFT, expand=True, fill=tk.X, padx=(8, 0))
        ttk.Button(side_win, text='取消', command=side_win.destroy).pack(pady=(4, 0))
        side_win.protocol('WM_DELETE_WINDOW', side_win.destroy)
