    def find_direct_paper_structure_template_pair(self, folder_path=None):
        """Find the conventional front/back template pair in the active folder.

        Scanner software changes the zero padding when a folder contains more
        pages, so the same first two pages may be named either 0.1/0.2 or
        0.01/0.02. Keep the pair on one padding convention to avoid combining
        unrelated files when both styles happen to exist.
        """
        root = Path(folder_path or self.selected_folder_path or '')
        if not root.exists() or not root.is_dir():
            return {}
        # The active folder itself is the source of truth. Do not search an
        # mb subfolder, which may hold an older or unrelated template.
        candidates = [root]
        extensions = ('.jpg', '.jpeg', '.png', '.bmp', '.webp', '.tif', '.tiff')

        def find_page(directory, page_name):
            if not directory.exists():
                return None
            wanted = page_name.lower()
            for path in directory.iterdir():
                if path.is_file() and path.suffix.lower() in extensions and path.stem.lower() == wanted:
                    return path
            return None

        page_name_pairs = (
            ('0.1', '0.2'),
            ('0.01', '0.02'),
        )
        for directory in candidates:
            for front_name, back_name in page_name_pairs:
                front = find_page(directory, front_name)
                back = find_page(directory, back_name)
                if front and back:
                    return {
                        'front': front,
                        'back': back,
                        'directory': directory,
                        'page_names': (front_name, back_name),
                    }
        return {}

    def detect_direct_paper_structure_mode_for_image(self, image_path):
        """Use coloured guides automatically when this template clearly has them."""
        try:
            _bgr, red_mask = self.load_direct_red_template_mask(image_path)
            if int(np.count_nonzero(red_mask)) >= 500:
                return 'red'
        except Exception:
            pass
        return 'normal'

    def open_direct_paper_structure_pair_setup(self, pair):
        """Edit the conventional front/back templates in one continuous view."""
        front_path = Path(pair.get('front') or '')
        back_path = Path(pair.get('back') or '')
        if not front_path.exists() or not back_path.exists():
            messagebox.showwarning(
                '未找到模板',
                '需要同时找到 0.1/0.2，或 0.01/0.02 两张正反面模板图。',
            )
            return
        pages = {}
        for side, path in (('front', front_path), ('back', back_path)):
            try:
                boxes = self.detect_direct_choice_boxes_from_red_template(
                    path,
                    include_top=(side == 'back'),
                )
            except Exception:
                boxes = []
            try:
                lines, _rejected = self.detect_direct_subjective_lines_from_red_template(path, side=side)
            except Exception:
                lines = []
            if not boxes and not lines:
                if side == 'back' and ('front' in pages and (pages['front']['boxes'] or pages['front']['lines'])):
                    pass
                else:
                    side_name = '背面' if side == 'back' else '正面'
                    messagebox.showerror('识别失败', f'{side_name}没有识别到小框或横线：{path.name}')
                    return
            with Image.open(path) as source_image:
                image_size = source_image.size
            pages[side] = {
                'path': path,
                'boxes': boxes,
                'lines': lines,
                'box_keep': {int(item.get('index', 0)) for item in boxes},
                'line_keep': {int(item.get('index', 0)) for item in lines},
                'image_size': image_size,
            }

        win = tk.Toplevel(self.root)
        win.title('设置试卷结构（正面 + 背面）')
        self.track_context_window(win)
        screen_width = win.winfo_screenwidth()
        screen_height = win.winfo_screenheight()
        win.geometry(f'{min(1540, max(1020, screen_width - 60))}x{min(960, max(660, screen_height - 70))}')
        win.minsize(980, 620)
        win.transient(self.root)

        left = ttk.Frame(win)
        left.pack(side=tk.LEFT, fill=tk.BOTH, expand=True, padx=(12, 6), pady=12)
        right = ttk.Frame(win)
        right.pack(side=tk.RIGHT, fill=tk.BOTH, padx=(6, 12), pady=12)
        ttk.Label(
            left,
            text='正面在上、背面在下。直接点击红框或蓝框可删除/恢复；编号会跨正反面自动连续重排。',
            font=('Arial', 11, 'bold'), foreground='#8a4b00',
        ).pack(anchor='w', pady=(0, 6))

        canvas_frame = ttk.Frame(left)
        canvas_frame.pack(fill=tk.BOTH, expand=True)
        canvas = tk.Canvas(canvas_frame, bg='#333333', highlightthickness=0)
        vbar = ttk.Scrollbar(canvas_frame, orient=tk.VERTICAL, command=canvas.yview)
        hbar = ttk.Scrollbar(canvas_frame, orient=tk.HORIZONTAL, command=canvas.xview)
        canvas.configure(yscrollcommand=vbar.set, xscrollcommand=hbar.set)
        canvas.grid(row=0, column=0, sticky='nsew')
        vbar.grid(row=0, column=1, sticky='ns')
        hbar.grid(row=1, column=0, sticky='ew')
        canvas_frame.rowconfigure(0, weight=1)
        canvas_frame.columnconfigure(0, weight=1)

        status_var = tk.StringVar()
        ttk.Label(right, text='自动结构', font=('Arial', 12, 'bold')).pack(anchor='w', pady=(0, 6))
        ttk.Label(
            right,
            text='选择题小框会按正面、背面的阅读顺序自动连续分题；主观横线编号也从正面接到背面。无需再填写小框或横线编号表。',
            wraplength=430,
        ).pack(anchor='w')
        ttk.Label(right, textvariable=status_var, foreground='#0B5CAD', wraplength=430).pack(anchor='w', pady=(8, 10))

        existing_calculation = self.direct_calculation_region_config()
        calculation_enabled_var = tk.BooleanVar(value=bool(existing_calculation.get('enabled')))
        calculation_offset_var = tk.DoubleVar(value=float(existing_calculation.get('top_offset') or 0))
        calculation_frame = ttk.LabelFrame(right, text='背面计算题区域')
        calculation_frame.pack(fill=tk.X, pady=(0, 10))
        ttk.Checkbutton(
            calculation_frame,
            text='启用：从背面最后一根保留横线下方裁到页面底部',
            variable=calculation_enabled_var,
        ).pack(anchor='w', padx=8, pady=(6, 3))
        calculation_row = ttk.Frame(calculation_frame)
        calculation_row.pack(fill=tk.X, padx=8, pady=(0, 6))
        ttk.Label(calculation_row, text='上边界微调：').pack(side=tk.LEFT)
        ttk.Spinbox(
            calculation_row, from_=-600, to=600, increment=20,
            textvariable=calculation_offset_var, width=8,
        ).pack(side=tk.LEFT, padx=(4, 0))

        photos = {}
        layout = {}

        def kept_items(side, key):
            state = pages[side]
            keep_key = 'box_keep' if key == 'boxes' else 'line_keep'
            return [item for item in state[key] if int(item.get('index', 0)) in state[keep_key]]

        def display_maps():
            front_boxes = kept_items('front', 'boxes')
            front_lines = kept_items('front', 'lines')
            maps = {
                'front': {
                    'boxes': {int(item.get('index', 0)): pos for pos, item in enumerate(front_boxes, 1)},
                    'lines': {int(item.get('index', 0)): pos for pos, item in enumerate(front_lines, 1)},
                },
                'back': {
                    'boxes': {},
                    'lines': {},
                },
            }
            back_boxes = kept_items('back', 'boxes')
            back_lines = kept_items('back', 'lines')
            maps['back']['boxes'] = {
                int(item.get('index', 0)): len(front_boxes) + pos
                for pos, item in enumerate(back_boxes, 1)
            }
            maps['back']['lines'] = {
                int(item.get('index', 0)): len(front_lines) + pos
                for pos, item in enumerate(back_lines, 1)
            }
            return maps

        def calculation_region():
            if not calculation_enabled_var.get():
                return None
            state = pages['back']
            return self.build_direct_calculation_region(
                kept_items('back', 'lines'),
                state['image_size'][0], state['image_size'][1],
                top_offset=calculation_offset_var.get(),
                boxes=kept_items('back', 'boxes'),
            )

        def refresh_preview():
            maps = display_maps()
            calc_region = calculation_region()
            canvas.delete('all')
            y_offset = 28
            for side, side_name in (('front', '正面 0.1.jpg'), ('back', '背面 0.2.jpg')):
                state = pages[side]
                preview = self.make_direct_paper_structure_preview(
                    state['path'], state['boxes'], state['lines'],
                    choice_keep_indices=state['box_keep'],
                    line_keep_indices=state['line_keep'],
                    choice_display_index_by_index=maps[side]['boxes'],
                    line_display_index_by_index=maps[side]['lines'],
                    calculation_rect=(calc_region or {}).get('rect') if side == 'back' else None,
                    max_w=980, max_h=2200,
                )
                photo = ImageTk.PhotoImage(preview)
                photos[side] = photo
                scale = preview.width / float(state['image_size'][0] or preview.width)
                canvas.create_text(8, y_offset, text=side_name, fill='white', anchor='nw', font=('Arial', 13, 'bold'))
                image_y = y_offset + 28
                canvas.create_image(0, image_y, image=photo, anchor='nw')
                layout[side] = {'y': image_y, 'scale': scale, 'height': preview.height}
                y_offset = image_y + preview.height + 34
            canvas.configure(scrollregion=(0, 0, max(photo.width() for photo in photos.values()), y_offset))
            total_boxes = sum(len(kept_items(side, 'boxes')) for side in ('front', 'back'))
            total_lines = sum(len(kept_items(side, 'lines')) for side in ('front', 'back'))
            drawing_count = sum(
                1 for side in ('front', 'back') for item in kept_items(side, 'lines')
                if str(item.get('kind') or '').lower() == 'drawing'
            )
            status_var.set(
                f'选择小框：{total_boxes} 个，自动对应约 {((total_boxes + 3) // 4)} 题；\n'
                f'主观区域：{total_lines} 个，其中作图 {drawing_count} 个。'
            )

        def toggle_at_canvas(event):
            canvas_x = canvas.canvasx(event.x)
            canvas_y = canvas.canvasy(event.y)
            target_side = None
            for side in ('front', 'back'):
                info = layout.get(side) or {}
                if info.get('y', 0) <= canvas_y <= info.get('y', 0) + info.get('height', 0):
                    target_side = side
                    break
            if not target_side:
                return
            info = layout[target_side]
            scale = float(info.get('scale') or 1.0)
            image_x = canvas_x / scale
            image_y = (canvas_y - info['y']) / scale
            state = pages[target_side]
            for item in reversed(state['boxes']):
                rect = item.get('template_rect') or {}
                x = float(rect.get('x', item.get('x', 0))); y = float(rect.get('y', item.get('y', 0)))
                w = float(rect.get('w', item.get('w', 0))); h = float(rect.get('h', item.get('h', 0)))
                if x - 14 <= image_x <= x + w + 14 and y - 14 <= image_y <= y + h + 14:
                    index = int(item.get('index', 0))
                    if index in state['box_keep']:
                        state['box_keep'].remove(index)
                    else:
                        state['box_keep'].add(index)
                    refresh_preview()
                    return
            for item in reversed(state['lines']):
                rect = item.get('template_rect') or {}
                x = float(rect.get('x', item.get('x', 0))); y = float(rect.get('y', item.get('y', 0)))
                w = float(rect.get('w', item.get('w', 0))); h = float(rect.get('h', item.get('h', 0)))
                pad_y = 18 if str(item.get('kind') or '').lower() == 'drawing' else 24
                if x - 12 <= image_x <= x + w + 12 and y - pad_y <= image_y <= y + h + pad_y:
                    index = int(item.get('index', 0))
                    if index in state['line_keep']:
                        state['line_keep'].remove(index)
                    else:
                        state['line_keep'].add(index)
                    refresh_preview()
                    return

        def save_pair_structure():
            try:
                active_boxes = [(side, kept_items(side, 'boxes')) for side in ('front', 'back')]
                questions_by_side, _box_count = self.build_direct_choice_questions_from_continuous_boxes(active_boxes)
                for side in ('front', 'back'):
                    questions = questions_by_side.get(side) or []
                    if questions:
                        self.save_direct_choice_structure(pages[side]['path'], questions, side=side)
                for side in ('front', 'back'):
                    kept = []
                    for position, item in enumerate(kept_items(side, 'lines'), 1):
                        cloned = copy.deepcopy(item)
                        cloned['index'] = position
                        kept.append(cloned)
                    region = calculation_region() if side == 'back' else None
                    if side == 'back' and not calculation_enabled_var.get():
                        region = {'enabled': False}
                    self.save_direct_subjective_line_structure_with_labels(
                        pages[side]['path'], kept, side=side,
                        labels_by_index=None, calculation_region=region,
                    )
                sync_info = self.ensure_answer_scheme_matches_current_structure()
                messagebox.showinfo(
                    '保存完成',
                    f'正反面结构已一次保存。\n\n'
                    f'答案设置已同步：选择题 {sync_info["objective_questions"]} 题，'
                    f'主观空 {sync_info["subjective_blanks"]} 个。',
                    parent=win,
                )
                win.destroy()
                self.open_saved_direct_paper_structure_preview()
            except Exception as exc:
                messagebox.showerror('保存失败', str(exc), parent=win)

        buttons = ttk.Frame(right)
        buttons.pack(side=tk.BOTTOM, fill=tk.X, pady=(10, 0))
        ttk.Button(buttons, text='保存正反面结构', command=save_pair_structure).pack(side=tk.LEFT, padx=4)
        ttk.Button(buttons, text='取消', command=win.destroy).pack(side=tk.LEFT, padx=4)
        calculation_enabled_var.trace_add('write', lambda *_args: refresh_preview())
        calculation_offset_var.trace_add('write', lambda *_args: refresh_preview())
        canvas.bind('<Button-1>', toggle_at_canvas)
        canvas.bind('<MouseWheel>', lambda event: canvas.yview_scroll(-1 if event.delta > 0 else 1, 'units'))
        refresh_preview()

    def open_direct_paper_structure_setup(
        self,
        side=None,
        image_file=None,
        detection_mode=None,
        after_save_callback=None,
        quick_pair=False,
    ):
        if not self.is_direct_paper_choice_template():
            messagebox.showinfo('提示', '当前模板不是“试卷直接批改”模板。')
            return
        if side is None:
            pair = self.find_direct_paper_structure_template_pair()
            if pair:
                self.open_direct_paper_structure_pair_setup(pair)
                return
            side = self.choose_direct_paper_side()
        if not side:
            return
        if detection_mode is None:
            detection_mode = self.choose_direct_paper_structure_detection_mode()
        if not detection_mode:
            return
        red_template = detection_mode == 'red'
        side_name = '背面' if side == 'back' else '正面'
        if not image_file:
            image_file = filedialog.askopenfilename(
                title=f'选择{side_name}空白试卷模板图片',
                initialdir=self.last_open_dir,
                filetypes=[('图片文件', '*.jpg;*.jpeg;*.png;*.bmp;*.webp;*.tif;*.tiff'), ('所有文件', '*.*')],
            )
        if not image_file:
            return
        image_path = Path(image_file)
        self.last_open_dir = str(image_path.parent)
        box_error = ''
        line_error = ''
        boxes = []
        assignment_text = ''
        choice_warnings = []
        used_indices = set()
        choice_preview = None
        lines = []
        rejected = []
        try:
            box_detector = self.detect_direct_choice_boxes_from_red_template if red_template else self.detect_direct_choice_boxes_from_blank
            boxes = box_detector(image_path, include_top=(side == 'back'))
            assignment_text = self.format_direct_choice_assignment_text(boxes, side=side, use_existing=False) if boxes else ''
            choice_warnings, used_indices = self.validate_direct_choice_assignment(assignment_text, boxes, side=side, prefer_current_order=True) if boxes else ([], set())
            choice_preview = self.make_direct_choice_boxes_preview(image_path, boxes, used_indices=used_indices) if boxes else None
        except Exception as e:
            box_error = str(e)
        try:
            line_detector = self.detect_direct_subjective_lines_from_red_template if red_template else self.detect_direct_subjective_lines_from_blank
            lines, rejected = line_detector(image_path, side=side)
        except Exception as e:
            line_error = str(e)
        if not boxes and not lines:
            if side == 'back':
                pass
            else:
                messagebox.showerror('识别失败', f'选择题小框和主观横线都没有识别到。\n\n小框：{box_error or "无"}\n横线：{line_error or "无"}')
                return

        win = tk.Toplevel(self.root)
        win.title(f'设置试卷结构（{side_name}：小框+横线）')
        self.track_context_window(win)
        screen_width = win.winfo_screenwidth()
        screen_height = win.winfo_screenheight()
        window_width = min(1480, max(980, screen_width - 70))
        window_height = min(920, max(620, screen_height - 90))
        win.geometry(f'{window_width}x{window_height}')
        win.minsize(900, 560)
        win.resizable(True, True)
        win.transient(self.root)

        left = ttk.Frame(win)
        left.pack(side=tk.LEFT, fill=tk.BOTH, expand=True, padx=12, pady=12)
        right = ttk.Frame(win)
        right.pack(side=tk.RIGHT, fill=tk.BOTH, padx=(0, 12), pady=12)

        flow_hint = '（快捷双面流程）' if quick_pair else ''
        ttk.Label(left, text=f'{side_name}{flow_hint}：识别到 {len(boxes)} 个选择题小框，{len(lines)} 条主观横线', font=('Arial', 11, 'bold')).pack(anchor='w')
        preview_tabs = ttk.Notebook(left)
        preview_tabs.pack(fill=tk.BOTH, expand=True, pady=(8, 0))
        choice_tab = ttk.Frame(preview_tabs)
        line_tab = ttk.Frame(preview_tabs)
        preview_tabs.add(choice_tab, text='选择题小框')
        preview_tabs.add(line_tab, text='主观横线')

        choice_canvas = tk.Canvas(choice_tab, bg='#333333', highlightthickness=0)
        choice_vbar = ttk.Scrollbar(choice_tab, orient=tk.VERTICAL, command=choice_canvas.yview)
        choice_hbar = ttk.Scrollbar(choice_tab, orient=tk.HORIZONTAL, command=choice_canvas.xview)
        choice_canvas.configure(yscrollcommand=choice_vbar.set, xscrollcommand=choice_hbar.set)
        choice_canvas.grid(row=0, column=0, sticky='nsew')
        choice_vbar.grid(row=0, column=1, sticky='ns')
        choice_hbar.grid(row=1, column=0, sticky='ew')
        choice_tab.rowconfigure(0, weight=1)
        choice_tab.columnconfigure(0, weight=1)
        line_canvas = tk.Canvas(line_tab, bg='#333333', highlightthickness=0)
        line_vbar = ttk.Scrollbar(line_tab, orient=tk.VERTICAL, command=line_canvas.yview)
        line_hbar = ttk.Scrollbar(line_tab, orient=tk.HORIZONTAL, command=line_canvas.xview)
        line_canvas.configure(yscrollcommand=line_vbar.set, xscrollcommand=line_hbar.set)
        line_canvas.grid(row=0, column=0, sticky='nsew')
        line_vbar.grid(row=0, column=1, sticky='ns')
        line_hbar.grid(row=1, column=0, sticky='ew')
        line_tab.rowconfigure(0, weight=1)
        line_tab.columnconfigure(0, weight=1)
        # Keep the former two specialised canvases for their existing edit
        # helpers, but show one combined canvas to the teacher.
        preview_tabs.pack_forget()
        ttk.Label(left, text='红框＝选择小框；红框/蓝框＝填空横线或作图区。直接点击任一框可取消或恢复。', foreground='#8a4b00').pack(anchor='w', pady=(2, 4))
        combined_frame = ttk.Frame(left)
        combined_frame.pack(fill=tk.BOTH, expand=True, pady=(4, 0))
        structure_canvas = tk.Canvas(combined_frame, bg='#333333', highlightthickness=0)
        structure_vbar = ttk.Scrollbar(combined_frame, orient=tk.VERTICAL, command=structure_canvas.yview)
        structure_hbar = ttk.Scrollbar(combined_frame, orient=tk.HORIZONTAL, command=structure_canvas.xview)
        structure_canvas.configure(yscrollcommand=structure_vbar.set, xscrollcommand=structure_hbar.set)
        structure_canvas.grid(row=0, column=0, sticky='nsew')
        structure_vbar.grid(row=0, column=1, sticky='ns')
        structure_hbar.grid(row=1, column=0, sticky='ew')
        combined_frame.rowconfigure(0, weight=1)
        combined_frame.columnconfigure(0, weight=1)

        choice_frame = ttk.LabelFrame(right, text='选择题小框归类')
        choice_frame.pack(fill=tk.BOTH, expand=True)
        ttk.Label(choice_frame, text='点左侧“选择题小框”预览里的红框可删除/恢复；右侧结构会自动重排。每行一题，建议用 1.ABCD、2.ABCD。', wraplength=470, font=('Arial', 11, 'bold')).pack(anchor='w', padx=8, pady=(8, 4))
        choice_text = scrolledtext.ScrolledText(choice_frame, width=42, height=12, font=('Consolas', 15), wrap=tk.WORD)
        choice_text.pack(fill=tk.BOTH, expand=True, padx=8, pady=(0, 8))
        choice_text.insert('1.0', assignment_text)
        initial_choice_warning = box_error if box_error else ('；'.join(choice_warnings[:3]) if choice_warnings else '选择题结构检查通过。')
        choice_warning_var = tk.StringVar(value=initial_choice_warning)
        ttk.Label(choice_frame, textvariable=choice_warning_var, foreground='#8a4b00', wraplength=470).pack(anchor='w', padx=8, pady=(0, 8))

        line_frame = ttk.LabelFrame(right, text='主观横线保留')
        line_frame.pack(fill=tk.BOTH, expand=True, pady=(10, 0))
        ttk.Label(line_frame, text='点左侧“主观横线”预览里的红框可删除/恢复；这里也可以直接删编号。', wraplength=470, font=('Arial', 11, 'bold')).pack(anchor='w', padx=8, pady=(8, 4))
        line_text = scrolledtext.ScrolledText(line_frame, width=42, height=6, font=('Consolas', 15), wrap=tk.WORD)
        line_text.pack(fill=tk.BOTH, expand=True, padx=8, pady=(0, 8))
        line_text.insert('1.0', '\n'.join(str(item.get('index')) for item in lines))
        ttk.Label(
            line_frame,
            text='题号对应（可选）：左边写红框编号，右边写真实题号/小题号。例：1=13，2=20(1)。',
            wraplength=470,
            font=('Arial', 10, 'bold'),
        ).pack(anchor='w', padx=8, pady=(0, 4))
        line_label_text = scrolledtext.ScrolledText(line_frame, width=42, height=5, font=('Consolas', 13), wrap=tk.WORD)
        line_label_text.pack(fill=tk.BOTH, expand=True, padx=8, pady=(0, 8))
        line_label_text.insert('1.0', self.default_direct_subjective_label_text(lines))
        line_status_var = tk.StringVar()
        ttk.Label(line_frame, textvariable=line_status_var, foreground='#8a4b00', wraplength=470).pack(anchor='w', padx=8, pady=(0, 8))

        other_side = 'back' if side == 'front' else 'front'
        other_side_name = '背面' if other_side == 'back' else '正面'
        clear_other_side_var = tk.BooleanVar(value=(side == 'front'))
        ttk.Checkbutton(
            line_frame,
            text=f'保存时清除旧{other_side_name}结构，避免旧试卷串进答案设置',
            variable=clear_other_side_var,
        ).pack(anchor='w', padx=8, pady=(0, 8))

        with Image.open(image_path) as source_preview_image:
            source_image_size = source_preview_image.size
        existing_calculation_region = self.direct_calculation_region_config() if side == 'back' else {}
        calculation_enabled_var = tk.BooleanVar(
            value=bool(side == 'back' and existing_calculation_region.get('enabled'))
        )
        calculation_top_offset_var = tk.DoubleVar(
            value=float(existing_calculation_region.get('top_offset') or 0)
        )
        calculation_frame = None
        if side == 'back':
            calculation_frame = ttk.LabelFrame(right, text='背面计算题区域（无标准答案）')
            calculation_frame.pack(fill=tk.X, pady=(10, 0))
            ttk.Checkbutton(
                calculation_frame,
                text='启用：从最后一根保留横线下方裁到页面底部，全部人工评分',
                variable=calculation_enabled_var,
            ).pack(anchor='w', padx=8, pady=(8, 4))
            offset_row = ttk.Frame(calculation_frame)
            offset_row.pack(fill=tk.X, padx=8, pady=(0, 6))
            ttk.Label(offset_row, text='上边界微调（像素，正数向下）：').pack(side=tk.LEFT)
            ttk.Spinbox(
                offset_row,
                from_=-600,
                to=600,
                increment=20,
                width=8,
                textvariable=calculation_top_offset_var,
            ).pack(side=tk.LEFT, padx=(4, 0))
            ttk.Label(
                calculation_frame,
                text='紫框只是计算题整块裁图，不会进入答案设置或 OCR。题号和小题分值在“设置计算题分值”中填写。',
                foreground='#6b1d86',
                wraplength=470,
            ).pack(anchor='w', padx=8, pady=(0, 8))
        choice_keep_indices = {int(item.get('index', 0)) for item in boxes}
        choice_photo_holder = {'photo': None, 'scale': 1.0}
        line_photo_holder = {'photo': None, 'scale': 1.0}
        structure_photo_holder = {'photo': None, 'scale': 1.0}
        line_keep_indices = {int(item.get('index', 0)) for item in lines}

        def line_items_in_original_order(indices=None):
            index_set = set(line_keep_indices if indices is None else indices)
            return [item for item in lines if int(item.get('index', 0)) in index_set]

        def line_display_index_by_original(indices=None):
            return {
                int(item.get('index', 0)): pos
                for pos, item in enumerate(line_items_in_original_order(indices), 1)
            }

        def normalize_line_assignment_label(label):
            label = unicodedata.normalize('NFKC', str(label or '')).strip()
            label = re.sub(r'\s+', '', label)
            if label and self.is_direct_subjective_drawing_label(label):
                return '作图'
            return label

        def parse_line_keep_box_assignments():
            display_items = line_items_in_original_order()
            display_to_original = {pos: int(item.get('index', 0)) for pos, item in enumerate(display_items, 1)}
            found = []
            labels = {}
            for value in re.split(r'[,，、\s]+', str(line_text.get('1.0', tk.END) or '').strip()):
                if not value:
                    continue
                label_match = re.match(r'^(\d+)\s*(?:=|:|：)\s*(.*?)\s*$', value)
                if label_match:
                    display_index = int(label_match.group(1))
                    label = normalize_line_assignment_label(label_match.group(2))
                elif value.isdigit():
                    display_index = int(value)
                    label = ''
                else:
                    raise ValueError(f'保留编号里有不是数字的内容：{value}')
                if display_index not in display_to_original:
                    raise ValueError(f'编号不存在：{display_index}')
                original = display_to_original[display_index]
                found.append(original)
                if label:
                    labels[original] = label
            return set(found), labels

        def line_labels_by_original_from_text():
            mapping = line_display_index_by_original()
            reverse = {display: original for original, display in mapping.items()}
            labels = {}
            for raw in line_label_text.get('1.0', tk.END).splitlines():
                line = raw.strip()
                if not line or line.startswith('#'):
                    continue
                match = re.match(r'^(\d+)\s*(?:=|:|：|\s)\s*(.*?)\s*$', line)
                if not match:
                    continue
                original = reverse.get(int(match.group(1)))
                if original is None:
                    continue
                label = normalize_line_assignment_label(match.group(2))
                if label:
                    labels[original] = label
            try:
                _keep_indices, keep_box_labels = parse_line_keep_box_assignments()
                labels.update(keep_box_labels)
            except Exception:
                pass
            return labels

        def set_line_keep_indices(indices, labels_by_original=None):
            nonlocal line_keep_indices
            line_keep_indices = {int(value) for value in indices}
            display_items = line_items_in_original_order()
            labels_by_original = labels_by_original if labels_by_original is not None else line_labels_by_original_from_text()
            line_text.delete('1.0', tk.END)
            line_text.insert('1.0', '\n'.join(str(pos) for pos in range(1, len(display_items) + 1)))
            line_label_text.delete('1.0', tk.END)
            label_rows = [
                '# 可选：给横线绑定真实题号，格式如 1=13、2=14、3=20(1)。左边是当前红框编号。',
                '# 作图题只写 3=作图；不需要在这里写第几题，题号会按答案设置里的内容同步。',
                '# 删除横线后这里会按新的红框编号自动重排。',
            ]
            for pos, item in enumerate(display_items, 1):
                original = int(item.get('index', 0))
                label = labels_by_original.get(original) or str(item.get('answer_label') or item.get('label') or '').strip()
                label_rows.append(f'{pos}={label}')
            line_label_text.insert('1.0', '\n'.join(label_rows))

        def current_line_keep_indices():
            keep_indices, _labels = parse_line_keep_box_assignments()
            return keep_indices

        def current_calculation_region(keep_indices=None):
            if side != 'back' or not calculation_enabled_var.get():
                return None
            keep_indices = current_line_keep_indices() if keep_indices is None else set(keep_indices)
            kept_lines = [item for item in lines if int(item.get('index', 0)) in keep_indices]
            return self.build_direct_calculation_region(
                kept_lines,
                source_image_size[0],
                source_image_size[1],
                top_offset=calculation_top_offset_var.get(),
                boxes=[item for item in boxes if int(item.get('index', 0)) in choice_keep_indices],
            )

        def refresh_structure_preview():
            try:
                keep_lines = current_line_keep_indices() if lines else set()
            except Exception as e:
                line_status_var.set(str(e))
                return
            calculation_region = None
            if side == 'back' and calculation_enabled_var.get():
                try:
                    calculation_region = current_calculation_region(keep_lines)
                except Exception as e:
                    line_status_var.set(str(e))
            preview = self.make_direct_paper_structure_preview(
                image_path,
                boxes,
                lines,
                choice_keep_indices=choice_keep_indices,
                line_keep_indices=keep_lines,
                line_display_index_by_index=line_display_index_by_original(keep_lines),
                calculation_rect=(calculation_region or {}).get('rect'),
                max_w=1000,
                max_h=2200,
            )
            photo = ImageTk.PhotoImage(preview)
            structure_photo_holder['photo'] = photo
            structure_photo_holder['scale'] = preview.width / float(source_image_size[0] or preview.width)
            structure_canvas.delete('all')
            structure_canvas.create_image(0, 0, image=photo, anchor='nw')
            structure_canvas.configure(scrollregion=(0, 0, preview.width, preview.height))
            if lines:
                line_status_var.set(f'当前保留 {len(keep_lines)} 条横线/作图区，删除 {len(lines) - len(keep_lines)} 条。可直接点击左侧任意框取消或恢复。')

        def refresh_line_preview():
            refresh_structure_preview()
            return
            if not lines:
                line_canvas.delete('all')
                line_status_var.set('这一面没有识别到主观横线。')
                return
            try:
                keep_indices = current_line_keep_indices()
            except Exception as e:
                line_status_var.set(str(e))
                return
            calculation_region = None
            if side == 'back' and calculation_enabled_var.get():
                try:
                    calculation_region = current_calculation_region(keep_indices)
                except Exception as e:
                    line_status_var.set(str(e))
            preview = self.make_direct_subjective_line_preview(
                image_path,
                lines,
                keep_indices=keep_indices,
                rejected=rejected,
                max_w=1000,
                max_h=2200,
                display_index_by_index=line_display_index_by_original(keep_indices),
                calculation_rect=(calculation_region or {}).get('rect'),
            )
            photo = ImageTk.PhotoImage(preview)
            line_photo_holder['photo'] = photo
            line_photo_holder['scale'] = preview.width / float(source_image_size[0] or preview.width)
            line_canvas.delete('all')
            line_canvas.create_image(0, 0, image=photo, anchor='nw')
            line_canvas.configure(scrollregion=(0, 0, preview.width, preview.height))
            visible_lines = [item for item in lines if int(item.get('index', 0)) in keep_indices] or lines
            try:
                min_y = min(float((item.get('template_rect') or {}).get('y', item.get('y', 0))) for item in visible_lines)
                scroll_y = max(0.0, (min_y * line_photo_holder['scale'] - 90.0) / max(1.0, float(preview.height)))
                line_canvas.yview_moveto(min(1.0, scroll_y))
            except Exception:
                pass
            calculation_note = '；紫框为计算题区域' if calculation_region else ''
            line_status_var.set(f'当前保留 {len(keep_indices)} 条，删除 {len(lines) - len(keep_indices)} 条{calculation_note}。已滚到第一条横线附近。')

        def toggle_line_at_canvas(event):
            if not lines:
                return
            try:
                keep_indices = current_line_keep_indices()
            except Exception as e:
                line_status_var.set(str(e))
                return
            scale = float(line_photo_holder.get('scale') or 1.0)
            if scale <= 0:
                return
            image_x = line_canvas.canvasx(event.x) / scale
            image_y = line_canvas.canvasy(event.y) / scale
            hit_index = None
            for item in reversed(lines):
                idx = int(item.get('index', 0))
                rect = item.get('template_rect') or {}
                x = float(rect.get('x', item.get('x', 0)))
                y = float(rect.get('y', item.get('y', 0)))
                w = float(rect.get('w', item.get('w', 0)))
                h = float(rect.get('h', item.get('h', 0)))
                if x - 12 <= image_x <= x + w + 12 and y - 24 <= image_y <= y + h + 24:
                    hit_index = idx
                    break
            if hit_index is None:
                return
            labels_by_original = line_labels_by_original_from_text()
            if hit_index in keep_indices:
                keep_indices.remove(hit_index)
            else:
                keep_indices.add(hit_index)
            set_line_keep_indices(keep_indices, labels_by_original=labels_by_original)
            refresh_line_preview()

        def on_line_mousewheel(event):
            line_canvas.yview_scroll(-1 if event.delta > 0 else 1, 'units')

        def clear_all_lines():
            labels_by_original = line_labels_by_original_from_text()
            set_line_keep_indices(set(), labels_by_original=labels_by_original)
            refresh_line_preview()

        line_canvas.bind('<Button-1>', toggle_line_at_canvas)
        line_canvas.bind('<MouseWheel>', on_line_mousewheel)

        def current_choice_boxes():
            return [item for item in boxes if int(item.get('index', 0)) in choice_keep_indices]

        def refresh_choice_preview():
            refresh_structure_preview()
            return
            if not boxes:
                choice_canvas.delete('all')
                choice_canvas.create_text(30, 30, text='这一面没有识别到选择题小框。', fill='white', anchor='nw')
                return
            try:
                _warnings, active_used = self.validate_direct_choice_assignment(
                    choice_text.get('1.0', tk.END),
                    current_choice_boxes(),
                    side=side,
                    prefer_current_order=True,
                )
            except Exception:
                active_used = set()
            preview = self.make_direct_choice_boxes_preview(
                image_path,
                boxes,
                used_indices=active_used,
                keep_indices=choice_keep_indices,
            )
            photo = ImageTk.PhotoImage(preview)
            choice_photo_holder['photo'] = photo
            choice_photo_holder['scale'] = preview.width / float(source_image_size[0] or preview.width)
            choice_canvas.delete('all')
            choice_canvas.create_image(0, 0, image=photo, anchor='nw')
            choice_canvas.configure(scrollregion=(0, 0, preview.width, preview.height))

        def rebuild_choice_assignment_from_kept():
            active_boxes = current_choice_boxes()
            choice_text.delete('1.0', tk.END)
            if active_boxes:
                choice_text.insert('1.0', self.format_direct_choice_assignment_text(active_boxes, side=side, use_existing=False))
            refresh_choice_warning()
            refresh_choice_preview()

        def toggle_choice_at_canvas(event):
            if not boxes:
                return
            scale = float(choice_photo_holder.get('scale') or 1.0)
            if scale <= 0:
                return
            image_x = choice_canvas.canvasx(event.x) / scale
            image_y = choice_canvas.canvasy(event.y) / scale
            hit_index = None
            for item in reversed(boxes):
                idx = int(item.get('index', 0))
                rect = item.get('template_rect') or {}
                x = float(rect.get('x', 0))
                y = float(rect.get('y', 0))
                w = float(rect.get('w', 0))
                h = float(rect.get('h', 0))
                if x - 14 <= image_x <= x + w + 14 and y - 14 <= image_y <= y + h + 14:
                    hit_index = idx
                    break
            if hit_index is None:
                return
            if hit_index in choice_keep_indices:
                choice_keep_indices.remove(hit_index)
            else:
                choice_keep_indices.add(hit_index)
            rebuild_choice_assignment_from_kept()

        def on_choice_mousewheel(event):
            choice_canvas.yview_scroll(-1 if event.delta > 0 else 1, 'units')

        choice_canvas.bind('<Button-1>', toggle_choice_at_canvas)
        choice_canvas.bind('<MouseWheel>', on_choice_mousewheel)

        def toggle_structure_at_canvas(event):
            scale = float(structure_photo_holder.get('scale') or 1.0)
            if scale <= 0:
                return
            image_x = structure_canvas.canvasx(event.x) / scale
            image_y = structure_canvas.canvasy(event.y) / scale
            # Choice boxes are intentionally checked first: they are smaller
            # and more precise than the enlarged subjective hit areas.
            for item in reversed(boxes):
                index = int(item.get('index', 0))
                rect = item.get('template_rect') or {}
                x = float(rect.get('x', item.get('x', 0))); y = float(rect.get('y', item.get('y', 0)))
                w = float(rect.get('w', item.get('w', 0))); h = float(rect.get('h', item.get('h', 0)))
                if x - 14 <= image_x <= x + w + 14 and y - 14 <= image_y <= y + h + 14:
                    if index in choice_keep_indices:
                        choice_keep_indices.remove(index)
                    else:
                        choice_keep_indices.add(index)
                    rebuild_choice_assignment_from_kept()
                    return
            try:
                keep_indices = current_line_keep_indices()
            except Exception as e:
                line_status_var.set(str(e))
                return
            for item in reversed(lines):
                index = int(item.get('index', 0))
                rect = item.get('template_rect') or {}
                x = float(rect.get('x', item.get('x', 0))); y = float(rect.get('y', item.get('y', 0)))
                w = float(rect.get('w', item.get('w', 0))); h = float(rect.get('h', item.get('h', 0)))
                pad_y = 18 if str(item.get('kind') or '').lower() == 'drawing' else 24
                if x - 12 <= image_x <= x + w + 12 and y - pad_y <= image_y <= y + h + pad_y:
                    labels_by_original = line_labels_by_original_from_text()
                    if index in keep_indices:
                        keep_indices.remove(index)
                    else:
                        keep_indices.add(index)
                    set_line_keep_indices(keep_indices, labels_by_original=labels_by_original)
                    refresh_structure_preview()
                    return

        structure_canvas.bind('<Button-1>', toggle_structure_at_canvas)
        structure_canvas.bind('<MouseWheel>', lambda event: structure_canvas.yview_scroll(-1 if event.delta > 0 else 1, 'units'))

        def refresh_choice_warning():
            active_boxes = current_choice_boxes()
            if not active_boxes:
                choice_warning_var.set(f'这一面当前没有保留选择题小框，将只保存主观横线。{box_error}')
                return
            warnings, _used = self.validate_direct_choice_assignment(choice_text.get('1.0', tk.END), active_boxes, side=side, prefer_current_order=True)
            prefix = f'选择题小框：保留 {len(active_boxes)} 个，删除 {len(boxes) - len(active_boxes)} 个。'
            choice_warning_var.set(prefix + ('；'.join(warnings[:3]) if warnings else '结构检查通过。'))

        def save_structure():
            try:
                saved_choice = False
                saved_lines = False
                choice_backup = None
                line_backup = None
                active_boxes = current_choice_boxes()
                if active_boxes:
                    warnings, _used = self.validate_direct_choice_assignment(choice_text.get('1.0', tk.END), active_boxes, side=side, prefer_current_order=True)
                    blocking = [item for item in warnings if '格式可疑' in item or '重复引用' in item or '不存在' in item or '没有填写选项编号' in item]
                    if blocking and not messagebox.askyesno('选择题结构有可疑项', '检测到这些问题：\n\n' + '\n'.join(blocking[:8]) + '\n\n仍然保存吗？', parent=win):
                        return
                    questions = self.parse_direct_choice_assignment_text(choice_text.get('1.0', tk.END), active_boxes, side=side, prefer_current_order=True)
                    if questions:
                        if not self.confirm_direct_choice_structure_preview([(side_name, image_path, questions)], f'{side_name}：{self.direct_choice_question_option_summary(questions)}'):
                            return
                        choice_backup = self.save_direct_choice_structure(image_path, questions, side=side)
                        saved_choice = True
                keep_indices = current_line_keep_indices() if lines else set()
                kept_original = [item for item in lines if int(item.get('index')) in keep_indices]
                labels_by_original = line_labels_by_original_from_text() if kept_original else {}
                kept = []
                for pos, item in enumerate(kept_original, 1):
                    cloned = copy.deepcopy(item)
                    cloned['original_index'] = int(item.get('index', pos) or pos)
                    cloned['index'] = pos
                    kept.append(cloned)
                labels_by_index = {
                    pos: labels_by_original.get(int(item.get('original_index', item.get('index', pos)) or pos))
                    for pos, item in enumerate(kept, 1)
                    if labels_by_original.get(int(item.get('original_index', item.get('index', pos)) or pos))
                }
                calculation_region = None
                if side == 'back':
                    calculation_region = current_calculation_region(keep_indices) if calculation_enabled_var.get() else {'enabled': False}
                _line_path, line_backup = self.save_direct_subjective_line_structure_with_labels(
                    image_path,
                    kept,
                    side=side,
                    labels_by_index=labels_by_index,
                    calculation_region=calculation_region,
                )
                saved_lines = True
                if not saved_choice and not saved_lines:
                    messagebox.showwarning('提示', '没有可保存的小框或横线。', parent=win)
                    return
                detail = []
                if saved_choice:
                    detail.append(f'选择题结构已保存，备份：{choice_backup}')
                if saved_lines:
                    detail.append(f'主观横线结构已保存：{len(kept) if lines else 0} 条，备份：{line_backup or "无"}')
                if side == 'back':
                    detail.append('计算题区域：已启用（无标准答案，人工评分）' if calculation_enabled_var.get() else '计算题区域：未启用')
                if clear_other_side_var.get():
                    cleared = self.clear_direct_paper_side_structure(other_side)
                    if cleared.get('choice') or cleared.get('subjective'):
                        detail.append(f'已清除旧{other_side_name}结构')
                sync_info = self.ensure_answer_scheme_matches_current_structure()
                detail.append(f'答案设置已同步：选择题 {sync_info["objective_questions"]} 题，主观空 {sync_info["subjective_blanks"]} 个')
                messagebox.showinfo('保存完成', f'{side_name}试卷结构已保存。\n\n' + '\n'.join(detail), parent=win)
                win.destroy()
                if after_save_callback:
                    self.root.after_idle(after_save_callback)
                else:
                    self.open_saved_direct_paper_structure_preview()
            except Exception as e:
                messagebox.showerror('保存失败', str(e), parent=win)

        buttons = ttk.Frame(right)
        # Keep the action row visible even when a small screen compresses the
        # editable sections above it.
        buttons.pack(side=tk.BOTTOM, fill=tk.X, pady=(10, 0), before=choice_frame)
        ttk.Button(buttons, text='检查选择题', command=refresh_choice_warning).pack(side=tk.LEFT, padx=4)
        ttk.Button(buttons, text='预览横线', command=lambda: (preview_tabs.select(line_tab), refresh_line_preview())).pack(side=tk.LEFT, padx=4)
        ttk.Button(buttons, text='清空本页横线', command=lambda: (preview_tabs.select(line_tab), clear_all_lines())).pack(side=tk.LEFT, padx=4)
        ttk.Button(buttons, text='保存本页结构', command=save_structure).pack(side=tk.LEFT, padx=4)
        ttk.Button(buttons, text='取消', command=win.destroy).pack(side=tk.LEFT, padx=4)
        if side == 'back':
            calculation_enabled_var.trace_add('write', lambda *_args: refresh_line_preview())
            calculation_top_offset_var.trace_add('write', lambda *_args: refresh_line_preview())
        refresh_choice_warning()
        refresh_choice_preview()
        set_line_keep_indices(line_keep_indices)
        refresh_line_preview()

    def format_direct_choice_assignment_text(self, boxes):
        by_center = []
        for box in boxes:
            pixel = box.get('template_pixel') or {}
            by_center.append((box.get('index'), float(pixel.get('x', 0)), float(pixel.get('y', 0))))
        lines = [
            '# 每行一题。冒号后按 A,B,C,D 的顺序写左图红色编号。',
            '# 例：1: 1,2,3,4',
            '# 如果某题在另一面，本面先不要写。',
        ]
        existing_questions = []
        for zone in (getattr(self, 'answer_config', {}) or {}).get('zones', []) or []:
            for question in zone.get('questions', []) or []:
                qno = question.get('question_no_in_zone')
                indices = []
                for opt in ['A', 'B', 'C', 'D']:
                    opt_data = (question.get('options') or {}).get(opt) or {}
                    center = opt_data.get('template_pixel') or {}
                    try:
                        cx = float(center.get('x'))
                        cy = float(center.get('y'))
                    except Exception:
                        continue
                    nearest = min(by_center, key=lambda item: (item[1] - cx) ** 2 + (item[2] - cy) ** 2, default=None)
                    if nearest and (nearest[1] - cx) ** 2 + (nearest[2] - cy) ** 2 <= 35 ** 2:
                        indices.append(str(nearest[0]))
                if qno and indices:
                    existing_questions.append((int(qno), indices))
        if existing_questions:
            for qno, indices in sorted(existing_questions, key=lambda item: item[0]):
                lines.append(f"{qno}: {','.join(indices)}")
            return '\n'.join(lines)
        ordered_boxes = self.sort_direct_choice_boxes_reading_order(boxes)
        for start in range(0, len(ordered_boxes), 4):
            group = ordered_boxes[start:start + 4]
            if len(group) < 4:
                break
            lines.append(f"{start // 4 + 1}: {','.join(str(item['index']) for item in group)}")
        return '\n'.join(lines)

    def validate_direct_choice_assignment(self, text, boxes):
        warnings = []
        used = []
        question_count = 0
        for raw_line in str(text or '').splitlines():
            line = raw_line.strip()
            if not line or line.startswith('#'):
                continue
            match = re.match(r'^(\d+)\s*[:：]\s*(.+)$', line)
            if not match:
                warnings.append(f'格式可疑：{raw_line}')
                continue
            question_count += 1
            numbers = [value for value in re.split(r'[,，、\s]+', match.group(2).strip()) if value]
            if len(numbers) != 4:
                warnings.append(f'第{match.group(1)}题不是4个选项编号，当前是{len(numbers)}个。')
            for value in numbers:
                if value.isdigit():
                    used.append(int(value))
        box_indices = {int(box['index']) for box in boxes}
        used_set = set(used)
        duplicate_used = sorted({value for value in used if used.count(value) > 1})
        missing_refs = sorted(value for value in used_set if value not in box_indices)
        unused = sorted(box_indices - used_set)
        if duplicate_used:
            warnings.append('这些编号被重复引用：' + ', '.join(map(str, duplicate_used)))
        if missing_refs:
            warnings.append('这些编号不存在：' + ', '.join(map(str, missing_refs)))
        if unused:
            warnings.append('有候选框未被使用：' + ', '.join(map(str, unused[:20])) + (' ...' if len(unused) > 20 else ''))
        if len(used) % 4 != 0:
            warnings.append('已使用编号数量不是4的倍数，可能有题目漏了选项。')
        if boxes and question_count == 0:
            warnings.append('还没有填写任何题目结构。')
        return warnings, used_set

    def parse_direct_choice_assignment_text(self, text, boxes):
        box_lookup = {int(box['index']): box for box in boxes}
        questions = []
        for raw_line in str(text or '').splitlines():
            line = raw_line.strip()
            if not line or line.startswith('#'):
                continue
            match = re.match(r'^(\d+)\s*[:：]\s*(.+)$', line)
            if not match:
                raise ValueError(f'格式不正确：{raw_line}\n请按“1: 1,2,3,4”的格式填写。')
            qno = int(match.group(1))
            numbers = [value for value in re.split(r'[,，、\s]+', match.group(2).strip()) if value]
            if len(numbers) < 2:
                raise ValueError(f'第{qno}题至少要填写两个选项编号。')
            if len(numbers) > 4:
                raise ValueError(f'第{qno}题目前最多支持 A-D 四个选项。')
            options = {}
            for opt, number_text in zip(['A', 'B', 'C', 'D'], numbers):
                box_index = int(number_text)
                box = box_lookup.get(box_index)
                if not box:
                    raise ValueError(f'第{qno}题引用了不存在的红色编号：{box_index}')
                options[opt] = {
                    'label': opt,
                    'template_pixel': box['template_pixel'],
                    'template_rect': box['template_rect'],
                    'match_score': box.get('match_score'),
                }
            questions.append({
                'question_no_in_zone': qno,
                'question_label': f'第{qno}题',
                'question_type': 'single',
                'options': options,
            })
        if not questions:
            raise ValueError('没有解析到任何题目。')
        seen = set()
        for question in questions:
            qno = question['question_no_in_zone']
            if qno in seen:
                raise ValueError(f'第{qno}题重复填写了。')
            seen.add(qno)
        return sorted(questions, key=lambda item: item['question_no_in_zone'])

    def direct_choice_existing_box_map_for_question(self, question_no, boxes):
        by_center = []
        for box in boxes:
            pixel = box.get('template_pixel') or {}
            by_center.append((box, float(pixel.get('x', 0)), float(pixel.get('y', 0))))
        for zone in (getattr(self, 'answer_config', {}) or {}).get('zones', []) or []:
            for question in zone.get('questions', []) or []:
                if int(question.get('question_no_in_zone') or -1) != int(question_no):
                    continue
                mapped = {}
                for opt in ['A', 'B', 'C', 'D']:
                    opt_data = (question.get('options') or {}).get(opt) or {}
                    center = opt_data.get('template_pixel') or {}
                    try:
                        cx = float(center.get('x'))
                        cy = float(center.get('y'))
                    except Exception:
                        continue
                    nearest = min(by_center, key=lambda item: (item[1] - cx) ** 2 + (item[2] - cy) ** 2, default=None)
                    if nearest and (nearest[1] - cx) ** 2 + (nearest[2] - cy) ** 2 <= 35 ** 2:
                        mapped[opt] = nearest[0]
                if mapped:
                    return mapped
        return {}

    def direct_choice_fallback_box_map_for_question(self, question_no, boxes):
        ordered_boxes = self.sort_direct_choice_boxes_reading_order(boxes)
        start = max(0, (int(question_no) - 1) * 4)
        group = ordered_boxes[start:start + 4]
        return {opt: box for opt, box in zip(['A', 'B', 'C', 'D'], group)}

    def direct_choice_box_map_for_question(self, question_no, boxes):
        mapped = self.direct_choice_existing_box_map_for_question(question_no, boxes)
        if len(mapped) >= 4:
            return mapped
        fallback = self.direct_choice_fallback_box_map_for_question(question_no, boxes)
        for opt, box in fallback.items():
            mapped.setdefault(opt, box)
        return mapped

    def parse_direct_choice_line(self, raw_line):
        line = raw_line.strip()
        match = re.match(r'^(\d+)\s*[.:：。]\s*(.+)$', line)
        if not match:
            return None, None
        return int(match.group(1)), match.group(2).strip()

    def direct_choice_payload_is_letters(self, payload):
        compact = re.sub(r'[\s,，、]+', '', str(payload or '')).upper()
        return bool(compact) and all(ch in {'A', 'B', 'C', 'D'} for ch in compact)

    def format_direct_choice_assignment_text(self, boxes, side=None, use_existing=True):
        lines = [
            '# 默认写法：1.ABCD 表示第1题有 A/B/C/D 四个选项。',
            '# 如果自动对应错了，才用高级写法：1: 2,4,5,7',
            '# 如果一题跨正反面，可以在本面只保存识别到的那几个框，另一面继续写同一个题号。',
        ]
        existing_qnos = []
        if use_existing:
            for zone in (getattr(self, 'answer_config', {}) or {}).get('zones', []) or []:
                if side and str(zone.get('side') or 'front').lower() != str(side).lower():
                    continue
                for question in zone.get('questions', []) or []:
                    qno = question.get('question_no_in_zone')
                    if qno:
                        existing_qnos.append(int(qno))
        if use_existing and existing_qnos:
            for qno in sorted(set(existing_qnos)):
                lines.append(f'{qno}.ABCD')
            return '\n'.join(lines)
        start_qno = 1
        if side and str(side).lower() == 'back':
            front_qnos = []
            for zone in (getattr(self, 'answer_config', {}) or {}).get('zones', []) or []:
                if str(zone.get('side') or 'front').lower() == 'back':
                    continue
                for question in zone.get('questions', []) or []:
                    try:
                        front_qnos.append(int(question.get('question_no_in_zone') or 0))
                    except Exception:
                        pass
            if front_qnos:
                start_qno = max(front_qnos) + 1
        ordered_boxes = self.sort_direct_choice_boxes_reading_order(boxes)
        for start in range(0, len(ordered_boxes), 4):
            group = ordered_boxes[start:start + 4]
            if len(group) < 1:
                break
            letters = 'ABCD'[:len(group)]
            lines.append(f'{start_qno + start // 4}.{letters}')
        return '\n'.join(lines)

    def direct_choice_existing_options_for_question(self, question_no, side=None, exclude_side=False):
        existing = set()
        for zone in (getattr(self, 'answer_config', {}) or {}).get('zones', []) or []:
            zone_side = str(zone.get('side') or 'front').lower()
            if side:
                target_side = str(side).lower()
                if exclude_side and zone_side == target_side:
                    continue
                if not exclude_side and zone_side != target_side:
                    continue
            for question in zone.get('questions', []) or []:
                try:
                    if int(question.get('question_no_in_zone') or -1) != int(question_no):
                        continue
                except Exception:
                    continue
                existing.update(str(opt).upper() for opt in (question.get('options') or {}).keys())
        return existing

    def validate_direct_choice_assignment(self, text, boxes, side=None, prefer_current_order=False):
        warnings = []
        used = []
        question_count = 0
        ordered_boxes = self.sort_direct_choice_boxes_reading_order(boxes)
        next_box_index = 0
        for raw_line in str(text or '').splitlines():
            line = raw_line.strip()
            if not line or line.startswith('#'):
                continue
            qno, payload = self.parse_direct_choice_line(line)
            if not qno:
                warnings.append(f'格式可疑：{raw_line}')
                continue
            question_count += 1
            if self.direct_choice_payload_is_letters(payload):
                letters = re.sub(r'[\s,，、]+', '', payload).upper()
                if letters != 'ABCD':
                    warnings.append(f'第{qno}题不是 ABCD 完整选项，当前是 {letters}。')
                other_side_options = self.direct_choice_existing_options_for_question(qno, side=side, exclude_side=True)
                target_letters = [opt for opt in letters if opt not in other_side_options] or list(letters)
                box_map = {} if prefer_current_order else self.direct_choice_box_map_for_question(qno, boxes)
                mapped_count = 0
                for opt in target_letters:
                    if opt in box_map:
                        used.append(int(box_map[opt]['index']))
                        mapped_count += 1
                if mapped_count < len(target_letters):
                    missing_count = len(target_letters) - mapped_count
                    while next_box_index < len(ordered_boxes) and missing_count > 0:
                        candidate = ordered_boxes[next_box_index]
                        next_box_index += 1
                        candidate_index = int(candidate['index'])
                        if candidate_index in used:
                            continue
                        used.append(candidate_index)
                        missing_count -= 1
                        mapped_count += 1
                if mapped_count and mapped_count < len(target_letters):
                    warnings.append(f'第{qno}题本面只找到{mapped_count}个选项；如果剩余选项在另一面，可以正常保存。')
                continue
            numbers = [value for value in re.split(r'[,，、\s]+', payload) if value]
            if len(numbers) < 1:
                warnings.append(f'第{qno}题没有填写选项编号。')
            elif len(numbers) != 4:
                warnings.append(f'第{qno}题本面填写了{len(numbers)}个选项编号；跨页题可以少于4个。')
            for value in numbers:
                if value.isdigit():
                    used.append(int(value))
        box_indices = {int(box['index']) for box in boxes}
        used_set = set(used)
        duplicate_used = sorted({value for value in used if used.count(value) > 1})
        missing_refs = sorted(value for value in used_set if value not in box_indices)
        unused = sorted(box_indices - used_set)
        if duplicate_used:
            warnings.append('这些编号被重复引用：' + ', '.join(map(str, duplicate_used)))
        if missing_refs:
            warnings.append('这些编号不存在：' + ', '.join(map(str, missing_refs)))
        if unused:
            warnings.append('有候选框未被使用：' + ', '.join(map(str, unused[:20])) + (' ...' if len(unused) > 20 else ''))
        if boxes and question_count == 0:
            warnings.append('还没有填写任何题目结构。')
        return warnings, used_set

    def parse_direct_choice_assignment_text(self, text, boxes, side=None, prefer_current_order=False):
        box_lookup = {int(box['index']): box for box in boxes}
        ordered_boxes = self.sort_direct_choice_boxes_reading_order(boxes)
        used_box_indices = set()
        next_box_index = 0
        questions = []
        for raw_line in str(text or '').splitlines():
            line = raw_line.strip()
            if not line or line.startswith('#'):
                continue
            qno, payload = self.parse_direct_choice_line(line)
            if not qno:
                raise ValueError(f'格式不正确：{raw_line}\n请按“1.ABCD”或“1: 2,4,5,7”的格式填写。')
            options = {}
            if self.direct_choice_payload_is_letters(payload):
                letters = re.sub(r'[\s,，、]+', '', payload).upper()
                if len(set(letters)) != len(letters):
                    raise ValueError(f'第{qno}题选项重复：{letters}')
                other_side_options = self.direct_choice_existing_options_for_question(qno, side=side, exclude_side=True)
                target_letters = [opt for opt in letters if opt not in other_side_options] or list(letters)
                box_map = {} if prefer_current_order else self.direct_choice_box_map_for_question(qno, boxes)
                for opt in target_letters:
                    box = box_map.get(opt)
                    if not box:
                        while next_box_index < len(ordered_boxes):
                            candidate = ordered_boxes[next_box_index]
                            next_box_index += 1
                            candidate_index = int(candidate['index'])
                            if candidate_index in used_box_indices:
                                continue
                            box = candidate
                            break
                    if not box:
                        continue
                    used_box_indices.add(int(box['index']))
                    options[opt] = {
                        'label': opt,
                        'template_pixel': box['template_pixel'],
                        'template_rect': box['template_rect'],
                        'match_score': box.get('match_score'),
                    }
            else:
                numbers = [value for value in re.split(r'[,，、\s]+', payload) if value]
                if len(numbers) < 1:
                    raise ValueError(f'第{qno}题至少要填写一个选项编号。')
                if len(numbers) > 4:
                    raise ValueError(f'第{qno}题目前最多支持 A-D 四个选项。')
                other_side_options = self.direct_choice_existing_options_for_question(qno, side=side, exclude_side=True)
                option_order = [opt for opt in ['A', 'B', 'C', 'D'] if opt not in other_side_options] or ['A', 'B', 'C', 'D']
                for opt, number_text in zip(option_order, numbers):
                    box_index = int(number_text)
                    box = box_lookup.get(box_index)
                    if not box:
                        raise ValueError(f'第{qno}题引用了不存在的红色编号：{box_index}')
                    used_box_indices.add(box_index)
                    options[opt] = {
                        'label': opt,
                        'template_pixel': box['template_pixel'],
                        'template_rect': box['template_rect'],
                        'match_score': box.get('match_score'),
                    }
            if not options:
                raise ValueError(f'第{qno}题本面没有找到任何可保存的小方框。')
            questions.append({
                'question_no_in_zone': qno,
                'question_label': f'第{qno}题',
                'question_type': 'single',
                'options': options,
            })
        if not questions:
            raise ValueError('没有解析到任何题目。')
        seen = set()
        for question in questions:
            qno = question['question_no_in_zone']
            if qno in seen:
                raise ValueError(f'第{qno}题重复填写了。')
            seen.add(qno)
        return sorted(questions, key=lambda item: item['question_no_in_zone'])

    def build_direct_choice_questions_from_continuous_boxes(self, side_boxes, choice_question_numbers=None):
        questions_by_side = defaultdict(dict)
        option_order = ['A', 'B', 'C', 'D']
        stream = []
        for side, boxes in side_boxes:
            for box in self.sort_direct_choice_boxes_reading_order(boxes):
                stream.append((side, box))
        total_questions = len(stream) // 4
        if choice_question_numbers and len(choice_question_numbers) == total_questions:
            try:
                qnos = [int(x) for x in choice_question_numbers]
            except Exception:
                qnos = list(choice_question_numbers)
        else:
            qnos = list(range(1, total_questions + 1))
        for global_index, (side, box) in enumerate(stream):
            q_idx = global_index // 4
            qno = qnos[q_idx] if q_idx < len(qnos) else (q_idx + 1)
            opt = option_order[global_index % 4]
            question = questions_by_side[side].setdefault(qno, {
                'question_no_in_zone': qno,
                'question_label': f'第{qno}题',
                'question_type': 'single',
                'options': {},
            })
            question['options'][opt] = {
                'label': opt,
                'template_pixel': box['template_pixel'],
                'template_rect': box['template_rect'],
                'match_score': box.get('match_score'),
            }
        return {
            side: [questions[qno] for qno in sorted(questions, key=self.safe_question_sort_key)]
            for side, questions in questions_by_side.items()
        }, len(stream)

    def save_direct_choice_structure(self, image_path, questions, side='front'):
        side = 'back' if str(side or '').lower() == 'back' else 'front'
        paths = getattr(self, 'current_template_paths', {}) or {}
        answer_path = Path(paths.get('answer_config') or '')
        marker_path = Path(paths.get('marker_config') or '')
        base_template_path = Path(paths.get('template_image') or '')
        template_path = base_template_path if side == 'front' else base_template_path.with_name('template_back.jpg')
        if not answer_path or not marker_path or not base_template_path:
            raise RuntimeError('当前模板路径不完整，不能保存结构。')
        if (getattr(self, 'answer_config', {}) or {}).get('mode') == 'direct_paper_choice':
            marker_payload = self.detect_direct_back_corner_markers_robust(Path(image_path))
            if not marker_payload:
                marker_payload = detect_corner_markers(Path(image_path))
        else:
            marker_payload = detect_corner_markers(Path(image_path))
        template_path.parent.mkdir(parents=True, exist_ok=True)
        if Path(image_path).resolve() != template_path.resolve():
            if template_path.exists():
                shutil.copy2(template_path, template_path.with_name(f"{template_path.stem}.backup_{datetime.now().strftime('%Y%m%d_%H%M%S')}{template_path.suffix}"))
            self.copy_direct_template_for_scoring(image_path, template_path)
        if side == 'front':
            if marker_path.exists():
                shutil.copy2(marker_path, marker_path.with_name(f"{marker_path.stem}.backup_{datetime.now().strftime('%Y%m%d_%H%M%S')}.json"))
            atomic_write_json(marker_path, marker_payload)
        with Image.open(template_path) as image:
            width, height = image.size
        markers = {
            name: {'x': round(payload['center']['x'], 2), 'y': round(payload['center']['y'], 2)}
            for name, payload in marker_payload.get('markers', {}).items()
        }
        xs = [markers[name]['x'] for name in ['top_left', 'top_right', 'bottom_right', 'bottom_left']]
        ys = [markers[name]['y'] for name in ['top_left', 'top_right', 'bottom_right', 'bottom_left']]
        marker_diag = float(np.hypot(max(xs) - min(xs), max(ys) - min(ys)))
        for question in questions:
            for option_data in (question.get('options') or {}).values():
                center = option_data.get('template_pixel') or {}
                signature = {}
                for marker_name in ['top_left', 'top_right', 'bottom_right', 'bottom_left']:
                    mx = markers[marker_name]['x']
                    my = markers[marker_name]['y']
                    signature[marker_name] = round(float(np.hypot(center['x'] - mx, center['y'] - my) / marker_diag), 6)
                option_data['marker_signature'] = signature
        if answer_path.exists():
            backup_path = answer_path.with_name(f"{answer_path.stem}.backup_{datetime.now().strftime('%Y%m%d_%H%M%S')}_direct_choice.json")
            shutil.copy2(answer_path, backup_path)
            try:
                config = copy.deepcopy(self.answer_config or {})
            except Exception:
                config = {}
        else:
            backup_path = answer_path
            config = {}
        config['mode'] = 'direct_paper_choice'
        config['direct_mark_threshold'] = float((getattr(self, 'answer_config', {}) or {}).get('direct_mark_threshold', 3.0) or 3.0)
        config['direct_inner_shrink'] = float((getattr(self, 'answer_config', {}) or {}).get('direct_inner_shrink', 0.34) or 0.34)
        config['direct_use_template_diff'] = True
        config['direct_refine_box'] = False
        config['direct_multi_adaptive_gap'] = float((getattr(self, 'answer_config', {}) or {}).get('direct_multi_adaptive_gap', 0.0) or 0.0)
        config['updated_at'] = datetime.now().isoformat(timespec='seconds')
        if side == 'front' or not config.get('template_image'):
            config['template_image'] = {'path': str(base_template_path), 'width': width, 'height': height}
            config['markers'] = markers
            config['marker_diag'] = round(marker_diag, 4)
        sides = config.get('sides') if isinstance(config.get('sides'), dict) else {}
        sides[side] = {
            'template_image': {'path': str(template_path), 'width': width, 'height': height},
            'markers': markers,
            'marker_diag': round(marker_diag, 4),
        }
        config['sides'] = sides
        zone_name = 'paper_back' if side == 'back' else 'paper_front'
        zone_label = '试卷背面选择题' if side == 'back' else '试卷正面选择题'
        zone_payload = {'zone_name': zone_name, 'zone_label': zone_label, 'side': side, 'questions': questions}
        zones = [zone for zone in (config.get('zones') or []) if zone.get('zone_name') != zone_name]
        zones.append(zone_payload)
        config['zones'] = sorted(zones, key=lambda zone: 0 if zone.get('zone_name') == 'paper_front' else 1)
        config['double_sided'] = any(str(zone.get('side') or '').lower() == 'back' for zone in config['zones'])
        atomic_write_json(answer_path, config)
        self.answer_config = config
        self._session_requires_structure = False
        if side == 'front':
            self.marker_config = marker_payload
        self.template_marker_points = self.get_template_marker_points()
        self.available_zone_names = [zone.get('zone_name', f'zone{i + 1}') for i, zone in enumerate(self.answer_config.get('zones', []))]
        self.selected_zones = list(self.available_zone_names)
        self.update_template_ui_state()
        return backup_path

    def open_direct_choice_structure_setup(self):
        if not self.is_direct_paper_choice_template():
            messagebox.showinfo('提示', '当前模板不是“试卷直接批改”模板。')
            return
        if messagebox.askyesno(
            '设置方式',
            '要一次选择“正面+背面”并按题号连续自动识别吗？\n\n'
            '建议双面试卷选“是”，这样跨页题会自动接上。\n'
            '如果只想单独调整某一面，选“否”。',
        ):
            self.open_direct_choice_double_side_structure_setup()
            return
        side = 'back' if messagebox.askyesno(
            '设置哪一面',
            '这次要设置“背面”的选择题结构吗？\n\n选择“是”：设置背面\n选择“否”：设置正面',
        ) else 'front'
        image_file = filedialog.askopenfilename(
            title='选择背面空白模板图片' if side == 'back' else '选择正面空白模板图片',
            initialdir=self.last_open_dir,
            filetypes=[('图片文件', '*.jpg;*.jpeg;*.png;*.bmp;*.webp;*.tif;*.tiff'), ('所有文件', '*.*')],
        )
        if not image_file:
            return
        self.last_open_dir = str(Path(image_file).parent)
        try:
            boxes = self.detect_direct_choice_boxes_from_blank(Path(image_file), include_top=(side == 'back'))
            assignment_text = self.format_direct_choice_assignment_text(boxes, side=side)
            used_indices = set()
            for raw_line in assignment_text.splitlines():
                line = raw_line.strip()
                if not line or line.startswith('#') or ':' not in line and '：' not in line:
                    continue
                payload = re.split(r'[:：]', line, maxsplit=1)[-1]
                for value in re.split(r'[,，、\s]+', payload):
                    if value.strip().isdigit():
                        used_indices.add(int(value.strip()))
            _warnings, used_indices = self.validate_direct_choice_assignment(assignment_text, boxes, side=side)
            preview = self.make_direct_choice_boxes_preview(Path(image_file), boxes, used_indices=used_indices)
        except Exception as e:
            messagebox.showerror('识别失败', str(e))
            return
        win = tk.Toplevel(self.root)
        win.title('设置试卷选择题结构（背面）' if side == 'back' else '设置试卷选择题结构（正面）')
        self.track_context_window(win)
        win.geometry('1380x880')
        win.minsize(1180, 720)
        win.transient(self.root)
        left = ttk.Frame(win)
        left.pack(side=tk.LEFT, fill=tk.BOTH, expand=True, padx=12, pady=12)
        right = ttk.Frame(win)
        right.pack(side=tk.RIGHT, fill=tk.BOTH, expand=True, padx=(0, 12), pady=12)
        ttk.Label(left, text=f'{"背面" if side == "back" else "正面"}：识别到 {len(boxes)} 个候选小方框', font=('Arial', 10, 'bold')).pack(anchor='w')
        preview_photo = ImageTk.PhotoImage(preview)
        preview_label = ttk.Label(left, image=preview_photo, anchor='center')
        preview_label.image = preview_photo
        preview_label.pack(fill=tk.BOTH, expand=True)
        ttk.Label(
            right,
            text='按左图红色编号归类。每行一题，直接写 1.ABCD、2.ABCD；如果自动归类不对，再用 1: 2,4,5,7 这种编号方式微调。',
            wraplength=470,
            font=('Arial', 13, 'bold'),
        ).pack(anchor='w', pady=(0, 8))
        text = scrolledtext.ScrolledText(right, width=42, height=24, font=('Consolas', 16), wrap=tk.WORD)
        text.pack(fill=tk.BOTH, expand=True)
        text.insert('1.0', assignment_text)
        warning_var = tk.StringVar()
        ttk.Label(right, textvariable=warning_var, foreground='#a35b00', wraplength=470, font=('Arial', 12)).pack(anchor='w', pady=(6, 0))

        def refresh_warning():
            warnings, _used = self.validate_direct_choice_assignment(text.get('1.0', tk.END), boxes, side=side)
            if warnings:
                warning_var.set('提示：' + '；'.join(warnings[:3]))
            else:
                warning_var.set('结构检查通过：每题4个选项，没有重复引用。')

        refresh_warning()

        def save_structure():
            try:
                warnings, _used = self.validate_direct_choice_assignment(text.get('1.0', tk.END), boxes, side=side)
                blocking = [item for item in warnings if '格式可疑' in item or '重复引用' in item or '不存在' in item or '没有填写选项编号' in item]
                if blocking:
                    if not messagebox.askyesno(
                        '结构有可疑项',
                        '检测到这些问题：\n\n' + '\n'.join(blocking[:8]) + '\n\n仍然保存吗？',
                        parent=win,
                    ):
                        return
                questions = self.parse_direct_choice_assignment_text(text.get('1.0', tk.END), boxes, side=side)
                if not self.confirm_direct_choice_structure_preview(
                    [('背面' if side == 'back' else '正面', Path(image_file), questions)],
                    f'{"背面" if side == "back" else "正面"}：{self.direct_choice_question_option_summary(questions)}',
                ):
                    return
                backup_path = self.save_direct_choice_structure(Path(image_file), questions, side=side)
                sync_info = self.ensure_answer_scheme_matches_current_structure()
                messagebox.showinfo(
                    '保存完成',
                    f'{"背面" if side == "back" else "正面"}选择题结构已保存。\n'
                    f'题目数：{len(questions)}\n'
                    f'答案设置已同步：选择题 {sync_info["objective_questions"]} 题，主观空 {sync_info["subjective_blanks"]} 个\n'
                    f'备份：{backup_path}',
                    parent=win,
                )
                win.destroy()
            except Exception as e:
                messagebox.showerror('保存失败', str(e), parent=win)

        buttons = ttk.Frame(right)
        buttons.pack(fill=tk.X, pady=(8, 0))
        ttk.Button(buttons, text='检查结构', command=refresh_warning).pack(side=tk.LEFT, padx=4)
        ttk.Button(buttons, text='保存结构', command=save_structure).pack(side=tk.LEFT, padx=4)
        ttk.Button(buttons, text='取消', command=win.destroy).pack(side=tk.LEFT, padx=4)

    def open_direct_choice_double_side_structure_setup(self):
        front_file = filedialog.askopenfilename(
            title='选择正面空白模板图片',
            initialdir=self.last_open_dir,
            filetypes=[('图片文件', '*.jpg;*.jpeg;*.png;*.bmp;*.webp;*.tif;*.tiff'), ('所有文件', '*.*')],
        )
        if not front_file:
            return
        self.last_open_dir = str(Path(front_file).parent)
        back_file = filedialog.askopenfilename(
            title='选择背面空白模板图片',
            initialdir=self.last_open_dir,
            filetypes=[('图片文件', '*.jpg;*.jpeg;*.png;*.bmp;*.webp;*.tif;*.tiff'), ('所有文件', '*.*')],
        )
        if not back_file:
            return
        self.last_open_dir = str(Path(back_file).parent)

        try:
            front_boxes = self.detect_direct_choice_boxes_from_blank(Path(front_file), include_top=False)
            back_boxes = self.detect_direct_choice_boxes_from_blank(Path(back_file), include_top=True)
            choice_qnos = None
            parent_dir = Path(front_file).parent
            try:
                match_res = self.find_folder_answer_template_files(parent_dir)
                word_path = match_res.get('word')
                if word_path:
                    word_payload = self.read_word_answer_template(word_path)
                    choice_answers = self.extract_direct_choice_answers_from_text(word_payload.get('answer_text') or '')
                    if choice_answers:
                        choice_qnos = list(choice_answers.keys())
            except Exception:
                pass
            questions_by_side, total_boxes = self.build_direct_choice_questions_from_continuous_boxes(
                [('front', front_boxes), ('back', back_boxes)],
                choice_question_numbers=choice_qnos,
            )
            full_questions, remainder = divmod(total_boxes, 4)
            front_count = len(front_boxes)
            back_count = len(back_boxes)
            front_questions = questions_by_side.get('front', [])
            back_questions = questions_by_side.get('back', [])
            message = (
                f'正面识别到 {front_count} 个小框，背面识别到 {back_count} 个小框。\n'
                f'合计 {total_boxes} 个小框，可组成 {full_questions} 道完整选择题。'
            )
            if remainder:
                message += f'\n\n注意：还剩 {remainder} 个小框不能组成完整一题，请确认模板是否漏扫或误识别。'
            message += (
                f'\n\n正面保存题号：{self.direct_choice_question_range_text(front_questions)}'
                f'\n背面保存题号：{self.direct_choice_question_range_text(back_questions)}'
                '\n\n是否保存这个正反面连续结构？'
            )
            if not self.confirm_direct_choice_structure_preview(
                [
                    ('正面', Path(front_file), front_questions),
                    ('背面', Path(back_file), back_questions),
                ],
                message.replace('\n\n是否保存这个正反面连续结构？', ''),
            ):
                return
            front_backup = self.save_direct_choice_structure(Path(front_file), front_questions, side='front')
            back_backup = self.save_direct_choice_structure(Path(back_file), back_questions, side='back')
            sync_info = self.ensure_answer_scheme_matches_current_structure()
            messagebox.showinfo(
                '保存完成',
                f'正反面选择题结构已连续保存。\n'
                f'总题数：{full_questions}\n'
                f'答案设置已同步：选择题 {sync_info["objective_questions"]} 题，主观空 {sync_info["subjective_blanks"]} 个\n'
                f'正面备份：{front_backup}\n背面备份：{back_backup}',
            )
        except Exception as e:
            messagebox.showerror('保存失败', str(e))

    def direct_choice_question_range_text(self, questions):
        qnos = [int(q.get('question_no_in_zone')) for q in questions or [] if q.get('question_no_in_zone')]
        if not qnos:
            return '无'
        ranges = []
        start = prev = qnos[0]
        for qno in qnos[1:]:
            if qno == prev + 1:
                prev = qno
                continue
            ranges.append(f'{start}' if start == prev else f'{start}-{prev}')
            start = prev = qno
        ranges.append(f'{start}' if start == prev else f'{start}-{prev}')
        return '、'.join(ranges)

    def open_experiment_structure_setup(self, after_save_callback=None):
        if not self.subjective_items():
            messagebox.showinfo('提示', '当前模板没有主观题配置。')
            return

        image_file = filedialog.askopenfilename(
            title='选择空白模板图片',
            initialdir=self.last_open_dir,
            filetypes=[
                ('图片文件', '*.jpg;*.jpeg;*.png;*.bmp;*.webp;*.tif;*.tiff'),
                ('所有文件', '*.*'),
            ],
        )
        if not image_file:
            return

        try:
            lines, preview = self.detect_experiment_lines_from_blank(Path(image_file))
        except Exception as e:
            messagebox.showerror('识别失败', str(e))
            return

        if not lines:
            messagebox.showwarning('识别结果', '没有在实验题区域识别到横线，请确认空白模板清晰。')
            return

        win = tk.Toplevel(self.root)
        win.title('设置实验题结构')
        self.track_context_window(win)
        win.geometry('980x720')
        win.minsize(820, 560)
        win.transient(self.root)

        left_frame = ttk.Frame(win)
        left_frame.pack(side=tk.LEFT, fill=tk.BOTH, expand=True, padx=12, pady=12)
        right_frame = ttk.Frame(win)
        right_frame.pack(side=tk.RIGHT, fill=tk.BOTH, expand=True, padx=(0, 12), pady=12)

        ttk.Label(left_frame, text='实验题横线编号预览', font=('Arial', 10, 'bold')).pack(anchor='w')
        preview_photo = ImageTk.PhotoImage(preview)
        preview_label = ttk.Label(left_frame, image=preview_photo, anchor='center')
        preview_label.image = preview_photo
        preview_label.pack(fill=tk.BOTH, expand=True)

        ttk.Label(
            right_frame,
            text=f'识别到 {len(lines)} 条横线。默认同一行上的空属于同一个小题，13-18题不用设置。',
            font=('Arial', 11, 'bold'),
        ).pack(anchor='w', pady=(0, 8))
        line_summary = '编号顺序：' + '、'.join(str(line['index']) for line in lines)
        ttk.Label(right_frame, text=line_summary, wraplength=360).pack(anchor='w', pady=(0, 8))
        text = tk.Text(right_frame, width=42, height=28, font=('Consolas', 10))
        text.pack(fill=tk.BOTH, expand=True)
        text.insert('1.0', self.default_experiment_assignment_text(lines))

        def save_structure():
            assignments = self.parse_experiment_assignment_text(text.get('1.0', tk.END), lines)
            if not assignments:
                messagebox.showwarning('提示', '没有解析到有效的实验题结构。', parent=win)
                return
            if not messagebox.askyesno(
                '确认保存',
                '保存后会按新的实验题结构裁图；如果之前已经批过主观题，建议重新批一次实验题部分。\n\n确定保存吗？',
                parent=win,
            ):
                return
            try:
                backup_path = self.save_experiment_structure_from_assignments(assignments)
                self.update_template_ui_state()
                should_run_after_save_callback = callable(after_save_callback)
                messagebox.showinfo('保存完成', f'实验题结构已保存。\n已备份旧配置：\n{backup_path}', parent=win)
                win.destroy()
                if should_run_after_save_callback:
                    self.root.after(100, after_save_callback)
            except Exception as e:
                messagebox.showerror('保存失败', str(e), parent=win)

        buttons = ttk.Frame(right_frame)
        buttons.pack(fill=tk.X, pady=(8, 0))
        ttk.Button(buttons, text='保存结构', command=save_structure).pack(side=tk.LEFT, padx=4)
        ttk.Button(buttons, text='取消', command=win.destroy).pack(side=tk.LEFT, padx=4)

    def refresh_main_result_views(self, payload=None):
        """刷新主界面学生成绩明细、统计汇总与错题分析视图"""
        if payload is not None:
            self.apply_subjective_scores_to_entries(payload)
        if hasattr(self, 'detail_text') and self.detail_text:
            try:
                self.detail_text.delete(1.0, tk.END)
                for entry in self.summary_data:
                    self.display_single_result(entry)
            except Exception:
                pass
        self.update_summary_display()
        self.update_analysis_display()
        self.notify_result_views()
        try:
            self.root.update_idletasks()
        except Exception:
            pass

    def open_llm_grading_settings(self, parent=None):
        """打开大模型智能批改与涂改过滤设置对话框"""
        try:
            import llm_grading_service
        except ImportError:
            messagebox.showerror('错误', '找不到 llm_grading_service 模块。', parent=parent or self.root)
            return

        parent_win = parent or self.root
        cfg = llm_grading_service.load_llm_config()

        win = tk.Toplevel(parent_win)
        win.title('🤖 大模型智能批改与涂改过滤设置 (通义千问 / 本地 Ollama)')
        win.geometry('680x640')
        win.minsize(620, 580)
        win.transient(parent_win)
        win.grab_set()

        content = ttk.Frame(win, padding=16)
        content.pack(fill=tk.BOTH, expand=True)

        ttk.Label(
            content,
            text='多模态大模型智能批改设置（Qwen-VL / OpenAI 兼容协议）',
            font=('Arial', 11, 'bold'),
            foreground='#0B5CAD',
        ).pack(anchor='w', pady=(0, 4))

        desc_text = (
            '说明：用于将基础 OCR 之后剩余的待人工题目（含学生涂改、划线重写、超出横线等）\n'
            '批量送往多模态大模型，自动进行视觉去噪、删除线识别、提取真实答案并智能判定得分。'
        )
        ttk.Label(content, text=desc_text, foreground='#555555', justify=tk.LEFT).pack(anchor='w', pady=(0, 8))

        form = ttk.LabelFrame(content, text='接口参数配置', padding=(12, 8))
        form.pack(fill=tk.X, pady=(0, 8))

        # 1. Endpoint
        r1 = ttk.Frame(form)
        r1.pack(fill=tk.X, pady=3)
        ttk.Label(r1, text='接口地址 (Base URL):', width=18, anchor='w').pack(side=tk.LEFT)
        endpoint_var = tk.StringVar(value=cfg.get('endpoint', ''))
        ttk.Entry(r1, textvariable=endpoint_var, font=('Arial', 9)).pack(side=tk.LEFT, fill=tk.X, expand=True)

        # 2. API Key
        r2 = ttk.Frame(form)
        r2.pack(fill=tk.X, pady=3)
        ttk.Label(r2, text='API Key (密钥):', width=18, anchor='w').pack(side=tk.LEFT)
        key_var = tk.StringVar(value=cfg.get('api_key', ''))
        key_entry = ttk.Entry(r2, textvariable=key_var, show='*', font=('Arial', 9))
        key_entry.pack(side=tk.LEFT, fill=tk.X, expand=True, padx=(0, 4))
        show_key_var = tk.BooleanVar(value=False)
        def toggle_key_show():
            key_entry.configure(show='' if show_key_var.get() else '*')
        ttk.Checkbutton(r2, text='显示', variable=show_key_var, command=toggle_key_show).pack(side=tk.LEFT)

        # 3. Model
        r3 = ttk.Frame(form)
        r3.pack(fill=tk.X, pady=3)
        ttk.Label(r3, text='模型名称 (Model):', width=18, anchor='w').pack(side=tk.LEFT)
        model_var = tk.StringVar(value=cfg.get('model', 'qwen-vl-plus'))
        model_combo = ttk.Combobox(
            r3,
            textvariable=model_var,
            values=[
                'qwen-vl-plus',
                'qwen-vl-max',
                'qwen-vl-ocr',
                'qwen3-vl-plus',
                'qwen3-vl-flash',
                'qwen2.5-vl-7b-instruct',
                'qwen2.5-vl-72b-instruct',
            ],
            width=24,
            font=('Arial', 9),
        )
        model_combo.pack(side=tk.LEFT)
        ttk.Label(r3, text='（推荐 qwen-vl-max 识别最准；qwen-vl-plus 速度最快）', foreground='#666666').pack(side=tk.LEFT, padx=6)

        # 4. Concurrency
        r4 = ttk.Frame(form)
        r4.pack(fill=tk.X, pady=3)
        ttk.Label(r4, text='并发线程数:', width=18, anchor='w').pack(side=tk.LEFT)
        conc_var = tk.IntVar(value=cfg.get('concurrency', 3))
        ttk.Spinbox(r4, from_=1, to=10, textvariable=conc_var, width=6).pack(side=tk.LEFT)
        ttk.Label(r4, text='（建议 3~5 并发，兼顾速度与稳定性）', foreground='#666666').pack(side=tk.LEFT, padx=6)

        # 5. Confidence Threshold
        r5 = ttk.Frame(form)
        r5.pack(fill=tk.X, pady=3)
        ttk.Label(r5, text='置信度阈值:', width=18, anchor='w').pack(side=tk.LEFT)
        conf_var = tk.DoubleVar(value=float(cfg.get('confidence_threshold', 0.85)))
        ttk.Spinbox(r5, from_=0.5, to=0.99, increment=0.05, textvariable=conf_var, width=6).pack(side=tk.LEFT)
        ttk.Label(r5, text='（低于此阈值或字迹模糊时自动退回人工复核，杜绝误杀与脑补）', foreground='#666666').pack(side=tk.LEFT, padx=6)

        # 6. Strictness & Anti-leniency Rule Frame
        rule_frame = ttk.LabelFrame(content, text='判分严格度与语义放水限制（防加字、防脑补、防放水）', padding=(12, 8))
        rule_frame.pack(fill=tk.BOTH, expand=True, pady=(0, 8))

        # Strictness level
        r_mode = ttk.Frame(rule_frame)
        r_mode.pack(fill=tk.X, pady=(0, 4))
        ttk.Label(r_mode, text='评判严格度等级:', width=16, anchor='w').pack(side=tk.LEFT)

        strictness_var = tk.StringVar(value=cfg.get('strictness', 'strict'))
        mode_map = {
            '极严格模式（中高考级：严禁脑补加字，禁止生活口语，错字0分，缺字0分）': 'strict',
            '标准学术模式（常规期中期末：允许规范学术近义词，禁口语）': 'standard',
            '宽容理解模式（随堂练习：语义相近即可给分）': 'lenient',
        }
        rev_mode_map = {v: k for k, v in mode_map.items()}
        current_display = rev_mode_map.get(strictness_var.get(), list(mode_map.keys())[0])

        mode_display_var = tk.StringVar(value=current_display)
        def _on_mode_change(event=None):
            val = mode_map.get(mode_display_var.get(), 'strict')
            strictness_var.set(val)

        mode_combo = ttk.Combobox(
            r_mode,
            textvariable=mode_display_var,
            values=list(mode_map.keys()),
            state='readonly',
            font=('Arial', 9),
        )
        mode_combo.pack(side=tk.LEFT, fill=tk.X, expand=True)
        mode_combo.bind('<<ComboboxSelected>>', _on_mode_change)

        # Custom rules text area
        r_custom = ttk.Frame(rule_frame)
        r_custom.pack(fill=tk.BOTH, expand=True, pady=(4, 0))
        ttk.Label(r_custom, text='自定义限制指令 (Prompt)：', anchor='w').pack(anchor='w', pady=(0, 2))

        txt_container = ttk.Frame(r_custom)
        txt_container.pack(fill=tk.BOTH, expand=True)
        custom_txt = tk.Text(txt_container, height=4, font=('Arial', 9), wrap=tk.WORD)
        custom_txt.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
        custom_scroll = ttk.Scrollbar(txt_container, orient=tk.VERTICAL, command=custom_txt.yview)
        custom_scroll.pack(side=tk.RIGHT, fill=tk.Y)
        custom_txt.configure(yscrollcommand=custom_scroll.set)

        default_custom = cfg.get('custom_rules', llm_grading_service.DEFAULT_CONFIG.get('custom_rules', ''))
        custom_txt.insert('1.0', default_custom)

        # Template buttons
        tpl_row = ttk.Frame(rule_frame)
        tpl_row.pack(fill=tk.X, pady=(4, 0))
        ttk.Label(tpl_row, text='快速填入模板：', foreground='#666666').pack(side=tk.LEFT)

        def _apply_template(tpl_str):
            custom_txt.delete('1.0', tk.END)
            custom_txt.insert('1.0', tpl_str)

        tpl_science = (
            "1. 严禁把切片边缘的试卷印刷题干字计入学生答案；\n"
            "2. 严禁脑补加字，学生漏写字符（如‘S点上方’漏写‘S’）必须判 0 分；\n"
            "3. 严禁使用生活俗语代替学科术语（如‘变大’不可替代‘增大’，‘反光’不可替代‘反射’）；\n"
            "4. 错别字、音近字、形近字一律判 0 分。"
        )
        tpl_liberal = (
            "1. 必须与标准答案字面完全一致，错一字、添一字、漏一字一律判 0 分；\n"
            "2. 严禁同义词放水，字面字形必须准确规范；\n"
            "3. 笔画严重残缺或无法辨识的一律按错字判 0 分。"
        )

        ttk.Button(tpl_row, text='🔬 理科严格防放水模板', command=lambda: _apply_template(tpl_science)).pack(side=tk.LEFT, padx=3)
        ttk.Button(tpl_row, text='📖 语文/文科字面模板', command=lambda: _apply_template(tpl_liberal)).pack(side=tk.LEFT, padx=3)
        ttk.Button(tpl_row, text='🧹 清空', command=lambda: custom_txt.delete('1.0', tk.END)).pack(side=tk.LEFT, padx=3)

        test_result_var = tk.StringVar(value='提示：极严格模式下，系统将在大模型判分后进行代码级字面校验，杜绝漏字、近义词放水。')
        test_label = ttk.Label(content, textvariable=test_result_var, foreground='#555555', wraplength=640)
        test_label.pack(fill=tk.X, pady=(2, 6))

        def do_test():
            test_cfg = {
                'endpoint': endpoint_var.get().strip(),
                'api_key': key_var.get().strip(),
                'model': model_var.get().strip(),
            }
            test_result_var.set('正在测试接口连接，请稍候...')
            win.update()
            ok, msg = llm_grading_service.test_llm_connection(test_cfg)
            if ok:
                test_label.configure(foreground='#28a745')
                test_result_var.set(f"✅ {msg}")
            else:
                test_label.configure(foreground='#dc3545')
                test_result_var.set(f"❌ {msg}")

        def do_save():
            new_cfg = {
                'enabled': True,
                'endpoint': endpoint_var.get().strip(),
                'api_key': key_var.get().strip(),
                'model': model_var.get().strip() or 'qwen-vl-plus',
                'concurrency': max(1, min(10, conc_var.get())),
                'timeout': 30,
                'confidence_threshold': max(0.5, min(0.99, float(conf_var.get()))),
                'strictness': strictness_var.get().strip() or 'strict',
                'custom_rules': custom_txt.get('1.0', tk.END).strip(),
            }
            if llm_grading_service.save_llm_config(new_cfg):
                messagebox.showinfo('保存成功', '大模型配置与严格度规则已成功保存！', parent=win)
                win.destroy()
            else:
                messagebox.showerror('保存失败', '写入配置文件失败。', parent=win)

        def do_reset_default():
            endpoint_var.set(llm_grading_service.DEFAULT_CONFIG['endpoint'])
            key_var.set(llm_grading_service.DEFAULT_CONFIG['api_key'])
            model_var.set(llm_grading_service.DEFAULT_CONFIG['model'])
            conc_var.set(3)
            conf_var.set(llm_grading_service.DEFAULT_CONFIG.get('confidence_threshold', 0.85))
            def_strict = llm_grading_service.DEFAULT_CONFIG.get('strictness', 'strict')
            strictness_var.set(def_strict)
            mode_display_var.set(rev_mode_map.get(def_strict, list(mode_map.keys())[0]))
            custom_txt.delete('1.0', tk.END)
            custom_txt.insert('1.0', llm_grading_service.DEFAULT_CONFIG.get('custom_rules', ''))
            test_result_var.set('已恢复为默认配置，包含极严格中高考防脑补与防放水规则。')

        btn_row = ttk.Frame(content)
        btn_row.pack(fill=tk.X, pady=(10, 0))
        ttk.Button(btn_row, text='⚡ 测试连接', command=do_test).pack(side=tk.LEFT, padx=4)
        ttk.Button(btn_row, text='🔍 试卷切片效果实测', command=lambda: self.open_llm_preview_dialog(win)).pack(side=tk.LEFT, padx=4)
        ttk.Button(btn_row, text='📋 大模型识别结果', command=lambda: self.open_llm_results_review_dialog(win)).pack(side=tk.LEFT, padx=4)
        ttk.Button(btn_row, text='🔄 恢复默认配置', command=do_reset_default).pack(side=tk.LEFT, padx=4)
        ttk.Button(btn_row, text='保存配置', command=do_save).pack(side=tk.RIGHT, padx=4)
        ttk.Button(btn_row, text='取消', command=win.destroy).pack(side=tk.RIGHT, padx=4)

    def open_llm_preview_dialog(self, parent_win, task_item=None, on_apply_callback=None):
        """打开大模型识图与判分效果实测/预览对话框"""
        part = (task_item or {}).get('part', {})
        kind = str(part.get('kind') or '').lower()
        pid = str((task_item or {}).get('part_id') or '').lower()
        if kind in ('calculation', 'drawing') or bool(part.get('manual_only')) or pid.startswith('calc_'):
            messagebox.showinfo('提示', '计算题/作图题属于纯人工评阅题目，不支持大模型判分。', parent=parent_win)
            return

        try:
            import llm_grading_service
        except ImportError:
            messagebox.showerror('错误', '找不到 llm_grading_service 模块。', parent=parent_win)
            return

        cfg = llm_grading_service.load_llm_config()
        if not cfg.get('endpoint') or not cfg.get('api_key'):
            if messagebox.askyesno(
                '需要配置大模型',
                '大模型接口地址或 API Key 尚未配置。\n是否现在打开设置窗口？',
                parent=parent_win,
            ):
                self.open_llm_grading_settings(parent_win)
            return

        win = tk.Toplevel(parent_win)
        win.title('🤖 大模型智能识图与判分效果实测预览')
        win.geometry('720x680')
        win.minsize(660, 600)
        win.transient(parent_win)
        win.grab_set()

        current_crop = {'path': ''}
        if task_item and os.path.exists(task_item.get('crop_path', '')):
            current_crop['path'] = task_item['crop_path']
        else:
            ocr_temp_dir = PROJECT_DIR / 'ocr_temp'
            if not ocr_temp_dir.exists():
                ocr_temp_dir = Path(__file__).resolve().parent / 'ocr_temp'
            if ocr_temp_dir.exists():
                c_files = list(ocr_temp_dir.glob('*.jpg')) + list(ocr_temp_dir.glob('*.png'))
                if c_files:
                    current_crop['path'] = str(c_files[0])

        content = ttk.Frame(win, padding=14)
        content.pack(fill=tk.BOTH, expand=True)

        model_name = cfg.get('model', 'qwen-vl-plus')
        hdr_frame = ttk.Frame(content)
        hdr_frame.pack(fill=tk.X, pady=(0, 6))
        st_name = (task_item or {}).get('entry', {}).get('student_name', '')
        p_label = (task_item or {}).get('part', {}).get('label', '')
        hdr_title = f"多模态视觉大模型识图效果实测 ({model_name})"
        if st_name or p_label:
            hdr_title += f" — 【{st_name} {p_label}】"
        ttk.Label(
            hdr_frame,
            text=hdr_title,
            font=('Arial', 11, 'bold'),
            foreground='#0B5CAD',
        ).pack(side=tk.LEFT)

        # Top Control: Image selection
        img_sel_frame = ttk.LabelFrame(content, text='切片图片来源', padding=(8, 6))
        img_sel_frame.pack(fill=tk.X, pady=(0, 8))

        crop_path_var = tk.StringVar(value=current_crop['path'])
        path_label = ttk.Label(img_sel_frame, textvariable=crop_path_var, foreground='#444444', font=('Consolas', 8))
        path_label.pack(side=tk.LEFT, fill=tk.X, expand=True, padx=(0, 8))

        def choose_local_file():
            f = filedialog.askopenfilename(
                title='选择待测试的学生答题切片图片',
                filetypes=[('图片文件', '*.jpg;*.jpeg;*.png;*.webp'), ('所有文件', '*.*')],
                parent=win,
            )
            if f and os.path.exists(f):
                current_crop['path'] = f
                crop_path_var.set(f)
                update_image_display()

        def pick_random_ocr_temp():
            import random
            ocr_temp_dir = PROJECT_DIR / 'ocr_temp'
            if not ocr_temp_dir.exists():
                ocr_temp_dir = Path(__file__).resolve().parent / 'ocr_temp'
            if ocr_temp_dir.exists():
                c_files = list(ocr_temp_dir.glob('*.jpg')) + list(ocr_temp_dir.glob('*.png'))
                if c_files:
                    pick = random.choice(c_files)
                    current_crop['path'] = str(pick)
                    crop_path_var.set(str(pick))
                    update_image_display()

        ttk.Button(img_sel_frame, text='🎲 换一张历史切片', command=pick_random_ocr_temp).pack(side=tk.RIGHT, padx=2)
        ttk.Button(img_sel_frame, text='📁 本地选图', command=choose_local_file).pack(side=tk.RIGHT, padx=2)

        # Image preview area
        preview_frame = ttk.Frame(content, height=170, relief='groove', borderwidth=1)
        preview_frame.pack(fill=tk.X, pady=(0, 8))
        preview_frame.pack_propagate(False)

        img_label = ttk.Label(preview_frame, text='暂无图片预览', anchor='center')
        img_label.pack(fill=tk.BOTH, expand=True)

        photo_ref = [None]
        def update_image_display():
            p = current_crop['path']
            if p and os.path.exists(p):
                try:
                    im = Image.open(p)
                    im.thumbnail((650, 150), Image.LANCZOS)
                    tk_img = ImageTk.PhotoImage(im)
                    photo_ref[0] = tk_img
                    img_label.configure(image=tk_img, text='')
                except Exception as e:
                    img_label.configure(image='', text=f'图片加载失败: {e}')
            else:
                img_label.configure(image='', text='切片图片不存在，请点击上方按钮选取')

        update_image_display()

        # Question inputs
        input_frame = ttk.LabelFrame(content, text='评分参考标准', padding=(8, 6))
        input_frame.pack(fill=tk.X, pady=(0, 8))

        row1 = ttk.Frame(input_frame)
        row1.pack(fill=tk.X, pady=2)
        ttk.Label(row1, text='参考答案:', width=10, anchor='w').pack(side=tk.LEFT)
        default_ans = ''
        if task_item:
            part = task_item.get('part', {})
            ocr_cfg = part.get('ocr') or {}
            exps = self.subjective_expected_answers_from_config(ocr_cfg)
            default_ans = ' / '.join(exps) if exps else ''
            if not default_ans:
                entry_key = task_item.get('entry_key', '')
                part_id = task_item.get('part_id', '')
                rec = {}
                if hasattr(self, 'current_session_scores') and isinstance(self.current_session_scores, dict):
                    rec = self.current_session_scores.get(entry_key, {}).get(part_id, {})
                prev_exp = rec.get('auto_grade_expected', '') or rec.get('paddle_ocr_expected', '')
                if prev_exp and not str(prev_exp).startswith('关键词：'):
                    default_ans = str(prev_exp)
        ans_var = tk.StringVar(value=default_ans)
        ttk.Entry(row1, textvariable=ans_var, font=('Arial', 9)).pack(side=tk.LEFT, fill=tk.X, expand=True, padx=(0, 12))

        ttk.Label(row1, text='满分:', width=6, anchor='w').pack(side=tk.LEFT)
        default_max_s = 1.0
        if task_item:
            default_max_s = float(task_item.get('part', {}).get('score') or 1.0)
        max_score_var = tk.DoubleVar(value=default_max_s)
        ttk.Spinbox(row1, from_=0.5, to=100.0, increment=0.5, textvariable=max_score_var, width=6).pack(side=tk.LEFT)

        row2 = ttk.Frame(input_frame)
        row2.pack(fill=tk.X, pady=2)
        ttk.Label(row2, text='采分关键词:', width=10, anchor='w').pack(side=tk.LEFT)
        default_kw = ''
        if task_item:
            part = task_item.get('part', {})
            ocr_cfg = part.get('ocr') or {}
            kws = self.split_expected_keywords(ocr_cfg.get('expected_keywords'))
            default_kw = ' / '.join(kws) if kws else ''
        kw_var = tk.StringVar(value=default_kw)
        ttk.Entry(row2, textvariable=kw_var, font=('Arial', 9)).pack(side=tk.LEFT, fill=tk.X, expand=True)

        # Trigger button
        action_bar = ttk.Frame(content)
        action_bar.pack(fill=tk.X, pady=(0, 8))
        test_btn = ttk.Button(action_bar, text='🚀 立即请求大模型识别并判分')
        test_btn.pack(side=tk.LEFT, fill=tk.X, expand=True)

        # Results Display Card
        res_card = ttk.LabelFrame(content, text='🤖 大模型实际识别与评分结果', padding=(12, 10))
        res_card.pack(fill=tk.BOTH, expand=True, pady=(0, 8))

        res_rec_var = tk.StringVar(value='（等待发起测试）')
        res_corr_var = tk.StringVar(value='-')
        res_score_var = tk.StringVar(value='-')
        res_reason_var = tk.StringVar(value='-')
        res_meta_var = tk.StringVar(value='-')

        # Row: Recognized text (Prominent)
        r_rec = ttk.Frame(res_card)
        r_rec.pack(fill=tk.X, pady=3)
        ttk.Label(r_rec, text='识别学生作答：', font=('Arial', 10, 'bold'), width=14, anchor='w').pack(side=tk.LEFT)
        rec_label = ttk.Label(r_rec, textvariable=res_rec_var, font=('Arial', 13, 'bold'), foreground='#0B5CAD')
        rec_label.pack(side=tk.LEFT, fill=tk.X, expand=True)

        # Row: Correction detection
        r_corr = ttk.Frame(res_card)
        r_corr.pack(fill=tk.X, pady=3)
        ttk.Label(r_corr, text='涂改/划线检测：', font=('Arial', 9, 'bold'), width=14, anchor='w').pack(side=tk.LEFT)
        corr_label = ttk.Label(r_corr, textvariable=res_corr_var, font=('Arial', 9))
        corr_label.pack(side=tk.LEFT, fill=tk.X, expand=True)

        # Row: Score
        r_score = ttk.Frame(res_card)
        r_score.pack(fill=tk.X, pady=3)
        ttk.Label(r_score, text='判定得分：', font=('Arial', 10, 'bold'), width=14, anchor='w').pack(side=tk.LEFT)
        score_label = ttk.Label(r_score, textvariable=res_score_var, font=('Arial', 11, 'bold'))
        score_label.pack(side=tk.LEFT, fill=tk.X, expand=True)

        # Row: Reason
        r_reason = ttk.Frame(res_card)
        r_reason.pack(fill=tk.X, pady=3)
        ttk.Label(r_reason, text='判分详细理由：', font=('Arial', 9, 'bold'), width=14, anchor='nw').pack(side=tk.LEFT)
        reason_label = ttk.Label(r_reason, textvariable=res_reason_var, font=('Arial', 9), wraplength=480, justify=tk.LEFT)
        reason_label.pack(side=tk.LEFT, fill=tk.X, expand=True)

        # Row: Meta (time, model)
        r_meta = ttk.Frame(res_card)
        r_meta.pack(fill=tk.X, pady=(6, 0))
        ttk.Label(r_meta, textvariable=res_meta_var, font=('Arial', 8), foreground='#888888').pack(side=tk.LEFT)

        last_result_cache = {}

        def do_run_test():
            p = current_crop['path']
            if not p or not os.path.exists(p):
                messagebox.showwarning('提示', '请先选取有效的切片图片。', parent=win)
                return

            test_btn.configure(state='disabled', text='⏳ 正在由大模型识别与评判中...')
            res_rec_var.set('正在分析图像...')
            res_corr_var.set('正在分析...')
            res_score_var.set('正在分析...')
            res_reason_var.set('正在请求大模型，请稍候...')
            res_meta_var.set('正在上传图像至阿里百炼服务端...')

            answers_list = [a.strip() for a in ans_var.get().split('/') if a.strip()]
            keywords_list = [k.strip() for k in kw_var.get().split('/') if k.strip()]
            ms_val = max_score_var.get()

            def _worker():
                import time
                t0 = time.time()
                part = (task_item or {}).get('part', {})
                ocr_cfg = part.get('ocr') or {}
                if not ocr_cfg and isinstance(task_item, dict):
                    ocr_cfg = task_item.get('ocr_config') or {}
                mock_task = {
                    'crop_path': p,
                    'part': {'label': (task_item or {}).get('part', {}).get('label', '测试题'), 'score': ms_val},
                    'entry': {'student_name': '测试学生', 'score_id': '00'},
                }
                res = llm_grading_service.grade_single_subjective_task(
                    mock_task,
                    expected_answers=answers_list,
                    expected_keywords=keywords_list,
                    ocr_config=ocr_cfg,
                    config=cfg,
                )
                elapsed = round(time.time() - t0, 2)
                res['elapsed'] = elapsed
                res['model'] = cfg.get('model', 'qwen-vl-plus')

                def _update():
                    if not win.winfo_exists():
                        return
                    test_btn.configure(state='normal', text='🚀 立即请求大模型识别并判分')
                    last_result_cache.clear()
                    last_result_cache.update(res)

                    if res.get('success'):
                        rec_text = res.get('recognized_text') or '（未检测到手写字符）'
                        res_rec_var.set(f"“{rec_text}”")

                        has_corr = res.get('has_correction', False)
                        if has_corr:
                            corr_label.configure(foreground='#D97706')
                            res_corr_var.set('⚠️ 检测到涂改/划线痕迹（已自动智能忽略被涂改文字）')
                        else:
                            corr_label.configure(foreground='#10B981')
                            res_corr_var.set('✅ 无涂改痕迹（文字整洁）')

                        s = float(res.get('score', 0.0))
                        s_str = f"{int(s)} 分" if s.is_integer() else f"{s:g} 分"
                        res_score_var.set(f"{s_str}  /  满分 {ms_val:g} 分")
                        if s >= ms_val:
                            score_label.configure(foreground='#10B981')
                        elif s > 0:
                            score_label.configure(foreground='#2563EB')
                        else:
                            score_label.configure(foreground='#EF4444')

                        res_reason_var.set(res.get('reason') or '大模型已完成裁决')
                        res_meta_var.set(f"模型：{res.get('model')}  |  耗时：{elapsed} 秒  |  状态：成功")
                        if on_apply_callback and apply_btn:
                            apply_btn.configure(state='normal')
                    else:
                        res_rec_var.set('识别失败')
                        res_corr_var.set('-')
                        res_score_var.set('0 分')
                        score_label.configure(foreground='#EF4444')
                        res_reason_var.set(f"错误信息：{res.get('reason') or res.get('error')}")
                        res_meta_var.set(f"耗时：{elapsed} 秒  |  状态：失败")

                self.root.after(0, _update)

            threading.Thread(target=_worker, daemon=True).start()

        test_btn.configure(command=do_run_test)

        # Bottom Bar
        bottom_bar = ttk.Frame(content)
        bottom_bar.pack(fill=tk.X, pady=(6, 0))

        apply_btn = None
        if on_apply_callback and task_item:
            def do_apply():
                if not last_result_cache or not last_result_cache.get('success'):
                    messagebox.showinfo('提示', '请先进行大模型识别并取得成功结果后再采纳。', parent=win)
                    return
                on_apply_callback(last_result_cache)
                win.destroy()

            apply_btn = ttk.Button(bottom_bar, text='✅ 采纳此判定并填入当前题', command=do_apply, state='disabled')
            apply_btn.pack(side=tk.LEFT, padx=4)

        ttk.Button(bottom_bar, text='关闭', command=win.destroy).pack(side=tk.RIGHT, padx=4)

        # If opened for a specific task, automatically run test on dialog launch!
        if task_item and current_crop['path'] and os.path.exists(current_crop['path']):
            win.after(200, do_run_test)

    def open_llm_results_review_dialog(self, parent_win, tasks=None, all_scores=None, payload=None, refresh_callback=None):
        """打开大模型智能批改识别结果与评分回看面板（全透明回看识别字、判分详情、涂改滤除状态与学生作答原图）"""
        target_payload = payload or self.load_subjective_score_payload()
        target_scores = all_scores if all_scores is not None else target_payload.setdefault('scores', {})
        target_tasks = tasks or []

        task_map = {}
        for t in target_tasks:
            task_map[(t.get('entry_key'), t.get('part_id'))] = t

        llm_items = []
        for e_key, p_dict in target_scores.items():
            if not isinstance(p_dict, dict):
                continue
            for p_id, rec in p_dict.items():
                if not isinstance(rec, dict):
                    continue
                eng = str(rec.get('auto_grade_engine') or '')
                if '大模型' not in eng:
                    continue

                t_item = task_map.get((e_key, p_id))
                part = (t_item or {}).get('part', {})
                entry = (t_item or {}).get('entry', {})
                crop_path = (t_item or {}).get('crop_path', '')
                if not crop_path:
                    crop_path = rec.get('crop_path', '')

                st_name = rec.get('student_name') or entry.get('student_name', '')
                sc_id = rec.get('score_id') or entry.get('score_id', '')
                label = rec.get('label') or part.get('label', '') or p_id

                ocr_cfg = part.get('ocr') or {}
                exps = self.subjective_expected_answers_from_config(ocr_cfg) if ocr_cfg else []
                std_ans = ' / '.join(exps) if exps else '未设置'

                max_s = float(rec.get('max_score') or part.get('score', 1.0) or 1.0)
                score_val = float(rec.get('score', 0.0))
                reason = str(rec.get('auto_grade_reason', '')).strip()
                has_corr = '已滤除涂改' in reason or bool(rec.get('has_correction'))
                ocr_text = rec.get('ocr_text') or rec.get('paddle_ocr_text') or ''

                llm_items.append({
                    'entry_key': e_key,
                    'part_id': p_id,
                    'record': rec,
                    'task': t_item,
                    'student_name': st_name,
                    'score_id': sc_id,
                    'label': label,
                    'ocr_text': ocr_text,
                    'score': score_val,
                    'max_score': max_s,
                    'standard_answer': std_ans,
                    'has_correction': has_corr,
                    'reason': reason,
                    'crop_path': crop_path,
                    'engine': eng,
                    'updated_at': rec.get('updated_at', ''),
                })

        if not llm_items:
            messagebox.showinfo(
                '大模型识别结果',
                '当前尚无由大模型批改的题目记录。\n\n'
                '您可以点击【🤖 大模型智能批改剩余题】对试卷进行批量智能批改，\n'
                '或在批改界面点击【🔍 大模型试判当前题】单独体验。',
                parent=parent_win
            )
            return

        llm_items.sort(key=lambda x: (x.get('label', ''), str(x.get('score_id', ''))))

        win = tk.Toplevel(parent_win)
        win.title('📋 大模型智能批改识别结果与评分回看面板')
        win.geometry('1120x720')
        win.minsize(980, 600)
        win.transient(parent_win)
        win.grab_set()

        content = ttk.Frame(win, padding=12)
        content.pack(fill=tk.BOTH, expand=True)

        top_frame = ttk.Frame(content)
        top_frame.pack(fill=tk.X, pady=(0, 8))

        ttk.Label(
            top_frame,
            text=f"📋 大模型智能批改明细回看（共 {len(llm_items)} 题）",
            font=('Arial', 12, 'bold'),
            foreground='#0B5CAD'
        ).pack(side=tk.LEFT)

        filter_frame = ttk.Frame(content)
        filter_frame.pack(fill=tk.X, pady=(0, 8))

        ttk.Label(filter_frame, text='分类筛选：', font=('Arial', 9, 'bold')).pack(side=tk.LEFT)
        filter_var = tk.StringVar(value='all')

        total_corr_count = sum(1 for it in llm_items if it['has_correction'])
        full_score_count = sum(1 for it in llm_items if it['score'] >= it['max_score'])
        zero_score_count = sum(1 for it in llm_items if it['score'] <= 0.0)

        r_all = ttk.Radiobutton(filter_frame, text=f'全部 ({len(llm_items)})', variable=filter_var, value='all')
        r_all.pack(side=tk.LEFT, padx=4)
        r_corr = ttk.Radiobutton(filter_frame, text=f'⚠️ 滤除涂改 ({total_corr_count})', variable=filter_var, value='correction')
        r_corr.pack(side=tk.LEFT, padx=4)
        r_full = ttk.Radiobutton(filter_frame, text=f'✅ 满分/正确 ({full_score_count})', variable=filter_var, value='full')
        r_full.pack(side=tk.LEFT, padx=4)
        r_zero = ttk.Radiobutton(filter_frame, text=f'❌ 0分/错误 ({zero_score_count})', variable=filter_var, value='zero')
        r_zero.pack(side=tk.LEFT, padx=4)

        ttk.Label(filter_frame, text='   搜索：', font=('Arial', 9, 'bold')).pack(side=tk.LEFT)
        search_var = tk.StringVar()
        search_entry = ttk.Entry(filter_frame, textvariable=search_var, width=18)
        search_entry.pack(side=tk.LEFT, padx=2)

        def export_review_table():
            import csv
            f_path = filedialog.asksaveasfilename(
                title='导出大模型识别与批改结果',
                defaultextension='.csv',
                initialfile=f"大模型识别结果_{datetime.now().strftime('%Y%m%d_%H%M%S')}.csv",
                filetypes=[('CSV表格文件', '*.csv'), ('所有文件', '*.*')],
                parent=win
            )
            if not f_path:
                return
            try:
                with open(f_path, 'w', encoding='utf-8-sig', newline='') as fp:
                    writer = csv.writer(fp)
                    writer.writerow(['序号', '题位', '学生姓名', '学号', '大模型识别内容', '得分', '满分', '是否滤除涂改', '判定理由', '引擎版本', '批改时间', '切片路径'])
                    for i, it in enumerate(llm_items, 1):
                        writer.writerow([
                            i,
                            it['label'],
                            it['student_name'],
                            it['score_id'],
                            it['ocr_text'],
                            it['score'],
                            it['max_score'],
                            '是' if it['has_correction'] else '否',
                            it['reason'],
                            it['engine'],
                            it['updated_at'],
                            it['crop_path'],
                        ])
                messagebox.showinfo('导出成功', f'大模型识别结果已成功导出至：\n{f_path}', parent=win)
            except Exception as e:
                messagebox.showerror('导出失败', f'导出文件时出错：{e}', parent=win)

        ttk.Button(filter_frame, text='📊 导出为CSV表格', command=export_review_table).pack(side=tk.RIGHT, padx=4)

        paned = ttk.PanedWindow(content, orient=tk.HORIZONTAL)
        paned.pack(fill=tk.BOTH, expand=True, pady=(0, 8))

        left_frame = ttk.Frame(paned)
        paned.add(left_frame, weight=3)

        right_frame = ttk.Frame(paned)
        paned.add(right_frame, weight=2)

        tree_cols = ('#', 'student', 'id', 'part', 'ocr_text', 'score', 'corr', 'reason')
        tree = ttk.Treeview(left_frame, columns=tree_cols, show='headings', selectmode='browse')
        tree.heading('#', text='#')
        tree.heading('student', text='学生')
        tree.heading('id', text='学号')
        tree.heading('part', text='题位')
        tree.heading('ocr_text', text='🤖 识别文字')
        tree.heading('score', text='得分')
        tree.heading('corr', text='涂改/划线')
        tree.heading('reason', text='判定理由')

        tree.column('#', width=35, anchor='center')
        tree.column('student', width=70, anchor='center')
        tree.column('id', width=50, anchor='center')
        tree.column('part', width=80, anchor='center')
        tree.column('ocr_text', width=110, anchor='w')
        tree.column('score', width=55, anchor='center')
        tree.column('corr', width=85, anchor='center')
        tree.column('reason', width=200, anchor='w')

        sb_v = ttk.Scrollbar(left_frame, orient=tk.VERTICAL, command=tree.yview)
        tree.configure(yscrollcommand=sb_v.set)
        tree.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
        sb_v.pack(side=tk.RIGHT, fill=tk.Y)

        card = ttk.LabelFrame(right_frame, text='作答切片原图与判分详情', padding=(10, 8))
        card.pack(fill=tk.BOTH, expand=True)

        sel_info_var = tk.StringVar(value='请在左侧列表中点击选择任意一项')
        ttk.Label(card, textvariable=sel_info_var, font=('Arial', 10, 'bold'), foreground='#0B5CAD').pack(anchor='w', pady=(0, 4))

        sel_std_var = tk.StringVar(value='标准答案：-')
        ttk.Label(card, textvariable=sel_std_var, foreground='#444444').pack(anchor='w', pady=(0, 6))

        crop_box = ttk.Frame(card, height=170, relief='sunken', borderwidth=1)
        crop_box.pack(fill=tk.X, pady=(0, 8))
        crop_box.pack_propagate(False)

        crop_img_label = ttk.Label(crop_box, text='点击列表项即可查看切片原图', anchor='center')
        crop_img_label.pack(fill=tk.BOTH, expand=True)
        crop_photo_ref = [None]

        d_rec_var = tk.StringVar(value='识别文字：-')
        ttk.Label(card, textvariable=d_rec_var, font=('Arial', 11, 'bold'), foreground='#0B5CAD').pack(anchor='w', pady=2)

        d_corr_var = tk.StringVar(value='涂改检测：-')
        d_corr_lbl = ttk.Label(card, textvariable=d_corr_var, font=('Arial', 9, 'bold'))
        d_corr_lbl.pack(anchor='w', pady=2)

        d_score_var = tk.StringVar(value='判定得分：-')
        d_score_lbl = ttk.Label(card, textvariable=d_score_var, font=('Arial', 11, 'bold'))
        d_score_lbl.pack(anchor='w', pady=2)

        d_reason_var = tk.StringVar(value='判定理由：-')
        ttk.Label(card, textvariable=d_reason_var, font=('Arial', 9), wraplength=380, justify=tk.LEFT).pack(anchor='w', pady=3)

        d_meta_var = tk.StringVar(value='')
        ttk.Label(card, textvariable=d_meta_var, font=('Arial', 8), foreground='#888888').pack(anchor='w', pady=(4, 8))

        override_frame = ttk.LabelFrame(card, text='人工就地改分（若认为大模型判题有误）', padding=(8, 6))
        override_frame.pack(fill=tk.X, pady=(4, 0))

        current_selected_item = [None]

        def do_override_score(new_score_val):
            it = current_selected_item[0]
            if not it:
                messagebox.showinfo('提示', '请先在左侧选择一道题目。', parent=win)
                return
            rec = it['record']
            max_s = float(it['max_score'])
            try:
                ns = max(0.0, min(max_s, float(new_score_val)))
            except Exception:
                return

            score_disp = f"{int(ns)}分" if ns.is_integer() else f"{ns:g}分"
            rec['score'] = ns
            rec['manual_graded'] = True
            rec['auto_grade_reason'] = f"{it['reason']}（教师改判为{score_disp}）"
            it['score'] = ns
            it['reason'] = rec['auto_grade_reason']

            self.save_subjective_score_payload(target_payload)
            self.refresh_main_result_views(target_payload)
            if callable(refresh_callback):
                refresh_callback()

            on_item_select()
            repopulate_tree(keep_selection=True)

        btn_row_re = ttk.Frame(override_frame)
        btn_row_re.pack(fill=tk.X, pady=2)
        ttk.Button(btn_row_re, text='改判满分', command=lambda: do_override_score(current_selected_item[0]['max_score'] if current_selected_item[0] else 1.0)).pack(side=tk.LEFT, padx=2)
        ttk.Button(btn_row_re, text='改判0分', command=lambda: do_override_score(0.0)).pack(side=tk.LEFT, padx=2)

        custom_score_var = tk.StringVar()
        ttk.Label(btn_row_re, text='自定义:').pack(side=tk.LEFT, padx=(6, 2))
        ttk.Entry(btn_row_re, textvariable=custom_score_var, width=5).pack(side=tk.LEFT, padx=2)
        ttk.Button(btn_row_re, text='确定', width=4, command=lambda: do_override_score(custom_score_var.get().strip()) if custom_score_var.get().strip() else None).pack(side=tk.LEFT, padx=2)

        item_iid_map = {}

        def on_item_select(event=None):
            sel = tree.selection()
            if not sel:
                return
            iid = sel[0]
            it = item_iid_map.get(iid)
            if not it:
                return
            current_selected_item[0] = it

            sel_info_var.set(f"学生：{it['student_name']}（学号 {it['score_id']}） | 题位：{it['label']} | 满分：{it['max_score']:g}分")
            sel_std_var.set(f"标准参考答案：{it['standard_answer']}")

            p = it['crop_path']
            if p and os.path.exists(p):
                try:
                    im = Image.open(p)
                    im.thumbnail((370, 150), Image.LANCZOS)
                    tk_img = ImageTk.PhotoImage(im)
                    crop_photo_ref[0] = tk_img
                    crop_img_label.configure(image=tk_img, text='')
                except Exception as e:
                    crop_img_label.configure(image='', text=f'切片加载失败: {e}')
            else:
                crop_img_label.configure(image='', text='（无切片原图或文件不存在）')

            rec_text = it['ocr_text'] or '（未识别到有效文字）'
            d_rec_var.set(f"🤖 识别学生作答：【{rec_text}】")

            if it['has_correction']:
                d_corr_lbl.configure(foreground='#D97706')
                d_corr_var.set('✍️ 涂改检测：⚠️ 检测到涂改/划线（已自动智能滤除）')
            else:
                d_corr_lbl.configure(foreground='#10B981')
                d_corr_var.set('✍️ 涂改检测：✅ 无涂改痕迹（字迹整洁）')

            s = it['score']
            ms = it['max_score']
            s_str = f"{int(s)}分" if s.is_integer() else f"{s:g}分"
            d_score_var.set(f"⚖️ 判定得分：{s_str}  /  满分 {ms:g}分")
            if s >= ms:
                d_score_lbl.configure(foreground='#10B981')
            elif s > 0:
                d_score_lbl.configure(foreground='#2563EB')
            else:
                d_score_lbl.configure(foreground='#EF4444')

            d_reason_var.set(f"💡 判定理由：{it['reason'] or '无详细评语'}")
            d_meta_var.set(f"引擎：{it['engine']}  |  时间：{it['updated_at']}")

        tree.bind('<<TreeviewSelect>>', on_item_select)

        def repopulate_tree(keep_selection=False):
            sel_entry_key = (current_selected_item[0] or {}).get('entry_key')
            sel_part_id = (current_selected_item[0] or {}).get('part_id')

            tree.delete(*tree.get_children())
            item_iid_map.clear()

            f_mode = filter_var.get()
            q_search = search_var.get().strip().lower()

            count = 0
            to_select_iid = None
            for idx, it in enumerate(llm_items, 1):
                if f_mode == 'correction' and not it['has_correction']:
                    continue
                if f_mode == 'full' and it['score'] < it['max_score']:
                    continue
                if f_mode == 'zero' and it['score'] > 0.0:
                    continue

                if q_search:
                    corpus = f"{it['student_name']} {it['score_id']} {it['label']} {it['ocr_text']} {it['reason']}".lower()
                    if q_search not in corpus:
                        continue

                count += 1
                iid = f"item_{idx}"
                item_iid_map[iid] = it

                s_str = f"{int(it['score'])}" if it['score'].is_integer() else f"{it['score']:g}"
                ms_str = f"{int(it['max_score'])}" if it['max_score'].is_integer() else f"{it['max_score']:g}"
                score_col = f"{s_str} / {ms_str}"
                corr_col = '⚠️ 滤除涂改' if it['has_correction'] else '无涂改'

                tree.insert(
                    '',
                    tk.END,
                    iid=iid,
                    values=(count, it['student_name'], it['score_id'], it['label'], it['ocr_text'], score_col, corr_col, it['reason'])
                )

                if keep_selection and it.get('entry_key') == sel_entry_key and it.get('part_id') == sel_part_id:
                    to_select_iid = iid

            children = tree.get_children()
            if children:
                target_iid = to_select_iid if to_select_iid else children[0]
                tree.selection_set(target_iid)
                tree.focus(target_iid)
                on_item_select()

        r_all.configure(command=repopulate_tree)
        r_corr.configure(command=repopulate_tree)
        r_full.configure(command=repopulate_tree)
        r_zero.configure(command=repopulate_tree)
        search_entry.bind('<KeyRelease>', lambda e: repopulate_tree())

        repopulate_tree()

        bottom_bar = ttk.Frame(content)
        bottom_bar.pack(fill=tk.X, pady=(6, 0))

        correct_rate = round((full_score_count / len(llm_items)) * 100, 1) if llm_items else 0.0
        summary_text = (
            f"📊 汇总统计：大模型共批改 {len(llm_items)} 题  |  "
            f"满分/正确：{full_score_count} 题 ({correct_rate}%)  |  "
            f"智能滤除涂改：{total_corr_count} 题  |  "
            f"0分/错误：{zero_score_count} 题"
        )
        ttk.Label(bottom_bar, text=summary_text, font=('Arial', 9, 'bold'), foreground='#333333').pack(side=tk.LEFT)
        ttk.Button(bottom_bar, text='关闭', command=win.destroy).pack(side=tk.RIGHT, padx=4)

    def run_llm_batch_grading(self, parent_win, tasks, all_scores, payload, refresh_callback=None):
        """执行大模型批量智能批改（过滤涂改并自动打分）"""
        task_context = self.score_context_identity()
        try:
            import llm_grading_service
        except ImportError:
            messagebox.showerror('错误', '找不到 llm_grading_service 模块。', parent=parent_win)
            return

        cfg = llm_grading_service.load_llm_config()
        if not cfg.get('endpoint') or not cfg.get('api_key'):
            if messagebox.askyesno(
                '需要配置大模型',
                '大模型接口地址或 API Key 尚未配置。\n是否现在打开设置窗口？',
                parent=parent_win,
            ):
                self.open_llm_grading_settings(parent_win)
            return

        # 1. 搜集所有待人工打分的试卷小题
        def is_task_pending_manual(task_item):
            rec = all_scores.get(task_item['entry_key'], {}).get(task_item['part_id'], {})
            if not isinstance(rec, dict):
                return True
            if rec.get('manual_graded'):
                return False
            if rec.get('auto_graded') and not rec.get('ocr_auto_need_manual'):
                return False
            score_val = rec.get('score')
            if score_val is not None and str(score_val).strip() != '':
                return False
            return True

        def is_calc_or_drawing(task_item):
            part = (task_item or {}).get('part', {})
            kind = str(part.get('kind') or '').lower()
            pid = str((task_item or {}).get('part_id') or '').lower()
            return kind in ('drawing', 'calculation') or bool(part.get('manual_only')) or pid.startswith('calc_')

        target_tasks = [
            t for t in tasks
            if is_task_pending_manual(t)
            and not is_calc_or_drawing(t)
            and os.path.exists(t.get('crop_path', ''))
        ]

        if not target_tasks:
            messagebox.showinfo('提示', '当前没有待人工打分的试卷题目需要大模型处理。', parent=parent_win)
            return

        total_count = len(target_tasks)
        model_name = cfg.get('model', 'qwen-vl-plus')

        if not messagebox.askyesno(
            '启动大模型智能批改',
            f"已检测到 {total_count} 个待人工/涂改的主观题切片。\n\n"
            f"调用模型：{model_name}\n"
            f"功能特性：自动过滤涂改与划线、提取有效文字并智能给分。\n\n"
            f"是否立即启动智能批改？",
            parent=parent_win,
        ):
            return

        # 2. 进度弹窗
        prog_win = tk.Toplevel(parent_win)
        prog_win.title(f"🤖 正在进行大模型智能批改 ({model_name})")
        prog_win.geometry('540x250')
        prog_win.minsize(500, 230)
        prog_win.transient(parent_win)
        prog_win.grab_set()

        p_frame = ttk.Frame(prog_win, padding=16)
        p_frame.pack(fill=tk.BOTH, expand=True)

        header_var = tk.StringVar(value=f"正在使用 {model_name} 多线程智能批改中...")
        ttk.Label(p_frame, textvariable=header_var, font=('Arial', 11, 'bold'), foreground='#0B5CAD').pack(anchor='w', pady=(0, 6))

        status_var = tk.StringVar(value='正在分配任务与并发识别...')
        ttk.Label(p_frame, textvariable=status_var, wraplength=500).pack(anchor='w', pady=(0, 8))

        prog_bar = ttk.Progressbar(p_frame, mode='determinate', maximum=total_count)
        prog_bar.pack(fill=tk.X, pady=(0, 8))

        detail_var = tk.StringVar(value=f"进度：0 / {total_count} 题（成功: 0 | 过滤涂改: 0 | 失败: 0）")
        ttk.Label(p_frame, textvariable=detail_var, font=('Arial', 9)).pack(anchor='w', pady=(0, 10))

        cancel_flag = {'cancelled': False}
        def on_cancel():
            cancel_flag['cancelled'] = True
            status_var.set('正在中止并保存已完成题目，请稍候...')

        stop_btn = ttk.Button(p_frame, text='停止批改', command=on_cancel)
        stop_btn.pack(side=tk.RIGHT, pady=(6, 0))

        # 3. 统计计数与回调
        stats = {
            'completed': 0,
            'success': 0,
            'correction': 0,
            'failed': 0,
            'needs_manual': 0,
        }

        def get_rules_for_task(task_item):
            part = task_item.get('part', {})
            ocr_cfg = self.normalize_ocr_config(part.get('ocr'))
            exp_ans = self.subjective_expected_answers_from_config(ocr_cfg)
            exp_kw = self.split_expected_keywords(ocr_cfg.get('expected_keywords'))
            # 多源兜底：若横线配置中未填标准答案，从该题已有评分记录中提取真实的 auto_grade_expected
            if not exp_ans:
                entry_key = task_item.get('entry_key', '')
                part_id = task_item.get('part_id', '')
                rec = all_scores.get(entry_key, {}).get(part_id, {})
                prev_exp = rec.get('auto_grade_expected', '') or rec.get('paddle_ocr_expected', '')
                if prev_exp and not str(prev_exp).startswith('关键词：'):
                    exp_ans = [x.strip() for x in str(prev_exp).split('/') if x.strip()]
            return exp_ans, exp_kw, ocr_cfg

        def on_progress_step(done, total, last_task, last_res):
            def _update_ui():
                if not prog_win.winfo_exists() or self.score_context_identity() != task_context:
                    return
                stats['completed'] = done
                prog_bar['value'] = done
                st_name = last_task['entry'].get('student_name', '')
                p_lbl = last_task['part'].get('label', '')
                if last_res.get('success'):
                    # 更新底层 record
                    entry_key = last_task['entry_key']
                    part_id = last_task['part_id']
                    record = all_scores.setdefault(entry_key, {}).setdefault(part_id, {})
                    max_s = float(last_task['part'].get('score') or 1.0)
                    assigned_s = max(0.0, min(max_s, float(last_res.get('score') or 0.0)))
                    has_corr = last_res.get('has_correction', False)
                    corr_prefix = "【已滤除涂改】" if has_corr else ""
                    full_reason = f"{corr_prefix}{last_res.get('reason', '')}".strip()

                    if last_res.get('needs_manual'):
                        stats['needs_manual'] += 1
                        record.update({
                            'score': 0.0,
                            'max_score': max_s,
                            'manual_graded': False,
                            'auto_graded': False,
                            'ocr_auto_need_manual': True,
                            'auto_grade_engine': f"大模型({model_name})",
                            'auto_grade_reason': full_reason,
                            'ocr_text': last_res.get('recognized_text', ''),
                            'paddle_ocr_text': last_res.get('recognized_text', ''),
                            'label': last_task['part'].get('label', ''),
                            'student_name': st_name,
                            'score_id': last_task['entry'].get('score_id', ''),
                            'file': last_task['entry'].get('file', ''),
                            'updated_at': datetime.now().isoformat(timespec='seconds'),
                        })
                        status_var.set(f"❓ {st_name} {p_lbl} ➔ 字迹存疑退回人工（{full_reason}）")
                    else:
                        stats['success'] += 1
                        if has_corr:
                            stats['correction'] += 1
                        record.update({
                            'score': assigned_s,
                            'max_score': max_s,
                            'manual_graded': True,
                            'auto_graded': False,
                            'ocr_auto_need_manual': False,
                            'auto_grade_engine': f"大模型({model_name})",
                            'auto_grade_reason': full_reason,
                            'ocr_text': last_res.get('recognized_text', ''),
                            'paddle_ocr_text': last_res.get('recognized_text', ''),
                            'label': last_task['part'].get('label', ''),
                            'student_name': st_name,
                            'score_id': last_task['entry'].get('score_id', ''),
                            'file': last_task['entry'].get('file', ''),
                            'updated_at': datetime.now().isoformat(timespec='seconds'),
                        })
                        score_disp = f"{int(assigned_s)}分" if assigned_s.is_integer() else f"{assigned_s}分"
                        status_var.set(f"✅ {st_name} {p_lbl} ➔ 判 {score_disp}（{full_reason}）")
                else:
                    stats['failed'] += 1
                    status_var.set(f"⚠️ {st_name} {p_lbl} ➔ 识别失败：{last_res.get('reason', '')}")

                detail_var.set(
                    f"进度：{done} / {total} 题（成功打分: {stats['success']} | 滤除涂改: {stats['correction']} | 存疑转人工: {stats['needs_manual']} | 失败: {stats['failed']}）"
                )

            self.root.after(0, _update_ui)

        def worker_thread():
            llm_grading_service.batch_grade_tasks_concurrent(
                target_tasks,
                get_rules_for_task,
                progress_callback=on_progress_step,
                cancel_check_fn=lambda: cancel_flag['cancelled'],
                config=cfg,
            )

            def _on_finish():
                if prog_win.winfo_exists():
                    prog_win.destroy()
                if self.score_context_identity() != task_context:
                    messagebox.showerror('测试已切换', '旧批改任务的结果未写入当前测试，请回到原测试重新批改。')
                    return
                self.save_subjective_score_payload(payload)
                self.refresh_main_result_views(payload)
                if callable(refresh_callback):
                    refresh_callback()

                msg = (
                    f"🎉 大模型智能批改完成！\n\n"
                    f"本次处理总数：{stats['completed']} / {total_count} 题\n"
                    f"✅ 成功打分：{stats['success']} 题\n"
                    f"🔍 智能过滤涂改并准确识别：{stats['correction']} 题\n"
                )
                if stats.get('needs_manual', 0) > 0:
                    msg += f"❓ 字迹存疑/模糊：{stats['needs_manual']} 题（已自动保留待人工复核）\n"
                if stats['failed'] > 0:
                    msg += f"⚠️ 失败/超时：{stats['failed']} 题（已自动保留人工打分）\n"
                if cancel_flag['cancelled']:
                    msg += "\n（用户已中途停止，已完成题目已安全保存）"


                if stats['success'] > 0:
                    msg += "\n\n是否立即打开【大模型识别结果】详细回看每题识别文字、判分理由与切片原图？"
                    if messagebox.askyesno('大模型批改完成', msg, parent=parent_win):
                        self.open_llm_results_review_dialog(
                            parent_win, tasks=target_tasks, all_scores=all_scores, payload=payload, refresh_callback=refresh_callback
                        )
                else:
                    messagebox.showinfo('大模型批改完成', msg, parent=parent_win)

            self.root.after(0, _on_finish)

        threading.Thread(target=worker_thread, daemon=True).start()

    def open_subjective_grading(self, target_part_id=None, target_kind=None):
        if not self.context_change_allowed():
            return
        if not self.require_current_session_for_grading('主观题批改'):
            return
        self.ensure_answer_scheme_loaded_for_grading()
        parts = [part for part in self.iter_subjective_parts() if float(part.get('score') or 0) > 0]
        parts.extend(self.direct_calculation_manual_parts())
        if not parts:
            messagebox.showinfo('提示', '当前模板没有需要计分的主观题空。')
            return
        if not self.summary_data:
            if self.is_direct_paper_choice_template() and self.image_paths:
                if messagebox.askyesno(
                    '先生成学生结果',
                    '主观题批改需要先知道每张卷子对应哪个学生。\n\n当前已经选择了图片，但还没有生成批改结果。是否现在先自动处理一遍？',
                ):
                    self.process_all()
                    if not self.summary_data:
                        return
                else:
                    return
            else:
                messagebox.showwarning('提示', '请先选择图片/文件夹并生成一次学生结果，再进行主观题批改。')
                return
        self.status_var.set('正在准备主观题裁图...')
        self.root.update_idletasks()
        export_root, _saved, errors, crop_map = self.generate_subjective_crops(reuse_existing=True)
        if errors and not crop_map:
            messagebox.showwarning('主观题批改', '\n'.join(errors[:10]))
            return

        payload = self.load_subjective_score_payload()
        if not self.subjective_payload_matches_current_answers(payload):
            payload = self.prepare_subjective_payload_for_grading(payload)
            self.save_subjective_score_payload(payload)
        payload = self.apply_subjective_scores_to_entries(payload)
        all_scores = payload.setdefault('scores', {})
        entry_order = {
            self.subjective_entry_key(entry): index
            for index, entry in enumerate(self.summary_data)
        }
        part_order = {
            part.get('part_id'): index
            for index, part in enumerate(parts)
        }
        drawing_part_ids = {
            part.get('part_id')
            for part in parts
            if part.get('kind') == 'drawing'
        }
        calc_part_ids = {
            part.get('part_id')
            for part in parts
            if part.get('kind') == 'calculation'
        }

        def build_subjective_tasks(active_crop_map):
            built_tasks = []
            for entry in self.summary_data:
                entry_key = self.subjective_entry_key(entry)
                for part in parts:
                    part_id = part.get('part_id')
                    crop_id = 'calculation_back_region' if part.get('kind') == 'calculation' else part_id
                    crop_path = active_crop_map.get(entry_key, {}).get(crop_id)
                    if crop_path and Path(crop_path).exists():
                        built_tasks.append({
                            'entry': entry,
                            'entry_key': entry_key,
                            'part': part,
                            'part_id': part_id,
                            'crop_path': crop_path,
                        })
            built_tasks.sort(key=lambda task: (
                1 if task.get('part', {}).get('kind') == 'calculation' else 0,
                entry_order.get(task.get('entry_key'), 999999) if task.get('part', {}).get('kind') == 'calculation' else part_order.get(task.get('part_id'), 999999),
                part_order.get(task.get('part_id'), 999999) if task.get('part', {}).get('kind') == 'calculation' else entry_order.get(task.get('entry_key'), 999999),
            ))
            return built_tasks

        tasks = build_subjective_tasks(crop_map)
        if calc_part_ids and not any(task.get('part_id') in calc_part_ids for task in tasks):
            self.status_var.set('未找到计算题裁图，正在重新生成主观题裁图...')
            self.root.update_idletasks()
            export_root, _saved, retry_errors, crop_map = self.generate_subjective_crops(reuse_existing=False)
            tasks = build_subjective_tasks(crop_map)
            if retry_errors and not any(task.get('part_id') in calc_part_ids for task in tasks):
                errors.extend(retry_errors)

        if drawing_part_ids and not any(task.get('part_id') in drawing_part_ids for task in tasks):
            self.status_var.set('未找到作图题裁图，正在重新生成主观题裁图...')
            self.root.update_idletasks()
            export_root, _saved, retry_errors, crop_map = self.generate_subjective_crops(reuse_existing=False)
            tasks = build_subjective_tasks(crop_map)
            if retry_errors and not any(task.get('part_id') in drawing_part_ids for task in tasks):
                errors.extend(retry_errors)

        if not tasks:
            messagebox.showwarning('主观题批改', f'没有找到可批改的裁图。\n目录：{export_root}')
            return

        win = tk.Toplevel(self.root)
        win.title('主观题快速批改')
        self.track_context_window(win)
        win.geometry('1280x760')
        win.minsize(980, 600)
        win.transient(self.root)

        title_var = tk.StringVar()
        progress_var = tk.StringVar()
        score_var = tk.StringVar()
        ocr_var = tk.StringVar(value='OCR建议：未识别')
        manual_ocr_var = tk.StringVar()
        standard_answer_var = tk.StringVar(value='标准答案：未设置')
        image_label = ttk.Label(win, anchor='center')
        image_label.pack(fill=tk.BOTH, expand=True, padx=12, pady=(12, 4))

        info = ttk.Frame(win)
        info.pack(fill=tk.X, padx=12, pady=4)
        ttk.Label(info, textvariable=title_var, font=('Arial', 12, 'bold')).pack(anchor='w')
        ttk.Label(info, textvariable=progress_var).pack(anchor='w')
        ttk.Label(info, textvariable=score_var).pack(anchor='w')
        ocr_display_label = ttk.Label(info, textvariable=ocr_var, foreground='#0B5CAD', wraplength=900)
        ocr_display_label.pack(anchor='w')

        # 显目的人工赋分操作栏
        score_action_frame = ttk.LabelFrame(win, text=' ✍️ 人工赋分操作 (点击按钮或按键盘数字键0~9) ', padding=(8, 6))
        score_action_frame.pack(fill=tk.X, padx=12, pady=(2, 6))

        top_switch_bar = ttk.Frame(score_action_frame)
        top_switch_bar.pack(fill=tk.X, pady=(0, 4))
        tk.Button(
            top_switch_bar,
            text='📐 切换到计算题整大题批注工作台 (一次改完整题+画线打勾打叉批语印章)',
            font=('Arial', 10, 'bold'),
            bg='#EFF6FF',
            fg='#1D4ED8',
            activebackground='#DBEAFE',
            command=lambda: (win.destroy(), self.open_calculation_score_entry()),
        ).pack(side=tk.LEFT, padx=2)

        score_buttons_container = ttk.Frame(score_action_frame)
        score_buttons_container.pack(fill=tk.X)

        initial_index = 0
        if target_part_id:
            for i, t in enumerate(tasks):
                if t.get('part_id') == target_part_id:
                    initial_index = i
                    break
        elif target_kind:
            for i, t in enumerate(tasks):
                if t.get('part', {}).get('kind') == target_kind:
                    initial_index = i
                    break

        state = {'index': initial_index, 'photo': None, 'manual_mode': False, 'manual_scope': 'all', 'closing': False}

        part_nav_var = tk.StringVar()
        part_jump_options = []
        part_jump_map = {}
        has_draw_part = False
        has_calc_part = False
        first_draw_idx = None
        first_calc_idx = None
        for i, t in enumerate(tasks):
            p = t.get('part', {})
            pid = t.get('part_id')
            pkind = p.get('kind', '')
            if pkind == 'drawing':
                has_draw_part = True
                if first_draw_idx is None:
                    first_draw_idx = i
            elif pkind == 'calculation':
                has_calc_part = True
                if first_calc_idx is None:
                    first_calc_idx = i
            if pid not in part_jump_map:
                part_jump_map[pid] = i
                kind_tag = " [作图题]" if pkind == 'drawing' else (" [计算题]" if pkind == 'calculation' else "")
                score_str = f"{float(p.get('score') or 1):g}分"
                label_text = f"{p.get('label', pid)}{kind_tag} ({score_str})"
                part_jump_options.append((label_text, pid))

        def refresh_main_result_views():
            self.refresh_main_result_views(payload)

        def best_ocr_text_for_auto_grade(record):
            if not isinstance(record, dict):
                return ''
            return (
                record.get('ocr_manual_text')
                or record.get('ocr_text')
                or ('' if record.get('paddle_ocr_need_review') else record.get('paddle_ocr_text'))
                or ''
            )

        def regrade_existing_ocr_results(show_message=True):
            old_rules = payload.get('subjective_part_rules')
            affected = (changed_parts(old_rules, self.subjective_part_rules())
                        if isinstance(old_rules, dict) else set(self.subjective_part_rules()))
            self.prepare_subjective_payload_for_regrading(payload)
            graded = 0
            skipped = 0
            for task in tasks:
                if task['part_id'] not in affected:
                    continue
                record = all_scores.get(task['entry_key'], {}).get(task['part_id'])
                if not isinstance(record, dict) or record.get('manual_graded'):
                    skipped += 1
                    continue
                answer_text = best_ocr_text_for_auto_grade(record)
                if not answer_text:
                    skipped += 1
                    continue
                matched = self.apply_subjective_answer_auto_score(record, task, answer_text)
                if matched is None:
                    skipped += 1
                else:
                    graded += 1
            self.save_subjective_score_payload(payload)
            refresh_main_result_views()
            refresh()
            if show_message:
                ocr_var.set(f'OCR建议：已按标准答案重新判分 {graded} 个空，跳过 {skipped} 个空。')
            return graded, skipped

        def open_ocr_part_settings():
            setting_win = tk.Toplevel(win)
            setting_win.title('OCR空位设置')
            self.track_context_window(setting_win)
            setting_win.geometry('1560x640')
            setting_win.minsize(1160, 500)
            setting_win.transient(win)

            intro = ttk.Label(
                setting_win,
                text='只勾选适合 OCR 的空；前/后诱导字会临时加到识别图片上，识别后自动去掉。',
                font=('Arial', 10, 'bold'),
            )
            intro.pack(fill=tk.X, padx=12, pady=(12, 6))

            canvas = tk.Canvas(setting_win, bg='#f7f7f7')
            scrollbar = ttk.Scrollbar(setting_win, orient=tk.VERTICAL, command=canvas.yview)
            body = ttk.Frame(canvas)
            body.bind('<Configure>', lambda _e: canvas.configure(scrollregion=canvas.bbox('all')))
            canvas.create_window((0, 0), window=body, anchor='nw')
            canvas.configure(yscrollcommand=scrollbar.set)
            canvas.pack(side=tk.LEFT, fill=tk.BOTH, expand=True, padx=(12, 0), pady=6)
            scrollbar.pack(side=tk.RIGHT, fill=tk.Y, pady=6)

            headers = ['OCR', '单字', '空位', '标准答案', '常见错答案', '错误关键词', '前诱导字', '后诱导字/单位', '左留白', '右留白', '低置信度', '关键词']
            for col, header in enumerate(headers):
                ttk.Label(body, text=header, font=('Arial', 9, 'bold')).grid(row=0, column=col, padx=4, pady=4, sticky='w')

            row_vars = {}
            for row, part in enumerate(parts, 1):
                config = self.apply_ocr_memory_to_config(part.get('ocr'))
                enabled_var = tk.BooleanVar(value=config.get('enabled', False))
                single_char_var = tk.BooleanVar(value=config.get('single_char', False))
                prefix_var = tk.StringVar(value=config.get('prefix', ''))
                suffix_var = tk.StringVar(value=config.get('suffix', ''))
                left_var = tk.StringVar(value=str(config.get('pad_left', 180)))
                right_var = tk.StringVar(value=str(config.get('pad_right', 180)))
                low_conf_var = tk.StringVar(value=str(config.get('low_confidence_threshold', 0.6)))
                keyword_var = tk.StringVar(value=config.get('expected_keywords', ''))
                expected_answer_var = tk.StringVar(value=config.get('expected_answer', ''))
                common_wrong_var = tk.StringVar(value=config.get('common_wrong_answers', ''))
                wrong_keyword_var = tk.StringVar(value=config.get('wrong_keywords', ''))
                row_vars[part['part_id']] = {
                    'enabled': enabled_var,
                    'single_char': single_char_var,
                    'expected_answer': expected_answer_var,
                    'common_wrong_answers': common_wrong_var,
                    'wrong_keywords': wrong_keyword_var,
                    'prefix': prefix_var,
                    'suffix': suffix_var,
                    'pad_left': left_var,
                    'pad_right': right_var,
                    'low_confidence_threshold': low_conf_var,
                    'expected_keywords': keyword_var,
                }
                ttk.Checkbutton(body, variable=enabled_var).grid(row=row, column=0, padx=4, pady=3, sticky='w')
                ttk.Checkbutton(body, variable=single_char_var).grid(row=row, column=1, padx=4, pady=3, sticky='w')
                ttk.Label(body, text=part.get('label', ''), width=18).grid(row=row, column=2, padx=4, pady=3, sticky='w')
                expected_entry = ttk.Entry(body, textvariable=expected_answer_var, width=18)
                expected_entry.grid(row=row, column=3, padx=4, pady=3, sticky='w')
                expected_entry.bind('<FocusOut>', lambda _e, m=row_vars[part['part_id']]: self.apply_ocr_memory_to_vars(m))
                expected_entry.bind('<Return>', lambda _e, m=row_vars[part['part_id']]: self.apply_ocr_memory_to_vars(m))
                ttk.Entry(body, textvariable=common_wrong_var, width=16).grid(row=row, column=4, padx=4, pady=3, sticky='w')
                ttk.Entry(body, textvariable=wrong_keyword_var, width=16).grid(row=row, column=5, padx=4, pady=3, sticky='w')
                ttk.Entry(body, textvariable=prefix_var, width=14).grid(row=row, column=6, padx=4, pady=3, sticky='w')
                ttk.Entry(body, textvariable=suffix_var, width=14).grid(row=row, column=7, padx=4, pady=3, sticky='w')
                ttk.Entry(body, textvariable=left_var, width=8).grid(row=row, column=8, padx=4, pady=3, sticky='w')
                ttk.Entry(body, textvariable=right_var, width=8).grid(row=row, column=9, padx=4, pady=3, sticky='w')
                ttk.Entry(body, textvariable=low_conf_var, width=8).grid(row=row, column=10, padx=4, pady=3, sticky='w')
                ttk.Entry(body, textvariable=keyword_var, width=18).grid(row=row, column=11, padx=4, pady=3, sticky='w')

            def save_settings():
                settings = {}
                for part_id, vars_map in row_vars.items():
                    settings[part_id] = self.normalize_ocr_config({
                        'enabled': vars_map['enabled'].get(),
                        'single_char': vars_map['single_char'].get(),
                        'expected_answer': vars_map['expected_answer'].get(),
                        'common_wrong_answers': vars_map['common_wrong_answers'].get(),
                        'wrong_keywords': vars_map['wrong_keywords'].get(),
                        'prefix': vars_map['prefix'].get(),
                        'suffix': vars_map['suffix'].get(),
                        'pad_left': vars_map['pad_left'].get(),
                        'pad_right': vars_map['pad_right'].get(),
                        'low_confidence_threshold': vars_map['low_confidence_threshold'].get(),
                        'expected_keywords': vars_map['expected_keywords'].get(),
                        'pad_top': 20,
                        'pad_bottom': 20,
                    })
                try:
                    self.save_ocr_settings_for_parts(settings)
                    synced_count = self.sync_loaded_answer_scheme_ocr_settings()
                    fresh_parts = {part['part_id']: part for part in self.iter_subjective_parts()}
                    for part in parts:
                        if part['part_id'] in fresh_parts:
                            part['ocr'] = fresh_parts[part['part_id']].get('ocr')
                    regrade_existing_ocr_results(show_message=False)
                    sync_text = f'，已同步答案方案“{self.loaded_answer_key_scheme_name}”' if synced_count else ''
                    ocr_var.set(f'OCR建议：OCR空位设置已保存{sync_text}，并已按已有OCR结果重新判分。')
                    setting_win.destroy()
                except Exception as e:
                    messagebox.showerror('保存失败', str(e), parent=setting_win)

            footer = ttk.Frame(setting_win)
            footer.pack(fill=tk.X, padx=12, pady=(4, 12))
            ttk.Button(footer, text='保存设置', command=save_settings).pack(side=tk.LEFT, padx=4)
            ttk.Button(footer, text='取消', command=setting_win.destroy).pack(side=tk.LEFT, padx=4)
            setting_win.protocol('WM_DELETE_WINDOW', save_settings)

        def task_matches_manual_scope(task):
            scope = state.get('manual_scope') or 'all'
            if scope == 'drawing':
                return task.get('part', {}).get('kind') == 'drawing'
            if scope == 'calculation':
                return task.get('part', {}).get('kind') == 'calculation'
            return True

        def is_manual_review_task(task):
            if not task_matches_manual_scope(task):
                return False
            record = all_scores.get(task['entry_key'], {}).get(task['part_id'], {})
            if not isinstance(record, dict):
                return True
            if record.get('manual_graded'):
                return True
            if record.get('auto_graded') and not record.get('ocr_auto_need_manual'):
                return False
            return is_manual_grade_task(task)

        def next_pending_manual_index_after_current():
            pending = [
                idx for idx, task_item in enumerate(tasks)
                if idx != state['index'] and task_matches_manual_scope(task_item) and is_manual_grade_task(task_item)
            ]
            if not pending:
                return None
            forward = [idx for idx in pending if idx > state['index']]
            return forward[0] if forward else pending[0]

        def save_current_score(value):
            task = tasks[state['index']]
            max_score = float(task['part'].get('score') or 1)
            value = float(value)
            if value > max_score and max_score <= 1:
                return
            value = max(0.0, min(max_score, value))
            entry_scores = all_scores.setdefault(task['entry_key'], {})
            record = entry_scores.setdefault(task['part_id'], {})
            record.update({
                'score': value,
                'max_score': max_score,
                'manual_graded': True,
                'auto_graded': False,
                'ocr_auto_need_manual': False,
                'label': task['part'].get('label', ''),
                'student_name': task['entry'].get('student_name', ''),
                'score_id': task['entry'].get('score_id', ''),
                'file': task['entry'].get('file', ''),
                'updated_at': datetime.now().isoformat(timespec='seconds'),
            })
            self.save_subjective_score_payload(payload)
            try:
                from core.blank_recheck import get_blank_recheck_collector
                get_blank_recheck_collector().update_manual_judgment(
                    session_id=str((self.current_session or {}).get('id') or ''),
                    part_id=str(task.get('part_id') or ''),
                    score_id_or_entry=str(task.get('entry', {}).get('score_id') or task.get('entry_key') or ''),
                    manual_score=value,
                )
            except Exception:
                pass
            refresh_main_result_views()
            if state.get('manual_mode'):
                next_idx = next_pending_manual_index_after_current()
                if next_idx is None:
                    completed_scope = state.get('manual_scope') or 'all'
                    state['manual_mode'] = False
                    state['manual_scope'] = 'all'
                    if completed_scope == 'drawing':
                        ocr_var.set('OCR建议：作图题人工打分已完成。')
                        messagebox.showinfo('作图题打分完成', '已完成所有待人工打分的作图题。', parent=win)
                    elif completed_scope == 'calculation':
                        ocr_var.set('OCR建议：计算题人工打分已完成。')
                        messagebox.showinfo('计算题打分完成', '已完成所有计算题小题的人工打分。', parent=win)
                    else:
                        ocr_var.set('OCR建议：人工打分已完成，当前没有待人工打分的主观题空。')
                        messagebox.showinfo('人工打分完成', '已完成所有待人工打分的主观题空。', parent=win)
                    refresh()
                    return
                state['index'] = next_idx
            elif state['index'] < len(tasks) - 1:
                state['index'] += 1
            refresh()

        def update_score_buttons():
            for w in score_buttons_container.winfo_children():
                w.destroy()
            if not tasks or state['index'] >= len(tasks):
                return
            curr_task = tasks[state['index']]
            curr_part = curr_task['part']
            curr_max = float(curr_part.get('score') or (curr_part.get('max_score') or 1))
            rec = all_scores.get(curr_task['entry_key'], {}).get(curr_task['part_id'], {})
            curr_score = rec.get('score') if isinstance(rec, dict) else None

            if curr_max <= 1.0:
                step_values = [0.0, 0.5, curr_max]
            elif curr_max <= 2.0:
                step_values = [0.0, 0.5, 1.0, 1.5, curr_max]
            elif curr_max <= 3.0:
                step_values = [0.0, 1.0, 1.5, 2.0, 2.5, curr_max]
            elif curr_max <= 5.0:
                step_values = [0.0, 1.0, 2.0, 3.0, 4.0, curr_max]
            else:
                step_values = [0.0, 1.0, 2.0, round(curr_max / 2, 1), curr_max - 1, curr_max]

            cand_vals = sorted(set([round(v, 2) for v in step_values if 0 <= v <= curr_max]))

            ttk.Label(score_buttons_container, text='快捷给分: ', font=('Microsoft YaHei', 10, 'bold')).pack(side=tk.LEFT, padx=(2, 6))

            for val in cand_vals:
                is_selected = (curr_score is not None and abs(float(curr_score) - val) < 1e-4)
                if val == 0.0:
                    btn_text = '❌ 0分'
                    bg_col = '#DC2626' if is_selected else '#FEE2E2'
                    fg_col = 'white' if is_selected else '#991B1B'
                    act_bg = '#B91C1C'
                elif abs(val - curr_max) < 1e-4:
                    btn_text = f'✔ 满分({curr_max:g}分)'
                    bg_col = '#16A34A' if is_selected else '#DCFCE7'
                    fg_col = 'white' if is_selected else '#166534'
                    act_bg = '#15803D'
                else:
                    btn_text = f'{val:g}分'
                    bg_col = '#2563EB' if is_selected else '#EFF6FF'
                    fg_col = 'white' if is_selected else '#1E40AF'
                    act_bg = '#1D4ED8'

                if val.is_integer() and int(val) < 10:
                    btn_text += f' [{int(val)}]'

                b = tk.Button(
                    score_buttons_container,
                    text=btn_text,
                    command=lambda v=val: save_current_score(v),
                    bg=bg_col,
                    fg=fg_col,
                    activebackground=act_bg,
                    activeforeground='white',
                    font=('Microsoft YaHei', 10, 'bold'),
                    relief='solid' if is_selected else 'groove',
                    bd=2 if is_selected else 1,
                    padx=10,
                    pady=4,
                    cursor='hand2',
                )
                b.pack(side=tk.LEFT, padx=3)

            custom_box = ttk.Frame(score_buttons_container)
            custom_box.pack(side=tk.LEFT, padx=(16, 2))
            ttk.Label(custom_box, text='自定义得分:').pack(side=tk.LEFT, padx=(0, 2))
            cust_val_var = tk.StringVar(value='' if curr_score is None else f"{float(curr_score):g}")
            cust_entry = ttk.Entry(custom_box, textvariable=cust_val_var, width=6, font=('Arial', 10))
            cust_entry.pack(side=tk.LEFT, padx=2)

            def submit_custom():
                raw = cust_val_var.get().strip()
                try:
                    num = float(raw)
                    if 0 <= num <= curr_max:
                        save_current_score(num)
                    else:
                        messagebox.showwarning('分数超出范围', f'该题满分为 {curr_max:g} 分，请输入 0 ~ {curr_max:g} 之间的分数。', parent=win)
                except ValueError:
                    messagebox.showwarning('输入错误', '请输入有效的分数数值。', parent=win)

            cust_btn = tk.Button(
                custom_box,
                text='打分并下一份 ↵',
                command=submit_custom,
                bg='#4F46E5',
                fg='white',
                font=('Microsoft YaHei', 9, 'bold'),
                padx=8,
                pady=3,
                cursor='hand2',
            )
            cust_btn.pack(side=tk.LEFT, padx=3)
            cust_entry.bind('<Return>', lambda _e: submit_custom())

        def jump(delta):
            if state.get('manual_mode'):
                if not tasks:
                    return
                direction = 1 if delta > 0 else -1
                start = state['index']
                for step in range(1, len(tasks) + 1):
                    idx = (start + direction * step) % len(tasks)
                    if is_manual_review_task(tasks[idx]):
                        state['index'] = idx
                        refresh()
                        return
                ocr_var.set('OCR建议：当前没有可切换的人工打分空。')
                return
            state['index'] = max(0, min(len(tasks) - 1, state['index'] + delta))
            state['manual_mode'] = False
            state['manual_scope'] = 'all'
            refresh()

        def is_manual_grade_task(task):
            record = all_scores.get(task['entry_key'], {}).get(task['part_id'], {})
            if not isinstance(record, dict):
                return True
            if record.get('manual_graded'):
                return False
            if record.get('ocr_auto_need_manual'):
                return True
            if record.get('auto_graded'):
                return False
            score_value = record.get('score')
            if score_value is not None and str(score_value).strip() != '':
                return False
            ocr_config = task['part'].get('ocr') or {}
            auto_allowed = bool(
                ocr_config.get('enabled')
                and self.subjective_has_auto_rule(ocr_config)
            )
            if not auto_allowed:
                return True
            return True

        def open_ocr_result_classification():
            action_map = {
                '备选答案': 'alternate_answer',
                '答案关键字': 'correct_keyword',
                '错误答案': 'wrong_answer',
                '错误答案关键字': 'wrong_keyword',
                '备选正确答案': 'alternate_answer',
                '正确答案关键词': 'correct_keyword',
                '常见错答案': 'wrong_answer',
            }
            action_labels = {
                'alternate_answer': '备选答案',
                'correct_keyword': '答案关键字',
                'wrong_answer': '错误答案',
                'wrong_keyword': '错误答案关键字',
            }
            ignored_groups = set()

            def apply_standard_to_pending_tasks(target_part_id=None):
                """用当前最新的全套标准（备选答案、答案关键字、错误答案、错误答案关键字及长效记忆），自动二次批改待人工打分的主观题"""
                re_scored = 0
                for task_item in tasks:
                    if target_part_id and task_item.get('part_id') != target_part_id:
                        continue
                    part = task_item.get('part', {})
                    kind = str(part.get('kind') or '').lower()
                    pid = str(task_item.get('part_id') or '').lower()
                    if kind in ('drawing', 'calculation') or bool(part.get('manual_only')) or pid.startswith('calc_'):
                        continue
                    record = all_scores.get(task_item['entry_key'], {}).get(task_item['part_id'], {})
                    if not isinstance(record, dict) or record.get('manual_graded'):
                        continue
                    if record.get('auto_graded') and not record.get('ocr_auto_need_manual'):
                        continue

                    rec_text = self.recognized_ocr_text_for_classification(record)
                    if not rec_text:
                        first_text = str(record.get('paddle_ocr_text') or '').strip()
                        sec_text = str(record.get('ocr_text') or '').strip()
                        if first_text in ('', '未识别到文字') and sec_text in ('', '未识别到文字'):
                            res_status = self.handle_both_blank_with_recheck(
                                record,
                                task_item,
                                task_item.get('crop_path'),
                                engine=str(record.get('ocr_engine') or 'OCR自动判分'),
                            )
                            if res_status == 'zero':
                                re_scored += 1
                        continue

                    part_ocr = task_item['part'].get('ocr') or {}
                    exp_answers = self.subjective_expected_answers_from_config(part_ocr)
                    wrong_answers = self.subjective_wrong_answers_from_config(part_ocr)
                    rem_action = self.lookup_ocr_result_classification(part_ocr, rec_text)

                    # 1. 尝试匹配正确标准（当前题目设置优先，长效记忆作为补充）
                    if (
                        self.any_subjective_answer_matches(rec_text, exp_answers)
                        or self.subjective_keyword_matches(rec_text, part_ocr)
                        or rem_action in ('alternate_answer', 'correct_keyword')
                    ):
                        matched = self.apply_subjective_answer_auto_score(record, task_item, rec_text)
                        if matched:
                            engine_label = 'OCR长效记忆' if rem_action else 'OCR二次批改'
                            record.update({
                                'auto_grade_engine': engine_label,
                                'ocr_auto_need_manual': False,
                                'ocr_auto_reason': '',
                            })
                            re_scored += 1
                    # 2. 尝试匹配错误标准
                    elif (
                        self.any_subjective_answer_matches(rec_text, wrong_answers)
                        or self.subjective_wrong_keyword_matches(rec_text, part_ocr)
                        or rem_action in ('wrong_answer', 'wrong_keyword')
                    ):
                        engine_label = 'OCR长效记忆' if rem_action else 'OCR二次批改'
                        reason_label = f'命中长效记忆的{action_labels.get(rem_action)}' if rem_action else '命中当前错误答案/关键字设置'
                        self.mark_subjective_auto_zero_record(
                            record,
                            task_item,
                            rec_text,
                            engine_label,
                            reason_label,
                        )
                        re_scored += 1
                    elif part_ocr.get('unique_answer') and part_ocr.get('split_char_check', True) and exp_answers:
                        is_missing, expected_chars = self.check_subjective_split_char_missing(rec_text, exp_answers)
                        if is_missing:
                            exp_disp = ' / '.join(exp_answers)
                            self.mark_subjective_auto_zero_record(
                                record,
                                task_item,
                                rec_text,
                                'OCR拆字判错',
                                f'拆字判错：完全未命中答案字（“{exp_disp}”）',
                            )
                            re_scored += 1
                return re_scored

            # 打开窗口前，先用已有设置和长效记忆处理一遍
            remembered_count = apply_standard_to_pending_tasks()
            if remembered_count:
                self.save_subjective_score_payload(payload)
                refresh_main_result_views()

            classify_win = tk.Toplevel(win)
            classify_win.title('OCR识别结果分类')
            try:
                classify_win.state('zoomed')
            except Exception:
                classify_win.geometry('1360x860')
            classify_win.minsize(1020, 640)
            classify_win.transient(win)

            ttk.Label(
                classify_win,
                text='同一题位、相同OCR结果会合并显示；支持复选/多选批量归类，极大提升改卷效率。',
                font=('Arial', 11, 'bold'),
            ).pack(fill=tk.X, padx=12, pady=(10, 2))
            ttk.Label(
                classify_win,
                text='💡【极速右键批改】：单选或多选后直接在列表【右键单击】，弹出菜单一键直接绑定（相当于瞬间批改完成）！\n'
                     '💡【复选/多选】：可在列表中勾选复选框或按住 Ctrl/Shift 选多项，批量一键绑定归类。\n'
                     '💡【长效记忆】：写入标准答案长效记忆库（只允许新记忆覆盖），以后在其他试卷中自动长效生效。',
                font=('Arial', 9),
                foreground='#0B5CAD',
                justify=tk.LEFT,
            ).pack(anchor='w', padx=12, pady=(0, 6))

            body = ttk.Panedwindow(classify_win, orient=tk.HORIZONTAL)
            body.pack(fill=tk.BOTH, expand=True, padx=12, pady=4)
            list_frame = ttk.Frame(body)
            preview_frame = ttk.Frame(body)
            body.add(list_frame, weight=1)
            body.add(preview_frame, weight=3)

            selection_summary_var = tk.StringVar(value='已选 0 项')
            batch_info_var = tk.StringVar(value='')
            remember_also_var = tk.BooleanVar(value=True)

            list_toolbar = ttk.Frame(list_frame)
            list_toolbar.pack(fill=tk.X, pady=(0, 4))
            ttk.Button(list_toolbar, text='☑ 全选', width=7, command=lambda: toggle_check_all()).pack(side=tk.LEFT, padx=(0, 3))
            ttk.Button(list_toolbar, text='☐ 全不选', width=8, command=lambda: uncheck_all()).pack(side=tk.LEFT, padx=3)
            ttk.Button(list_toolbar, text='反选', width=6, command=lambda: invert_check()).pack(side=tk.LEFT, padx=3)
            ttk.Label(list_toolbar, textvariable=selection_summary_var, font=('Arial', 9, 'bold'), foreground='#0B5CAD').pack(side=tk.LEFT, padx=(8, 0))

            columns = ('check', 'part', 'expected', 'ocr', 'count')
            group_tree = ttk.Treeview(list_frame, columns=columns, show='headings', height=18)
            group_tree.column('check', width=45, minwidth=40, anchor='center', stretch=False)
            group_tree.column('part', width=115, anchor='w')
            group_tree.column('expected', width=210, anchor='w')
            group_tree.column('ocr', width=250, anchor='w')
            group_tree.column('count', width=95, anchor='center')

            def sort_tree_column(col, reverse):
                if col == 'check':
                    toggle_check_all()
                    return
                items = []
                for k in group_tree.get_children(''):
                    val = group_tree.set(k, col)
                    if col == 'count':
                        try:
                            val = int(val)
                        except Exception:
                            val = 0
                    elif col == 'part':
                        grp = dialog_state['groups'].get(k)
                        val = part_order.get(grp['part_id'], 999999) if grp else 999999
                    items.append((val, k))
                items.sort(reverse=reverse)
                for index, (_val, k) in enumerate(items):
                    group_tree.move(k, '', index)
                labels = {'check': '☑', 'part': '题位', 'expected': '标准答案/关键词', 'ocr': 'OCR识别结果', 'count': '学生数'}
                arrow = ' ▲' if reverse else ' ▼'
                for c in columns:
                    if c == 'check':
                        continue
                    base = labels.get(c, c)
                    indic = f"{base}{arrow}" if c == col else base
                    next_rev = (not reverse) if c == col else (True if c == 'count' else False)
                    group_tree.heading(c, text=indic, command=lambda _c=c, _r=next_rev: sort_tree_column(_c, _r))

            group_tree.heading('check', text='☑', command=lambda: toggle_check_all())
            group_tree.heading('part', text='题位', command=lambda: sort_tree_column('part', False))
            group_tree.heading('expected', text='标准答案/关键词', command=lambda: sort_tree_column('expected', False))
            group_tree.heading('ocr', text='OCR识别结果', command=lambda: sort_tree_column('ocr', False))
            group_tree.heading('count', text='学生数 (由多到少▼)', command=lambda: sort_tree_column('count', False))
            tree_scroll = ttk.Scrollbar(list_frame, orient=tk.VERTICAL, command=group_tree.yview)
            group_tree.configure(yscrollcommand=tree_scroll.set)
            group_tree.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
            tree_scroll.pack(side=tk.RIGHT, fill=tk.Y)

            # ==================== 右侧画廊与操作区 ====================
            # 1. 顶部操作条（固定在顶部，不随图片滚动）
            gallery_header = tk.Frame(preview_frame, bg='#eaf2f8', bd=1, relief='solid', padx=10, pady=6)
            gallery_header.pack(fill=tk.X, padx=8, pady=(4, 3))

            header_top = tk.Frame(gallery_header, bg='#eaf2f8')
            header_top.pack(fill=tk.X)

            gallery_title_var = tk.StringVar(value='请在左侧选择一个题目分类')
            ttk.Label(
                header_top,
                textvariable=gallery_title_var,
                font=('微软雅黑', 11, 'bold'),
                foreground='#0B5CAD',
                background='#eaf2f8',
            ).pack(side=tk.LEFT, fill=tk.X, expand=True)

            # 🚀 顶部醒目主提交按钮
            gallery_submit_btn = tk.Button(
                header_top,
                text='🚀 提交本组全部判分 (对 0 / 错 0)',
                font=('微软雅黑', 12, 'bold'),
                bg='#28a745',
                fg='white',
                activebackground='#218838',
                activeforeground='white',
                relief='raised',
                cursor='hand2',
                padx=18,
                pady=5,
                state='disabled',
                command=lambda: execute_gallery_batch_submit(),
            )
            gallery_submit_btn.pack(side=tk.RIGHT, padx=4)

            header_bottom = tk.Frame(gallery_header, bg='#eaf2f8')
            header_bottom.pack(fill=tk.X, pady=(4, 0))

            gallery_stat_var = tk.StringVar(value='')
            tk.Label(
                header_bottom,
                textvariable=gallery_stat_var,
                font=('微软雅黑', 9, 'bold'),
                foreground='#2c3e50',
                background='#eaf2f8',
            ).pack(side=tk.LEFT)

            gallery_quick_tools = tk.Frame(header_bottom, bg='#eaf2f8')
            gallery_quick_tools.pack(side=tk.RIGHT)

            tk.Button(
                gallery_quick_tools,
                text='✔ 全部设为对(1分)',
                font=('微软雅黑', 9, 'bold'),
                bg='#d4edda',
                fg='#155724',
                activebackground='#c3e6cb',
                relief='groove',
                cursor='hand2',
                padx=8,
                pady=2,
                command=lambda: set_all_gallery_correct(),
            ).pack(side=tk.LEFT, padx=3)

            tk.Button(
                gallery_quick_tools,
                text='❌ 全部设为错(0分)',
                font=('微软雅黑', 9, 'bold'),
                bg='#f8d7da',
                fg='#721c24',
                activebackground='#f5c6cb',
                relief='groove',
                cursor='hand2',
                padx=8,
                pady=2,
                command=lambda: set_all_gallery_wrong(),
            ).pack(side=tk.LEFT, padx=3)

            tk.Button(
                gallery_quick_tools,
                text='🔄 反选切换',
                font=('微软雅黑', 9),
                bg='#e2e3e5',
                fg='#383d41',
                activebackground='#d6d8db',
                relief='groove',
                cursor='hand2',
                padx=8,
                pady=2,
                command=lambda: invert_gallery_decisions(),
            ).pack(side=tk.LEFT, padx=3)

            # 2. 中间多列平铺卡片滚动画廊（自适应宽度与滚动条）
            canvas_container = ttk.Frame(preview_frame)
            canvas_container.pack(fill=tk.BOTH, expand=True, padx=6, pady=3)

            gallery_canvas = tk.Canvas(canvas_container, bg='#f4f6f9', highlightthickness=0)
            gallery_scrollbar = ttk.Scrollbar(canvas_container, orient=tk.VERTICAL, command=gallery_canvas.yview)
            gallery_canvas.configure(yscrollcommand=gallery_scrollbar.set)

            gallery_canvas.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
            gallery_scrollbar.pack(side=tk.RIGHT, fill=tk.Y)

            cards_inner_frame = tk.Frame(gallery_canvas, bg='#f4f6f9')
            canvas_win_id = gallery_canvas.create_window((0, 0), window=cards_inner_frame, anchor='nw')

            def on_cards_frame_configure(event=None):
                gallery_canvas.configure(scrollregion=gallery_canvas.bbox('all'))

            cards_inner_frame.bind('<Configure>', on_cards_frame_configure)

            def on_gallery_canvas_configure(event):
                gallery_canvas.itemconfig(canvas_win_id, width=event.width)
                relayout_cards()

            gallery_canvas.bind('<Configure>', on_gallery_canvas_configure)

            def _on_mousewheel(event):
                if gallery_canvas.winfo_exists():
                    gallery_canvas.yview_scroll(int(-1 * (event.delta / 120)), 'units')

            gallery_canvas.bind('<Enter>', lambda e: gallery_canvas.bind_all('<MouseWheel>', _on_mousewheel))
            gallery_canvas.bind('<Leave>', lambda e: gallery_canvas.unbind_all('<MouseWheel>'))

            # 3. 底部直接提交操作栏（顶底双提交，无论滚到哪里都可一键提交）
            bottom_submit_bar = tk.Frame(preview_frame, bg='#eaf2f8', bd=1, relief='solid', padx=10, pady=5)
            bottom_submit_bar.pack(fill=tk.X, padx=8, pady=(2, 3))

            tk.Label(
                bottom_submit_bar,
                text='💡 提示：点击图片切换对/错状态；支持按回车键 (Enter) 直接提交本组',
                font=('微软雅黑', 9),
                foreground='#555555',
                background='#eaf2f8',
            ).pack(side=tk.LEFT, padx=4)

            bottom_submit_btn = tk.Button(
                bottom_submit_bar,
                text='🚀 提交本组全部判分 (对 0 / 错 0)',
                font=('微软雅黑', 12, 'bold'),
                bg='#28a745',
                fg='white',
                activebackground='#218838',
                activeforeground='white',
                relief='raised',
                cursor='hand2',
                padx=18,
                pady=4,
                state='disabled',
                command=lambda: execute_gallery_batch_submit(),
            )
            bottom_submit_btn.pack(side=tk.RIGHT, padx=4)

            tk.Button(
                bottom_submit_bar,
                text='🔄 反选',
                font=('微软雅黑', 9),
                bg='#e2e3e5',
                fg='#383d41',
                activebackground='#d6d8db',
                relief='groove',
                cursor='hand2',
                padx=6,
                pady=2,
                command=lambda: invert_gallery_decisions(),
            ).pack(side=tk.RIGHT, padx=2)

            tk.Button(
                bottom_submit_bar,
                text='❌ 全错',
                font=('微软雅黑', 9, 'bold'),
                bg='#f8d7da',
                fg='#721c24',
                activebackground='#f5c6cb',
                relief='groove',
                cursor='hand2',
                padx=6,
                pady=2,
                command=lambda: set_all_gallery_wrong(),
            ).pack(side=tk.RIGHT, padx=2)

            tk.Button(
                bottom_submit_bar,
                text='✔ 全对',
                font=('微软雅黑', 9, 'bold'),
                bg='#d4edda',
                fg='#155724',
                activebackground='#c3e6cb',
                relief='groove',
                cursor='hand2',
                padx=6,
                pady=2,
                command=lambda: set_all_gallery_correct(),
            ).pack(side=tk.RIGHT, padx=2)

            # 4. 底部紧凑型归类与长效记忆面板
            bind_card = ttk.LabelFrame(preview_frame, text='OCR识别结果归类与长效记忆 (高级)', padding=(6, 3))
            bind_card.pack(fill=tk.X, padx=6, pady=(2, 4))

            batch_info_label = ttk.Label(bind_card, textvariable=batch_info_var, font=('Arial', 9, 'bold'), foreground='#0B5CAD', wraplength=430, justify=tk.LEFT)
            batch_info_label.pack(fill=tk.X, pady=(0, 2))

            row1 = ttk.Frame(bind_card)
            row1.pack(fill=tk.X, pady=(1, 2))
            ttk.Label(row1, text='OCR文本:', font=('Arial', 9, 'bold')).pack(side=tk.LEFT, padx=(0, 4))
            ocr_edit_var = tk.StringVar()
            ocr_edit_entry = ttk.Entry(row1, textvariable=ocr_edit_var, font=('Arial', 9))
            ocr_edit_entry.pack(side=tk.LEFT, fill=tk.X, expand=True, padx=(0, 4))

            action_options = ['备选答案', '答案关键字', '错误答案', '错误答案关键字']
            action_combo = ttk.Combobox(row1, values=action_options, state='readonly', width=12, font=('Arial', 9))
            action_combo.set('备选答案')
            action_combo.pack(side=tk.LEFT, padx=(0, 4))

            save_btn = ttk.Button(row1, text='保存', width=8, command=lambda: on_save_clicked())
            save_btn.pack(side=tk.LEFT, padx=(0, 3))

            remember_btn = ttk.Button(row1, text='记忆', width=8, command=lambda: on_remember_clicked())
            remember_btn.pack(side=tk.LEFT, padx=(0, 3))

            delete_btn = ttk.Button(row1, text='删除', width=8, command=lambda: on_delete_clicked())
            delete_btn.pack(side=tk.LEFT, padx=(0, 3))

            skip_btn = ttk.Button(row1, text='保留人工', width=9, command=lambda: keep_group_for_manual())
            skip_btn.pack(side=tk.LEFT, padx=(0, 0))

            quick_frame = ttk.Frame(bind_card)
            quick_frame.pack(fill=tk.X, pady=(2, 1))

            ttk.Button(quick_frame, text='✔ 设为备选答案', command=lambda: apply_batch_action('alternate_answer')).pack(side=tk.LEFT, padx=2)
            ttk.Button(quick_frame, text='✔ 设为答案关键字', command=lambda: apply_batch_action('correct_keyword')).pack(side=tk.LEFT, padx=2)
            ttk.Button(quick_frame, text='✖ 设为错误答案', command=lambda: apply_batch_action('wrong_answer')).pack(side=tk.LEFT, padx=2)
            ttk.Button(quick_frame, text='✖ 设为错误关键字', command=lambda: apply_batch_action('wrong_keyword')).pack(side=tk.LEFT, padx=2)
            ttk.Checkbutton(quick_frame, text='存入长效记忆库', variable=remember_also_var).pack(side=tk.LEFT, padx=4)

            dialog_state = {
                'groups': {},
                'selected': '',
                'sample_index': 0,
                'photo': None,
                'checked_ids': set(),
                'gallery_photos': [],
                'gallery_card_widgets': {},
                'gallery_decisions': {},
                'persisted_decisions': {}, # 跨分类持久记忆判分决策字典，切换分类绝不复位！
                'gallery_max_scores': {},
                'gallery_card_frames': [],
                'current_gallery_group': None,
                'current_cols': None,
                'bottom_submit_btn': bottom_submit_btn,
            }
            status_text = '等待归类。'
            if remembered_count:
                status_text = f'已先按长效记忆及设置自动二次批改处理 {remembered_count} 个空。'
            classify_status_var = tk.StringVar(value=status_text)

            def open_full_image_viewer(image_path, title_text):
                if not image_path or not os.path.exists(image_path):
                    return
                viewer = tk.Toplevel(classify_win)
                viewer.title(f"答题原图查看 - {title_text}")
                viewer.geometry('800x600')
                viewer.transient(classify_win)
                try:
                    raw_img = Image.open(image_path).convert('RGB')
                    raw_photo = ImageTk.PhotoImage(raw_img)
                    v_lbl = ttk.Label(viewer, image=raw_photo, anchor='center')
                    v_lbl.image = raw_photo
                    v_lbl.pack(fill=tk.BOTH, expand=True, padx=8, pady=8)
                except Exception as e:
                    ttk.Label(viewer, text=f"无法加载原图：{e}").pack(pady=20)
                ttk.Button(viewer, text='关闭', command=viewer.destroy).pack(pady=(0, 8))

            def update_single_card_ui(t_key):
                w = dialog_state['gallery_card_widgets'].get(t_key)
                if not w:
                    return
                score = dialog_state['persisted_decisions'].get(t_key, 0.0)
                m_score = dialog_state['gallery_max_scores'].get(t_key, 1.0)
                score_disp = int(score) if score.is_integer() else score

                if score > 0:
                    bg = '#e8f5e9'
                    border = '#28a745'
                    badge_bg = '#28a745'
                    badge_fg = 'white'
                    badge_text = f"✔ 对 ({score_disp}分)"
                    hint_text = "✔ 已判对 (点击设为错)"
                    name_fg = '#1b5e20'
                else:
                    bg = '#ffebee'
                    border = '#dc3545'
                    badge_bg = '#dc3545'
                    badge_fg = 'white'
                    badge_text = "❌ 错 (0分)"
                    hint_text = "❌ 已判错 (点击设为对)"
                    name_fg = '#b71c1c'

                w['frame'].configure(bg=bg, highlightthickness=2, highlightbackground=border)
                w['top_row'].configure(bg=bg)
                w['name_lbl'].configure(bg=bg, fg=name_fg)
                w['badge_lbl'].configure(bg=badge_bg, fg=badge_fg, text=badge_text)
                w['img_lbl'].configure(bg=bg)
                w['hint_lbl'].configure(bg=bg, fg=name_fg, text=hint_text)

            def update_gallery_summary():
                group = dialog_state.get('current_gallery_group')
                if not group or not group.get('tasks'):
                    gallery_stat_var.set('')
                    gallery_submit_btn.configure(text='🚀 提交本组全部判分', state='disabled')
                    if 'bottom_submit_btn' in dialog_state:
                        dialog_state['bottom_submit_btn'].configure(text='🚀 提交本组全部判分', state='disabled')
                    return
                tasks_list = group['tasks']
                total = len(tasks_list)
                right_cnt = sum(
                    1 for t in tasks_list
                    if dialog_state['persisted_decisions'].get((t['entry_key'], t['part_id']), 0.0) > 0
                )
                wrong_cnt = total - right_cnt

                status_txt = f"判定状态：✔ 对 {right_cnt} 份  |  ❌ 错 {wrong_cnt} 份  (共 {total} 份，点击图片直接切换)"
                gallery_stat_var.set(status_txt)
                submit_txt = f"🚀 提交本组全部判分 (对 {right_cnt} / 错 {wrong_cnt})"
                gallery_submit_btn.configure(
                    text=submit_txt,
                    state='normal',
                )
                if 'bottom_submit_btn' in dialog_state:
                    dialog_state['bottom_submit_btn'].configure(
                        text=submit_txt,
                        state='normal',
                    )

            def set_all_gallery_correct():
                group = dialog_state.get('current_gallery_group')
                if not group:
                    return
                for task_item in group.get('tasks', []):
                    t_key = (task_item['entry_key'], task_item['part_id'])
                    m_score = dialog_state['gallery_max_scores'].get(t_key, 1.0)
                    dialog_state['persisted_decisions'][t_key] = m_score
                    dialog_state['gallery_decisions'][t_key] = m_score
                    update_single_card_ui(t_key)
                update_gallery_summary()

            def set_all_gallery_wrong():
                group = dialog_state.get('current_gallery_group')
                if not group:
                    return
                for task_item in group.get('tasks', []):
                    t_key = (task_item['entry_key'], task_item['part_id'])
                    dialog_state['persisted_decisions'][t_key] = 0.0
                    dialog_state['gallery_decisions'][t_key] = 0.0
                    update_single_card_ui(t_key)
                update_gallery_summary()

            def invert_gallery_decisions():
                group = dialog_state.get('current_gallery_group')
                if not group:
                    return
                for task_item in group.get('tasks', []):
                    t_key = (task_item['entry_key'], task_item['part_id'])
                    cur = dialog_state['persisted_decisions'].get(t_key, 0.0)
                    m_score = dialog_state['gallery_max_scores'].get(t_key, 1.0)
                    new_val = 0.0 if cur > 0 else m_score
                    dialog_state['persisted_decisions'][t_key] = new_val
                    dialog_state['gallery_decisions'][t_key] = new_val
                    update_single_card_ui(t_key)
                update_gallery_summary()

            def relayout_cards():
                cards = dialog_state.get('gallery_card_frames', [])
                if not cards:
                    return
                canvas_w = gallery_canvas.winfo_width()
                if canvas_w <= 100:
                    return
                cols = max(2, (canvas_w - 24) // 250)
                if dialog_state.get('current_cols') == cols:
                    return
                dialog_state['current_cols'] = cols
                for idx, card in enumerate(cards):
                    r = idx // cols
                    c = idx % cols
                    card.grid(row=r, column=c, padx=6, pady=6, sticky='nsew')

            def render_gallery(group):
                for child in cards_inner_frame.winfo_children():
                    child.destroy()
                dialog_state['gallery_photos'] = []
                dialog_state['gallery_card_widgets'] = {}
                dialog_state['gallery_card_frames'] = []
                dialog_state['current_gallery_group'] = group
                dialog_state['current_cols'] = None

                if not group or not group.get('tasks'):
                    gallery_title_var.set('请在左侧选择一个题目分类')
                    gallery_stat_var.set('')
                    gallery_submit_btn.configure(text='🚀 提交本组全部判分', state='disabled')
                    if 'bottom_submit_btn' in dialog_state:
                        dialog_state['bottom_submit_btn'].configure(text='🚀 提交本组全部判分', state='disabled')
                    lbl = ttk.Label(
                        cards_inner_frame,
                        text='当前分类无待判试卷，或所有试卷已完成批改。',
                        font=('微软雅黑', 11),
                        foreground='#888888',
                    )
                    lbl.pack(pady=50)
                    return

                tasks_list = group['tasks']
                total_tasks = len(tasks_list)
                part_label = group.get('label', '')
                ocr_disp = group.get('ocr_text', '')
                exp_disp = group.get('expected', '')
                sample_part = tasks_list[0]['part']
                max_score = float(sample_part.get('score') or 1.0)
                score_lbl = int(max_score) if max_score.is_integer() else max_score

                gallery_title_var.set(
                    f"【{part_label} (满分 {score_lbl}分) | OCR：“{ocr_disp}”】 标准：{exp_disp}  (共 {total_tasks} 份作答)"
                )

                for idx, task_item in enumerate(tasks_list):
                    t_key = (task_item['entry_key'], task_item['part_id'])
                    t_max = float(task_item['part'].get('score') or 1.0)
                    dialog_state['gallery_max_scores'][t_key] = t_max

                    # 关键改进：使用持久化判分字典，切换分类切回时保留状态，绝不复位！
                    if t_key not in dialog_state['persisted_decisions']:
                        # 用户需求：图片的默认状态为错 (0分)
                        dialog_state['persisted_decisions'][t_key] = 0.0

                    dialog_state['gallery_decisions'][t_key] = dialog_state['persisted_decisions'][t_key]

                    card_frame = tk.Frame(
                        cards_inner_frame,
                        bd=2,
                        relief='solid',
                        cursor='hand2',
                    )

                    top_row = tk.Frame(card_frame)
                    top_row.pack(fill=tk.X, padx=4, pady=(3, 2))

                    st_name = task_item['entry'].get('student_name', '') or '未知学生'
                    sc_id = task_item['entry'].get('score_id', '')
                    name_text = f"#{idx + 1} {st_name}" + (f" ({sc_id})" if sc_id else "")
                    name_lbl = tk.Label(top_row, text=name_text, font=('Arial', 9, 'bold'), anchor='w')
                    name_lbl.pack(side=tk.LEFT, fill=tk.X, expand=True)

                    badge_lbl = tk.Label(top_row, font=('Arial', 9, 'bold'), width=9, anchor='center')
                    badge_lbl.pack(side=tk.RIGHT)

                    crop_path = task_item.get('crop_path')
                    crop_ok = False
                    if crop_path and os.path.exists(crop_path):
                        try:
                            pil_img = Image.open(crop_path).convert('RGB')
                            pil_img.thumbnail((230, 115), Image.LANCZOS)
                            tk_photo = ImageTk.PhotoImage(pil_img)
                            dialog_state['gallery_photos'].append(tk_photo)
                            img_lbl = tk.Label(card_frame, image=tk_photo, cursor='hand2')
                            crop_ok = True
                        except Exception as err:
                            img_lbl = tk.Label(card_frame, text=f"图片读取失败\n{err}", height=5, cursor='hand2')
                    else:
                        img_lbl = tk.Label(card_frame, text="无答题切片图片", height=5, cursor='hand2')
                    img_lbl.pack(fill=tk.BOTH, expand=True, padx=4, pady=2)

                    hint_lbl = tk.Label(card_frame, font=('Arial', 8), anchor='center')
                    hint_lbl.pack(fill=tk.X, padx=2, pady=(1, 3))

                    dialog_state['gallery_card_widgets'][t_key] = {
                        'frame': card_frame,
                        'top_row': top_row,
                        'name_lbl': name_lbl,
                        'badge_lbl': badge_lbl,
                        'img_lbl': img_lbl,
                        'hint_lbl': hint_lbl,
                    }
                    dialog_state['gallery_card_frames'].append(card_frame)

                    # 点击切换状态 (错 0分 <-> 对 满分/1分)
                    def make_toggle(target_key=t_key, full_score=t_max):
                        def _handler(event=None):
                            cur = dialog_state['persisted_decisions'].get(target_key, 0.0)
                            new_val = full_score if cur == 0.0 else 0.0
                            dialog_state['persisted_decisions'][target_key] = new_val
                            dialog_state['gallery_decisions'][target_key] = new_val
                            update_single_card_ui(target_key)
                            update_gallery_summary()
                        return _handler

                    toggle_fn = make_toggle(t_key, t_max)
                    for w in (card_frame, top_row, name_lbl, badge_lbl, img_lbl, hint_lbl):
                        w.bind('<Button-1>', toggle_fn)

                    # 双击或右键图片放大看原图
                    if crop_ok and crop_path:
                        def make_zoom(cp=crop_path, title=name_text):
                            def _zoom(event=None):
                                open_full_image_viewer(cp, title)
                                return 'break'
                            return _zoom
                        img_lbl.bind('<Double-Button-1>', make_zoom(crop_path, name_text))
                        img_lbl.bind('<Button-3>', make_zoom(crop_path, name_text))

                    update_single_card_ui(t_key)

                relayout_cards()
                update_gallery_summary()

            def execute_gallery_batch_submit(target_groups=None):
                if target_groups is None:
                    curr = dialog_state.get('current_gallery_group')
                    target_groups = [curr] if curr else []

                valid_targets = [g for g in target_groups if g and g.get('tasks')]
                if not valid_targets:
                    messagebox.showinfo('OCR结果分类', '当前没有可提交判分的分类试卷。', parent=classify_win)
                    return

                total_processed = 0
                total_right = 0
                total_wrong = 0

                for group in valid_targets:
                    tasks_list = group['tasks']
                    for task_item in tasks_list:
                        t_key = (task_item['entry_key'], task_item['part_id'])
                        score = dialog_state['persisted_decisions'].get(t_key, 0.0)
                        m_score = dialog_state['gallery_max_scores'].get(t_key, float(task_item['part'].get('score') or 1.0))
                        assigned = max(0.0, min(float(score), m_score))
                        if assigned > 0:
                            total_right += 1
                        else:
                            total_wrong += 1

                        entry_scores = all_scores.setdefault(task_item['entry_key'], {})
                        record = entry_scores.setdefault(task_item['part_id'], {})
                        record.update({
                            'score': assigned,
                            'max_score': m_score,
                            'manual_graded': True,
                            'teacher_regraded': True,
                            'auto_graded': False,
                            'ocr_auto_need_manual': False,
                            'auto_grade_engine': 'OCR分类看图判分',
                            'auto_grade_reason': f'看图批量判分：{assigned}分 (满分{m_score}分)',
                            'label': task_item['part'].get('label', ''),
                            'student_name': task_item['entry'].get('student_name', ''),
                            'score_id': task_item['entry'].get('score_id', ''),
                            'file': task_item['entry'].get('file', ''),
                            'updated_at': datetime.now().isoformat(timespec='seconds'),
                        })
                        dialog_state['persisted_decisions'].pop(t_key, None)
                        total_processed += 1

                self.save_subjective_score_payload(payload)
                refresh_main_result_views()
                refresh()

                if len(valid_targets) == 1:
                    g = valid_targets[0]
                    classify_status_var.set(
                        f"【批量判分完成】已成功提交【{g['label']} - “{g['ocr_text']}”】共 {total_processed} 份：对 {total_right} 份，错 {total_wrong} 份！"
                    )
                else:
                    classify_status_var.set(
                        f"【多选批量提交完成】已成功提交 {len(valid_targets)} 个分类共 {total_processed} 份试卷：对 {total_right} 份，错 {total_wrong} 份！"
                    )

                rebuild_groups()

            def on_key_return_submit(_event=None):
                focus_w = classify_win.focus_get()
                if isinstance(focus_w, (tk.Entry, ttk.Entry, tk.Text)):
                    return
                execute_gallery_batch_submit()
                return 'break'

            classify_win.bind('<Return>', on_key_return_submit)
            classify_win.bind('<KP_Enter>', on_key_return_submit)

            def expected_display(task_item):
                config = self.normalize_ocr_config(task_item['part'].get('ocr'))
                answers = self.subjective_expected_answers_from_config(config)
                keywords = self.split_expected_keywords(config.get('expected_keywords'))
                values = []
                if answers:
                    values.append(' / '.join(answers))
                if keywords:
                    values.append('关键词：' + ' / '.join(keywords))
                return '；'.join(values) or '未设置'

            def collect_groups():
                grouped = {}
                for task_item in tasks:
                    part = task_item.get('part', {})
                    kind = str(part.get('kind') or '').lower()
                    pid = str(task_item.get('part_id') or '').lower()
                    if kind in ('drawing', 'calculation') or bool(part.get('manual_only')) or pid.startswith('calc_'):
                        continue
                    if not is_manual_grade_task(task_item):
                        continue
                    record = all_scores.get(task_item['entry_key'], {}).get(task_item['part_id'], {})
                    recognized_text = self.recognized_ocr_text_for_classification(record)
                    text_key = self.normalize_subjective_answer_for_match(recognized_text)
                    if not text_key:
                        continue
                    group_key = (task_item['part_id'], text_key)
                    if group_key in ignored_groups:
                        continue
                    group = grouped.setdefault(group_key, {
                        'part_id': task_item['part_id'],
                        'label': task_item['part'].get('label', ''),
                        'expected': expected_display(task_item),
                        'ocr_text': recognized_text,
                        'tasks': [],
                    })
                    group['tasks'].append(task_item)
                return sorted(
                    grouped.values(),
                    key=lambda item: (
                        -len(item['tasks']),
                        part_order.get(item['part_id'], 999999),
                        item['ocr_text'],
                    ),
                )

            def current_group():
                return dialog_state['groups'].get(dialog_state.get('selected'))

            def get_target_groups():
                checked_ids = dialog_state.get('checked_ids', set())
                checked = [dialog_state['groups'][k] for k in checked_ids if k in dialog_state['groups']]
                if checked:
                    return checked
                tree_selected = group_tree.selection()
                if len(tree_selected) > 1:
                    return [dialog_state['groups'][k] for k in tree_selected if k in dialog_state['groups']]
                if tree_selected and tree_selected[0] in dialog_state['groups']:
                    return [dialog_state['groups'][tree_selected[0]]]
                curr = current_group()
                if curr:
                    return [curr]
                return []

            def update_selection_ui():
                targets = get_target_groups()
                count = len(targets)
                total_tasks = sum(len(g['tasks']) for g in targets)

                if count == 0:
                    selection_summary_var.set('已选 0 项')
                    ocr_edit_var.set('')
                    ocr_edit_entry.configure(state='normal')
                    batch_info_var.set('请在左侧列表点击或勾选要归类的一组/多组识别结果。')
                    save_btn.configure(text='保存')
                    remember_btn.configure(text='记忆')
                    delete_btn.configure(text='删除')
                    skip_btn.configure(text='保留人工')
                elif count == 1:
                    g = targets[0]
                    selection_summary_var.set(f"已选 1 项 (共 {total_tasks} 份)")
                    ocr_edit_entry.configure(state='normal')
                    ocr_edit_var.set(g['ocr_text'])
                    ocr_config = g['tasks'][0]['part'].get('ocr') or {}
                    existing_action = self.lookup_ocr_result_classification(ocr_config, g['ocr_text'])
                    if existing_action and existing_action in action_labels:
                        action_combo.set(action_labels[existing_action])
                    batch_info_var.set(f"当前单项：{g['label']}（该分类共 {total_tasks} 份学生作答）")
                    save_btn.configure(text='保存')
                    remember_btn.configure(text='记忆')
                    delete_btn.configure(text='删除')
                    skip_btn.configure(text='保留人工')
                else:
                    selection_summary_var.set(f"已选 {count} 项 (共 {total_tasks} 份)")
                    ocr_edit_var.set(f"【批量操作】已勾选/选中 {count} 个项目（将分别归类各题对应OCR结果）")
                    ocr_edit_entry.configure(state='readonly')
                    batch_info_var.set(f"⚡ 批量模式：已选中 {count} 个题目分类，共涵盖 {total_tasks} 份学生试卷")
                    save_btn.configure(text=f'批量保存 ({count})')
                    remember_btn.configure(text=f'批量记忆 ({count})')
                    delete_btn.configure(text=f'批量删除 ({count})')
                    skip_btn.configure(text=f'批量保留 ({count})')

            def toggle_check_item(item_id):
                if not item_id or item_id not in dialog_state['groups']:
                    return
                checked_set = dialog_state.setdefault('checked_ids', set())
                if item_id in checked_set:
                    checked_set.remove(item_id)
                    sym = '☐'
                else:
                    checked_set.add(item_id)
                    sym = '☑'
                vals = list(group_tree.item(item_id, 'values'))
                if vals:
                    vals[0] = sym
                    group_tree.item(item_id, values=vals)
                dialog_state['selected'] = item_id
                update_selection_ui()
                render_gallery(current_group())

            def toggle_check_all():
                checked_set = dialog_state.setdefault('checked_ids', set())
                all_ids = list(dialog_state['groups'].keys())
                if not all_ids:
                    return
                if len(checked_set) == len(all_ids):
                    checked_set.clear()
                    for k in all_ids:
                        vals = list(group_tree.item(k, 'values'))
                        if vals:
                            vals[0] = '☐'
                            group_tree.item(k, values=vals)
                else:
                    checked_set.update(all_ids)
                    for k in all_ids:
                        vals = list(group_tree.item(k, 'values'))
                        if vals:
                            vals[0] = '☑'
                            group_tree.item(k, values=vals)
                update_selection_ui()

            def uncheck_all():
                checked_set = dialog_state.setdefault('checked_ids', set())
                checked_set.clear()
                for k in dialog_state['groups'].keys():
                    vals = list(group_tree.item(k, 'values'))
                    if vals:
                        vals[0] = '☐'
                        group_tree.item(k, values=vals)
                update_selection_ui()

            def invert_check():
                checked_set = dialog_state.setdefault('checked_ids', set())
                all_ids = list(dialog_state['groups'].keys())
                if not all_ids:
                    return
                for k in all_ids:
                    if k in checked_set:
                        checked_set.remove(k)
                        sym = '☐'
                    else:
                        checked_set.add(k)
                        sym = '☑'
                    vals = list(group_tree.item(k, 'values'))
                    if vals:
                        vals[0] = sym
                        group_tree.item(k, values=vals)
                update_selection_ui()

            def refresh_sample():
                render_gallery(current_group())

            def select_first_group():
                children = group_tree.get_children()
                if not children:
                    dialog_state['selected'] = ''
                    update_selection_ui()
                    render_gallery(None)
                    return
                first = children[0]
                group_tree.selection_set(first)
                group_tree.focus(first)
                dialog_state['selected'] = first
                dialog_state['sample_index'] = 0
                update_selection_ui()
                render_gallery(current_group())

            def rebuild_groups():
                for item_id in group_tree.get_children():
                    group_tree.delete(item_id)
                dialog_state['groups'] = {}
                dialog_state.setdefault('checked_ids', set()).clear()
                for index, group in enumerate(collect_groups()):
                    item_id = f'group_{index}'
                    dialog_state['groups'][item_id] = group
                    group_tree.insert('', tk.END, iid=item_id, values=(
                        '☐', group['label'], group['expected'], group['ocr_text'], len(group['tasks']),
                    ))
                select_first_group()
                remaining = len(dialog_state['groups'])
                if remaining == 0:
                    classify_status_var.set('所有待分类试卷已全部打分完成！')
                update_selection_ui()

            def on_group_selected(_event=None):
                selected = group_tree.selection()
                if not selected:
                    return
                dialog_state['selected'] = selected[0]
                dialog_state['sample_index'] = 0
                update_selection_ui()
                render_gallery(current_group())

            def on_tree_click(event):
                region = group_tree.identify_region(event.x, event.y)
                if region in ('cell', 'tree'):
                    col = group_tree.identify_column(event.x)
                    if col == '#1':
                        item_id = group_tree.identify_row(event.y)
                        if item_id:
                            toggle_check_item(item_id)
                            return 'break'

            def on_tree_double_click(event):
                item_id = group_tree.identify_row(event.y)
                if item_id:
                    toggle_check_item(item_id)
                    return 'break'

            def on_space_pressed(_event):
                sel = group_tree.selection()
                if not sel:
                    return
                checked_set = dialog_state.setdefault('checked_ids', set())
                should_check = any(k not in checked_set for k in sel)
                for k in sel:
                    if should_check:
                        checked_set.add(k)
                        sym = '☑'
                    else:
                        checked_set.discard(k)
                        sym = '☐'
                    vals = list(group_tree.item(k, 'values'))
                    if vals:
                        vals[0] = sym
                        group_tree.item(k, values=vals)
                update_selection_ui()
                return 'break'

            group_tree.bind('<<TreeviewSelect>>', on_group_selected)
            group_tree.bind('<Button-1>', on_tree_click, add='+')
            group_tree.bind('<Double-1>', on_tree_double_click)
            group_tree.bind('<space>', on_space_pressed)
            ocr_edit_entry.bind('<Return>', lambda _e: on_save_clicked())

            def execute_save(targets, action):
                if not targets:
                    messagebox.showinfo('OCR结果分类', '请先在左侧勾选或选择至少一组识别结果。', parent=classify_win)
                    return
                display_label = action_labels.get(action, action)
                affected_part_ids = set()
                updated_configs_map = {}

                for group in targets:
                    part_id = group['part_id']
                    affected_part_ids.add(part_id)
                    if part_id in updated_configs_map:
                        source_config = updated_configs_map[part_id]
                    else:
                        source_config = self.normalize_ocr_config(group['tasks'][0]['part'].get('ocr'))

                    if len(targets) == 1:
                        text_to_bind = ocr_edit_var.get().strip() or group['ocr_text']
                    else:
                        text_to_bind = group['ocr_text'].strip()

                    if not text_to_bind:
                        continue

                    updated_config = self.append_ocr_classification_to_config(
                        source_config,
                        text_to_bind,
                        action,
                    )
                    updated_configs_map[part_id] = updated_config

                try:
                    self.save_ocr_settings_for_parts(updated_configs_map)
                    self.sync_loaded_answer_scheme_ocr_settings()
                except Exception as e:
                    messagebox.showerror('保存失败', str(e), parent=classify_win)
                    return

                fresh_parts = {part['part_id']: part for part in self.iter_subjective_parts()}
                for pid in affected_part_ids:
                    fresh_part = fresh_parts.get(pid)
                    if fresh_part:
                        for part in parts:
                            if part.get('part_id') == pid:
                                part['ocr'] = fresh_part.get('ocr')
                        for task_item in tasks:
                            if task_item.get('part_id') == pid:
                                task_item['part']['ocr'] = fresh_part.get('ocr')

                processed = 0
                for group in targets:
                    if len(targets) == 1:
                        text_to_bind = ocr_edit_var.get().strip() or group['ocr_text']
                    else:
                        text_to_bind = group['ocr_text'].strip()

                    for task_item in group['tasks']:
                        record = all_scores.get(task_item['entry_key'], {}).get(task_item['part_id'], {})
                        if not isinstance(record, dict) or record.get('manual_graded'):
                            continue
                        if action in ('alternate_answer', 'correct_keyword'):
                            matched = self.apply_subjective_answer_auto_score(record, task_item, group['ocr_text'])
                            if not matched and text_to_bind:
                                matched = self.apply_subjective_answer_auto_score(record, task_item, text_to_bind)
                            if not matched:
                                continue
                            record.update({
                                'auto_grade_engine': 'OCR结果分类',
                                'ocr_auto_need_manual': False,
                                'ocr_auto_reason': '',
                            })
                        else:
                            self.mark_subjective_auto_zero_record(
                                record,
                                task_item,
                                group['ocr_text'],
                                'OCR结果分类',
                                f'当前归类为{display_label}',
                            )
                        record.update({
                            'ocr_classification_action': action,
                            'ocr_classification_text': text_to_bind,
                            'ocr_classification_updated_at': datetime.now().isoformat(timespec='seconds'),
                        })
                        processed += 1

                other_re_scored = 0
                for pid in affected_part_ids:
                    other_re_scored += apply_standard_to_pending_tasks(target_part_id=pid)

                self.save_subjective_score_payload(payload)
                refresh_main_result_views()
                refresh()

                extra_note = f'，二次重判相关题目待人工项 {other_re_scored} 份' if other_re_scored else ''
                if len(targets) == 1:
                    g = targets[0]
                    classify_status_var.set(
                        f"【当前有效】{g['label']} 的“{text_to_bind}”已保存为【{display_label}】；当前完成 {processed} 份{extra_note}。"
                    )
                else:
                    classify_status_var.set(
                        f"【批量保存完成】已将 {len(targets)} 个识别分类保存为【{display_label}】；直接完成 {processed} 份{extra_note}。"
                    )
                dialog_state.setdefault('checked_ids', set()).clear()
                rebuild_groups()

            def execute_remember(targets, action, silent=False):
                if not targets:
                    messagebox.showinfo('OCR结果分类', '请先在左侧勾选或选择至少一组识别结果。', parent=classify_win)
                    return
                display_label = action_labels.get(action, action)
                affected_part_ids = set()
                updated_configs_map = {}

                for group in targets:
                    part_id = group['part_id']
                    affected_part_ids.add(part_id)
                    if part_id in updated_configs_map:
                        source_config = updated_configs_map[part_id]
                    else:
                        source_config = self.normalize_ocr_config(group['tasks'][0]['part'].get('ocr'))

                    if len(targets) == 1:
                        text_to_bind = ocr_edit_var.get().strip() or group['ocr_text']
                    else:
                        text_to_bind = group['ocr_text'].strip()

                    if not text_to_bind:
                        continue

                    # 1. 存入长效记忆库
                    self.remember_ocr_result_classification(source_config, text_to_bind, action)
                    if group['ocr_text'] and group['ocr_text'] != text_to_bind:
                        self.remember_ocr_result_classification(source_config, group['ocr_text'], action)

                    # 2. 同时更新当前设置
                    updated_config = self.append_ocr_classification_to_config(
                        source_config,
                        text_to_bind,
                        action,
                    )
                    updated_configs_map[part_id] = updated_config

                try:
                    self.save_ocr_settings_for_parts(updated_configs_map)
                    self.sync_loaded_answer_scheme_ocr_settings()
                except Exception:
                    pass

                fresh_parts = {part['part_id']: part for part in self.iter_subjective_parts()}
                for pid in affected_part_ids:
                    fresh_part = fresh_parts.get(pid)
                    if fresh_part:
                        for part in parts:
                            if part.get('part_id') == pid:
                                part['ocr'] = fresh_part.get('ocr')
                        for task_item in tasks:
                            if task_item.get('part_id') == pid:
                                task_item['part']['ocr'] = fresh_part.get('ocr')

                processed = 0
                for group in targets:
                    if len(targets) == 1:
                        text_to_bind = ocr_edit_var.get().strip() or group['ocr_text']
                    else:
                        text_to_bind = group['ocr_text'].strip()

                    for task_item in group['tasks']:
                        record = all_scores.get(task_item['entry_key'], {}).get(task_item['part_id'], {})
                        if not isinstance(record, dict) or record.get('manual_graded'):
                            continue
                        if action in ('alternate_answer', 'correct_keyword'):
                            matched = self.apply_subjective_answer_auto_score(record, task_item, group['ocr_text'])
                            if not matched and text_to_bind:
                                matched = self.apply_subjective_answer_auto_score(record, task_item, text_to_bind)
                            if not matched:
                                continue
                            record.update({
                                'auto_grade_engine': 'OCR长效记忆',
                                'ocr_auto_need_manual': False,
                                'ocr_auto_reason': '',
                            })
                        else:
                            self.mark_subjective_auto_zero_record(
                                record,
                                task_item,
                                group['ocr_text'],
                                'OCR长效记忆',
                                f'命中长效记忆的{display_label}',
                            )
                        record.update({
                            'ocr_classification_action': action,
                            'ocr_classification_text': text_to_bind,
                            'ocr_classification_updated_at': datetime.now().isoformat(timespec='seconds'),
                        })
                        processed += 1

                other_re_scored = 0
                for pid in affected_part_ids:
                    other_re_scored += apply_standard_to_pending_tasks(target_part_id=pid)

                self.save_subjective_score_payload(payload)
                refresh_main_result_views()
                refresh()

                total_graded = processed + other_re_scored
                if len(targets) == 1:
                    g = targets[0]
                    classify_status_var.set(
                        f"★【长效记忆】已将“{text_to_bind}”关联到标准答案！当前试卷二次批改完成 {total_graded} 份。"
                    )
                    if not silent:
                        messagebox.showinfo(
                            '长效记忆已保存',
                            f"已将“{text_to_bind}”关联为标准答案的【{display_label}】！\n\n"
                            f"该规则为长效记忆（只允许新记忆覆盖）。\n"
                            f"以后批改其他试卷时，只要遇到相同的试题标准答案，系统将自动长效引用生效。",
                            parent=classify_win,
                        )
                else:
                    classify_status_var.set(
                        f"★【批量长效记忆】已将 {len(targets)} 项批量关联到标准答案库并完成批改 {total_graded} 份！"
                    )
                    if not silent:
                        messagebox.showinfo(
                            '批量长效记忆已保存',
                            f"已将选中的 {len(targets)} 个识别分类批量关联为【{display_label}】！\n\n"
                            f"全部已写入长效记忆库（只允许新记忆覆盖），以后批改其他试卷遇到相同题型标准时将自动长效复用生效。\n\n"
                            f"当前试卷已完成批改 {total_graded} 份！",
                            parent=classify_win,
                        )
                dialog_state.setdefault('checked_ids', set()).clear()
                rebuild_groups()

            def execute_delete(targets):
                if not targets:
                    messagebox.showinfo('OCR结果分类', '请先在左侧选择要删除的规则项。', parent=classify_win)
                    return
                if len(targets) > 1:
                    if not messagebox.askyesno('确认批量删除', f'确定要删除选中的 {len(targets)} 项归类规则和长效记忆吗？', parent=classify_win):
                        return
                selected_label = action_combo.get().strip()
                action = action_map.get(selected_label)
                affected_part_ids = set()
                updated_configs_map = {}

                for group in targets:
                    part_id = group['part_id']
                    affected_part_ids.add(part_id)
                    if part_id in updated_configs_map:
                        source_config = updated_configs_map[part_id]
                    else:
                        source_config = self.normalize_ocr_config(group['tasks'][0]['part'].get('ocr'))

                    if len(targets) == 1:
                        text_to_delete = ocr_edit_var.get().strip() or group['ocr_text']
                    else:
                        text_to_delete = group['ocr_text'].strip()

                    if not text_to_delete:
                        continue

                    updated_config = self.remove_ocr_classification_from_config(
                        source_config,
                        text_to_delete,
                        action=action,
                    )
                    if group['ocr_text'] and group['ocr_text'] != text_to_delete:
                        updated_config = self.remove_ocr_classification_from_config(
                            updated_config,
                            group['ocr_text'],
                            action=action,
                        )
                    updated_configs_map[part_id] = updated_config
                    self.forget_ocr_result_classification(source_config, text_to_delete)
                    if group['ocr_text'] and group['ocr_text'] != text_to_delete:
                        self.forget_ocr_result_classification(source_config, group['ocr_text'])

                try:
                    self.save_ocr_settings_for_parts(updated_configs_map)
                    self.sync_loaded_answer_scheme_ocr_settings()
                except Exception as e:
                    messagebox.showerror('删除失败', str(e), parent=classify_win)
                    return

                fresh_parts = {part['part_id']: part for part in self.iter_subjective_parts()}
                for pid in affected_part_ids:
                    fresh_part = fresh_parts.get(pid)
                    if fresh_part:
                        for part in parts:
                            if part.get('part_id') == pid:
                                part['ocr'] = fresh_part.get('ocr')
                        for task_item in tasks:
                            if task_item.get('part_id') == pid:
                                task_item['part']['ocr'] = fresh_part.get('ocr')

                classify_status_var.set(f"已删除选中的 {len(targets)} 项设置及长效记忆。")
                dialog_state.setdefault('checked_ids', set()).clear()
                rebuild_groups()

            def on_save_clicked():
                targets = get_target_groups()
                if not targets:
                    messagebox.showinfo('OCR结果分类', '请先在左侧选择或勾选识别结果。', parent=classify_win)
                    return
                selected_label = action_combo.get().strip()
                action = action_map.get(selected_label, 'alternate_answer')
                execute_save(targets, action)

            def on_remember_clicked():
                targets = get_target_groups()
                if not targets:
                    messagebox.showinfo('OCR结果分类', '请先在左侧选择或勾选识别结果。', parent=classify_win)
                    return
                selected_label = action_combo.get().strip()
                action = action_map.get(selected_label, 'alternate_answer')
                execute_remember(targets, action)

            def on_delete_clicked():
                targets = get_target_groups()
                execute_delete(targets)

            def apply_batch_action(action):
                targets = get_target_groups()
                if not targets:
                    messagebox.showinfo('OCR结果分类', '请先在左侧勾选或选择要归类的识别结果。', parent=classify_win)
                    return
                if action in action_labels:
                    action_combo.set(action_labels[action])
                if remember_also_var.get():
                    execute_remember(targets, action)
                else:
                    execute_save(targets, action)

            def apply_group_classification(action):
                apply_batch_action(action)

            def keep_group_for_manual():
                targets = get_target_groups()
                if not targets:
                    return
                for group in targets:
                    ignored_groups.add((group['part_id'], self.normalize_subjective_answer_for_match(group['ocr_text'])))
                classify_status_var.set(
                    f"已将选中的 {len(targets)} 个分类保留逐份人工打分。"
                )
                dialog_state.setdefault('checked_ids', set()).clear()
                rebuild_groups()

            def execute_direct_score(targets, score_value):
                if not targets:
                    messagebox.showinfo('OCR结果分类', '请先在左侧选择或勾选识别结果。', parent=classify_win)
                    return
                processed = 0
                for group in targets:
                    for task_item in group['tasks']:
                        entry_key = task_item['entry_key']
                        part_id = task_item['part_id']
                        entry_scores = all_scores.setdefault(entry_key, {})
                        record = entry_scores.setdefault(part_id, {})
                        max_score = float(task_item['part'].get('score') or 1.0)
                        if score_value == 'full':
                            assigned_score = max_score
                        else:
                            assigned_score = max(0.0, min(float(score_value), max_score))

                        record.update({
                            'score': assigned_score,
                            'max_score': max_score,
                            'manual_graded': True,
                            'auto_graded': False,
                            'ocr_auto_need_manual': False,
                            'auto_grade_engine': 'OCR分类直接打分',
                            'auto_grade_reason': f'同类试卷批量直接判{assigned_score}分',
                            'label': task_item['part'].get('label', ''),
                            'student_name': task_item['entry'].get('student_name', ''),
                            'score_id': task_item['entry'].get('score_id', ''),
                            'file': task_item['entry'].get('file', ''),
                            'updated_at': datetime.now().isoformat(timespec='seconds'),
                        })
                        processed += 1

                self.save_subjective_score_payload(payload)
                refresh_main_result_views()
                refresh()

                count = len(targets)
                score_label = "满分" if score_value == 'full' else (f"{int(score_value)}分" if float(score_value).is_integer() else f"{score_value}分")
                if count == 1:
                    g = targets[0]
                    classify_status_var.set(
                        f"【直接判分】已将 {g['label']} 的“{g['ocr_text']}”同类试卷全部直接判为 {score_label}；完成 {processed} 份打分。"
                    )
                else:
                    classify_status_var.set(
                        f"【批量直接判分】已将选中的 {count} 个分类所有试卷直接判为 {score_label}；完成 {processed} 份打分。"
                    )
                dialog_state.setdefault('checked_ids', set()).clear()
                rebuild_groups()

            def execute_single_sample_score(score_value):
                group = current_group()
                if not group or not group.get('tasks'):
                    messagebox.showinfo('OCR结果分类', '当前没有可打分的样张图片。', parent=classify_win)
                    return

                sample_tasks = group['tasks']
                sample_idx = dialog_state.get('sample_index', 0)
                if sample_idx < 0 or sample_idx >= len(sample_tasks):
                    sample_idx = 0

                task_item = sample_tasks[sample_idx]
                entry_key = task_item['entry_key']
                part_id = task_item['part_id']
                entry_scores = all_scores.setdefault(entry_key, {})
                record = entry_scores.setdefault(part_id, {})
                max_score = float(task_item['part'].get('score') or 1.0)
                if score_value == 'full':
                    assigned_score = max_score
                else:
                    assigned_score = max(0.0, min(float(score_value), max_score))

                student_name = task_item['entry'].get('student_name', '')
                score_id = task_item['entry'].get('score_id', '')

                record.update({
                    'score': assigned_score,
                    'max_score': max_score,
                    'manual_graded': True,
                    'auto_graded': False,
                    'ocr_auto_need_manual': False,
                    'auto_grade_engine': 'OCR分类单图即判',
                    'auto_grade_reason': f'看图直接判{assigned_score}分',
                    'label': task_item['part'].get('label', ''),
                    'student_name': student_name,
                    'score_id': score_id,
                    'file': task_item['entry'].get('file', ''),
                    'updated_at': datetime.now().isoformat(timespec='seconds'),
                })

                self.save_subjective_score_payload(payload)
                refresh_main_result_views()
                refresh()

                score_label = "满分" if score_value == 'full' else (
                    f"{int(assigned_score)}分" if assigned_score.is_integer() else f"{assigned_score}分"
                )

                # 从当前分类的待办任务中剔除已判的这一份
                group['tasks'].pop(sample_idx)
                remaining = len(group['tasks'])
                selected_item_id = dialog_state.get('selected')

                if remaining > 0:
                    # 分类内仍有其他学生作答：更新左侧列表中该分类的剩余数量
                    if selected_item_id and group_tree.exists(selected_item_id):
                        vals = list(group_tree.item(selected_item_id, 'values'))
                        if vals and len(vals) >= 5:
                            vals[4] = remaining
                            group_tree.item(selected_item_id, values=vals)

                    # 自动指向下一个学生样张
                    if sample_idx >= remaining:
                        dialog_state['sample_index'] = 0
                    else:
                        dialog_state['sample_index'] = sample_idx

                    update_selection_ui()
                    refresh_sample()
                    classify_status_var.set(
                        f"【单项看图即判】已判当前试卷（学生：{student_name} / {score_id}）为 {score_label}；该分类还剩 {remaining} 份待判，已显示下一份。"
                    )
                else:
                    # 该分类的学生作答已全部判阅完毕，从左侧列表中移除
                    if selected_item_id and group_tree.exists(selected_item_id):
                        group_tree.delete(selected_item_id)
                    dialog_state['groups'].pop(selected_item_id, None)
                    dialog_state.setdefault('checked_ids', set()).discard(selected_item_id)

                    children = group_tree.get_children()
                    if children:
                        next_item = children[0]
                        group_tree.selection_set(next_item)
                        group_tree.focus(next_item)
                        dialog_state['selected'] = next_item
                        dialog_state['sample_index'] = 0
                        update_selection_ui()
                        refresh_sample()
                        classify_status_var.set(
                            f"【单项看图即判】学生 {student_name}（{score_id}）已判 {score_label}；该分类全部判完，已自动切换到下一分类。"
                        )
                    else:
                        dialog_state['selected'] = ''
                        dialog_state['sample_index'] = 0
                        update_selection_ui()
                        refresh_sample()
                        classify_status_var.set(
                            f"🎉 最后一项学生 {student_name} 已判 {score_label}，所有待分类试卷已全部打分完成！"
                        )

            def show_context_menu(event):
                clicked_item = group_tree.identify_row(event.y)
                checked_ids = dialog_state.get('checked_ids', set())
                selected_tree_ids = set(group_tree.selection())

                if clicked_item:
                    if clicked_item in checked_ids:
                        # Right-clicked on one of the checked items: preserve checked items!
                        pass
                    elif clicked_item in selected_tree_ids and not checked_ids:
                        # Right-clicked on one of the multi-selected rows: preserve selection!
                        pass
                    else:
                        # Right-clicked on a row outside current check/selection:
                        # Clear old checkmarks and focus this single row
                        checked_ids.clear()
                        for k in dialog_state['groups'].keys():
                            vals = list(group_tree.item(k, 'values'))
                            if vals and vals[0] == '☑':
                                vals[0] = '☐'
                                group_tree.item(k, values=vals)
                        group_tree.selection_set(clicked_item)
                        group_tree.focus(clicked_item)
                        dialog_state['selected'] = clicked_item
                        dialog_state['sample_index'] = 0
                        update_selection_ui()
                        refresh_sample()

                targets = get_target_groups()
                if not targets:
                    return

                count = len(targets)
                total_papers = sum(len(g['tasks']) for g in targets)

                menu = tk.Menu(classify_win, tearoff=0)

                # Title / Header
                if count == 1:
                    g = targets[0]
                    header_text = f"【单项归类】{g['label']}：“{g['ocr_text']}” ({total_papers} 份)"
                else:
                    header_text = f"【批量归类】已选 {count} 项（涵盖 {total_papers} 份作答）"
                menu.add_command(label=header_text, state='disabled')
                menu.add_separator()

                # 🚀 核心新增：全部提交当前判分状态 (支持单选与多选批量提交！)
                total_right = 0
                total_wrong = 0
                for g in targets:
                    for t in g['tasks']:
                        t_key = (t['entry_key'], t['part_id'])
                        sc = dialog_state.get('persisted_decisions', {}).get(t_key, 0.0)
                        if sc > 0:
                            total_right += 1
                        else:
                            total_wrong += 1

                if count == 1:
                    submit_menu_label = f"🚀 提交当前分类判分 (共 {total_papers} 份：对 {total_right} / 错 {total_wrong})"
                else:
                    submit_menu_label = f"🚀 全部提交所选 {count} 个分类判分 (共 {total_papers} 份：对 {total_right} / 错 {total_wrong})"

                menu.add_command(
                    label=submit_menu_label,
                    command=lambda: execute_gallery_batch_submit(targets),
                    font=('微软雅黑', 10, 'bold'),
                )
                menu.add_separator()

                # ⭐ 直接判分区（批量直接给0分或1分）
                has_multi_score = any(float(g['tasks'][0]['part'].get('score') or 1.0) > 1.0 for g in targets)
                if count == 1:
                    g = targets[0]
                    n = len(g['tasks'])
                    menu.add_command(
                        label=f"⭐ 该类所有试卷直接判 1 分 (共 {n} 份全部给 1 分)",
                        command=lambda: execute_direct_score(targets, 1.0),
                    )
                    menu.add_command(
                        label=f"⭐ 该类所有试卷直接判 0 分 (共 {n} 份全部给 0 分)",
                        command=lambda: execute_direct_score(targets, 0.0),
                    )
                    if has_multi_score:
                        menu.add_command(
                            label=f"⭐ 该类所有试卷直接判满分 (共 {n} 份全部给满分)",
                            command=lambda: execute_direct_score(targets, 'full'),
                        )
                    menu.add_separator()
                    menu.add_command(
                        label="🖼 仅当前这 1 份看图判 1 分 (单份)",
                        command=lambda: execute_single_sample_score(1.0),
                    )
                    menu.add_command(
                        label="🖼 仅当前这 1 份看图判 0 分 (单份)",
                        command=lambda: execute_single_sample_score(0.0),
                    )
                else:
                    menu.add_command(
                        label=f"⭐ 所选 {count} 类所有试卷批量判 1 分 (共 {total_papers} 份全部给 1 分)",
                        command=lambda: execute_direct_score(targets, 1.0),
                    )
                    menu.add_command(
                        label=f"⭐ 所选 {count} 类所有试卷批量判 0 分 (共 {total_papers} 份全部给 0 分)",
                        command=lambda: execute_direct_score(targets, 0.0),
                    )
                    if has_multi_score:
                        menu.add_command(
                            label=f"⭐ 所选 {count} 类所有试卷批量判满分 (共 {total_papers} 份全部给满分)",
                            command=lambda: execute_direct_score(targets, 'full'),
                        )
                menu.add_separator()

                # 长效记忆+立即批改（最常用快捷方式）
                menu.add_command(
                    label="✔ 设为【备选答案】 (长效记忆+立即重判)",
                    command=lambda: execute_remember(targets, 'alternate_answer', silent=True),
                )
                menu.add_command(
                    label="✔ 设为【答案关键字】 (长效记忆+立即重判)",
                    command=lambda: execute_remember(targets, 'correct_keyword', silent=True),
                )
                menu.add_command(
                    label="✖ 设为【错误答案】 (长效记忆+立即判0分)",
                    command=lambda: execute_remember(targets, 'wrong_answer', silent=True),
                )
                menu.add_command(
                    label="✖ 设为【错误关键字】 (长效记忆+立即判0分)",
                    command=lambda: execute_remember(targets, 'wrong_keyword', silent=True),
                )

                menu.add_separator()

                cur_menu = tk.Menu(menu, tearoff=0)
                cur_menu.add_command(
                    label="设为【备选答案】(仅当前有效)",
                    command=lambda: execute_save(targets, 'alternate_answer'),
                )
                cur_menu.add_command(
                    label="设为【答案关键字】(仅当前有效)",
                    command=lambda: execute_save(targets, 'correct_keyword'),
                )
                cur_menu.add_command(
                    label="设为【错误答案】(仅当前有效)",
                    command=lambda: execute_save(targets, 'wrong_answer'),
                )
                cur_menu.add_command(
                    label="设为【错误关键字】(仅当前有效)",
                    command=lambda: execute_save(targets, 'wrong_keyword'),
                )
                menu.add_cascade(label="仅对当前试卷有效 (不存长效库) ▶", menu=cur_menu)

                menu.add_separator()

                menu.add_command(
                    label=f"✋ 保留逐份人工打分 ({count}项)",
                    command=keep_group_for_manual,
                )
                menu.add_command(
                    label=f"🗑 删除归类规则与记忆 ({count}项)",
                    command=lambda: execute_delete(targets),
                )

                menu.add_separator()

                if clicked_item and clicked_item in dialog_state['groups']:
                    is_chk = clicked_item in checked_ids
                    chk_label = "☐ 取消勾选此项" if is_chk else "☑ 勾选此项"
                    menu.add_command(label=chk_label, command=lambda: toggle_check_item(clicked_item))

                menu.add_command(label="☑ 全选所有项", command=toggle_check_all)
                menu.add_command(label="☐ 全部取消勾选", command=uncheck_all)
                menu.add_command(label="🔄 反向选择", command=invert_check)

                try:
                    menu.tk_popup(event.x_root, event.y_root)
                finally:
                    menu.grab_release()

            group_tree.bind('<Button-3>', show_context_menu)
            group_tree.bind('<Button-2>', show_context_menu)

            def on_key_score(val, _event=None):
                focus_w = classify_win.focus_get()
