        auto_grade_all_button.pack(side=tk.LEFT, padx=4)

        # 分组二：⚙️ 规则配置与单空维护（配置与维护）
        tools_group = ttk.LabelFrame(toolbar_container, text=' ⚙️ 规则配置与单空维护 ', padding=(8, 6))
        tools_group.pack(fill=tk.X, pady=(0, 5))

